async def _send_with_retry(bot: Bot, chat_id: int, text: str, retries: int = 3, **kwargs) -> bool:
    """ارسال پیام با retry خودکار در صورت timeout."""
    for attempt in range(retries):
        try:
            await bot.send_message(chat_id, text, **kwargs)
            return True
        except Exception as e:
            err = str(e)
            if attempt < retries - 1 and ("timeout" in err.lower() or "network" in err.lower()):
                await asyncio.sleep(2 ** attempt)  # 1s, 2s
                continue
            raise
    return False


