def plan_expiry_from_now(plan: str) -> datetime.datetime:
    """تاریخ سررسید یک پلن از همین لحظه."""
    return datetime.datetime.now() + datetime.timedelta(days=PLAN_DAYS.get(plan, 30))


async def set_tenant_webhook(token: str) -> bool:
    """تنظیم وب‌هوک ربات مستأجر با ۳ بار تلاش مجدد."""
    if not WEBHOOK_BASE:
        return False
    url = f"{WEBHOOK_BASE}/webhook/{token}"
    for attempt in range(3):
        try:
            live = Bot(token=token)
            try:
                await live.set_webhook(url, drop_pending_updates=True,
                                       allowed_updates=__import__("webhook_utils").TENANT_ALLOWED_UPDATES)   # PATCH_JOIN_CHAT_MEMBER_V1
            finally:
                await live.session.close()
            return True
        except Exception as e:
            print(f"set_tenant_webhook failed (attempt {attempt + 1}/3): {e}")
            if attempt < 2:
                await asyncio.sleep(2 ** attempt)   # 1s, 2s
    return False


async def apply_brand_bio(token: str, plan: str) -> None:
    """=== PATCH_REMOVE_BIO_LOCK_V1 ===
    «قفلِ بیو» برداشته شد: دیگر هیچ متنی به بیویِ رباتِ رایگان تحمیل
    نمی‌شود و مالک آزاد است هرچه می‌خواهد بنویسد.

    این تابع حذف نشد چون از سه جا صدا زده می‌شود (ساختِ ربات، تغییرِ پلن،
    و رباتِ همکار). حالا فقط یک کارِ پاک‌سازی می‌کند: اگر بیویِ فعلی
    *دقیقاً* همان تبلیغِ قدیمی باشد، خالی‌اش می‌کند. بیویی که خودِ مالک
    نوشته دست‌نخورده می‌ماند — به همین دلیل بی‌قید `set("")` نمی‌زنیم.
    """
    try:
        tb = Bot(token=token)
        try:
            try:
                cur = (await tb.get_my_short_description()).short_description or ""
            except Exception:
                cur = ""
            if cur.strip() == BRAND_BIO.strip():
                await tb.set_my_short_description(short_description="")
        finally:
            await tb.session.close()
    except Exception as e:
        print("brand bio cleanup error:", e)


# === PATCH_TRIAL_EXPIRY_BUTTONS_V1 ===
async def _trial_expiry_kb(bot: "Bot") -> "InlineKeyboardMarkup | None":
    """دو دکمهٔ «ساخت ربات» و «خرید/ارتقا پلن» زیرِ پیامِ پایانِ مهلتِ تست.
    از دیپ‌لینکِ ?start=hcb-<key> استفاده می‌کنه (همون مکانیزمی که دکمه‌هایِ
    پستِ کانال ازش استفاده می‌کنن) — چون این پیام از یه تسکِ پس‌زمینه
    فرستاده می‌شه و دکمهٔ callback نیاز به مسیرِ جداگانه داشت."""
    try:
        me = await bot.get_me()
    except Exception:
        return None
    return InlineKeyboardMarkup(inline_keyboard=[
        [hx_button(BTN_CREATE, url=f"https://t.me/{me.username}?start=hcb-create",
                              style=ButtonStyle.SUCCESS)],
        [hx_button(BTN_PLANS, url=f"https://t.me/{me.username}?start=hcb-plans",
                              style=ButtonStyle.PRIMARY)],
    ])


async def sweep_trials(bot: "Bot | None" = None) -> None:
    """تست‌های منقضی‌شده را رسیدگی می‌کند: ربات‌ها را به پلن پایه برمی‌گرداند
    (فقط امکانات پایه فعال می‌ماند) و به کاربر اطلاع می‌دهد. این تابع سبک است و
    در نقاط ورودی پرتردد (start/ساخت ربات/ربات‌های من/پنل) فراخوانی می‌شود تا
    حتی بدون زمان‌بند هم تست‌ها سر وقت غیرفعال شوند."""
    try:
        events = await plan_trials.expire_due_trials()
    except Exception as e:
        print("sweep_trials error:", e)
        return
    for ev in events:
        try:
            if ev["kind"] == "archived":
                token = ev.get("token") or ""
                if token:
                    try:
                        import tenant_status_bus
                        await tenant_status_bus.publish_tenant_invalidate(token)
                    except Exception:
                        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
                    try:
                        async with _temp_bot(token) as tb:
                            await tb.delete_webhook()
                    except Exception:
                        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
                if bot is not None:
                    uname = ev.get("username") or ""
                    await bot.send_message(
                        ev["owner_id"],
                        f"⏳ مهلت تست پلن «{PLAN_INFO[Plan(ev['plan'])]['title']}» "
                        f"برای ربات @{uname} به پایان رسید و چون تمدید نشده بود، "
                        f"ربات به‌صورت خودکار <b>غیرفعال/بایگانی</b> شد.\n"
                        f"اگه دوست داری ادامه بدی، از «🗂 ربات‌های من» می‌تونی پلنی رو "
                        f"بخری و ربات رو برگردونی.",
                    )
            elif ev["kind"] == "start_deadline_missed" and bot is not None:
                await bot.send_message(
                    ev["owner_id"],
                    f"⏳ تستِ پلن «{PLAN_INFO[Plan(ev['plan'])]['title']}» شما چون ظرفِ "
                    f"<b>{getattr(plan_trials, 'TRIAL_START_DEADLINE_DAYS', '؟')} روز</b> پس از تاییدِ ادمین "
                    f"برای ساختِ ربات استفاده نشد، <b>غیرفعال</b> شد. "
                    f"در صورت نیاز می‌تونی پلن رو تهیه کنی.",
                    reply_markup=await _trial_expiry_kb(bot),
                )
            elif ev["kind"] == "lapsed" and bot is not None:
                await bot.send_message(
                    ev["owner_id"],
                    f"⏳ مهلت تست پلن «{PLAN_INFO[Plan(ev['plan'])]['title']}» "
                    f"بدون استفاده به پایان رسید. در صورت نیاز می‌توانی تمدید یا خریداری کنید.",
                    reply_markup=await _trial_expiry_kb(bot),
                )
        except Exception as e:
            print("sweep_trials notify error:", e)


