async def smart_cancel_kb() -> "InlineKeyboardMarkup | ReplyKeyboardMarkup":
    """PATCH_PLATFORM_SMART_CANCEL_V1 — کیبوردِ «لغو» هماهنگ با نوعِ منویِ فعلیِ صفحهٔ اصلی: در حالتِ
    اینلاین یک دکمهٔ اینلاینِ «❌ لغو» برمی‌گرداند (هیچ کیبوردِ پایینی نشان
    داده نمی‌شود)، در حالتِ کیبورد همان کیبوردِ معمولیِ قبلی."""
    if await get_pset("home_menu_mode", "reply") == "inline":
        return InlineKeyboardMarkup(inline_keyboard=[
            [hx_button("❌ لغو", callback_data="hm:fsm_cancel", style=ButtonStyle.DANGER)]
        ])
    return cancel_kb()


async def smart_ticket_cancel_kb() -> "InlineKeyboardMarkup | ReplyKeyboardMarkup":
    """PATCH_PLATFORM_SMART_CANCEL_V1 — نسخهٔ هوشمندِ ticket_cancel_kb؛ در حالتِ اینلاین دو دکمهٔ
    اینلاین («⬅️ بازگشت به تیکت‌ها» و «❌ لغو») برمی‌گرداند."""
    if await get_pset("home_menu_mode", "reply") == "inline":
        return InlineKeyboardMarkup(inline_keyboard=[
            [hx_button(BTN_TICKET_BACK, callback_data="hm:ticket_back", style=ButtonStyle.PRIMARY)],
            [hx_button("❌ لغو", callback_data="hm:fsm_cancel", style=ButtonStyle.DANGER)],
        ])
    return ticket_cancel_kb()


@router.callback_query(F.data == "hm:fsm_cancel")
async def hm_fsm_cancel(cb: CallbackQuery, state: FSMContext):
    await _delete_home_aux_messages(state, cb.message.bot)
    """PATCH_PLATFORM_SMART_CANCEL_V1 — نسخهٔ اینلاینِ دکمهٔ «❌ لغو»: لغوِ هر فرآیندِ متنیِ در حالِ
    انتظار و بازگشت به منوی اصلیِ اینلاین (معادلِ cancel_any در حالتِ کیبورد)."""
    await state.clear()
    try:
        await cb.message.edit_text("❌ لغو شد. به منوی اصلی برگشتی.")
    except Exception:
        try:
            await cb.message.answer("❌ لغو شد. به منوی اصلی برگشتی.")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    show_admin = await _home_show_admin(cb.from_user.id)
    await cb.message.answer("🏠 منوی اصلی:", reply_markup=home_inline_kb(cb.from_user.id, show_admin))
    await cb.answer()


@router.callback_query(F.data == "hm:ticket_back")
async def hm_ticket_back(cb: CallbackQuery, state: FSMContext, bot: Bot):
    await _delete_home_aux_messages(state, cb.message.bot)
    """PATCH_PLATFORM_SMART_CANCEL_V1 — نسخهٔ اینلاینِ دکمهٔ «⬅️ بازگشت به تیکت‌ها»؛ همون
    ticket_back_handler را با کاربرِ واقعی صدا می‌زند تا رفتار دقیقاً یکسان بماند."""
    # PATCH_SPLIT_TICKETS_V1 — ticket_back_handler حالا توی platform_tickets.py هست
    from platform_tickets import ticket_back_handler
    await cb.answer()
    fake = cb.message.model_copy(update={"from_user": cb.from_user}).as_(bot)
    await ticket_back_handler(fake, state)


