async def refresh_home_cfg() -> None:
    """تنظیمات دکمه‌ها را از Setting (bot_id=0) در کش بارگذاری می‌کند."""
    global _HOME_LOADED
    for k in HOME_DEFAULT_LABEL:
        label = (await get_pset(f"hbtn:{k}:label", "")) or HOME_DEFAULT_LABEL[k]
        enabled = (await get_pset(f"hbtn:{k}:enabled", "1")) != "0"
        rule = await get_pset(f"hbtn:{k}:rule", "")
        icon_emoji_id = await get_pset(f"hbtn:{k}:emoji", "")
        sticker_file_id = await get_pset(f"hbtn:{k}:sticker", "")  # PATCH_HOME_BTN_STICKER_V1
        # === PATCH_HOME_BTN_SEND_EMOJI_V1 ===
        send_emoji_id = await get_pset(f"hbtn:{k}:send_emoji_id", "")
        send_emoji_char = await get_pset(f"hbtn:{k}:send_emoji_char", "")
        command = await get_pset(f"hbtn:{k}:command", "")  # PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_V1
        admin_only = (await get_pset(f"hbtn:{k}:admin_only", "off")) == "on" if k == "self_saz" else False
        _HOME_CFG[k] = {"label": label, "enabled": enabled, "rule": rule,
                        "icon_emoji_id": icon_emoji_id, "sticker_file_id": sticker_file_id,
                        "send_emoji_id": send_emoji_id, "send_emoji_char": send_emoji_char,
                        "command": command, "admin_only": admin_only}
    global _HOME_CUSTOM
    try:
        raw = await get_pset("home_custom_btns", "[]")
        parsed = json.loads(raw or "[]")
        _HOME_CUSTOM = parsed if isinstance(parsed, list) else []
    except Exception:
        _HOME_CUSTOM = []
    # === PATCH_HOME_BTN_REORDER_V2 ===
    global _HOME_ROWS
    all_valid: set[str] = set(HOME_DEFAULT_LABEL) | {
        f"custom:{b['id']}" for b in _HOME_CUSTOM if not b.get("parent_id")}
    try:
        raw_order = await get_pset("home_key_order", "")
        parsed_rows = json.loads(raw_order) if raw_order.strip() else None
        if not isinstance(parsed_rows, list):
            parsed_rows = None
    except Exception:
        parsed_rows = None
    if parsed_rows is None:
        _HOME_ROWS = None  # سفارشی‌سازی نشده — از پیش‌فرض استفاده می‌شه
    else:
        # پاک‌سازی: کلیدهایِ حذف‌شده (مثلاً دکمهٔ دلخواهی که پاک شده) دور
        # ریخته می‌شن؛ ردیف‌هایِ خالی هم حذف می‌شن.
        seen: set[str] = set()
        cleaned: list[list[str]] = []
        for row in parsed_rows:
            if not isinstance(row, list):
                continue
            new_row = [e for e in row if isinstance(e, str) and e in all_valid and e not in seen]
            seen.update(new_row)
            if new_row:
                cleaned.append(new_row[:2])  # حداکثر ۲ تا در هر ردیف
        # کلیدها/دکمه‌هایِ جدیدی که تویِ چیدمانِ ذخیره‌شده نیستن (مثلاً یه
        # قابلیتِ تازه یا یه دکمهٔ دلخواهِ تازه‌ساخته) — ته‌لیست، هرکدوم ردیفِ
        # جداگونه، اضافه می‌شن تا گم نشن.
        for k in all_valid:
            if k not in seen:
                cleaned.append([k])
        _HOME_ROWS = cleaned
    # === PATCH_INVITE_CAMPAIGN_DAYS_SETTING_V1 ===
    global INVITE_CAMPAIGN_WEEKDAYS
    try:
        raw_days = await get_pset("icb_active_days", "")
        if raw_days.strip() == "all":
            INVITE_CAMPAIGN_WEEKDAYS = set(range(7))
        elif raw_days.strip():
            INVITE_CAMPAIGN_WEEKDAYS = {int(x) for x in raw_days.split(",") if x.strip().isdigit()}
        # اگه هنوز هیچ تنظیمی ثبت نشده (raw_days خالی)، مقدارِ پیش‌فرضِ
        # فعلیِ INVITE_CAMPAIGN_WEEKDAYS (دوشنبه/پنج‌شنبه) دست‌نخورده می‌مونه.
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    _HOME_LOADED = True


async def ensure_home_loaded() -> None:
    if not _HOME_LOADED:
        await refresh_home_cfg()


def _resolve_home_key(text: str | None) -> str | None:
    if not text:
        return None
    for k, c in _HOME_CFG.items():
        if (c.get("label") or HOME_DEFAULT_LABEL[k]) == text:
            return k
    for b in _HOME_CUSTOM:
        if (b.get("label") or "") == text:
            return f"custom:{b.get('id')}"
    return None


_HOME_RESERVED_COMMANDS = {"start", "help"}


def _resolve_home_command(text: str | None) -> str | None:
    """PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_V1 — از رویِ متنِ یک پیامِ کامندی (مثلِ «/wallet» یا «/wallet@Bot»)
    کلیدِ دکمهٔ متناظرش را برمی‌گرداند (چه دکمهٔ ثابت، چه دلخواه در هر عمقی)."""
    if not text or not text.startswith("/"):
        return None
    parts = text[1:].split()
    cmd = parts[0].split("@")[0].strip().lower() if parts else ""
    if not cmd:
        return None
    for k, c in _HOME_CFG.items():
        if (c.get("command") or "").strip().lower() == cmd:
            return k
    for b in _HOME_CUSTOM:
        if (b.get("command") or "").strip().lower() == cmd:
            return f"custom:{b.get('id')}"
    return None


def _home_command_taken(cmd: str, exclude_key: str | None = None) -> bool:
    """PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_V1 — بررسیِ یکتاییِ یک کامند بینِ همهٔ دکمه‌های ثابت/دلخواه."""
    cmd = cmd.strip().lower()
    for k, c in _HOME_CFG.items():
        if k == exclude_key:
            continue
        if (c.get("command") or "").strip().lower() == cmd:
            return True
    for b in _HOME_CUSTOM:
        if f"custom:{b.get('id')}" == exclude_key:
            continue
        if (b.get("command") or "").strip().lower() == cmd:
            return True
    return False


class HomeCommandFilter(BaseFilter):
    async def __call__(self, message: Message) -> bool:
        return _resolve_home_command(message.text) is not None


# === PATCH_HOME_MENU_STUCK_STATE_V1 ===
# باگ: این هندلر (و مشابهش پایین‌تر برایِ لیبلِ دکمه‌ها) قبلاً با
# StateFilter(None) محدود شده بود — یعنی اگه کاربر به هر دلیلی وسطِ یک
# ویزاردِ ناتمام گیر می‌کرد (مثلاً وارد «✏️ ویرایش کامل ربات» شده بود که
# EditBot.menu ست می‌کنه، بعد بدونِ اتمامِ اون ویزارد به‌جای دیگه‌ای رفته
# بود، مثلاً حذفِ یک ربات)، state هیچ‌وقت پاک نمی‌شد. نتیجه: از اون لحظه به
# بعد، زدنِ هر دکمه‌ای از کیبوردِ فیزیکی (ربات‌های من/ساخت ربات/ارتقا/...)
# اصلاً جوابی نمی‌داد — چون این هندلر با state غیرِNone هرگز matchنمی‌شد —
# و فقط /start (که خودش state رو پاک می‌کنه) دوباره کار می‌کرد. حالا این
# فیلتر دیگه به state وابسته نیست؛ زدنِ هر دکمهٔ سطحِ‌بالا همیشه کار می‌کنه
# و خودش هم به‌عنوانِ اقدامِ ایمن، state رو پاک می‌کنه (دقیقاً مثلِ /start).
# === PATCH_PLATFORM_PRIVATE_ONLY_V3 ===
# باگ: رباتِ بات‌ساز در گروه هم به /start و دکمه‌هایِ منو جواب می‌داد و
# پیامِ خوش‌آمد و منویِ «شارژِ کیف پول» را وسطِ گروه پست می‌کرد.
#
# دو تلاشِ قبلی اشتباه بودند و درس‌شان اینجاست:
#  V1) router.message.filter(...) → در aiogram این فیلتر در check_root_filters
#      قبل از همه بررسی می‌شود و ردشدنش *کلِ روتر با همهٔ زیرروترها* را کنار
#      می‌گذارد؛ نتیجه: تاس و قرعه‌کشی و نگهبانِ گروه هم خاموش شدند.
#  V2) یک زیرروترِ «بلعنده» → بی‌فایده بود، چون _propagate_event اول
#      هندلرهایِ *خودِ* روترِ والد را اجرا می‌کند و تازه بعدش سراغِ
#      زیرروترها می‌رود؛ پس /start قبل از رسیدن به بلعنده جواب داده بود.
#
# راهِ درست و کم‌ریسک: همان دو-سه ورودیِ منو خودشان در چتِ غیرخصوصی
# بی‌صدا برمی‌گردند. بقیهٔ چیزها (بازی‌هایِ گروهی، قرعه‌کشی، نگهبان) اصلاً
# لمس نمی‌شوند.
def _skip_in_group(event) -> bool:
    chat = getattr(event, "chat", None)
    return chat is not None and getattr(chat, "type", "private") != "private"


@router.message(HomeCommandFilter())
async def _home_command_interceptor(msg: Message, state: FSMContext, bot: Bot):
    """PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_V1 — اجرایِ دکمه از رویِ کامندِ اسلشِ اختصاصی‌اش."""
    if _skip_in_group(msg):  # PATCH_PLATFORM_PRIVATE_ONLY_V3
        return
    key = _resolve_home_command(msg.text)
    if key is None:
        return
    await state.clear()
    await _dispatch_home_key(key, msg, state, bot)


async def _run_custom_home_btn(b: dict, msg: Message, state: FSMContext | None = None,
                               bot: Bot | None = None) -> None:
    """اجرای دکمهٔ دلخواه صفحهٔ اصلی: متن / مینی‌اپ / لینک / درخواست ربات تست."""
    btype = b.get("type") or "text"
    text = (b.get("message") or "").strip()
    url = (b.get("url") or "").strip()
    if btype == "invite_campaign":
        await invite_campaign_open(msg, msg.bot)
    elif btype == "trial_request":
        if state is not None and bot is not None:
            await trial_request_start(msg, state, bot)
        else:
            await msg.answer("این دکمه در حال حاضر قابل اجرا نیست، دوباره تلاش کن.")
    elif btype == "web_app" and url.startswith("https://"):
        kb = InlineKeyboardMarkup(inline_keyboard=[[
            hx_button(f"🌐 باز کردن {b.get('label') or 'مینی‌اپ'}",
                                 web_app=WebAppInfo(url=url), style=ButtonStyle.SUCCESS)]])
        await msg.answer(text or "برای باز کردن مینی‌اپ روی دکمهٔ زیر بزنید 👇", reply_markup=kb)
    elif btype == "url" and url.startswith(("https://", "http://", "tg://")):
        kb = InlineKeyboardMarkup(inline_keyboard=[[
            hx_button(f"🔗 {b.get('label') or 'باز کردن لینک'}", url=url)]])
        await msg.answer(text or "برای باز کردن لینک روی دکمهٔ زیر بزنید 👇", reply_markup=kb)
    elif btype == "submenu":
        await _run_home_submenu(b, msg)
    elif text:
        await msg.answer(text)
    else:
        await msg.answer("این دکمه هنوز تنظیم نشده است.")


async def _run_home_submenu(b: dict, msg: Message) -> None:
    """PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_V1 — نمایشِ فرزندانِ یک دکمهٔ «زیرمنو» به‌صورتِ اینلاین. چون
    فرزندان هم می‌توانند خودشان زیرمنو باشند، این تابع خودش را دوباره فرا
    نمی‌خواند — با تپِ فرزند، همان مسیرِ عادیِ hm:custom:<id> دوباره به این
    تابع می‌رسد، پس تو در توییِ نامحدود به‌طورِ طبیعی کار می‌کند."""
    children = [x for x in _HOME_CUSTOM if x.get("parent_id") == b.get("id") and x.get("enabled", True)]
    rows: list[list[InlineKeyboardButton]] = []
    for c in children:
        tmark = {"web_app": " 🌐", "url": " 🔗", "submenu": " 📁"}.get(c.get("type") or "", "")
        rows.append([hx_button(f"{c.get('label') or 'دکمه'}{tmark}",
                                          callback_data=f"hm:custom:{c['id']}", style=ButtonStyle.PRIMARY)])
    parent_id = b.get("parent_id")
    rows.append([hx_button("⬅️ بازگشت",
        callback_data=(f"hm:custom:{parent_id}" if parent_id else "hm:home"), style=ButtonStyle.DANGER)])
    if parent_id:
        rows.append([hx_button("🏠 خانه", callback_data="hm:home", style=ButtonStyle.DANGER)])
    title = b.get("label") or "زیرمنو"
    txt = f"📁 <b>{title}</b>\n\n" + ("یکی را انتخاب کن:" if children else "این زیرمنو هنوز خالی است.")
    await msg.answer(txt, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))


