@router.callback_query(F.data.startswith("hbtn:rowmove:"))
async def hbtn_rowmove(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    _, _, direction, i_s = cb.data.split(":", 3)
    i = int(i_s)
    rows_state = _home_active_rows(keep_partner=True)  # PATCH_PARTNER_REQ_MOVABLE_V1
    j = i - 1 if direction == "up" else i + 1
    if i < 0 or i >= len(rows_state) or j < 0 or j >= len(rows_state):
        await cb.answer()
        return
    rows_state[i], rows_state[j] = rows_state[j], rows_state[i]
    await _home_rows_save(rows_state)
    await cb.answer("✅ جابه‌جا شد")
    try:
        await cb.message.edit_reply_markup(reply_markup=_home_order_kb())
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


@router.callback_query(F.data.startswith("hbtn:rowswap:"))
async def hbtn_rowswap(cb: CallbackQuery):
    """جابه‌جاییِ جایِ دو دکمهٔ داخلِ یک ردیفِ دوتایی (چپ↔راست)."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    i = int(cb.data.split(":")[2])
    rows_state = _home_active_rows(keep_partner=True)  # PATCH_PARTNER_REQ_MOVABLE_V1
    if i < 0 or i >= len(rows_state) or len(rows_state[i]) != 2:
        await cb.answer("نامعتبر", show_alert=True)
        return
    rows_state[i] = [rows_state[i][1], rows_state[i][0]]
    await _home_rows_save(rows_state)
    await cb.answer("✅ جابه‌جا شد")
    try:
        await cb.message.edit_reply_markup(reply_markup=_home_order_kb())
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


@router.callback_query(F.data.startswith("hbtn:rowsplit:"))
async def hbtn_rowsplit(cb: CallbackQuery):
    """جداکردنِ یک ردیفِ چنددکمه‌ای — آخرین دکمه به ردیفِ تازه جدا می‌شود."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    i = int(cb.data.split(":")[2])
    rows_state = _home_active_rows(keep_partner=True)  # PATCH_PARTNER_REQ_MOVABLE_V1
    # === PATCH_HOME_BTN_3COL_V1 ===
    if i < 0 or i >= len(rows_state) or len(rows_state[i]) < 2:
        await cb.answer("نامعتبر", show_alert=True)
        return
    rest, last = rows_state[i][:-1], rows_state[i][-1]
    rows_state[i:i + 1] = [rest, [last]]
    await _home_rows_save(rows_state)
    await cb.answer("✅ جدا شد")
    try:
        await cb.message.edit_reply_markup(reply_markup=_home_order_kb())
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


@router.callback_query(F.data.startswith("hbtn:rowmerge:"))
async def hbtn_rowmerge(cb: CallbackQuery):
    """کنارِ هم گذاشتنِ ردیفِ i با ردیفِ بعدی (تا سقفِ سه دکمه در یک ردیف)."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    i = int(cb.data.split(":")[2])
    rows_state = _home_active_rows(keep_partner=True)  # PATCH_PARTNER_REQ_MOVABLE_V1
    # === PATCH_HOME_BTN_3COL_V1 ===
    if i < 0 or i + 1 >= len(rows_state) or len(rows_state[i]) + len(rows_state[i + 1]) > 3:
        await cb.answer("نامعتبر", show_alert=True)
        return
    merged = rows_state[i] + rows_state[i + 1]
    rows_state[i:i + 2] = [merged]
    await _home_rows_save(rows_state)
    await cb.answer("✅ کنارِ هم قرار گرفتن")
    try:
        await cb.message.edit_reply_markup(reply_markup=_home_order_kb())
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


