@router.message(HomeBtnFSM.cmd, F.text)
async def hbtn_cmd_save(msg: Message, state: FSMContext):
    """PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_V1"""
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    data = await state.get_data()
    key = data.get("hbtn_key")
    raw = (msg.text or "").strip()
    await state.clear()
    if raw == BTN_CANCEL or raw == "❌ لغو / بازگشت":
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    cmd = raw.lstrip("/").strip().lower()
    import re as _re
    if not key or not cmd or not _re.fullmatch(r"[a-z0-9_]{1,32}", cmd) or cmd in _HOME_RESERVED_COMMANDS:
        await msg.answer(
            "❌ نامعتبر. فقط حروفِ انگلیسیِ کوچک/عدد/آندرلاین (حداکثر ۳۲ کاراکتر) و نه "
            "یکی از کامندهای رزرو‌شده (start, help). دوباره بفرست:")
        return
    if _home_command_taken(cmd, exclude_key=key):
        await msg.answer("❌ این کامند قبلاً برایِ دکمهٔ دیگری تنظیم شده. کلمهٔ دیگری بفرست:")
        return
    await set_pset(f"hbtn:{key}:command", cmd)
    await refresh_home_cfg()
    await msg.answer(f"✅ کامندِ /{cmd} ذخیره شد.",
                     reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
    await msg.answer("ادامهٔ مدیریت 👇", reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
        hx_button("🏠 مدیریت دکمه‌ها", callback_data="adm:homebtns", style=ButtonStyle.DANGER)
    ]]))


