# ─────────────── دکمه‌های دلخواه صفحهٔ اصلی بات‌ساز (hcb:) ───────────────

def _hcb_menu_kb(b: dict) -> InlineKeyboardMarkup:
    btype = b.get("type") or "text"
    has_rule = bool((b.get("rule") or "").strip())
    rows = [
        [hx_button("📝 تغییر نام", callback_data=f"hcb:ren:{b['id']}", style=ButtonStyle.SUCCESS)],
        [hx_button(f"🎯 نوع دکمه ({_HCB_TYPE_LABEL.get(btype, btype)})",
                              callback_data=f"hcb:type:{b['id']}")],
        [hx_button("✏️ متن/پیام دکمه", callback_data=f"hcb:msg:{b['id']}", style=ButtonStyle.PRIMARY)],
    ]
    if btype in ("web_app", "url"):
        rows.append([hx_button("🔗 تغییر لینک", callback_data=f"hcb:url:{b['id']}", style=ButtonStyle.PRIMARY)])
    if btype == "submenu":  # PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_2_V1
        rows.append([hx_button("📁 مدیریت زیرمنو", callback_data=f"adm:homebtns:{b['id']}",
                                          style=ButtonStyle.SUCCESS)])
    if btype == "invite_campaign":
        rows.append([
            hx_button("➖", callback_data=f"hcb:icbtgt:dec:{b['id']}", style=ButtonStyle.DANGER),
            hx_button("🎯 تعداد دعوت لازم", callback_data=f"hcb:icbtgt:noop:{b['id']}", style=ButtonStyle.PRIMARY),
            hx_button("➕", callback_data=f"hcb:icbtgt:inc:{b['id']}", style=ButtonStyle.SUCCESS),
        ])
        # === PATCH_INVITE_CAMPAIGN_DAYS_SETTING_V1 ===
        rows.append([hx_button("🗓 روزهای فعالِ طرح", callback_data="icbdays:menu")])
    rows.append([hx_button(("📜 ویرایش قانون" if has_rule else "📜 تنظیم قانون"),
        callback_data=f"hcb:rule:{b['id']}", style=ButtonStyle.PRIMARY)])
    if has_rule:
        rows.append([hx_button("🗑 حذف قانون", callback_data=f"hcb:ruledel:{b['id']}",
                                          style=ButtonStyle.DANGER)])
    has_cmd = bool((b.get("command") or "").strip())  # PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_2_V1
    rows.append([hx_button((f"⌨️ کامند: /{b.get('command')}" if has_cmd else "⌨️ تنظیمِ کامندِ سریع"),
        callback_data=f"hcb:cmd:{b['id']}")])
    if has_cmd:
        rows.append([hx_button("🗑 حذف کامند", callback_data=f"hcb:cmddel:{b['id']}",
                                          style=ButtonStyle.DANGER)])
    rows.append([hx_button(f"🎨 رنگ ({_HCB_COLOR_LABEL.get(b.get('color') or '', 'پیش‌فرض')})",
        callback_data=f"hcb:color:{b['id']}")])
    has_emoji = bool((b.get("icon_emoji_id") or "").strip())
    rows.append([hx_button(("😎 تغییر ایموجی پرمیوم" if has_emoji else "😎 افزودن ایموجی پرمیوم"),
        callback_data=f"hcb:emoji:{b['id']}", style=ButtonStyle.SUCCESS)])
    if has_emoji:
        rows.append([hx_button("🗑 حذف ایموجی پرمیوم", callback_data=f"hcb:emojidel:{b['id']}",
                                          style=ButtonStyle.DANGER)])
    siblings = [x for x in _HOME_CUSTOM if x.get("parent_id") == b.get("parent_id")]  # PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_2_V1
    sidx = next((i for i, x in enumerate(siblings) if x.get("id") == b["id"]), 0)
    mv = []
    if sidx > 0:
        mv.append(hx_button("⬆️ بالا", callback_data=f"hcb:up:{b['id']}", style=ButtonStyle.PRIMARY))
    if sidx < len(siblings) - 1:
        mv.append(hx_button("⬇️ پایین", callback_data=f"hcb:down:{b['id']}", style=ButtonStyle.PRIMARY))
    if mv:
        rows.append(mv)
    if b.get("enabled", True):
        rows.append([hx_button("⛔️ غیرفعال‌سازی", callback_data=f"hcb:toggle:{b['id']}",
                                          style=ButtonStyle.DANGER)])
    else:
        rows.append([hx_button("✅ فعال‌سازی", callback_data=f"hcb:toggle:{b['id']}",
                                          style=ButtonStyle.SUCCESS)])
    rows.append([hx_button("🗑 حذف دکمه", callback_data=f"hcb:del:{b['id']}",
                                      style=ButtonStyle.DANGER)])
    _back_cb = f"adm:homebtns:{b['parent_id']}" if b.get("parent_id") else "adm:homebtns"  # PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_2_V1
    rows.append([hx_button("⬅️ بازگشت", callback_data=_back_cb,
                                      style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _hcb_menu_text(b: dict) -> str:
    btype = b.get("type") or "text"
    lines = [
        f"⚙️ دکمهٔ دلخواه: <b>{b.get('label') or 'دکمه'}</b>",
        f"نوع: {_HCB_TYPE_LABEL.get(btype, btype)}",
        f"وضعیت: {'🟢 فعال' if b.get('enabled', True) else '🔴 غیرفعال'}",
        f"متن دکمه: {'✏️ دارد' if (b.get('message') or '').strip() else '—'}",
        f"قانون: {'📜 دارد' if (b.get('rule') or '').strip() else '—'}",
        f"کامند: {('/' + b['command']) if (b.get('command') or '').strip() else '—'}",  # PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_2_V1
        f"ایموجی پرمیوم: {'😎 دارد' if (b.get('icon_emoji_id') or '').strip() else '—'}",
    ]
    if btype in ("web_app", "url"):
        lines.append(f"🔗 لینک: {b.get('url') or '⚠️ تنظیم نشده'}")
    if btype == "invite_campaign":
        lines.append(f"🎯 تعداد دعوت لازم برای برنده‌شدن: <b>{await _icb_target()} نفر</b>")
    if btype == "submenu":
        _n_children = sum(1 for x in _HOME_CUSTOM if x.get("parent_id") == b.get("id"))
        lines.append(f"📁 تعدادِ زیردکمه‌ها: <b>{_n_children}</b>")
    return "\n".join(lines) + "\n\nیکی را انتخاب کن:"


async def _hcb_owner_ok(cb: CallbackQuery) -> bool:
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return False
    await ensure_home_loaded()
    return True


async def _hcb_show_menu(cb: CallbackQuery, b: dict):
    text = await _hcb_menu_text(b)
    try:
        await cb.message.edit_text(text, reply_markup=_hcb_menu_kb(b))
    except Exception:
        await cb.message.answer(text, reply_markup=_hcb_menu_kb(b))


@router.callback_query(F.data.startswith("hcb:new"))
async def hcb_new(cb: CallbackQuery, state: FSMContext):
    """PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_2_V1 — «hcb:new» زیردکمهٔ سطحِ بالا می‌سازد، «hcb:new:<parent_id>»
    زیردکمهٔ همان زیرمنو می‌سازد."""
    if not await _hcb_owner_ok(cb):
        return
    parent_id = cb.data[len("hcb:new"):].lstrip(":") or None
    if parent_id and not _hcb_find(parent_id):
        parent_id = None
    await state.set_state(HomeBtnFSM.cust_label)
    await state.update_data(hcb_new_parent=parent_id)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer(
        ("➕ <b>ساخت زیردکمهٔ جدید</b>" if parent_id else "➕ <b>ساخت دکمهٔ جدید صفحهٔ اصلی</b>") +
        "\n\nنام دکمه را بفرست (می‌توانی ایموجی هم بگذاری):",
        reply_markup=await smart_cancel_kb())
    await cb.answer()


@router.message(HomeBtnFSM.cust_label, F.text)
async def hcb_new_label(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    label = (msg.text or "").strip()
    if label in (BTN_CANCEL, "❌ لغو / بازگشت"):
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    if not label:
        await msg.answer("نام نامعتبر است، دوباره بفرست:")
        return
    if _resolve_home_key(label):
        await msg.answer("⛔️ دکمه‌ای با همین نام وجود دارد. نام دیگری بفرست:")
        return
    data = await state.get_data()  # PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_2_V1
    parent_id = data.get("hcb_new_parent")
    import secrets as _sec
    bid = _sec.token_hex(4)
    _HOME_CUSTOM.append({"id": bid, "label": label[:80], "type": "text",
                         "message": "", "url": "", "color": "", "rule": "", "command": "",
                         "parent_id": parent_id, "enabled": True, "icon_emoji_id": ""})
    await _hcb_save()
    await state.clear()
    await msg.answer(f"✅ دکمهٔ «{label[:80]}» ساخته شد.",
                     reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("📝 نمایش متن", callback_data=f"hcb:settype:text:{bid}",
                              style=ButtonStyle.PRIMARY)],
        [hx_button("🌐 مینی‌اپ (Web App)", callback_data=f"hcb:settype:web_app:{bid}",
                              style=ButtonStyle.SUCCESS)],
        [hx_button("🔗 لینک شیشه‌ای", callback_data=f"hcb:settype:url:{bid}", style=ButtonStyle.PRIMARY)],
        [hx_button("📁 زیرمنو (دکمه‌های دیگر داخلش)",
                              callback_data=f"hcb:settype:submenu:{bid}", style=ButtonStyle.PRIMARY)],
        [hx_button("🎁 قرعه‌کشی دعوت دوستان (ربات مادر)",
                              callback_data=f"hcb:settype:invite_campaign:{bid}", style=ButtonStyle.PRIMARY)],
        [hx_button("🧪 درخواست ربات تست",
                              callback_data=f"hcb:settype:trial_request:{bid}", style=ButtonStyle.PRIMARY)],
    ])
    await msg.answer("🎯 حالا نوع دکمه را انتخاب کن:", reply_markup=kb)


