@router.callback_query(F.data.startswith("hcb:settype:"))
async def hcb_set_type(cb: CallbackQuery, state: FSMContext):
    if not await _hcb_owner_ok(cb):
        return
    _, _, btype, bid = cb.data.split(":")
    b = _hcb_find(bid)
    if not b or btype not in ("text", "web_app", "url", "invite_campaign", "submenu", "trial_request"):  # PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_2_V1
        await cb.answer("نامعتبر", show_alert=True)
        return
    if btype == "invite_campaign":
        b["type"] = btype
        await _hcb_save()
        await _hcb_show_menu(cb, b)
        await cb.answer(
            "✅ این دکمه حالا مخصوص «قرعه‌کشی دعوت دوستان» است. رنگ آن خودکار "
            "(دوشنبه/پنج‌شنبه سبز، بقیهٔ روزها قرمز) تنظیم می‌شود.")
        return
    b["type"] = btype
    await _hcb_save()
    if btype in ("web_app", "url"):
        await state.set_state(HomeBtnFSM.cust_url)
        await state.update_data(hcb_id=bid)
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        hint = ("⚠️ لینک باید حتماً با https:// شروع شود."
                if btype == "web_app" else "لینک با https یا tg:// مجاز است.")
        await cb.message.answer(
            f"🔗 آدرس {_HCB_TYPE_LABEL[btype]} را بفرست.\n{hint}",
            reply_markup=await smart_cancel_kb())
        await cb.answer()
        return
    if btype == "text" and not (b.get("message") or "").strip():
        await state.set_state(HomeBtnFSM.cust_msg)
        await state.update_data(hcb_id=bid)
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.message.answer(
            "✏️ متنی که با زدن این دکمه به کاربر نمایش داده می‌شود را بفرست\n"
            "(قالب‌بندی تلگرام حفظ می‌شود):",
            reply_markup=await smart_cancel_kb())
        await cb.answer()
        return
    await _hcb_show_menu(cb, b)
    await cb.answer("تنظیم شد")


# === PATCH_INVITE_CAMPAIGN_DAYS_SETTING_V1 ===
# ترتیبِ نمایشِ روزهای هفته به فارسی (شنبه اول)، با مقدارِ weekday پایتون
# (دوشنبه=۰ ... یکشنبه=۶) که برای مقایسه با datetime.weekday() لازم است.
_PERSIAN_WEEKDAYS = [
    ("شنبه", 5), ("یکشنبه", 6), ("دوشنبه", 0), ("سه‌شنبه", 1),
    ("چهارشنبه", 2), ("پنج‌شنبه", 3), ("جمعه", 4),
]


def _icbdays_kb() -> InlineKeyboardMarkup:
    is_all = INVITE_CAMPAIGN_WEEKDAYS == set(range(7))
    rows = [[hx_button(("✅ " if is_all else "") + "🗓 همهٔ هفته فعال باشه",
        callback_data="icbdays:all")]]
    for name, wd in _PERSIAN_WEEKDAYS:
        mark = "☑️" if wd in INVITE_CAMPAIGN_WEEKDAYS else "⬜"
        rows.append([hx_button(f"{mark} {name}", callback_data=f"icbdays:toggle:{wd}")])
    rows.append([hx_button("⬅️ بازگشت", callback_data="adm:homebtns",
                                      style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def _icbdays_text() -> str:
    if INVITE_CAMPAIGN_WEEKDAYS == set(range(7)):
        cur = "همهٔ روزهای هفته"
    elif not INVITE_CAMPAIGN_WEEKDAYS:
        cur = "⚠️ هیچ روزی انتخاب نشده (طرح هیچ‌وقت باز نمی‌شود)"
    else:
        by_wd = {wd: name for name, wd in _PERSIAN_WEEKDAYS}
        cur = "، ".join(by_wd[wd] for _, wd in _PERSIAN_WEEKDAYS if wd in INVITE_CAMPAIGN_WEEKDAYS)
    return (
        "🗓 <b>روزهای فعالِ طرحِ دعوت از دوستان</b>\n\n"
        "این طرح فقط در روزهایی که اینجا انتخاب کنی «باز» می‌شود (یعنی فقط "
        "همون روزها برنده‌های روزانه اعلام می‌شن). یا «همهٔ هفته» رو بزن، یا "
        "خودت روزهای دلخواه رو تیک بزن (چندتا هم می‌تونی انتخاب کنی).\n\n"
        f"وضعیتِ فعلی: <b>{cur}</b>"
    )


async def _icbdays_save() -> None:
    """ذخیرهٔ مقدارِ فعلیِ INVITE_CAMPAIGN_WEEKDAYS در دیتابیس."""
    if INVITE_CAMPAIGN_WEEKDAYS == set(range(7)):
        await set_pset("icb_active_days", "all")
    else:
        await set_pset("icb_active_days", ",".join(str(x) for x in sorted(INVITE_CAMPAIGN_WEEKDAYS)))


@router.callback_query(F.data == "icbdays:menu")
async def icbdays_menu(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    await ensure_home_loaded()
    try:
        await cb.message.edit_text(_icbdays_text(), reply_markup=_icbdays_kb())
    except Exception:
        await cb.message.answer(_icbdays_text(), reply_markup=_icbdays_kb())
    await cb.answer()


@router.callback_query(F.data == "icbdays:all")
async def icbdays_toggle_all(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    global INVITE_CAMPAIGN_WEEKDAYS
    if INVITE_CAMPAIGN_WEEKDAYS == set(range(7)):
        INVITE_CAMPAIGN_WEEKDAYS = {0, 3}  # برگشت به پیش‌فرض (نه خالی)
    else:
        INVITE_CAMPAIGN_WEEKDAYS = set(range(7))
    await _icbdays_save()
    await cb.message.edit_text(_icbdays_text(), reply_markup=_icbdays_kb())
    await cb.answer("✅ ذخیره شد")


@router.callback_query(F.data.startswith("icbdays:toggle:"))
async def icbdays_toggle_day(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    global INVITE_CAMPAIGN_WEEKDAYS
    wd = int(cb.data.split(":")[2])
    INVITE_CAMPAIGN_WEEKDAYS = set(INVITE_CAMPAIGN_WEEKDAYS)  # کپی، برای جلوگیری از تغییرِ نامعلومِ رفرنسِ مشترک
    if wd in INVITE_CAMPAIGN_WEEKDAYS:
        INVITE_CAMPAIGN_WEEKDAYS.discard(wd)
    else:
        INVITE_CAMPAIGN_WEEKDAYS.add(wd)
    await _icbdays_save()
    await cb.message.edit_text(_icbdays_text(), reply_markup=_icbdays_kb())
    await cb.answer("✅ ذخیره شد")


@router.callback_query(F.data.startswith("hcb:icbtgt:"))
async def hcb_icbtgt(cb: CallbackQuery):
    if not await _hcb_owner_ok(cb):
        return
    parts = cb.data.split(":")
    op = parts[2]
    bid = parts[3] if len(parts) > 3 else ""
    b = _hcb_find(bid)
    if not b:
        await cb.answer("یافت نشد", show_alert=True)
        return
    if op == "noop":
        await cb.answer()
        return
    cur = await _icb_target()
    if op == "inc":
        new_val = cur + 1
    elif op == "dec":
        new_val = max(1, cur - 1)
    else:
        await cb.answer()
        return
    await set_pset("icb_target", str(new_val))
    await _hcb_show_menu(cb, b)
    await cb.answer(f"✅ تعداد دعوت لازم: {new_val} نفر")


