@router.message(HomeBtnFSM.cust_url, F.text)
async def hcb_url_save(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    data = await state.get_data()
    b = _hcb_find(data.get("hcb_id") or "")
    url = (msg.text or "").strip()
    if url in (BTN_CANCEL, "❌ لغو / بازگشت"):
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    if not b:
        await state.clear()
        await msg.answer("دکمه یافت نشد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    ok = (url.startswith("https://") if b.get("type") == "web_app"
          else url.startswith(("https://", "http://", "tg://")))
    if not ok or " " in url or len(url) > 500:
        await msg.answer("❌ لینک نامعتبر است. دوباره بفرست یا «لغو» را بزن:")
        return
    b["url"] = url
    await _hcb_save()
    await state.clear()
    await msg.answer(f"✅ لینک دکمهٔ «{b.get('label')}» ثبت شد.",
                     reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
    await msg.answer("ادامهٔ مدیریت 👇", reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
        hx_button("🏠 مدیریت دکمه‌ها", callback_data="adm:homebtns", style=ButtonStyle.DANGER)]]))


