@router.callback_query(F.data.startswith("hcb:up:") | F.data.startswith("hcb:down:"))
async def hcb_move(cb: CallbackQuery):
    """PATCH_PLATFORM_HOME_SUBMENUS_COMMANDS_2_V1 — جابه‌جایی فقط بینِ خواهر-برادرهایِ همون سطح/زیرمنو (نه کلِ لیستِ درهم)."""
    if not await _hcb_owner_ok(cb):
        return
    _, direction, bid = cb.data.split(":")
    b = _hcb_find(bid)
    if not b:
        await cb.answer("یافت نشد", show_alert=True)
        return
    sib_ids = [x["id"] for x in _HOME_CUSTOM if x.get("parent_id") == b.get("parent_id")]
    sidx = sib_ids.index(bid)
    j = sidx - 1 if direction == "up" else sidx + 1
    if 0 <= j < len(sib_ids):
        other_id = sib_ids[j]
        gi = next(i for i, x in enumerate(_HOME_CUSTOM) if x["id"] == bid)
        gj = next(i for i, x in enumerate(_HOME_CUSTOM) if x["id"] == other_id)
        _HOME_CUSTOM[gi], _HOME_CUSTOM[gj] = _HOME_CUSTOM[gj], _HOME_CUSTOM[gi]
        await _hcb_save()
    await _hcb_show_menu(cb, b)
    await cb.answer("جابه‌جا شد")


