# ---------- شبکهٔ انتخاب چیدمان (۵ ردیف × ۳ ستون) ----------
GRID_ROWS = 5
GRID_COLS = 3
# پلن پایه فقط به این تعداد ردیف اول دسترسی دارد؛ بقیه قفل است
FREE_UNLOCKED_ROWS = 2

GRID_INTRO = (
    "🎨 چیدمان دکمه‌های صفحهٔ اصلی را بساز.\n\n"
    "روی هر خانه بزن تا پس‌زمینه‌اش سبز شود (انتخاب) یا قرمز شود (خالی).\n"
    "تعداد خانه‌های سبزِ هر ردیف = تعداد دکمه‌های همان ردیف.\n"
    "ردیف‌هایی که هیچ خانهٔ سبزی ندارند نادیده گرفته می‌شوند.\n\n"
    "مثال: ردیف ۱ یک خانه سبز ← یک دکمه، ردیف ۲ دو خانه سبز ← دو دکمه.\n\n"
    "🔒 در پلن پایه فقط ۲ ردیف اول فعال است؛ ردیف‌های ۳ تا ۵ با ارتقای پلن باز می‌شوند.\n\n"
    "وقتی تمام شد «✅ تأیید و ادامه» را بزن."
)


def row_locked(plan: str, r: int) -> bool:
    """آیا این ردیف برای پلن داده‌شده قفل است؟ (پلن پایه = ردیف‌های ۳ تا ۵ قفل)"""
    return plan == Plan.FREE.value and r > FREE_UNLOCKED_ROWS


def grid_kb(selected: set[str], plan: str = Plan.FREE.value,
           edit_bot_id: int | None = None) -> InlineKeyboardMarkup:
    """شبکهٔ انتخاب چیدمان؛ پس‌زمینهٔ خانه‌ها با ButtonStyle رنگی می‌شود
    (سبز=انتخاب‌شده، قرمز=خالی، 🔒=قفل برای پلن پایه) — نیازمند aiogram 3.28+.

    === PATCH_GRID_EDIT_BACK_BUTTON_V1 ===
    edit_bot_id: فقط وقتی این چیدمان از داخلِ «ربات‌های من ← ویرایش ربات»
    باز شده (نه موقعِ ساختِ اولیهٔ ربات) پر می‌شود؛ در این حالت زیرِ
    «پاک‌کردن همه» یه دکمهٔ «لغو و برگشت به عقب» هم اضافه می‌شه که به
    همون صفحهٔ «ویرایش ربات» برمی‌گرده، نه کاملاً به خانه.
    """
    rows = []
    for r in range(1, GRID_ROWS + 1):
        locked = row_locked(plan, r)
        row = []
        for c in range(1, GRID_COLS + 1):
            if locked:
                row.append(hx_button("🔒", style=ButtonStyle.DANGER, callback_data="grid:locked"))
            else:
                on = f"{r},{c}" in selected
                row.append(hx_button("✓" if on else "·",
                    style=ButtonStyle.SUCCESS if on else ButtonStyle.DANGER,
                    callback_data=f"grid:{r}:{c}",
                ))
        rows.append(row)
    rows.append([hx_button("✅ تأیید و ادامه", style=ButtonStyle.PRIMARY, callback_data="grid:done")])
    rows.append([hx_button("🗑 پاک‌کردن همه", callback_data="grid:clear")])
    if edit_bot_id is not None:
        rows.append([hx_button("↩️ لغو و برگشت به عقب", style=ButtonStyle.DANGER,
                               callback_data=f"gridcancel:{edit_bot_id}")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


