    tg_id = State()
    # PATCH_ADM_REFCHECK_FIX_V1 — فیکسِ دستیِ دعوتِ گم‌شده: آیدیِ عددیِ کسی
    # که باید زیرمجموعه ثبت می‌شد ولی referrer_id نداشت
    fix_referred_id = State()


