@router.message(F.text.regexp(r"^/start(?:@\w+)?\s+selfsaz_connected$"))
async def selfsaz_deeplink_start(msg: Message):
    from platform_selfsaz import show_selfsaz_panel
    await msg.answer("✅ اتصال حساب موفق بود؛ پنل سلف‌ساز آماده است.")
    await show_selfsaz_panel(msg, msg.from_user.id)

@router.message(CommandStart())
async def start(msg: Message, command: CommandObject, state: FSMContext, bot: Bot):
    if _skip_in_group(msg):  # PATCH_PLATFORM_PRIVATE_ONLY_V3
        return
    await state.clear()
    await ensure_home_loaded()
    await sweep_trials(bot)
    referrer = fa_to_int(command.args) if command.args else None
    if referrer == msg.from_user.id:
        referrer = None
    async with Session() as s:
        await get_user(s, msg.from_user.id, msg.from_user.full_name, referrer, username=msg.from_user.username)
        await s.commit()
        sa = await get_sub_admin(s, msg.from_user.id)
        u_row = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == msg.from_user.id))
    # === PATCH_PLATFORM_PROMOTER_V1 === لینکِ معرفِ فروش: t.me/ربات?start=pr_کد
    # (باگِ قبلی: دو خطِ sa/u_row اشتباهاً داخلِ این if رفته بودند و /start بدونِ آرگومان NameError می‌داد)
    if command.args and command.args.startswith("pr_"):
        try:
            from platform_promoters import attach as _promo_attach, PREFIX as _PP
            _pok, _ptxt = await _promo_attach(msg.from_user.id, command.args[len(_PP):])
            await msg.answer(_ptxt)
        except Exception:
            logger.exception("اتصالِ کدِ معرف ناموفق بود")
    show_admin = sa is not None
    # === PATCH_PLATFORM_ONBOARDING_V1 ===
    # همان الگویِ tenant_start در tenant/__init__.py: قبل از هرچیزِ دیگر
    # (حتی دیپ‌لینک‌ها) چک می‌شود — اگه قوانین اجباری است و هنوز تاییدش
    # نکرده، کاربر فقط قوانین را می‌بیند، نه منویِ اصلی را.
    if u_row is not None and not u_row.rules_accepted:
        if await _pvso_show_rules_gate(msg, bot):
            return
    first_name = msg.from_user.first_name or msg.from_user.full_name or "دوست عزیز"
    # === PATCH_PLATFORM_START_REACTION_V1 ===
    _pstart_react = await get_pset("start_reaction_emoji", "")
    if _pstart_react:
        try:
            await msg.react([ReactionTypeEmoji(emoji=_pstart_react)], is_big=True)
        except Exception:
            logger.exception("ری‌اکشن‌زدن رویِ پیامِ /start ناموفق بود")
    custom = await get_pset("welcome_msg", "")
    if custom:
        text = apply_welcome_placeholders(custom, msg.from_user)
    else:
        text = (
            f"✨ درود <b>{first_name}</b> عزیز! ✨\n\n"
            f"🎉 به ربات <b>بات‌ساز</b> خوش اومدی!\n\n"
            f"🤖 من کمکت می‌کنم رباتت رو <b>خودت</b> بسازی, "
            f"جوری که هر جا نشونش بدی بگن «با چی ساختی؟» بگی: «با <b>بات‌ساز</b>!» 😄😉\n\n"
            f"(⚠️ بات‌ساز در حال آزمایش است؛ پلن‌های خرید فعلاً فعال نیستند و فقط تعداد محدودی "
            f"می‌توانند به‌صورت موقت از پلن‌های رشد و حرفه‌ای برای باگ‌گیری استفاده کنند.)\n\n"
            f"از منوی زیر شروع کن 👇"
        )
    # === PATCH_PLATFORM_START_STICKER_V1 ===
    _platform_start_sticker = (await get_pset("platform_start_sticker", "")).strip()
    if _platform_start_sticker:
        try:
            await msg.answer_sticker(_platform_start_sticker)
        except Exception as e:
            logger.warning("استیکر استارت ربات اصلی ارسال نشد: %s", e)
    # === PATCH_WEBAPP_GROUP_FIX_V1 ===
    # /start@BotName در گروه هم به همین هندلر می‌رسد؛ اگر منو دکمهٔ وب‌اپ
    # داشته باشد تلگرام کلِ پیام را رد می‌کند و کاربر ERR-XXXXXX می‌گیرد.
    _is_private = getattr(msg.chat, "type", "private") == "private"
    typewriter_enabled = (await get_pset("platform_welcome_typewriter_enabled", "0")) == "1"
    if await get_pset("home_menu_mode", "reply") == "inline":
        await _pvso_play_typewriter(msg, text, typewriter_enabled)
        await msg.answer("🏠 منوی اصلی:", reply_markup=home_inline_kb(msg.from_user.id, show_admin))
    elif typewriter_enabled:
        # === PATCH_WELCOME_TYPEWRITER_FIX_V2 ===
        # تلگرام اجازهٔ ادیتِ ReplyKeyboardMarkup را نمی‌دهد (فقط اینلاین)؛
        # به‌جایِ آن یک پیامِ کوتاهِ جداگانه با همان کیبورد فرستاده می‌شود.
        await _pvso_play_typewriter(msg, text, True)
        await msg.answer("🏠 منوی اصلی:", reply_markup=await smart_home_kb(
            msg.from_user.id, show_admin=show_admin, private=_is_private))
    else:
        await msg.answer(text, reply_markup=await smart_home_kb(
            msg.from_user.id, show_admin=show_admin, private=_is_private))
    # PATCH_PLATFORM_HOME_MENU_MODE_V1
    # PATCH_PLATFORM_CHPOST_HOME_BUTTONS_V1
    # دیپ‌لینکِ دکمه‌های صفحهٔ اصلی — وقتی از دکمهٔ اینلاینِ یک پستِ کانال با
    # start=hcb-<key> وارد می‌شود، همون عملِ آن دکمه بلافاصله اجرا می‌شود.
    deep_arg = (command.args or "").strip()
    if deep_arg.startswith("hcb-"):
        raw_key = deep_arg[len("hcb-"):]
        home_key = f"custom:{raw_key[len('custom-'):]}" if raw_key.startswith("custom-") else raw_key
        await _dispatch_home_key(home_key, msg, state, bot)
# === PATCH_ARCHIVED_START_DIRECT_RENEW_V1 ===
    elif deep_arg.startswith("mbup_"):
        bot_id_str = deep_arg[len("mbup_"):]
        if bot_id_str.isdigit():
            # === PATCH_MBUP_DEEPLINK_EDIT_CRASH_FIX_V1 ===
            # my_bot_upgrade در پایانِ کارش cb.message.edit_text(...) صدا
            # می‌زنه. قبلاً اینجا مستقیم پیامِ /start خودِ کاربر (msg) رو
            # به‌عنوانِ cb.message می‌دادیم — ولی ربات فقط می‌تونه پیام‌های
            # خودش رو ویرایش کنه، نه پیامِ کاربر. نتیجه: هر بار کاربر از
            # این دیپ‌لینک وارد می‌شد، edit_text با خطای واقعیِ Telegram
            # (نه «message is not modified») کرش می‌کرد و کاربر «ERR-XXXXXX»
            # می‌دید. حالا اول یه پیامِ موقتِ خودِ ربات فرستاده می‌شه و همون
            # (که قابلِ ویرایشه) به my_bot_upgrade داده می‌شه.
            _mbup_placeholder = await msg.answer("⏳")

            class _FakeCb:
                """شبیه‌سازیِ سبکِ CallbackQuery — برای صدازدنِ مستقیمِ
                my_bot_upgrade (صفحهٔ تمدید/پرداخت) از داخلِ /start،
                بدونِ عبور از صفحهٔ جزئیاتِ ربات."""
                # === PATCH_MBUP_DEEPLINK_FAKECB_OWNER_FIX_V1 ===
                # قبلاً from_user از رویِ خودِ پیامِ «⏳» (که پیامِ رباته، نه
                # کاربر) گرفته می‌شد؛ یعنی cb.from_user.id برابرِ آیدیِ خودِ
                # ربات می‌شد، نه ادمینی که دکمه را زده. نتیجه: چکِ مالکیتِ
                # داخلِ my_bot_upgrade (r.owner_id != cb.from_user.id) همیشه
                # true می‌شد، یه «یافت نشد» بی‌صدا (چون answer() اینجا pass
                # است) برمی‌گشت و پیامِ «⏳» هیچ‌وقت ادیت نمی‌شد — کاربر فقط
                # استارتِ معمولی می‌دید و صفحهٔ تمدید اصلاً ظاهر نمی‌شد. حالا
                # from_user صریحاً از رویِ msg (کاربرِ واقعیِ /start) گرفته
                # می‌شود.
                def __init__(self, message, data, from_user):
                    self.message = message
                    self.data = data
                    self.from_user = from_user

                async def answer(self, *a, **kw):
                    pass
            await my_bot_upgrade(_FakeCb(_mbup_placeholder, f"mbup:{bot_id_str}", msg.from_user))
    # === PATCH_PARTNER_V18 ===
    # ورود به ویزاردِ چیدمانِ صفحهٔ اصلی برایِ رباتی که تازه از یک
    # رباتِ همکار خریده شده. رباتِ همکار لینکِ ?start=bld_<id> می‌دهد.
    elif deep_arg.startswith("bld_"):
        _bid = deep_arg[len("bld_"):]
        if _bid.isdigit():
            await _partner_build_entry(int(_bid), msg, state)
    elif deep_arg.startswith("mb_"):
        bot_id_str = deep_arg[len("mb_"):]
        if bot_id_str.isdigit():
            class _FakeCb:
                """شبیه‌سازیِ سبکِ CallbackQuery از رویِ یک Message، فقط برای
                فراخوانیِ مجددِ هندلرهایی مثل my_bot_detail از داخلِ /start."""
                def __init__(self, message, data):
                    self.message = message
                    self.data = data
                    self.from_user = message.from_user

                async def answer(self, *a, **kw):
                    pass
            await my_bot_detail(_FakeCb(msg, f"mb:{bot_id_str}"))


# === PATCH_PARTNER_V18 ===
async def _partner_build_entry(bot_id: int, msg: Message, state: FSMContext) -> None:
    """ورودیِ ویزاردِ چیدمان برایِ رباتِ خریداری‌شده از همکار.

    همان مسیرِ save_token را بازتولید می‌کند (پاک‌کردنِ state، ست‌کردنِ
    Build.grid، نمایشِ GRID_INTRO) ولی بدونِ ساختِ ربات — چون ربات از
    قبل توسطِ رباتِ همکار ساخته شده است.
    """
    from models import Bot as BotRow, MainButton

    uid = msg.from_user.id
    async with Session() as s:
        row = await s.get(BotRow, bot_id)
        if not row:
            await msg.answer("این ربات پیدا نشد.")
            return
        if row.owner_id != uid:
            await msg.answer("این ربات متعلق به شما نیست.")
            return
        n_btn = await s.scalar(select(func.count(MainButton.id)).where(
            MainButton.bot_id == bot_id)) or 0
        plan, field, uname = row.plan, row.field, row.username

    if n_btn:
        # از قبل چیده شده — به‌جایِ ویزارد، به ویرایشگر بفرست تا
        # چیدمانِ موجود پاک نشود.
        await msg.answer(
            f"ℹ️ ربات @{uname or '—'} از قبل دکمه‌بندی شده است.\n\n"
            "برای ویرایش، از «🗂 ربات‌های من» واردش شو.",
            reply_markup=await smart_home_kb(uid))
        return

    await state.clear()
    await state.update_data(build_bot_id=bot_id, grid_selected=[],
                            grid_plan=plan, grid_field=field)
    await state.set_state(Build.grid)
    await msg.answer(
        f"✅ ربات @{uname or '—'} آمادهٔ چیدمان است!\n\n" + GRID_INTRO,
        reply_markup=grid_kb(set(), plan),
    )


@router.callback_query(F.data == "hm:toggle_mode")
async def hm_toggle_mode(cb: CallbackQuery, state: FSMContext):
    """PATCH_PLATFORM_HOME_MENU_MODE_V1 — تاگلِ نوعِ منویِ صفحهٔ اصلی بینِ کیبورد و اینلاین."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    cur = await get_pset("home_menu_mode", "reply")
    new = "reply" if cur == "inline" else "inline"
    await set_pset("home_menu_mode", new)
    if new == "inline":
        await cb.message.answer(
            "💠 منوی اصلی از این به بعد شیشه‌ای (اینلاین) نمایش داده می‌شود.",
            reply_markup=ReplyKeyboardRemove())
    else:
        await cb.message.answer(
            "⌨️ منوی اصلی از این به بعد با کیبوردِ پایینِ صفحه نمایش داده می‌شود.",
            reply_markup=await smart_home_kb(cb.from_user.id, show_admin=is_admin(cb.from_user.id)))
    await adm_homebtns(cb, state)


# === PATCH_PROFILE_HOME_BUTTON_MODE_FIX_V1 ===
@router.callback_query(F.data == "hm:home_smart")
async def hm_home_smart(cb: CallbackQuery, state: FSMContext):
    await _delete_home_aux_messages(state, cb.message.bot)
    """بازگشت به منویِ اصلی با توجه به مودِ واقعیِ کاربر (کیبورد یا اینلاین) —
    برخلافِ hm:home که همیشه اینلاین نشون می‌ده. برایِ دکمه‌هایی که از
    وسطِ یک پیامِ معمولی (نه خودِ منویِ اینلاینِ خانه) صدا زده می‌شن."""
    await cb.answer()
    await state.clear()
    show_admin = await _home_show_admin(cb.from_user.id)
    try:
        await cb.message.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer("🏠 منوی اصلی:", reply_markup=await smart_home_kb(cb.from_user.id, show_admin))


