@router.callback_query(F.data.startswith("hm:") & ~F.data.in_({"hm:home", "hm:admin", "hm:toggle_mode"}))
async def hm_key_tap(cb: CallbackQuery, bot: Bot, state: FSMContext):
    """PATCH_PLATFORM_HOME_MENU_MODE_V1 — تپِ یکی از دکمه‌های اینلاینِ منوی اصلی؛ از رویِ همون
    _dispatch_home_key که برایِ حالتِ کیبورد هم استفاده می‌شود، پس رفتار
    (پیام‌های ثابت/دلخواه، مینی‌اپ، لینک، قانون، ایموجی/استیکر و...) دقیقاً یکسان است."""
    key = cb.data[len("hm:"):]
    await cb.answer()
    # پیام را با کاربر واقعی (نه بات) بازسازی می‌کنیم تا عملکرد درست اجرا شود
    fake = cb.message.model_copy(update={"from_user": cb.from_user}).as_(bot)
    try:
        await cb.message.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await _dispatch_home_key(key, fake, state, bot)
    if await get_pset("home_menu_mode", "reply") == "inline":
        await fake.answer("👇", reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [hx_button("🏠 بازگشت به خانه", callback_data="hm:home", style=ButtonStyle.DANGER)]]))


# === PATCH_CANCEL_MATCH_V1 ===
def is_cancel_text(text: str | None) -> bool:
    """آیا این متن یعنی «لغو»؟

    تطابقِ دقیق با «❌ لغو» شکننده بود: بعضی کلاینت‌ها دکمه‌هایِ رنگیِ
    ReplyKeyboard را بدونِ ایموجی می‌فرستند (کاربر «لغو» می‌فرستد، نه
    «❌ لغو»). نتیجه: فیلتر رد می‌شد و هندلرِ بعدی متن را به‌عنوانِ ورودیِ
    واقعی می‌گرفت — مثلاً در شارژِ کارت‌به‌کارت که مدام «۴ رقمِ آخر» را
    دوباره می‌پرسید. حالا ایموجی و فاصله‌ها حذف و بعد مقایسه می‌شود.
    """
    if not text:
        return False
    t = text.strip()
    for ch in ("❌", "✖️", "✖", "🚫", "◀️", "⬅️", "🔙"):
        t = t.replace(ch, "")
    t = t.replace("\u200c", " ").strip()
    # «بازگشت»ِ تنها عمداً اینجا نیست: در چند منو برچسبِ واقعیِ ناوبری
    # است و اگر لغو حسابش کنیم، وسطِ کار state کاربر پاک می‌شود.
    return t in {"لغو", "لغو / بازگشت", "لغو/بازگشت", "انصراف",
                 "cancel", "Cancel"}


@router.message(StateFilter(Build.msg_text, Build.webapp_url), F.text.func(is_cancel_text))
async def build_typed_cancel_is_back(msg: Message, state: FSMContext):
    """=== PATCH_BUILD_BACK_STEPS_V1 === نوشتنِ «لغو» وسطِ ساختِ دکمه‌ها کلِ ویزارد را نمی‌پراند؛ فقط یک قدم برمی‌گردد."""
    cur = await state.get_state()
    await _flow_add(state, msg.chat.id, msg.message_id)
    if cur == Build.msg_text.state:
        await _build_show_msg_prompt(msg, state, edit=False)
    else:
        await _build_show_action_question(msg, state, edit=False)


