def _trial_can_manage(uid: int) -> bool:
    return uid == PLATFORM_ADMIN_ID


async def trial_pending_kb() -> InlineKeyboardMarkup:
    """فهرست درخواست‌های در انتظار + دکمه‌های تایید/رد."""
    pend = await plan_trials.list_pending()
    rows = []
    for r in pend:
        title = PLAN_INFO[Plan(r["plan"])]["title"]
        name = (r["name"] or str(r["tg_id"]))[:24]
        rows.append([hx_button(f"👤 {name} • {title}", callback_data=f"trq:info:{r['id']}")])
        rows.append([
            hx_button("✅ تایید", callback_data=f"trq:ap:{r['id']}",
                                 style=ButtonStyle.SUCCESS),
            hx_button("❌ رد", callback_data=f"trq:rj:{r['id']}",
                                 style=ButtonStyle.DANGER),
        ])
    rows.append([hx_button("🎁 اهدای تست به کاربر", callback_data="trq:gift",
                                      style=ButtonStyle.PRIMARY)])
    # === PATCH_TRIAL_AUTO_APPROVE_V1 ===
    _auto_on = (await get_pset("trial_auto_approve", "off")) == "on"
    _auto_days = await get_pset("trial_auto_approve_days", "2")
    rows.append([hx_button(
        (f"🤖 تاییدِ خودکار: ✅ روشن ({_auto_days} روزه)" if _auto_on else "🤖 تاییدِ خودکار: ❌ خاموش"),
        callback_data="trq:autotoggle",
        style=(ButtonStyle.SUCCESS if _auto_on else ButtonStyle.DANGER))])
    if _auto_on:
        rows.append([hx_button("⏱ تغییرِ مدتِ تاییدِ خودکار", callback_data="trq:autodays")])
    rows.append([hx_button("🔄 بازخوانی", callback_data="set:trials")])
    rows.append([hx_button("⬅️ بازگشت به تنظیمات پلن‌ها", callback_data="set:hub_plans",
                                      style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _show_trial_list(target: Message):
    pend = await plan_trials.list_pending()
    if not pend:
        text = "🎁 <b>درخواست‌های تست پلن</b>\n\nهیچ درخواست در انتظاری وجود ندارد."
    else:
        lines = ["🎁 <b>درخواست‌های تست پلن (در انتظار بررسی)</b>\n"]
        for r in pend:
            title = PLAN_INFO[Plan(r["plan"])]["title"]
            note = f" — {r['note']}" if r["note"] else ""
            lines.append(f"• {_html.escape(r['name'] or '')} (<code>{r['tg_id']}</code>) — {title}{note}")
        text = "\n".join(lines)
    try:
        await target.edit_text(text, reply_markup=await trial_pending_kb())
    except Exception:
        await target.answer(text, reply_markup=await trial_pending_kb())


