@router.message(TrialAdminFSM.gift_user, F.text)
async def adm_trial_gift_user(msg: Message, state: FSMContext):
    raw = (msg.text or "").strip()
    tg_id = fa_to_int(raw)
    name = ""
    if not tg_id:
        uname = raw.lstrip("@").strip()
        if not uname:
            await msg.answer("شناسه نامعتبر. آیدی عددی یا یوزرنیم بفرست.")
            return
        async with Session() as s:
            u = await s.scalar(select(PlatformUser).where(
                func.lower(PlatformUser.username) == uname.lower()))
        if not u:
            await msg.answer(
                "کاربری با این یوزرنیم تو ربات مادر پیدا نشد.\n"
                "(فقط کاربرانی که قبلاً ربات مادر رو استارت زدن قابل جستجو هستن — "
                "یا آیدی عددیش رو بفرست.)")
            return
        tg_id = u.telegram_id
        name = u.full_name or ""
    await state.update_data(gift_tg_id=tg_id, gift_name=name)
    b = InlineKeyboardBuilder()
    b.button(text=f"🚀 {PLAN_INFO[Plan.GROWTH]['title']}", callback_data="trqg:plan:" + Plan.GROWTH.value)
    b.button(text=f"👑 {PLAN_INFO[Plan.PRO]['title']}", callback_data="trqg:plan:" + Plan.PRO.value)
    b.adjust(1)
    await msg.answer(
        f"👤 گیرنده: <code>{tg_id}</code>\n\nکدوم پلن رو تست بدیم؟",
        reply_markup=b.as_markup())


