@router.message(TrialAdminFSM.gift_days, F.text)
async def adm_trial_gift_days(msg: Message, state: FSMContext, bot: Bot):
    days = fa_to_int(msg.text or "")
    if not days or days <= 0 or days > 3650:
        await msg.answer("یک عدد معتبر (تعداد روز) بفرست؛ مثلاً 7.")
        return
    data = await state.get_data()
    tg_id = data.get("gift_tg_id")
    plan = data.get("gift_plan")
    name = data.get("gift_name") or ""
    await state.clear()
    if not tg_id or not plan:
        await msg.answer("نشست منقضی شد؛ دوباره از «🎁 اهدای تست به کاربر» شروع کن.",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return
    status, res = await plan_trials.grant_direct(int(tg_id), name, plan, days)
    if status == "exists_active":
        await msg.answer(
            f"⚠️ این کاربر همین الان یه تستِ فعال داره "
            f"(پلن «{PLAN_INFO[Plan(res['plan'])]['title']}» تا {to_jalali(res['expires_at'])}).\n"
            "اول اون رو لغو کن یا صبر کن منقضی بشه.",
            reply_markup=await smart_home_kb(msg.from_user.id))
        return
    if status != "ok" or not res:
        await msg.answer("❌ اهدای تست انجام نشد (پلن نامعتبر).",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return
    title = PLAN_INFO[Plan(res["plan"])]["title"]
    await msg.answer(
        f"✅ تست پلن «{title}» برای کاربر <code>{res['tg_id']}</code> به مدت "
        f"<b>{res['days']} روز</b> فعال شد.\nسررسید: {to_jalali(res['expires_at'])}",
        reply_markup=await smart_home_kb(msg.from_user.id))
    try:
        await bot.send_message(
            res["tg_id"],
            f"🎁 مدیر برای شما تست پلن «{title}» فعال کرد!\n"
            f"⏳ مدت اعتبار: <b>{res['days']} روز</b> (تا {to_jalali(res['expires_at'])}).\n\n"
            f"{_trial_start_deadline_line()}"
            f"همین الان به «🤖 ساخت ربات» برو؛ این پلن به‌صورت رایگان برات فعاله و می‌تونی باهاش ربات بسازی "
            f"(حتی اگه به سقفِ رایگانِ ساختِ ربات رسیده باشی). "
            f"بعد از ساختِ ربات، اگه تا پایانِ مهلت تمدید نکرده باشی، این ربات به‌صورت خودکار غیرفعال/بایگانی می‌شه.",
        )
    except Exception as e:
        print("trial gift notify error:", e)


# === PATCH_TRIAL_AUTO_APPROVE_V1 ===
async def _notify_trial_approved(bot: Bot, res: dict) -> None:
    """پیامِ «تستت تایید شد» به کاربر — جدا شد تا هم مسیرِ تاییدِ دستیِ
    ادمین و هم مسیرِ تاییدِ خودکار (پچِ جدید) از یک متنِ واحد استفاده کنن."""
    title = PLAN_INFO[Plan(res["plan"])]["title"]
    try:
        await bot.send_message(
            res["tg_id"],
            f"🎉 درخواست تست پلن «{title}» شما تایید شد!\n"
            f"⏳ مدت اعتبار: <b>{res['days']} روز</b> (تا {to_jalali(res['expires_at'])}).\n\n"
            f"{_trial_start_deadline_line()}"
            f"همین الان به «🤖 ساخت ربات» برو؛ این پلن به‌صورت رایگان برات فعاله و می‌تونی باهاش ربات بسازی "
            f"(حتی اگه به سقفِ رایگانِ ساختِ ربات رسیده باشی). "
            f"بعد از ساختِ ربات، اگه تا پایانِ {res['days']} روز تمدید نکرده باشی، این ربات به‌صورت "
            f"خودکار غیرفعال/بایگانی می‌شه.",
        )
    except Exception as e:
        print("trial approve notify error:", e)


@router.message(TrialAdminFSM.days)
async def adm_trial_set_days(msg: Message, state: FSMContext, bot: Bot):
    days = fa_to_int(msg.text or "")
    if not days or days <= 0 or days > 3650:
        await msg.answer("یک عدد معتبر (تعداد روز) بفرست؛ مثلاً 7.")
        return
    data = await state.get_data()
    renew_req_id = data.get("trial_renew_id")
    await state.clear()
    # === PATCH_TRIAL_RENEW_REQUEST_V1 ===
    if renew_req_id:
        res = await plan_trials.extend_trial(int(renew_req_id), days)
        if not res:
            await msg.answer("این تست دیگر معتبر/فعال نیست.",
                             reply_markup=await smart_home_kb(msg.from_user.id))
            return
        title = PLAN_INFO[Plan(res["plan"])]["title"]
        await msg.answer(
            f"✅ تستِ ربات (پلن «{title}») برای کاربر <code>{res['tg_id']}</code> به مدتِ "
            f"<b>{days} روز</b> تمدید شد.\nسررسیدِ جدید: {to_jalali(res['expires_at'])}",
            reply_markup=await smart_home_kb(msg.from_user.id),
        )
        try:
            await bot.send_message(
                res["tg_id"],
                f"🎉 درخواستِ تمدیدِ ربات تست شما تایید شد!\n"
                f"⏳ سررسیدِ جدید: {to_jalali(res['expires_at'])}.",
            )
        except Exception as e:
            print("trial renew notify error:", e)
        return
    req_id = data.get("trial_approve_id")
    res = await plan_trials.approve_request(int(req_id), days) if req_id else None
    if not res:
        await msg.answer("این درخواست قبلاً رسیدگی شده یا یافت نشد.",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return
    title = PLAN_INFO[Plan(res["plan"])]["title"]
    await msg.answer(
        f"✅ تست پلن «{title}» برای کاربر <code>{res['tg_id']}</code> به مدت "
        f"<b>{res['days']} روز</b> تایید شد.\nسررسید: {to_jalali(res['expires_at'])}",
        reply_markup=await smart_home_kb(msg.from_user.id),
    )
    await _notify_trial_approved(bot, res)

