@router.callback_query(F.data == "trq:autotoggle")
async def adm_trial_auto_toggle(cb: CallbackQuery, bot: Bot):
    if not _trial_can_manage(cb.from_user.id):
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    cur = await get_pset("trial_auto_approve", "off")
    new = "off" if cur == "on" else "on"
    await set_pset("trial_auto_approve", new)
    if new == "on":
        days = await get_pset("trial_auto_approve_days", "2")
        await cb.answer(f"✅ تاییدِ خودکار روشن شد ({days} روزه)")
    else:
        await cb.answer("❌ تاییدِ خودکار خاموش شد")
    await _show_trial_list(cb.message)


