@router.callback_query(F.data.startswith("trialrenew:req:"))
async def trial_renew_request(cb: CallbackQuery, bot: Bot):
    """کاربر از صفحهٔ ربات، درخواستِ تمدیدِ تست می‌کند؛ فقط برای اطلاعِ ادمین است."""
    # === PATCH_TRIAL_NO_RENEW_V1 ===
    # سیاستِ جدید: تست تمدید نمی‌شود. این هندلر فقط برایِ دکمه‌هایِ
    # قدیمی‌ای مانده که هنوز در چتِ کاربران هستند — به‌جایِ درخواستِ
    # بی‌جواب، پاسخِ روشن می‌دهد.
    await cb.answer(
        "ربات تست تمدید نمی‌شود. برای ادامه، یکی از پلن‌ها را از همین "
        "صفحه تهیه کن.", show_alert=True)
    return

    req_id = int(cb.data.split(":")[2])
    req = await plan_trials.get_request(req_id)
    if not req or req["status"] != "used":
        await cb.answer("این تست دیگر فعال نیست.", show_alert=True)
        return
    await cb.answer("✅ درخواستِ تمدید برای مدیر ارسال شد.")
    try:
        await bot.send_message(
            PLATFORM_ADMIN_ID,
            f"🔄 <b>درخواستِ تمدیدِ ربات تست</b>\n\n"
            f"کاربر: <code>{cb.from_user.id}</code>\n"
            f"نام: {_html.escape(cb.from_user.full_name or '')}\n"
            f"پلن: {PLAN_INFO[Plan(req['plan'])]['title']}\n"
            f"سررسیدِ فعلی: {to_jalali(req['expires_at']) if req['expires_at'] else '—'}",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                hx_button("✅ تایید تمدید", callback_data=f"trialrenew:appr:{req_id}",
                                     style=ButtonStyle.SUCCESS),
                hx_button("❌ رد", callback_data=f"trialrenew:rej:{req_id}",
                                     style=ButtonStyle.DANGER),
            ]]),
        )
    except Exception as e:
        print("trial renew request notify error:", e)


