@router.message(TrialAdminFSM.revoke_note)
async def adm_trial_revoke_note(msg: Message, state: FSMContext, bot: Bot):
    data = await state.get_data()
    req_id = data.get("trial_revoke_id")
    target_uid = data.get("trial_revoke_uid")
    await state.clear()
    raw = (msg.text or "").strip()
    note = "" if raw in ("0", "/skip") else raw[:400]
    res = await plan_trials.revoke_request(int(req_id), note) if req_id else None
    if not res:
        await msg.answer("این تست قبلاً لغو/منقضی شده یا یافت نشد.",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return
    title = PLAN_INFO[Plan(res["plan"])]["title"]
    await msg.answer(
        f"✅ تستِ پلن «{title}» برای کاربر <code>{res['tg_id']}</code> لغو شد.",
        reply_markup=await smart_home_kb(msg.from_user.id))
    try:
        await bot.send_message(
            res["tg_id"],
            f"⚠️ دسترسیِ تستِ پلن «{title}» شما توسط مدیر لغو شد.\n"
            "برای ادامهٔ استفاده از امکانات این پلن می‌تونی اون رو خریداری کنی.",
        )
    except Exception as e:
        print("trial revoke notify error:", e)
    if target_uid:
        result = await _build_user_profile(int(target_uid))
        if result:
            text, kb = result
            await msg.answer(text, reply_markup=kb)


# ======================= ساخت ربات =======================
async def choose_field(msg: Message, state: FSMContext, bot: Bot):
    await sweep_trials(bot)
    global_cap_on = (await get_pset("global_bot_cap_enabled", "off")) == "on"
    if global_cap_on:
        global_cap = int(await get_pset("global_bot_cap_max", "500") or "500")
        async with Session() as s:
            total_bots = await s.scalar(select(func.count(BotRow.id))) or 0
        if total_bots >= global_cap:
            await msg.answer(
                "🚫 <b>ساخت ربات موقتاً بسته شده است</b>\n\n"
                "برای حفظ سرعت و پایداری، ساخت ربات بسته می‌باشد.\n"
                "به محض فعال شدن، در کانال و ربات اطلاع‌رسانی خواهد شد.",
                reply_markup=await smart_home_kb(msg.from_user.id))
            return
    async with Session() as s:
        cnt = await s.scalar(
            select(func.count()).select_from(BotRow).where(BotRow.owner_id == msg.from_user.id)
        )
        limit_on = (await get_pset("bot_limit_enabled", "on")) != "off"
        free_limit = int(await get_pset("bot_free_limit", "3") or "3")
        u = await get_user(s, msg.from_user.id, msg.from_user.full_name, username=msg.from_user.username)
        extra_slots = u.extra_bot_slots or 0
        await s.commit()
    max_allowed = free_limit + extra_slots
    # === PATCH_TRIAL_BOT_CAP_BYPASS_V1 ===
    # کاربری که یک تستِ تاییدشده و مصرف‌نشده دارد باید بتواند ربات تست را بسازد
    # حتی اگر قبلاً به سقفِ رایگانِ ساختِ ربات رسیده باشد؛ این ربات موقتی است و
    # با پایانِ مهلتِ تست (در صورتِ عدمِ تمدید) خودکار بایگانی/لغو می‌شود.
    has_active_trial = False
    for _plan_v in plan_trials.TRIALABLE_PLANS:
        if await plan_trials.active_trial_for(msg.from_user.id, _plan_v):
            has_active_trial = True
            break
    # === PATCH_FREE_CAP_ONLY_FOR_FREE_PLAN_V1 ===
    # قبلاً رسیدن به سقف، کلِ مسیرِ ساختِ ربات را می‌بست — حتی برایِ کسی که
    # می‌خواست پلنِ رشد/حرفه‌ای *بخرد*. این هم برایِ کاربر گیج‌کننده بود و هم
    # جلویِ فروش را می‌گرفت. حالا سقف فقط رویِ رباتِ **رایگان** اعمال می‌شود؛
    # کاربر واردِ مسیر می‌شود و در صفحهٔ انتخابِ پلن، گزینهٔ رایگان با توضیحِ
    # سقف و پیشنهادِ خریدِ اسلات نشان داده می‌شود، ولی پلن‌هایِ پولی باز است.
    at_free_cap = bool(limit_on and cnt >= max_allowed and not has_active_trial)
    await state.update_data(is_first=(cnt == 0), at_free_cap=at_free_cap,
                            cap_cnt=cnt, cap_free_limit=free_limit,
                            cap_extra_slots=extra_slots)
    b = InlineKeyboardBuilder()
    # === PATCH_CREATE_FLOW_COLORS_V1 ===
    for key, title in FIELDS.items():
        if key in ACTIVE_FIELDS:
            b.button(text=title, callback_data=f"field:{key}", style=ButtonStyle.SUCCESS)
        else:
            b.button(text=f"🔒 {title} (به‌زودی)", callback_data="field_locked", style=ButtonStyle.DANGER)
    # === PATCH_CREATE_FLOW_BACK_BUTTONS_V1 ===
    # این اولین صفحهٔ کلِ فلویِ ساختِ ربات بود و هیچ دکمهٔ برگشت/انصرافی
    # نداشت — کاربری که پشیمون می‌شد یا اشتباه زده بود، راهی جز /start یا
    # ارسالِ یه پیامِ نامربوط برای خروج نداشت.
    # === PATCH_PARTNER_V3 ===
    # اگر کاربر درخواستِ همکاری‌اش تایید شده و هنوز رباتِ همکارش را
    # نساخته، این گزینه این‌جا — کنارِ بقیهٔ گزینه‌هایِ ساخت — می‌آید.
    try:
        from platform_partner import partner_eligibility
        if await partner_eligibility(msg.from_user.id):
            b.button(text="🤝 ساخت ربات همکار",
                     callback_data="pnr:buildstart",
                     style=ButtonStyle.SUCCESS)
    except Exception:
        logger.exception("بررسیِ واجدِشرایط‌بودنِ همکاری ناموفق بود")
    b.button(text="⬅️ انصراف", callback_data="freerules:cancel", style=ButtonStyle.DANGER)
    b.adjust(1)
    await state.set_state(Create.field)
    await msg.answer(
        "ربات در چه زمینه‌ای باشه؟\n\n"
        "✅ فعلاً «فروش VPN / کانفیگ»، «فروشگاه دیجیتال / دوره آموزشی»، "
        "«خدمات مجازی تلگرام» و «ربات تبلیغاتی» فعال‌اند؛ "
        "بقیهٔ موارد به‌زودی اضافه می‌شوند.",
        reply_markup=b.as_markup())


