@router.callback_query(F.data.startswith("botslot:buy:"))
async def botslot_buy_start(cb: CallbackQuery, bot: Bot):
    qty = int(cb.data.split(":")[2])
    stars_per_bot = int(await get_pset("bot_stars_per_extra", "30") or "30")
    stars = stars_per_bot * qty
    await cb.answer()
    try:
        await bot.send_invoice(
            chat_id=cb.message.chat.id,
            title="خرید اسلاتِ ربات اضافه",
            description=f"خرید {qty} اسلاتِ ساختِ ربات اضافه (هرکدام {stars_per_bot} استارز)",
            payload=f"extra_bot_slot:{cb.from_user.id}:{qty}",
            provider_token="",  # برای پرداخت با استارز تلگرام، provider_token خالی است
            currency="XTR",
            prices=[LabeledPrice(label=f"{qty} اسلاتِ ربات اضافه", amount=stars)],
        )
    except Exception as e:
        await cb.message.answer(f"❌ ارسال فاکتور پرداخت با خطا مواجه شد:\n{e}")


