@router.callback_query(Create.plan, F.data.startswith("newmonths:"))
async def choose_new_months(cb: CallbackQuery, state: FSMContext):
    """انتخابِ مدت (۱ یا ۲ ماه) هنگامِ ساختِ ربات جدید با پلنِ پولی.
    قیمت و سررسید بر اساسِ تعدادِ ماه تنظیم می‌شوند."""
    months = 2 if cb.data.split(":")[1] == "2" else 1
    data = await state.get_data()
    base_price = int(data.get("price", 0))
    total_price = base_price * months
    # بازبینیِ موجودی برای مبلغِ نهایی
    async with Session() as s:
        u = await get_user(s, cb.from_user.id, cb.from_user.full_name, username=cb.from_user.username)
        bal = float(u.balance)
    if bal < total_price:
        await _record_failed_purchase(cb.from_user.id, data.get("plan", ""), total_price)
        await _insufficient_balance(cb, total_price, f"(برایِ {months} ماه)")
        return
    await state.update_data(price=total_price, sub_months=months)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await state.set_state(Create.token)
    await cb.message.answer(
        f"✅ پلنِ {months} ماهه انتخاب شد ({rial(total_price)}).\n\n"
        "توکن ربات خودت رو از @BotFather بگیر و همینجا بفرست.\n"
        "(چیزی شبیه <code>123456:ABC-...</code>)",
        reply_markup=await smart_cancel_kb())
    await cb.answer()


@router.callback_query(Create.plan, F.data.startswith("newplan:"))
async def choose_plan(cb: CallbackQuery, state: FSMContext):
    plan = cb.data.split(":", 1)[1]
    # === PATCH_PLAN_SALE_LOCK_V1 ===
    if await plan_sale_closed(plan):
        await cb.answer(PLAN_SALE_LOCK_MSG, show_alert=True)
        return
    price = 0
    ptc_new_note = ""     # PATCH_PTC_EVERYWHERE_V1
    promo_id, promo_pct = None, 0     # PATCH_PLATFORM_PROMOTER_V1
    trial_req_id = None
    trial_expires = None
    if plan == Plan.FREE.value:
        pass  # پلن پایه همیشه رایگان است
    elif not plan_enabled(plan):
        await cb.answer("این پلن فعلاً غیرفعال است.", show_alert=True)
        return
    elif not plans_paid_enabled():
        # حالت تست: پلن‌های پولی هم رایگان‌اند (بدون کسر از کیف پول)
        price = 0
    else:
        # اگر کاربر تستِ تاییدشدهٔ فعال برای این پلن دارد، رایگان و بدون نیاز به موجودی
        trial = await plan_trials.active_trial_for(cb.from_user.id, plan)
        if trial:
            trial_req_id = trial["id"]
            trial_expires = trial["expires_at"]
            price = 0
        else:
            async with Session() as s:
                u = await get_user(s, cb.from_user.id, cb.from_user.full_name, username=cb.from_user.username)
                refs = await s.scalar(
                    select(func.count()).select_from(PlatformUser)
                    .where(PlatformUser.referrer_id == cb.from_user.id)
                )
                await s.commit()
                bal = float(u.balance)
            disc = referral_discount(refs or 0)
            # === PATCH_PLATFORM_PROMOTER_V1 === تخفیفِ خریدِ اولِ معرف (بزرگ‌ترِ دو تخفیف)
            from platform_promoters import promo_for as _promo_for, pct_with_promo as _pwp
            _pinfo = await _promo_for(cb.from_user.id)
            disc, _promo_hit = _pwp(disc, _pinfo)
            promo_id = _pinfo.promoter_id if _promo_hit else None
            promo_pct = _pinfo.percent if _promo_hit else 0
            # === PATCH_PLATFORM_USER_DISCOUNT_V1 === تخفیفِ دائمیِ اختصاصی؛ بزرگ‌ترین اعمال می‌شود
            from platform_user_discounts import percent_for as _ud_pct
            _udp = await _ud_pct(cb.from_user.id, plan)
            if _udp > disc:
                disc, promo_id, promo_pct = _udp, None, 0
            # === PATCH_PTC_EVERYWHERE_V1 === تخفیفِ «نفراتِ برتر» در ساختِ رباتِ جدید هم اعمال شود (قبلاً فقط در تمدید/ارتقا بود)
            ptc_mode, ptc_amt = await ptc_discount_for(cb.from_user.id)
            if ptc_mode == "percent" and ptc_amt > disc:
                disc, promo_id, promo_pct = ptc_amt, None, 0
                ptc_new_note = f"🏆 تخفیفِ نفراتِ برتر ({ptc_amt}٪) روی قیمت‌ها اعمال شده است."
            elif ptc_mode == "flat" and ptc_amt > 0:
                ptc_new_note = f"🏆 تخفیفِ نفراتِ برتر ({rial(ptc_amt)} در هر ماه) روی قیمت‌ها اعمال شده است."
            base_after_plan_disc, _, _ = plan_price_final(plan)
            price = base_after_plan_disc * (100 - disc) // 100
            if ptc_mode == "flat" and ptc_amt > 0:
                price = max(0, price - ptc_amt)
            if bal < price:
                await _record_failed_purchase(cb.from_user.id, plan, price)
                await cb.answer(
                    f"موجودی کافی نیست. لازم: {rial(price)} (تخفیف {disc}٪). اول کیف پول را شارژ کن.",
                    show_alert=True)
                return
    await state.update_data(promo_id=promo_id, promo_pct=promo_pct)
    await state.update_data(plan=plan, price=price,
                            trial_req_id=trial_req_id,
                            trial_expires=(trial_expires.isoformat() if trial_expires else None))
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    if plan == Plan.FREE.value:
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [hx_button("✅ متوجه شدم، ادامه", callback_data="freerules:ok",
                                  style=ButtonStyle.SUCCESS)],
            [hx_button("⬅️ برگشت به انتخاب پلن", callback_data="cbk:plan", style=ButtonStyle.PRIMARY)],
            [hx_button("⬅️ انصراف", callback_data="freerules:cancel",
                                  style=ButtonStyle.DANGER)],
        ])
        await cb.message.answer(
            # PATCH_REMOVE_BIO_LOCK_V1 — بندِ «بیو قابلِ تغییر نیست» حذف شد
            "⚠️ <b>قوانین ربات رایگان</b>\n"
            "• ممکن است در ربات‌های رایگان تبلیغات نمایش داده شود.",
            reply_markup=kb,
        )
        await cb.answer()
        return
    # پلنِ پولیِ واقعی (نه تست/رایگان) → انتخابِ مدت (۱ یا ۲ ماه)
    if price and not trial_req_id:
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [hx_button(f"🗓 ۱ ماهه — {rial(price)}",
                                  callback_data="newmonths:1", style=ButtonStyle.SUCCESS)],
            [hx_button(f"🗓🗓 ۲ ماهه — {rial(price * 2)}",
                                  callback_data="newmonths:2", style=ButtonStyle.PRIMARY)],
            [hx_button("⬅️ برگشت به انتخاب پلن", callback_data="cbk:plan", style=ButtonStyle.PRIMARY)],
            [hx_button("⬅️ انصراف", callback_data="freerules:cancel",
                                  style=ButtonStyle.DANGER)],
        ])
        await cb.message.answer(
            "🗓 مدت پلن را انتخاب کن:"
            + (f"\n\n🎁 تخفیفِ خریدِ اول ({promo_pct}٪) روی قیمت‌ها اعمال شده است." if promo_id else "")
            + (f"\n\n{ptc_new_note}" if ptc_new_note else "")
            + f"\n\n{PURCHASE_TERMS}",       # قوانینِ خرید (اول تست، بعد خرید؛ عودت ندارد) قبلاً فقط در تمدید/ارتقا بود، نه خریدِ ربات تازه
            reply_markup=kb, parse_mode="HTML")
        await cb.answer()
        return
    await state.set_state(Create.token)
    await cb.message.answer(
        "توکن ربات خودت رو از @BotFather بگیر و همینجا بفرست.\n"
        "(چیزی شبیه <code>123456:ABC-...</code>)",
        reply_markup=await smart_cancel_kb(),
    )
    await cb.answer()


@router.callback_query(F.data == "cbk:field")
async def create_back_to_field(cb: CallbackQuery, state: FSMContext, bot: Bot):
    """=== PATCH_BUILD_BACK_STEPS_V1 === از صفحهٔ پلن برگرد به انتخابِ نوعِ ربات."""
    try:
        await cb.message.delete()
    except Exception:
        logger.debug("حذفِ پیامِ پلن ممکن نشد (بی‌اهمیت)")
    fake = cb.message.model_copy(update={"from_user": cb.from_user}).as_(bot)
    await choose_field(fake, state, bot)
    await cb.answer()


@router.callback_query(F.data == "cbk:plan")
async def create_back_to_plan(cb: CallbackQuery, state: FSMContext, bot: Bot):
    """=== PATCH_BUILD_BACK_STEPS_V1 === از «قوانینِ رایگان»/«انتخابِ مدت» برگرد به انتخابِ پلن."""
    data = await state.get_data()
    field = data.get("field")
    if not field:
        await cb.answer("این مرحله منقضی شده؛ دوباره از «ساخت ربات» شروع کن.", show_alert=True)
        return
    await state.set_state(Create.field)
    cb2 = cb.model_copy(update={"data": f"field:{field}"}).as_(bot)
    await show_pitch(cb2, state)


@router.callback_query(F.data == "freerules:ok")
async def free_plan_rules_ok(cb: CallbackQuery, state: FSMContext):
    await state.set_state(Create.token)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer(
        "توکن ربات خودت رو از @BotFather بگیر و همینجا بفرست.\n"
        "(چیزی شبیه <code>123456:ABC-...</code>)",
        reply_markup=await smart_cancel_kb(),
    )
    await cb.answer()


@router.callback_query(F.data == "freerules:cancel")
async def free_plan_rules_cancel(cb: CallbackQuery, state: FSMContext):
    await state.clear()
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer("منصرف شدی. هر وقت خواستی دوباره از منوی اصلی شروع کن.",
                            reply_markup=await smart_home_kb(cb.from_user.id))
    await cb.answer()


@router.message(Create.token)
async def save_token(msg: Message, state: FSMContext):
    token = (msg.text or "").strip()
    if ":" not in token or len(token) < 30:
        await msg.answer("توکن معتبر نیست. دوباره بفرست.")
        return
    try:
        async with _temp_bot(token) as tmp:
            me = await tmp.get_me()
    except Exception:
        await msg.answer("نتونستم با این توکن وصل بشم. درست کپی شده؟")
        return

    data = await state.get_data()
    # === PATCH_SAVE_TOKEN_MISSING_PLAN_GUARD_V1 ===
    # اگه کاربر روی یه دکمهٔ شیشه‌ایِ قدیمی (مثلاً «✅ متوجه شدم، ادامه»)
    # از یه پیامِ کهنه بزنه — بعد از اینکه مسیر ساختِ ربات از اول ری‌ست شده
    # (با /start یا گذشتِ زمان و خالی‌شدنِ FSM) — دیتای state دیگه شامل
    # «plan» نیست. قبلاً اینجا با data["plan"] کرش می‌کرد (KeyError) دقیقاً
    # بعد از اینکه توکنِ ربات هم چک شده بود — یعنی کاربر توکنشو فرستاده
    # ولی بی‌هیچ پیامِ روشنی با ERR-XXXXXX مواجه می‌شد. الان به‌جاش ازش
    # می‌خوایم دوباره از «🤖 ساخت ربات» شروع کنه.
    if "plan" not in data:
        await state.clear()
        await msg.answer(
            "⚠️ این مرحله منقضی شده (احتمالاً یه دکمهٔ قدیمی رو زدی). "
            "لطفاً دوباره از «🤖 ساخت ربات» شروع کن.",
            reply_markup=await smart_home_kb(msg.from_user.id))
        return
    trial_req_id = data.get("trial_req_id")
    trial_expires = data.get("trial_expires")
    trial_expires_dt = None
    if trial_expires:
        try:
            trial_expires_dt = datetime.datetime.fromisoformat(trial_expires)
        except Exception:
            trial_expires_dt = None
    uid = msg.from_user.id  # PATCH_TOKEN_RECLAIM_V1
    async with Session() as s:
        from bot_utils import reclaim_token_if_archived
        _freed, _dup = await reclaim_token_if_archived(s, token, uid)  # PATCH_TOKEN_RECLAIM_V1
        if _dup:
            await msg.answer(
                "این ربات همین حالا فعال و ثبت‌شده است.\n\n"
                "اگر مالِ خودته، اول از «🗂 ربات‌های من» حذفش کن و بعد "
                "دوباره امتحان کن.")
            await state.clear()
            return
        # === PATCH_DUP_USERNAME_TOKEN_RENEW_V1 ===
        # حفرهٔ قبلی: گاردِ بالا فقط *توکن* را چک می‌کرد. اگر مالک در BotFather
        # توکن را revoke و یک توکنِ تازه می‌گرفت و ربات را دوباره «اضافه»
        # می‌کرد، توکن جدید بود → گارد رد می‌شد → یک ردیفِ دومِ کاملاً جدا با
        # همان یوزرنیم ساخته می‌شد. نتیجه: کاربران/تنظیمات/سفارش‌ها روی ردیفِ
        # قدیمی جا می‌ماند و وب‌هوک روی ردیفِ جدید کار می‌کرد (کیسِ @Next_v2Bot).
        # حالا به‌جای ردیفِ جدید، توکنِ همان ردیف به‌روزرسانی می‌شود.
        _uname = (me.username or "").strip()
        # === PATCH_DUP_ARCHIVED_TWIN_V1 ===
        # حفرهٔ باقی‌مانده: شرطِ archived_at.is_(None) باعث می‌شد رباتِ
        # *بایگانی‌شده* اصلاً پیدا نشود. سناریویِ واقعی: ربات بایگانی
        # می‌شود → کاربر شارژ می‌کند → به‌جایِ تمدید، ربات را از اول
        # «اضافه» می‌کند → ردیفِ دومِ خالی ساخته می‌شود و همهٔ کاربران و
        # دکمه‌ها صفر به‌نظر می‌رسند (کیسِ @VPNrocketPNR_BOT).
        # حالا ردیفِ بایگانی‌شده هم پیدا و از بایگانی خارج می‌شود.
        # سنگ‌قبرهایِ ادغامِ قبلی کنار گذاشته می‌شوند (یوزرنیمشان هم عوض
        # شده، ولی محضِ احتیاط صریح رد می‌شوند).
        _twin = await s.scalar(select(BotRow).where(
            func.lower(BotRow.username) == _uname.lower(),
            func.coalesce(BotRow.archive_reason, "") != "merged_duplicate",
        ).order_by(BotRow.archived_at.is_(None).desc(),
                   BotRow.id.asc())) if _uname else None
        if _twin is not None:
            if _twin.owner_id != uid:
                await s.commit()
                await msg.answer(
                    "🚫 رباتی با این یوزرنیم قبلاً برای کاربرِ دیگری ثبت شده است.\n"
                    "اگر فکر می‌کنی اشتباهی رخ داده، به پشتیبانی پیام بده.",
                    reply_markup=await smart_home_kb(uid))
                await state.clear()
                return
            _old_token = _twin.token
            _twin.token = token
            _twin.status = "active" if _twin.status not in ("admin_paused", "locked") else _twin.status
            # === PATCH_DUP_ARCHIVED_TWIN_V1 ===
            _was_arch = _twin.archived_at is not None
            if _was_arch and _twin.status not in ("admin_paused", "locked"):
                # خروج از بایگانی + یک دورهٔ اعتبارِ تازه، وگرنه ربات
                # بلافاصله دوباره بایگانی می‌شود و کاربر گیج می‌ماند.
                _twin.archived_at = None
                _twin.archive_reason = None
                _twin.last_expiry_notice = None
                if not (_twin.plan_expires_at
                        and _twin.plan_expires_at > datetime.datetime.now()):
                    _twin.plan_expires_at = plan_expiry_from_now(_twin.plan)
            _twin_id = _twin.id
            await s.commit()
            import tenant_status_bus
            await tenant_status_bus.publish_tenant_invalidate(_old_token)
            try:
                async with _temp_bot(_old_token) as _ob:
                    await _ob.delete_webhook()
            except Exception:
                logger.exception("حذفِ وب‌هوکِ توکنِ قدیمی ناموفق بود (طبیعی است اگر revoke شده باشد)")
            _hook_ok = await set_tenant_webhook(token)
            await state.clear()
            await msg.answer(
                f"🔁 این ربات (@{_uname}) از قبل رویِ حسابِ خودت ثبت شده بود؛ "
                "به‌جای ساختِ رباتِ تکراری، <b>توکنش به‌روزرسانی شد</b>.\n\n"
                "✅ همهٔ کاربران، تنظیمات و سفارش‌هایِ قبلی سرِ جایشان هستند."
                + ("\n♻️ ربات از بایگانی خارج و فعال شد." if _was_arch else "")
                + ("" if _hook_ok else
                   "\n\n⚠️ اتصال برقرار نشد — از «🗂 ربات‌های من» «🔄 اتصال مجدد» را بزن."),
                reply_markup=await smart_home_kb(uid))
            logger.info("PATCH_DUP_USERNAME_TOKEN_RENEW_V1: توکنِ رباتِ id=%s تعویض شد", _twin_id)
            return
        global_cap_on = (await get_pset("global_bot_cap_enabled", "off")) == "on"
        if global_cap_on:
            global_cap = int(await get_pset("global_bot_cap_max", "500") or "500")
            total_bots = await s.scalar(select(func.count(BotRow.id))) or 0
            if total_bots >= global_cap:
                await s.commit()
                await msg.answer(
                    "🚫 <b>ساخت ربات موقتاً بسته شده است</b>\n\n"
                    "برای حفظ سرعت و پایداری، ساخت ربات بسته می‌باشد.\n"
                    "به محض فعال شدن، در کانال و ربات اطلاع‌رسانی خواهد شد.",
                    reply_markup=await smart_home_kb(msg.from_user.id))
                await state.clear()
                return
        cnt = await s.scalar(
            select(func.count()).select_from(BotRow).where(BotRow.owner_id == msg.from_user.id)
        )
        limit_on = (await get_pset("bot_limit_enabled", "on")) != "off"
        free_limit = int(await get_pset("bot_free_limit", "3") or "3")
        u_check = await get_user(s, msg.from_user.id, msg.from_user.full_name, username=msg.from_user.username)
        max_allowed = free_limit + (u_check.extra_bot_slots or 0)
        # === PATCH_FREE_CAP_ONLY_FOR_FREE_PLAN_V1 ===
        # سقف فقط رویِ رباتِ رایگان است؛ پلن‌هایِ پولی مشمولش نیستند.
        _is_free_plan = data.get("plan") == Plan.FREE.value
        if limit_on and _is_free_plan and cnt >= max_allowed and not trial_req_id:
            await s.commit()
            await msg.answer(
                "❌ به سقفِ ساختِ رباتِ <b>رایگان</b> رسیدی.\n\n"
                "یا از «🤖 ساخت ربات» اسلاتِ اضافه با ⭐ استارز بخر، یا این ربات را "
                "با پلنِ <b>رشد/حرفه‌ای</b> بساز — پلن‌هایِ پولی مشمولِ این سقف نیستند.",
                reply_markup=await smart_home_kb(msg.from_user.id))
            await state.clear()
            return
# === PATCH_FREE_NO_EXPIRY_PANEL_LOCK_NOTIFY_V1 ===
        # سررسید ربات: برای تستِ تاییدشده برابر پایان مهلت تست، برای پلنِ
        # رایگان اصلاً سررسید ندارد (None → همیشه قابل‌استفاده)، در غیر این
        # صورت (پلن پولیِ واقعی) بر اساسِ تعدادِ ماهِ انتخاب‌شده (۱ یا ۲ ماه).
        _sub_months = int(data.get("sub_months", 1) or 1)
        if trial_expires_dt:
            expiry = trial_expires_dt
        elif data["plan"] == Plan.FREE.value:
            expiry = None
        else:
            expiry = datetime.datetime.now() + datetime.timedelta(days=30 * _sub_months)
        price = data.get("price", 0)
        needs_charge = data["plan"] != Plan.FREE.value and price and not trial_req_id
        if needs_charge:
            # بازبینیِ موجودی همین‌جا (نه فقط موقعِ انتخابِ پلن)، چون ممکن است بینِ
            # انتخابِ پلن و فرستادنِ توکن، موجودیِ کاربر جای دیگری خرج شده باشد.
            u_pay = await get_user(s, msg.from_user.id, msg.from_user.full_name, username=msg.from_user.username)
            if float(u_pay.balance) < price:
                await s.commit()
                await msg.answer(
                    f"❌ موجودی کیف پول کافی نیست (لازم: {rial(price)}).\n"
                    "اول کیف پول را شارژ کن، بعد دوباره از «🤖 ساخت ربات» شروع کن.",
                    reply_markup=await smart_home_kb(msg.from_user.id))
                await state.clear()
                return
        # === PATCH_PLAN_SALE_LOCK_V1 ===
        if plan_sale_locked(data["plan"]):
            await s.commit()
            await msg.answer(PLAN_SALE_LOCK_MSG,
                             reply_markup=await smart_home_kb(msg.from_user.id))
            await state.clear()
            return
        cap = plan_cap(data["plan"])
        if cap > 0:
            built = await s.scalar(
                select(func.count()).select_from(BotRow)
                .where(BotRow.plan == data["plan"], BotRow.archived_at.is_(None))
            ) or 0
            if built >= cap:
                await s.commit()
                await msg.answer(
                    "🚫 فروش این پلن همین الان به سقف رسید و بسته شد. "
                    "لطفاً پلن دیگری را امتحان کن یا از «🤖 ساخت ربات» دوباره شروع کن.",
                    reply_markup=await smart_home_kb(msg.from_user.id))
                await state.clear()
                return
        row = BotRow(owner_id=msg.from_user.id, token=token, username=me.username,
                     field=data["field"], plan=data["plan"], status="active",
                     plan_expires_at=expiry)
        row.sub_months = int(data.get("sub_months", 1) or 1)
        s.add(row)
        await s.flush()
        s.add(Setting(bot_id=row.id, key="card_number", value=""))
        s.add(Setting(bot_id=row.id, key="volume_options", value="10,30,50,100"))
        s.add(Setting(bot_id=row.id, key="day_options", value="30,60,90"))
        s.add(Setting(bot_id=row.id, key="count_options", value="1"))
        if needs_charge:
            u = await get_user(s, msg.from_user.id, msg.from_user.full_name, for_update=True, username=msg.from_user.username)
            u.balance = float(u.balance) - price
            s.add(PlanOrder(user_telegram_id=msg.from_user.id, target_bot_id=row.id,
                            plan=data["plan"], amount=price))
            s.add(PlatformTxn(user_telegram_id=msg.from_user.id, amount=-price, kind="purchase",
                              note=f"ساخت ربات با پلن {data['plan']}"))
            # === PATCH_PLATFORM_PROMOTER_V1 === مصرفِ تخفیفِ خریدِ اول
            _promo_used = None
            if data.get("promo_id"):
                from platform_promoters import PromoInfo as _PI, finalize as _pfin
                _pi = _PI(int(data["promo_id"]), "", int(data.get("promo_pct") or 0))
                _pd = await _pfin(s, msg.from_user.id, _pi, int(price))
                if _pd:
                    _promo_used = (_pi, int(price), _pd)
        await s.commit()
        bot_id = row.id
    if needs_charge and _promo_used:
        try:
            from platform_promoters import notify_admin as _pnotify
            _pr_i, _pr_paid, _pr_disc = _promo_used
            async with Session() as _ps:
                from models import PlatformPromoter as _PP2
                _pr_row = await _ps.get(_PP2, _pr_i.promoter_id)
            _pr_i.name = _pr_row.name if _pr_row else str(_pr_i.promoter_id)
            await _pnotify(None, msg.from_user.id, _pr_i, _pr_paid, _pr_disc,
                           f"ساخت ربات @{me.username} — {data['plan']}")
        except Exception:
            logger.exception("اطلاعِ مصرفِ کدِ معرف ناموفق بود")

    # === PATCH_FREE_NO_EXPIRY_PANEL_LOCK_NOTIFY_V1: اطلاع به ادمین پلتفرم ===
    if needs_charge and not trial_req_id:
        try:
            _buyer_name = msg.from_user.full_name or msg.from_user.username or str(msg.from_user.id)
            _months_txt = f"{data.get('sub_months', 1) or 1} ماهه"
            # === PATCH_PLATFORM_BOT_NAME_FIX_V1 === «platform_bot» تویِ همین فایل هیچ‌جا import نشده بود
            from main_platform import platform_bot
            await platform_bot.send_message(
                PLATFORM_ADMIN_ID,
                f"🆕 <b>ساختِ رباتِ پولی</b>\n\n"
                f"👤 خریدار: {_buyer_name} (<code>{msg.from_user.id}</code>)\n"
                f"🤖 ربات: @{me.username}\n"
                f"💼 پلن: {PLAN_INFO[Plan(data['plan'])]['title']} — {_months_txt}\n"
                f"💰 مبلغ: {rial(price)}\n"
                f"💳 روشِ پرداخت: کسر از کیف‌پولِ بات‌ساز (شارژِ قبلی)",
            )
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (اطلاع‌رسانیِ خریدِ پلن به ادمین)")

    # مصرف تست (اتصال آن به همین ربات) تا دیگر قابل استفادهٔ مجدد نباشد
    if trial_req_id:
        try:
            await plan_trials.consume_trial(trial_req_id, bot_id)
        except Exception as e:
            print("consume_trial error:", e)

    # webhook و brand bio را موازی اجرا کن تا کاربر کمتر منتظر بماند
    results = await asyncio.gather(
        set_tenant_webhook(token),
        apply_brand_bio(token, data["plan"]),
        return_exceptions=True,
    )
    webhook_ok = results[0] if not isinstance(results[0], Exception) else False

    if trial_req_id:
        plan_note = (f"پلن: {PLAN_INFO[Plan(data['plan'])]['title']} — "
                     f"🎁 <b>تست رایگان تا {to_jalali(trial_expires_dt)}</b>\n"
                     f"⏳ بعد از این تاریخ ربات به‌صورت خودکار به پلن پایه برمی‌گردد و "
                     f"فقط امکانات پایه فعال می‌ماند.")
    elif data["plan"] == Plan.FREE.value:
        plan_note = "پلن: پایه (رایگان) — <b>بدون سررسید</b>، تا هر وقت بخوای می‌تونی استفاده کنی."
    else:
        plan_note = f"پلن: {PLAN_INFO[Plan(data['plan'])]['title']}"
    hook_note = "" if webhook_ok else (
        "\n\n⚠️ <b>اتصال ربات برقرار نشد!</b>\n"
        "برو «🗂 ربات‌های من» → روی ربات بزن → «🔄 فعال‌سازی/اتصال مجدد» را بزن.\n"
        "تا این کار را نکنی، ربات به پیام‌ها پاسخ نمی‌دهد.")
    await state.clear()
    await state.update_data(build_bot_id=bot_id, grid_selected=[], grid_plan=data["plan"],
                            grid_field=data["field"])
    await state.set_state(Build.grid)
    await msg.answer(
        f"✅ ربات @{me.username} ساخته شد!\n{plan_note}{hook_note}\n\n" + GRID_INTRO,
        reply_markup=grid_kb(set(), data["plan"]),
    )


# ======================= ویزارد ساخت صفحهٔ اصلی ربات =======================
def glass_naming_kb(buttons: list[dict]) -> InlineKeyboardMarkup:
    """پیش‌نمایش شیشه‌ای دکمه‌ها با همان چیدمان واقعی؛ روی هر دکمه می‌شود زد و اسمش را گذاشت."""
    rows_map: dict[int, list[dict]] = {}
    for b in buttons:
        rows_map.setdefault(b["row"], []).append(b)
    kb_rows = []
    for r in sorted(rows_map):
        row_btns = []
        for b in sorted(rows_map[r], key=lambda x: x["col"]):
            if b.get("label"):
                text, style = f"✅ {b['label']}", ButtonStyle.SUCCESS
            else:
                text, style = f"➕ نام‌گذاری (ردیف {b['row']}-{b['col']})", ButtonStyle.DANGER
            row_btns.append(hx_button(text, style=style, callback_data=f"bntap:{b['row']}:{b['col']}"))
        kb_rows.append(row_btns)
    all_named = all(b.get("label") for b in buttons)
    kb_rows.append([
        hx_button("⬅️ بازگشت", style=ButtonStyle.DANGER, callback_data="bnaming:back"),
        hx_button("✅ تایید و ادامه", style=(ButtonStyle.SUCCESS if all_named else ButtonStyle.PRIMARY),
                              callback_data="bnaming:confirm"),
    ])
    return InlineKeyboardMarkup(inline_keyboard=kb_rows)


async def start_naming(message: Message, state: FSMContext):
    data = await state.get_data()
    buttons = data["buttons"]
    sent = await message.answer(
        "📱 این چیدمان واقعی دکمه‌های رباتته.\n\n"
        "روی هر دکمه بزن و اسمی که می‌خوای روش باشه رو بفرست؛ دکمه‌های آماده با ✅ مشخص می‌شن.\n"
        "روی دکمه‌های نام‌گذاری‌شده هم می‌تونی دوباره بزنی تا اسمش رو عوض کنی.",
        reply_markup=glass_naming_kb(buttons),
    )
    await state.update_data(
        preview_chat_id=sent.chat.id, preview_msg_id=sent.message_id, awaiting=None,
    )


def make_3d_preview(buttons: list[dict]) -> str:
    """پیش‌نمایش سه‌بعدی چیدمان دکمه‌ها — شبیه کیبورد واقعی تلگرام."""
    rows_map: dict[int, list[str]] = {}
    for b in buttons:
        rows_map.setdefault(b["row"], []).append(b["label"] or "دکمه")
    
    lines = []
    total_rows = len(rows_map)
    for i, r in enumerate(sorted(rows_map)):
        btns = rows_map[r]
        # محاسبه عرض هر دکمه
        max_len = max(len(lbl) for lbl in btns)
        btn_width = max(max_len + 2, 8)
        
        # خط بالایی دکمه (سایه سه‌بعدی)
        top = "  ".join("╔" + "═" * btn_width + "╗" for _ in btns)
        lines.append(top)
        
        # متن دکمه
        mid_parts = []
        for lbl in btns:
            pad = btn_width - len(lbl)
            left = pad // 2
            right = pad - left
            mid_parts.append("║" + " " * left + lbl + " " * right + "║")
        lines.append("  ".join(mid_parts))
        
        # خط پایینی (سایه = حس سه‌بعدی)
        shadow_top = "  ".join("╚" + "═" * btn_width + "╝" for _ in btns)
        shadow_bot = "  ".join(" " + "▀" * btn_width + " " for _ in btns)
        lines.append(shadow_top)
        lines.append(shadow_bot)
        
        if i < total_rows - 1:
            lines.append("")
    
    return "\n".join(lines)


_COLOR_STYLE = {"danger": ButtonStyle.DANGER, "success": ButtonStyle.SUCCESS, "primary": ButtonStyle.PRIMARY}
_COLOR_EMOJI = {"danger": "🔴", "success": "🟢", "primary": "🔵"}
_COLOR_CYCLE = ["danger", "success", "primary"]


def color_kb(btn_id: int) -> InlineKeyboardMarkup:
    """کیبورد سه‌گزینه‌ای رنگ دکمه (قرمز / سبز / آبی) — برای ویرایش تک‌دکمه‌ای در «ربات‌های من»."""
    return InlineKeyboardMarkup(inline_keyboard=[[
        hx_button("🔴 قرمز", callback_data=f"bcolor:{btn_id}:danger",
                             style=ButtonStyle.DANGER),
        hx_button("🟢 سبز",  callback_data=f"bcolor:{btn_id}:success",
                             style=ButtonStyle.SUCCESS),
        hx_button("🔵 آبی",  callback_data=f"bcolor:{btn_id}:primary",
                             style=ButtonStyle.PRIMARY),
    ]])


def glass_color_kb(assign: list[dict]) -> InlineKeyboardMarkup:
    """پیش‌نمایش شیشه‌ای دکمه‌ها با همان چیدمان واقعی؛ روی هر دکمه می‌شود زد تا رنگش عوض شود."""
    rows_map: dict[int, list[dict]] = {}
    for b in assign:
        rows_map.setdefault(b["row"], []).append(b)
    kb_rows = []
    for r in sorted(rows_map):
        row_btns = []
        for b in sorted(rows_map[r], key=lambda x: x["col"]):
            color = b.get("color")
            if color in _COLOR_STYLE:
                text = f"{_COLOR_EMOJI[color]} {b['label']}"
                style = _COLOR_STYLE[color]
            else:
                text, style = f"🎨 {b['label']}", ButtonStyle.DANGER
            row_btns.append(hx_button(text, style=style, callback_data=f"bctap:{b['id']}"))
        kb_rows.append(row_btns)
    all_colored = all(b.get("color") in _COLOR_STYLE for b in assign)
    kb_rows.append([
        hx_button("⬅️ بازگشت", style=ButtonStyle.DANGER, callback_data="bcolor:back"),
        hx_button("✅ تایید و ادامه", style=(ButtonStyle.SUCCESS if all_colored else ButtonStyle.PRIMARY),
                              callback_data="bcolor:confirm"),
    ])
    return InlineKeyboardMarkup(inline_keyboard=kb_rows)


async def start_color_stage(message: Message, state: FSMContext):
    data = await state.get_data()
    assign = data["assign"]
    sent = await message.answer(
        "📱 این چیدمان واقعی دکمه‌های رباتته.\n\n"
        "روی هر دکمه بزن تا رنگش عوض بشه (🔴 قرمز ← 🟢 سبز ← 🔵 آبی ← ...)؛ "
        "هر چند بار که بخوای می‌تونی روی یک دکمه بزنی تا رنگ دلخواه رو پیدا کنی.",
        reply_markup=glass_color_kb(assign),
    )
    await state.update_data(color_preview_chat_id=sent.chat.id, color_preview_msg_id=sent.message_id)


async def finish_layout(msg: Message, state: FSMContext):
    data = await state.get_data()
    bot_id = data["build_bot_id"]
    buttons = data["buttons"]
    plan = data.get("grid_plan", Plan.FREE.value)

    async with Session() as s:
        old = (await s.scalars(select(MainButton).where(MainButton.bot_id == bot_id))).all()
        for o in old:
            await s.delete(o)
        for b in buttons:
            s.add(MainButton(bot_id=bot_id, row=b["row"], col=b["col"], label=b["label"]))
        await s.flush()
        saved = (await s.scalars(
            select(MainButton).where(MainButton.bot_id == bot_id)
            .order_by(MainButton.row, MainButton.col)
        )).all()
        assign = [{"id": m.id, "label": m.label, "row": m.row, "col": m.col} for m in saved]
        await s.commit()

    # === PATCH_PARTNER_V4 ===
    # partner هم مثلِ پلن‌هایِ پولی مرحلهٔ رنگِ شیشه‌ای را می‌گیرد؛
    # آن مرحله خودش پیش‌نمایشِ واقعی است و پیش‌نمایشِ متنیِ سه‌بعدی
    # برایش نه لازم است نه دقیق.
    is_paid = plan in (Plan.GROWTH.value, Plan.PRO.value, Plan.PARTNER.value)
    if is_paid and assign:
        # شروع مرحله انتخاب رنگ برای دکمه‌های پلن رشد/حرفه‌ای — با همون ساختار مرحله تعیین نام
        # توجه: اینجا پیام پیش‌نمایش متنی ارسال نمی‌شود، چون مرحلهٔ رنگ خودش پیام چیدمان شیشه‌ای واقعی را نشان می‌دهد
        for b in assign:
            b["color"] = None
        await state.set_state(Build.btn_color)
        await state.update_data(assign=assign)
        await start_color_stage(msg, state)
    else:
        preview_3d = make_3d_preview(buttons)
        await msg.answer(
            "✅ چیدمان صفحهٔ اصلی ساخته شد!\n\n"
            "🖼 پیش‌نمایش دکمه‌ها:\n\n"
            f"<pre>{preview_3d}</pre>",
        )
        await state.set_state(Build.action)
        await state.update_data(assign=assign)
        await start_action_stage(msg, state)


@router.callback_query(Build.btn_color, F.data.startswith("bctap:"))
async def build_color_tap(cb: CallbackQuery, state: FSMContext):
    """با هر بار زدن روی دکمهٔ شیشه‌ای، رنگش می‌چرخد: قرمز ← سبز ← آبی ← قرمز ..."""
    btn_id = int(cb.data.split(":")[1])
    data = await state.get_data()
    assign = data["assign"]
    for b in assign:
        if b["id"] == btn_id:
            cur = b.get("color")
            nxt = _COLOR_CYCLE[(_COLOR_CYCLE.index(cur) + 1) % len(_COLOR_CYCLE)] if cur in _COLOR_CYCLE else _COLOR_CYCLE[0]
            b["color"] = nxt
            break
    await state.update_data(assign=assign)
    try:
        await cb.message.edit_reply_markup(reply_markup=glass_color_kb(assign))
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer()


@router.callback_query(Build.btn_color, F.data == "bcolor:back")
async def build_color_back(cb: CallbackQuery, state: FSMContext):
    """بازگشت از مرحلهٔ رنگ‌بندی به مرحلهٔ نام‌گذاری."""
    await state.set_state(Build.naming)
