@router.callback_query(Build.action, F.data.startswith("act:"))
async def build_action(cb: CallbackQuery, state: FSMContext):
    act = cb.data.split(":")[1]
    data = await state.get_data()
    lst = data["assign"]
    btn_id = data["cur_btn_id"]
    btn = next((b for b in lst if b["id"] == btn_id), None)
    label = btn["label"] if btn else ""
    action_val = None if act == "skip" else act
    async with Session() as s:
        mb = await s.get(MainButton, btn_id)
        if mb:
            mb.action = action_val
            await s.commit()
    await state.update_data(cur_btn_id=btn_id)
    if act == "web_app":
        await state.set_state(Build.webapp_url)
        await cb.message.edit_text(
            f"🌐 دکمهٔ «{label}» یک <b>مینی‌اپ</b> است.\n\n"
            "آدرس صفحه‌ای که می‌خواهی با زدن این دکمه به‌صورت وب‌اپ داخل تلگرام باز شود را بفرست.\n"
            "⚠️ لینک باید حتماً با <code>https://</code> شروع شود.",
            reply_markup=_build_back_kb("abk:act", "⬅️ برگشت به انتخاب عملکرد"))
        await cb.answer()
        return
    if act == "skip":
        # دکمهٔ متن آزاد: مستقیم سراغ گرفتن متن می‌رویم
        await cb.message.edit_text(
            f"📝 دکمهٔ «{label}» یک دکمهٔ متن آزاد است.\n"
            f"می‌خوای همین حالا متن/پیامی که با زدن این دکمه نشان داده شود را بذاری؟",
            reply_markup=msg_prompt_kb(),
        )
        await cb.answer()
        return
    extra_note = ""
    if act == "buy_config":
        extra_note = ("\n\n💡 قیمت و بازهٔ حجم/روز این دکمه بعداً از پنل مدیریت ربات → "
                      "«مدیریت کانفیگ» تنظیم می‌شود.")
    await cb.message.edit_text(
        f"اقدام «{ACTION_TITLE.get(action_val)}» برای دکمهٔ «{label}» ثبت شد.{extra_note}\n"
        f"می‌خوای روی این دکمه پیام یا قوانینی بذاری؟",
        reply_markup=msg_prompt_kb(),
    )
    await cb.answer()


# === PATCH_BUILD_BACK_STEPS_V1 ===
# گزارش: وسطِ مرحلهٔ «عملکردِ دکمه‌ها» (انتخابِ عملکرد ← قوانین/پیام) دکمهٔ برگشت نبود و
# «لغو» کلِ ویزارد را می‌پراند. حالا هر صفحه یک قدم به عقب برمی‌گردد:
#   متنِ پیام ← «پیام بذارم؟» ← انتخابِ عملکرد ← پیش‌نمایشِ دکمه‌ها ← (رنگ/نام‌گذاری).
def _build_back_kb(cb_data: str, label: str) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(inline_keyboard=[[hx_button(label, callback_data=cb_data, style=ButtonStyle.DANGER)]])


_BUILD_SUB_STATES = (Build.action, Build.webapp_url, Build.msg_text)


async def _flow_add(state: FSMContext, chat_id: int, mid: int) -> None:
    fm = (await state.get_data()).get("action_flow_msgs", [])
    fm.append((chat_id, mid))
    await state.update_data(action_flow_msgs=fm)


async def _build_show_action_question(message: Message, state: FSMContext, edit: bool) -> None:
    data = await state.get_data()
    btn = next((b for b in data.get("assign", []) if b["id"] == data.get("cur_btn_id")), None)
    if not btn:
        return
    text = f"⚙️ دکمهٔ «{btn['label']}»: وقتی کاربر این دکمه را بزند چه اتفاقی بیفتد؟"
    kb = action_kb(data.get("grid_field", "vpn_sales"), back_cb="abk:q")
    await state.set_state(Build.action)
    if edit:
        try:
            await message.edit_text(text, reply_markup=kb)
            return
        except Exception:
            logger.debug("ویرایشِ پیامِ انتخابِ عملکرد ممکن نشد؛ پیامِ تازه")
    sent = await message.answer(text, reply_markup=kb)
    await _flow_add(state, sent.chat.id, sent.message_id)


async def _build_show_msg_prompt(message: Message, state: FSMContext, edit: bool) -> None:
    text = "می‌خوای روی این دکمه پیام یا قوانینی بذاری؟"
    await state.set_state(Build.action)
    if edit:
        try:
            await message.edit_text(text, reply_markup=msg_prompt_kb())
            return
        except Exception:
            logger.debug("ویرایشِ پیامِ «پیام بذارم؟» ممکن نشد؛ پیامِ تازه")
    sent = await message.answer(text, reply_markup=msg_prompt_kb())
    await _flow_add(state, sent.chat.id, sent.message_id)


@router.callback_query(StateFilter(*_BUILD_SUB_STATES), F.data == "abk:act")
async def build_back_to_action(cb: CallbackQuery, state: FSMContext):
    """برگشت به «وقتی کاربر این دکمه را زد چه اتفاقی بیفتد؟»"""
    await _build_show_action_question(cb.message, state, edit=True)
    await cb.answer()


@router.callback_query(StateFilter(*_BUILD_SUB_STATES), F.data == "abk:mp")
async def build_back_to_msg_prompt(cb: CallbackQuery, state: FSMContext):
    """برگشت از «متنِ پیام را بفرست» به «می‌خوای پیام بذاری؟»"""
    await _build_show_msg_prompt(cb.message, state, edit=True)
    await cb.answer()


@router.callback_query(StateFilter(*_BUILD_SUB_STATES), F.data == "abk:q")
async def build_back_to_preview(cb: CallbackQuery, state: FSMContext):
    """برگشت از انتخابِ عملکرد به پیش‌نمایشِ دکمه‌ها (همان دکمه بدونِ تغییر می‌ماند)."""
    data = await state.get_data()
    btn_id = data.get("cur_btn_id")
    btn = next((b for b in data.get("assign", []) if b["id"] == btn_id), None)
    if btn and not btn.get("action_set"):
        async with Session() as s:
            mb = await s.get(MainButton, btn_id)
            if mb:
                mb.action = None
                mb.message = None
                await s.commit()
    await state.set_state(Build.action)
    try:
        await cb.message.delete()
    except Exception:
        logger.debug("حذفِ پیامِ انتخابِ عملکرد ممکن نشد (بی‌اهمیت)")
    await state.update_data(action_flow_msgs=[])
    await cb.answer()


@router.callback_query(Build.action, F.data == "bact:back")
async def build_action_stage_back(cb: CallbackQuery, state: FSMContext):
    """برگشت از پیش‌نمایشِ عملکردها به مرحلهٔ قبل (رنگ در پلن‌هایِ پولی، وگرنه نام‌گذاری)."""
    data = await state.get_data()
    for chat_id, mid in data.get("action_flow_msgs", []):
        try:
            await cb.message.bot.delete_message(chat_id=chat_id, message_id=mid)
        except Exception:
            logger.debug("حذفِ پیامِ میانی ممکن نشد (بی‌اهمیت)")
    await state.update_data(action_flow_msgs=[])
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.debug("حذفِ دکمه‌ها ممکن نشد (بی‌اهمیت)")
    await cb.answer()
    plan = data.get("grid_plan", Plan.FREE.value)
    if plan in (Plan.GROWTH.value, Plan.PRO.value, Plan.PARTNER.value):
        await state.set_state(Build.btn_color)
        await start_color_stage(cb.message, state)
    else:
        if not data.get("buttons"):
            await state.update_data(buttons=[{"row": b["row"], "col": b["col"], "label": b["label"]}
                                             for b in data.get("assign", [])])
        await state.set_state(Build.naming)
        await start_naming(cb.message, state)


