@router.message(Build.webapp_url, F.text)
async def build_webapp_url(msg: Message, state: FSMContext):
    """دریافت و ذخیرهٔ لینک مینی‌اپ برای دکمهٔ در حال ساخت."""
    data = await state.get_data()
    btn_id = data["cur_btn_id"]
    url = (msg.text or "").strip()
    if not url.startswith("https://") or " " in url or len(url) > 500:
        await msg.answer("❌ لینک نامعتبر است. آدرس باید با https:// شروع شود و بدون فاصله باشد.\n"
                         "دوباره بفرست:")
        return
    async with Session() as s:
        mb = await s.get(MainButton, btn_id)
        if mb:
            cfg = {}
            if mb.config:
                try:
                    cfg = json.loads(mb.config) or {}
                except Exception:
                    cfg = {}
            cfg["webapp_url"] = url
            mb.config = json.dumps(cfg, ensure_ascii=False)
            await s.commit()
    await state.set_state(Build.action)
    flow_msgs = data.get("action_flow_msgs", [])
    flow_msgs.append((msg.chat.id, msg.message_id))
    q = await msg.answer(
        f"✅ لینک مینی‌اپ ثبت شد:\n{url}\n\n"
        "می‌خوای روی این دکمه پیام یا قوانینی بذاری؟",
        reply_markup=msg_prompt_kb(),
    )
    flow_msgs.append((q.chat.id, q.message_id))
    await state.update_data(action_flow_msgs=flow_msgs)


