@router.callback_query(Build.grid, F.data.startswith("grid:"))
async def build_grid(cb: CallbackQuery, state: FSMContext):
    parts = cb.data.split(":")
    data = await state.get_data()
    selected = set(data.get("grid_selected", []))
    plan = data.get("grid_plan", Plan.FREE.value)
    # === PATCH_GRID_EDIT_BACK_BUTTON_V1 ===
    # اگه این چیدمان از داخلِ «ویرایش ربات» باز شده، باید دکمهٔ برگشت رو
    # موقعِ بازسازیِ کیبورد (پاک‌کردن/تیک‌زدنِ هر خونه) هم حفظ کنیم.
    edit_bot_id = data.get("build_bot_id") if data.get("grid_mode") == "edit" else None

    if len(parts) == 2 and parts[1] == "locked":
        await cb.answer(
            "🔒 این ردیف در پلن پایه قفل است. برای باز شدن ردیف‌های ۳ تا ۵، پلن را ارتقا بده.",
            show_alert=True,
        )
        return

    if len(parts) == 2 and parts[1] == "clear":
        await state.update_data(grid_selected=[])
        try:
            await cb.message.edit_reply_markup(reply_markup=grid_kb(set(), plan, edit_bot_id=edit_bot_id))
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.answer("پاک شد")
        return

    if len(parts) == 2 and parts[1] == "done":
        if not selected:
            await cb.answer("حداقل یک خانه را سبز کن.", show_alert=True)
            return
        # تعداد خانه‌های سبز هر ردیف = تعداد دکمه‌های آن ردیف (ردیف‌های خالی حذف می‌شوند)
        per_row: dict[int, int] = {}
        for key in selected:
            r = int(key.split(",")[0])
            per_row[r] = per_row.get(r, 0) + 1
        buttons = []
        for new_row, r in enumerate(sorted(per_row), start=1):
            for col in range(1, per_row[r] + 1):
                buttons.append({"row": new_row, "col": col, "label": None})
        await state.update_data(buttons=buttons)
        await state.set_state(Build.naming)
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await start_naming(cb.message, state)
        await cb.answer()
        return

    # تغییر وضعیت یک خانه (toggle)
    r_idx = int(parts[1])
    if row_locked(plan, r_idx):
        await cb.answer(
            "🔒 این ردیف در پلن پایه قفل است. با ارتقای پلن باز می‌شود.",
            show_alert=True,
        )
        return
    key = f"{parts[1]},{parts[2]}"
    if key in selected:
        selected.discard(key)
    else:
        selected.add(key)
    await state.update_data(grid_selected=list(selected))
    try:
        await cb.message.edit_reply_markup(reply_markup=grid_kb(selected, plan, edit_bot_id=edit_bot_id))
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer()


@router.callback_query(Build.rows, F.data.startswith("brows:"))
async def build_rows(cb: CallbackQuery, state: FSMContext):
    n = int(cb.data.split(":")[1])
    await state.update_data(rows_total=n, current_row=1, counts=[])
    await state.set_state(Build.bcount)
    await cb.message.edit_text(f"ردیف ۱ از {n}: چند دکمه داشته باشد؟", reply_markup=bcount_kb())
    await cb.answer()


@router.callback_query(Build.bcount, F.data.startswith("bcnt:"))
async def build_bcount(cb: CallbackQuery, state: FSMContext):
    n = int(cb.data.split(":")[1])
    data = await state.get_data()
    counts = data["counts"] + [n]
    cur, total = data["current_row"], data["rows_total"]
    if cur < total:
        await state.update_data(counts=counts, current_row=cur + 1)
        await cb.message.edit_text(f"ردیف {cur+1} از {total}: چند دکمه داشته باشد؟", reply_markup=bcount_kb())
        await cb.answer()
        return
    buttons = []
    for r, c in enumerate(counts, start=1):
        for col in range(1, c + 1):
            buttons.append({"row": r, "col": col, "label": None})
    await state.update_data(counts=counts, buttons=buttons)
    await state.set_state(Build.naming)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await start_naming(cb.message, state)
    await cb.answer()


