@router.message(Build.naming, F.text)
async def build_name(msg: Message, state: FSMContext):
    data = await state.get_data()
    awaiting = data.get("awaiting")
    if not awaiting:
        await msg.answer("اول روی یکی از دکمه‌های بالا بزن، بعد اسمش رو بفرست.")
        return
    row, col = awaiting
    name = (msg.text or "").strip()
    if not name:
        await msg.answer("نام نامعتبر است. دوباره بفرست.")
        return

    buttons = data["buttons"]
    for b in buttons:
        if b["row"] == row and b["col"] == col:
            b["label"] = name
            break
    await state.update_data(buttons=buttons, awaiting=None)

    # پاک‌کردن پیام سؤال و پیام اسمی که کاربر فرستاد؛ اسم می‌رود می‌نشیند روی خودِ دکمه
    ask_msg_id = data.get("ask_msg_id")
    if ask_msg_id:
        try:
            await msg.bot.delete_message(msg.chat.id, ask_msg_id)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        await msg.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    try:
        await msg.bot.edit_message_reply_markup(
            chat_id=data["preview_chat_id"], message_id=data["preview_msg_id"],
            reply_markup=glass_naming_kb(buttons),
        )
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    if all(b.get("label") for b in buttons):
        await msg.answer("همهٔ دکمه‌ها اسم‌گذاری شدند. برای رفتن به مرحلهٔ بعد «✅ تایید و ادامه» را بزن.")


# ======================= ربات‌های من =======================
async def my_bots(msg: Message):
    async with Session() as s:
        rows = (await s.scalars(
            select(BotRow).where(BotRow.owner_id == msg.from_user.id).order_by(BotRow.id)
        )).all()
    if not rows:
        await msg.answer("هنوز رباتی نساختی. از «🤖 ساخت ربات» شروع کن.")
        return
    active = [r for r in rows if not r.archived_at]
    archived = [r for r in rows if r.archived_at and r.archive_reason != "user_deleted"]
    b = InlineKeyboardBuilder()
    for r in active:
        mark = "🟢" if r.status == "active" else "⏸"
        b.button(text=f"{mark} @{r.username} • {PLAN_INFO[Plan(r.plan)]['title']}",
                 callback_data=f"mb:{r.id}")
    if archived:
        b.button(text=f"🗄 بایگانی ({len(archived)})", callback_data="myarchive")
    # === PATCH_MYBOTS_BACK_BUTTON_V1 ===
    b.button(text="⬅️ بازگشت", callback_data="mybots:back_main", style=ButtonStyle.DANGER)
    b.adjust(1)
    await msg.answer("🗂 ربات‌های تو:", reply_markup=b.as_markup())


@router.callback_query(F.data == "myarchive")
async def my_archive(cb: CallbackQuery, state: FSMContext):
    await _delete_home_aux_messages(state, cb.message.bot)
    from config import archive_retention_days
    async with Session() as s:
        rows = (await s.scalars(
            select(BotRow).where(BotRow.owner_id == cb.from_user.id,
                                 BotRow.archived_at.is_not(None),
                                 BotRow.archive_reason != "user_deleted").order_by(BotRow.id)
        )).all()
        items = []
        now = datetime.datetime.now()
        for r in rows:
            retention = archive_retention_days(r.plan, r.archive_reason)
            left = max(retention - (now - r.archived_at).days, 0)
            items.append((r.id, r.username, r.plan, left))
    if not items:
        await cb.answer("بایگانی خالی است.", show_alert=True)
        return
    b = InlineKeyboardBuilder()
    lines = ["🗄 <b>بایگانی ربات‌ها</b>",
             "این ربات‌ها غیرفعال‌اند و تا مهلتِ زیر فرصت بازگردانی با پرداخت دارند؛ "
             "پس از آن برای همیشه حذف می‌شوند.\n"]
    for bid, uname, plan, left in items:
        lines.append(f"• @{uname} — {PLAN_INFO[Plan(plan)]['title']} — ⏳ {left} روز تا حذف")
        b.button(text=f"♻️ بازگردانی @{uname} (پرداخت)", callback_data=f"mbup:{bid}", style=ButtonStyle.SUCCESS)
    b.button(text="⬅️ بازگشت", callback_data="myback", style=ButtonStyle.DANGER)
    b.adjust(1)
    try:
        await cb.message.edit_text("\n".join(lines), reply_markup=b.as_markup())
    except Exception:
        await cb.message.answer("\n".join(lines), reply_markup=b.as_markup())
    await cb.answer()


@router.callback_query(F.data == "myback")
async def my_back(cb: CallbackQuery, state: FSMContext):
    await _delete_home_aux_messages(state, cb.message.bot)
    async with Session() as s:
        rows = (await s.scalars(
            select(BotRow).where(BotRow.owner_id == cb.from_user.id).order_by(BotRow.id)
        )).all()
        active = [(r.id, r.username, r.plan, r.status) for r in rows if not r.archived_at]
        n_arch = sum(1 for r in rows if r.archived_at and r.archive_reason != "user_deleted")
    b = InlineKeyboardBuilder()
    for bid, uname, plan, status in active:
        mark = "🟢" if status == "active" else "⏸"
        b.button(text=f"{mark} @{uname} • {PLAN_INFO[Plan(plan)]['title']}", callback_data=f"mb:{bid}")
    if n_arch:
        b.button(text=f"🗄 بایگانی ({n_arch})", callback_data="myarchive")
    # === PATCH_MYBOTS_BACK_BUTTON_V1 ===
    b.button(text="⬅️ بازگشت", callback_data="mybots:back_main", style=ButtonStyle.DANGER)
    b.adjust(1)
    try:
        await cb.message.edit_text("🗂 ربات‌های تو:", reply_markup=b.as_markup())
    except Exception:
        await cb.message.answer("🗂 ربات‌های تو:", reply_markup=b.as_markup())
    await cb.answer()


