# === PATCH_BOT_MAKER_SOURCE_V1 ===
async def _bot_maker_line(s, bot_id: int) -> str:
    """یک خط توضیح می‌سازد که این رباتِ مستأجر با کدام ابزار ساخته شده:
    مستقیم از بات‌سازِ اصلی، یا از طریقِ یک ربات همکار (و کدام همکار).

    منطق: اگر برای این bot_id ردیفی در PartnerSale باشد (sold_bot_id)، یعنی
    یک همکار آن را ساخته/فروخته؛ در غیر این صورت مستقیم از پلتفرمِ اصلی است.
    """
    from models import PartnerSale, PartnerBot
    sale = await s.scalar(select(PartnerSale).where(PartnerSale.sold_bot_id == bot_id))
    if not sale:
        return "🏭 ساخته‌شده با: بات‌سازِ اصلی (مستقیم)"
    pbot = await s.get(PartnerBot, sale.partner_bot_id)
    if not pbot:
        return "🤝 ساخته‌شده با: یک ربات همکار"
    prow = await s.get(BotRow, pbot.bot_id)
    puname = f"@{prow.username}" if prow and prow.username else "—"
    kind_lbl = " — به‌صورتِ تست" if sale.kind == "trial" else ""
    return (f"🤝 ساخته‌شده با: ربات همکار {puname} "
            f"(آیدیِ همکار: <code>{pbot.owner_id}</code>){kind_lbl}")


@router.callback_query(F.data.startswith("mb:"))
async def my_bot_detail(cb: CallbackQuery, state: FSMContext):
    await _delete_home_aux_messages(state, cb.message.bot)
    try:
        _mb_parts = cb.data.split(":")
        bot_id = int(_mb_parts[1])
    except Exception:
        await cb.answer("داده نامعتبر", show_alert=True)
        return
    # === PATCH_BOT_DETAIL_BACK_TO_PROFILE_V1 ===
    # originِ اختیاری (مثلاً از صفحهٔ پروفایل اومده) تا دکمهٔ بازگشت درست کار کنه
    _mb_origin = _mb_parts[2] if len(_mb_parts) > 2 else None
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r or r.owner_id != cb.from_user.id:
            await cb.answer("ربات یافت نشد", show_alert=True)
            return
        try:
            btn_count = await s.scalar(
                select(func.count()).select_from(MainButton).where(MainButton.bot_id == bot_id)) or 0
        except Exception:
            btn_count = 0
        uname, plan, field = r.username, r.plan, r.field
        status, sub_months = r.status, r.sub_months
        plan_expires_at, created_at = r.plan_expires_at, r.created_at
        last_activity_at, archived_at = r.last_activity_at, r.archived_at
        archive_reason, lock_reason = r.archive_reason, r.lock_reason
    field_title = FIELDS.get(field, field)
    _back_cb = "hm:profile" if _mb_origin == "profile" else "myback"
    # === PATCH_ARCHIVED_BOT_DETAIL_LOCK_V1 ===
    # قبلاً حتی برایِ رباتِ بایگانی‌شده هم همینِ منویِ کاملِ فعال (فعال‌سازی/
    # ویرایش/چیدمانِ دکمه‌ها/تعویضِ توکن/حذف) نشون داده می‌شد — یعنی مالکِ
    # رباتی که بایگانی شده می‌تونست توکن عوض کنه یا کلِ ربات رو حذف کنه، در
    # حالی که تنها کاری که باید بتونه بکنه بازگردانی (با پرداخت) است. حالا
    # برای رباتِ بایگانی‌شده فقط دکمهٔ بازگردانی + بازگشت نشون داده می‌شه.
    if archived_at:
        kb_rows = [
            [hx_button("♻️ بازگردانی از بایگانی (پرداخت)", callback_data=f"mbup:{bot_id}",
                                  style=ButtonStyle.SUCCESS)],
            [hx_button("⬅️ بازگشت", callback_data="myarchive", style=ButtonStyle.DANGER)],
        ]
    else:
        kb_rows = [
            [hx_button("🔄 فعال‌سازی/اتصال مجدد ربات", callback_data=f"mbhook:{bot_id}",
                                  style=ButtonStyle.SUCCESS)],
            [hx_button("✏️ ویرایش کامل ربات", callback_data=f"mbeditfull:{bot_id}")],
            [hx_button("🎨 بازسازی چیدمان دکمه‌ها", callback_data=f"mbedit:{bot_id}")],
            [hx_button("⭐️ ارتقا پلن", callback_data=f"mbup:{bot_id}", style=ButtonStyle.SUCCESS)],
        ]
        # === PATCH_WAGER_ADDON_V1 === افزونهٔ پولی «بازی‌های شرط‌بندی» (فقط برای ربات‌های واجد شرایط)
        try:
            from platform_wager_sale import mybot_button as _wager_btn
            _wb = await _wager_btn(bot_id, field, plan)
            if _wb is not None:
                kb_rows.append([_wb])
        except Exception:
            logger.exception("دکمهٔ بازی‌های شرط‌بندی ساخته نشد (نادیده گرفته شد)")
        # === PATCH_SELF_SERVICE_TOKEN_OWNER_V1 ===
        # درخواستِ تعویضِ توکن/واگذاریِ مالکیت (خودسرویس، بدونِ نیاز به تاییدِ
        # دستیِ ادمین) فقط برایِ پلن‌هایِ رشد/حرفه‌ای در دسترسه.
        # === PATCH_TRIAL_BOTS_LOCK_TOKEN_SWAP_V1 ===
        # رات‌هایِ رویِ تستِ فعال/استفاده‌شده (هنوز خریداری نشده) اجازهٔ
        # تعویضِ توکن/واگذاریِ مالکیتِ خودسرویس ندارند.
        # === PATCH_SELF_OWNERSHIP_LOCK_V1 === همان گیتِ سرورسایدِ ssbc_menu
        from bot_utils import owner_swap_lock_reason as _swap_lock
        async with Session() as _s_lock:
            _r_lock = await _s_lock.get(BotRow, bot_id)
            _lock_reason = await _swap_lock(_s_lock, _r_lock)
            _field_paid_ok = await _field_change_paid_ok(_s_lock, _r_lock) if _r_lock else False
        if not _lock_reason:
            kb_rows.append([hx_button("🔁 تعویضِ توکن / واگذاریِ مالکیت",
                                      callback_data=f"ssbc:menu:{bot_id}")])
        # === PATCH_CHANGE_FIELD_WALLET_PAID_V1 ===
        # دکمهٔ «🔄 تغییر نوع ربات» یا چون رایگان/اجباریه (زمینهٔ فعلی دیگه فعال
        # نیست) یا چون پلنِ رشد/حرفه‌ایِ فعال و غیرِ تستیه، نشون داده می‌شه.
        _field_free = field not in ACTIVE_FIELDS
        if _field_free or _field_paid_ok:
            _lbl = "🔄 تغییر نوع ربات" if _field_free else f"🔄 تغییر نوع ربات ({rial(CHANGE_FIELD_PRICE)})"
            kb_rows.append([hx_button(_lbl, callback_data=f"edt_field:{bot_id}")])
        # === PATCH_SPLIT_BOTRESET_V1 === منطقش در platform_botreset.py
        kb_rows.append([hx_button("♻️ ریستِ کاملِ ربات", callback_data=f"mbrs:menu:{bot_id}",
                                  style=ButtonStyle.DANGER)])
        kb_rows.append([hx_button("🗑 حذف ربات", callback_data=f"mbdel:{bot_id}", style=ButtonStyle.DANGER)])
        kb_rows.append([hx_button("⬅️ بازگشت", callback_data=_back_cb, style=ButtonStyle.DANGER)])
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    # === PATCH_MYBOT_FULL_INFO_V1 ===
    # قبلاً فقط یوزرنیم/نوع/پلن/تعدادِ دکمه نشون داده می‌شد؛ ادمین گفت
    # «تاریخ سررسید و همهٔ اطلاعاتِ اون ربات» هم لازمه.
    _status_labels = {
        "active": "🟢 فعال",
        "paused": "🔴 خاموش (توسط خودت)",
        "admin_paused": "🔴 غیرفعال‌شده توسط پلتفرم",
        "locked": "🔒 قفل‌شده توسط پلتفرم",
        "disabled_bad_token": "❌ توکن نامعتبر",
    }
    status_line = _status_labels.get(status, status or "—")
    if archived_at:
        status_line += " (در بایگانی)"
    lines = [
        f"🤖 <b>@{uname}</b>",
        f"نوع: {field_title}",
        f"پلن: {PLAN_INFO[Plan(plan)]['title']}" + (f" ({sub_months} ماهه)" if sub_months else ""),
        f"وضعیت: {status_line}",
        f"📅 تاریخ ساخت: {to_jalali(created_at)}",
        f"⏳ سررسید پلن: {to_jalali(plan_expires_at)}",
        f"🕓 آخرین فعالیتِ ربات: {to_jalali(last_activity_at)}",
        f"تعداد دکمه‌های صفحه: {btn_count}",
    ]
    if archived_at:
        lines.append(f"🗄 تاریخ بایگانی: {to_jalali(archived_at)}")
        _reason_labels = {
            "nonpayment": "عدم تمدید",
            "inactivity": "عدم فعالیت",
            "user_deleted": "حذف توسط خودِ کاربر",
        }
        lines.append(f"📋 دلیل بایگانی: {_reason_labels.get(archive_reason, archive_reason or '—')}")
    if status == "locked" and lock_reason:
        lines.append(f"🔒 دلیل قفل: {lock_reason}")
    # === PATCH_BOT_MAKER_SOURCE_V1 === این ربات با چه ابزاری ساخته شده
    try:
        async with Session() as _s_mk:
            lines.append(await _bot_maker_line(_s_mk, bot_id))
    except Exception:
        logger.exception("تعیینِ ابزارِ سازندهٔ ربات ناموفق بود (نادیده گرفته شد)")
    text = "\n".join(lines)
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


@router.callback_query(F.data.startswith("mbhook:"))
async def my_bot_rehook(cb: CallbackQuery):
    """PATCH_BLOCK_SELF_REACTIVATE_ADMIN_PAUSE_V1 — قبلاً این دکمه (که خودِ
    مالکِ بات می‌بینه) هر وضعیتِ غیرِactive‌ای رو بدونِ چک بی‌قیدوشرط
    «active» می‌کرد؛ یعنی اگه ادمینِ پلتفرم عمداً یه بات رو admin_paused یا
    locked کرده بود، مالک می‌تونست با همین دکمه دورش بزنه و دوباره فعالش
    کنه. حالا فقط توقفِ خودِ مالک (status == "paused") قابلِ فعال‌سازیِ
    خودکاره؛ برای admin_paused/locked باید حتماً از طریقِ ادمینِ پلتفرم اقدام
    بشه."""
    bot_id = int(cb.data.split(":")[1])
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r or r.owner_id != cb.from_user.id:
            await cb.answer("ربات یافت نشد", show_alert=True)
            return
        if r.status in ("admin_paused", "locked"):
            reason = (r.lock_reason or "").strip() if r.status == "locked" else ""
            msg = (
                "🔒 این ربات توسط مدیریتِ پلتفرم غیرفعال/قفل شده و از این طریق "
                "قابلِ فعال‌سازی نیست."
                + (f"\n\nدلیل: {reason}" if reason else "")
                + "\n\nلطفاً با پشتیبانیِ بات‌ساز تماس بگیر."
            )
            await cb.answer("این ربات توسط مدیریت غیرفعال/قفل شده است.", show_alert=True)
            await cb.message.answer(msg)
            return
        token = r.token
        uname = r.username
        if r.status != "active" and not r.archived_at:
            r.status = "active"
            await s.commit()
    await cb.answer("در حال اتصال…")
    ok = await set_tenant_webhook(token)
    if ok:
        # === PATCH_RECONNECT_START_BUTTON_V1 ===
        # قبلاً فقط می‌گفت «حالا داخل ربات خودت /start را بزن» بدونِ هیچ
        # دکمه‌ای — کاربر باید خودش دستی می‌رفت تو چتِ رباتش می‌گشت. الان
        # یه دکمهٔ آبی مستقیم می‌بره تو ربات و /start رو هم می‌زنه.
        kb = None
        if uname:
            kb = InlineKeyboardMarkup(inline_keyboard=[[
                hx_button("▶️ شروع | /start", url=f"https://t.me/{uname}?start=start",
                         style=ButtonStyle.PRIMARY)
            ]])
        await cb.message.answer(
            "✅ ربات دوباره فعال و متصل شد.\n"
            "اگر هنوز جواب نداد، چند ثانیه صبر کن و دوباره امتحان کن.",
            reply_markup=kb)
    else:
        await cb.message.answer(
            "❌ اتصال برقرار نشد. مطمئن شو سرور و دامنه (HTTPS) سالم‌اند و دوباره تلاش کن.")


@router.callback_query(F.data.startswith("mbedit:"))
async def my_bot_edit(cb: CallbackQuery, state: FSMContext):
    bot_id = int(cb.data.split(":")[1])
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r or r.owner_id != cb.from_user.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        plan = r.plan
    await state.clear()
    # === PATCH_GRID_EDIT_BACK_BUTTON_V1 ===
    # grid_mode="edit" یعنی این چیدمان از داخلِ «ویرایش ربات» باز شده، نه
    # ساختِ اولیه — پایین‌تر (build_grid) از همین پرچم برای تصمیم‌گیری در
    # موردِ نمایشِ دکمهٔ «لغو و برگشت به عقب» استفاده می‌شه.
    await state.update_data(build_bot_id=bot_id, grid_selected=[], grid_plan=plan, grid_mode="edit")
    await state.set_state(Build.grid)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer("🎨 بیا صفحهٔ اصلی را بسازیم/بازسازی کنیم.", reply_markup=await smart_cancel_kb())
    await cb.message.answer(GRID_INTRO, reply_markup=grid_kb(set(), plan, edit_bot_id=bot_id))
    await cb.answer()


@router.callback_query(F.data.startswith("gridcancel:"))
async def grid_cancel_to_edit_menu(cb: CallbackQuery, state: FSMContext):
    """لغوِ چیدمانِ دکمه‌ها و برگشت به صفحهٔ «ویرایش ربات» — نه کاملاً به خانه."""
    bot_id = int(cb.data.split(":")[1])
    await state.clear()
    await show_edit_menu(cb, bot_id, cb.from_user.id)
    await cb.answer("لغو شد")


# ======================= ویرایش کامل ربات =======================

async def show_edit_menu(target, bot_id: int, uid: int):
    """نمایش منوی اصلی ویرایش ربات."""
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r:
            return
        uname, plan, field = r.username, r.plan, r.field
        status, archived_at = r.status, r.archived_at
        buttons = (await s.scalars(
            select(MainButton).where(MainButton.bot_id == bot_id).order_by(MainButton.row, MainButton.col)
        )).all()
    
    field_title = FIELDS.get(field, field)
    
    # === PATCH_SHOW_FIELD_BUTTON_PAID_V1 ===
    # دکمهٔ «🔄 تغییر نوع ربات» دوباره نمایش داده می‌شود — یا چون تغییر برایِ
    # این ربات اجباری/رایگانه (زمینهٔ فعلی دیگه فعال نیست)، یا چون ربات پلنِ
    # رشد/حرفه‌ایِ فعال داره (تغییرِ پولی، ۵۰٬۰۰۰ تومان).
    field_change_free = field not in ACTIVE_FIELDS
    async with Session() as _s_chk:
        _r_chk = await _s_chk.get(BotRow, bot_id)
        field_change_paid_ok = await _field_change_paid_ok(_s_chk, _r_chk) if _r_chk else False
    kb_rows = [
        [hx_button("🖼 نمایش و ویرایش دکمه‌ها", callback_data=f"edt_btns:{bot_id}")],
        [hx_button("🏗 بازسازی کل چیدمان", callback_data=f"mbedit:{bot_id}")],
    ]
    if field_change_free or field_change_paid_ok:
        label = "🔄 تغییر نوع ربات" if field_change_free else f"🔄 تغییر نوع ربات ({rial(CHANGE_FIELD_PRICE)})"
        kb_rows.append([hx_button(label, callback_data=f"edt_field:{bot_id}")])
    # === PATCH_HIDE_RULES_FROM_PLATFORM_EDIT_V1 ===
    # دکمهٔ «📋 قوانین/پیام خوش‌آمد» از این‌جا برداشته شد — مالکِ ربات از
    # داخلِ پنلِ مدیریتِ خودِ ربات (بخشِ «🎛 دکمه‌ها و تنظیمات») بهش دسترسی
    # داره و نیازی نیست این‌جا هم تکرار بشه. خودِ هندلرِ edt_rules عمداً
    # حذف نشد تا اگه لینک/پیامِ قدیمی‌ای جایی مونده باشه هنوز کار کنه.
    kb_rows.append([hx_button("⬅️ بازگشت", callback_data=f"mb:{bot_id}", style=ButtonStyle.DANGER)])
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    
    text = (
        f"✏️ <b>ویرایش ربات @{uname}</b>\n"
        f"نوع: {field_title}\n"
        f"پلن: {PLAN_INFO[Plan(plan)]['title']}\n"
        f"تعداد دکمه: {len(buttons)}"
    )
    
    try:
        if hasattr(target, "message"):
            await target.message.edit_text(text, reply_markup=kb)
        else:
            await target.answer(text, reply_markup=kb)
    except Exception:
        if hasattr(target, "message"):
            await target.message.answer(text, reply_markup=kb)
        else:
            await target.answer(text, reply_markup=kb)


@router.callback_query(F.data.startswith("mbeditfull:"))
async def my_bot_edit_full(cb: CallbackQuery, state: FSMContext):
    bot_id = int(cb.data.split(":")[1])
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
