@router.callback_query(F.data.startswith("edt_btns:"))
async def edt_list_buttons(cb: CallbackQuery, state: FSMContext):
    bot_id = int(cb.data.split(":")[1])
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r or r.owner_id != cb.from_user.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        buttons = (await s.scalars(
            select(MainButton).where(MainButton.bot_id == bot_id).order_by(MainButton.row, MainButton.col)
        )).all()
    
    if not buttons:
        await cb.answer("هنوز دکمه‌ای ندارد. اول چیدمان بساز.", show_alert=True)
        return
    
    # ساخت پیش‌نمایش شیشه‌ای دکمه‌ها — شبیه چیدمان واقعی ربات
    rows_map: dict[int, list] = {}
    for btn in buttons:
        rows_map.setdefault(btn.row, []).append(btn)
    
    # ساخت کیبورد اینلاین با همان چیدمان ردیف/ستون واقعی ربات
    preview_rows = []
    for r in sorted(rows_map.keys()):
        row_btns = sorted(rows_map[r], key=lambda x: x.col)
        row = []
        for btn in row_btns:
            action_icon = {"buy_config": "🛒", "buy_vpn": "🛰", "buy_vpn_sanai": "🔵", "buy_vpn_pasargad": "🟣", "buy_vpn_pasarguard": "🛡️",
                           "buy_vpn_marzban": "🟠", "buy_vpn_marzneshin": "⚪️", "buy_vpn_hiddify": "🟢", "buy_vpn_rebecca": "🔴", "buy_vpn_alireza": "🟢", "buy_vpn_upanel_mizban": "🟡", "buy_vpn_shahan": "🟤",
                           "my_services": "📡", "profile": "👤", "wallet": "💰",
                           "referral": "👥", "ticket": "🎫", "submenu": "🗂",
                           "show_shop": "🛒", "slideshow": "🎞", "top_customers": "🏆"}.get(btn.action or "", "📌")
            row.append(hx_button(f"{action_icon} {btn.label}",
                callback_data=f"edt_btn:{btn.id}:{bot_id}"
            ))
        preview_rows.append(row)
    
    # دکمه‌های کنترلی پایین
    preview_rows.append([hx_button("⬅️ بازگشت", callback_data=f"mbeditfull:{bot_id}", style=ButtonStyle.DANGER)])
    
    await cb.message.edit_text(
        "🖼 <b>ویرایش دکمه‌ها</b>\n\n"
        "📱 دکمه‌ها دقیقاً همانند چیدمان ربات نمایش داده می‌شوند.\n"
        "روی هر دکمه بزن تا ویرایش کنی:",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=preview_rows)
    )
    await cb.answer()


