@router.callback_query(F.data.startswith("edt_act:"))
async def edt_btn_action_start(cb: CallbackQuery, state: FSMContext):
    parts = cb.data.split(":")
    btn_id, bot_id = int(parts[1]), int(parts[2])
    await state.set_state(EditBot.btn_action)
    await state.update_data(edit_btn_id=btn_id, edit_bot_id=bot_id)
    # === PATCH_ACTION_KB_FIELD_GATING_V1 ===
    # قبلاً اینجا action_kb() بدونِ هیچ آرگومانی صدا زده می‌شد که یعنی
    # همیشه پیش‌فرضِ «vpn_sales» — یعنی حتی رباتِ فروشگاهی/تبلیغاتی/عمومی
    # هم از همین مسیر ویرایش می‌شد، گزینه‌های VPN رو می‌دید. الان زمینهٔ
    # واقعیِ همون ربات از دیتابیس خونده و پاس داده می‌شه.
    async with Session() as s:
        brow = await s.get(BotRow, bot_id)
    field = brow.field if brow else "vpn_sales"
    # دریافت کیبورد اکشن‌ها و افزودن دکمه برگشت
    base_kb = action_kb(field)
    back_row = [hx_button("⬅️ بازگشت", callback_data=f"edt_btn:{btn_id}:{bot_id}", style=ButtonStyle.DANGER)]
    full_kb = InlineKeyboardMarkup(inline_keyboard=base_kb.inline_keyboard + [back_row])
    await cb.message.edit_text(
        "اکشن جدید این دکمه را انتخاب کن:",
        reply_markup=full_kb
    )
    await cb.answer()


