@router.message(EditBot.btn_webapp_url, F.text)
async def edt_btn_webapp_url_save(msg: Message, state: FSMContext):
    """دریافت و ذخیرهٔ لینک مینی‌اپ در ویرایش دکمه."""
    data = await state.get_data()
    btn_id = data["edit_btn_id"]
    bot_id = data["edit_bot_id"]
    url = (msg.text or "").strip()
    if url == BTN_CANCEL:
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id))
        return
    if not url.startswith("https://") or " " in url or len(url) > 500:
        await msg.answer("❌ لینک نامعتبر است. آدرس باید با https:// شروع شود و بدون فاصله باشد.\n"
                         "دوباره بفرست:")
        return
    async with Session() as s:
        mb = await s.get(MainButton, btn_id)
        if mb:
            cfg = {}
            if mb.config:
                try:
                    cfg = json.loads(mb.config) or {}
                except Exception:
                    cfg = {}
            cfg["webapp_url"] = url
            mb.config = json.dumps(cfg, ensure_ascii=False)
            mb.action = "web_app"
            await s.commit()
    await state.clear()
    await msg.answer(f"✅ دکمه به «مینی‌اپ» تبدیل شد.\n🌐 لینک: {url}",
                     reply_markup=await smart_home_kb(msg.from_user.id))
    await _show_edit_menu_after(msg, bot_id, msg.from_user.id)


