@router.message(EditBot.card, F.text)
async def edt_card_save(msg: Message, state: FSMContext):
    data = await state.get_data()
    bot_id = data["edit_bot_id"]
    card = (msg.text or "").strip().replace("-", "").replace(" ", "")
    if not card or card == BTN_CANCEL:
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id))
        return
    async with Session() as s:
        setting = await s.scalar(select(Setting).where(Setting.bot_id == bot_id, Setting.key == "card_number"))
        if setting:
            setting.value = card
        else:
            s.add(Setting(bot_id=bot_id, key="card_number", value=card))
        await s.commit()
    await state.clear()
    await msg.answer(f"✅ شماره کارت ذخیره شد: {card}", reply_markup=await smart_home_kb(msg.from_user.id))
    await _show_edit_menu_after(msg, bot_id, msg.from_user.id)


