@router.callback_query(F.data.startswith("mbup:"))
async def my_bot_upgrade(cb: CallbackQuery):
    _mbup_parts = cb.data.split(":")
    bot_id = int(_mbup_parts[1])
    _mbup_origin = _mbup_parts[2] if len(_mbup_parts) > 2 else None
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r or r.owner_id != cb.from_user.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        cur = r.plan
        archived = r.archived_at is not None
    b = InlineKeyboardBuilder()
    paid = plans_paid_enabled()
    cdown = plans_countdown_text()
    # === PATCH_TRIAL_NO_RENEW_LABEL_V1 ===
    # اگه ربات هنوز رویِ تستِ فعاله (چیزی خریده نشده)، دکمهٔ پلنِ فعلی نباید
    # «تمدید» باشه — چون چیزی برای تمدید کردن وجود نداره، باید «خرید» باشه.
    _on_trial_now = bool(await plan_trials.used_trial_for_bot(bot_id))
    for plan in (Plan.GROWTH, Plan.PRO):
        # تمدیدِ همون پلنِ فعلی همیشه مجازه (چه هنوز بایگانی نشده و نزدیکِ
        # سررسیده، چه بعد از بایگانی‌شدن) — قبلاً فقط بعد از بایگانی‌شدن
        # امکانِ تمدیدِ هم‌پلن بود و پلنِ حرفه‌ای پیش از بایگانی اصلاً امکانِ
        # تمدید نداشت («این ربات روی بالاترین پلن است»).
        if plan.value != cur and not plan_enabled(plan.value):
            continue
        # === PATCH_PLAN_SALE_LOCK_V1 ===
        # قفل فقط جلویِ خریدِ پلنِ جدید را می‌گیرد؛ تمدیدِ پلنِ فعلی باز است.
        if plan.value != cur and plan_sale_locked(plan.value):
            continue
        label = "♻️ تمدید " if (plan.value == cur and not _on_trial_now) else ""
        if not paid:
            price_txt = f"رایگان (⏳ {cdown} مانده)" if cdown else "رایگان (حالت تست)"
        else:
            final, _b, pdisc = plan_price_final(plan.value)
            price_txt = f"{rial(final)}/ماه" + (f" (٪{pdisc} تخفیف)" if pdisc else "")
        b.button(text=f"{label}{PLAN_INFO[plan]['title']} — {price_txt}",
                 callback_data=f"upg:{plan.value}:{bot_id}", style=ButtonStyle.SUCCESS)
    b.adjust(1)
    # === PATCH_TRIAL_NO_RENEW_V1 ===
    # دکمهٔ «درخواست تمدید ربات تست» حذف شد: تستِ ۲ روزه تمدید نمی‌شود.
    # کاربر بعد از پایانِ تست فقط می‌تواند پلن بخرد (دکمه‌هایِ بالا) —
    # وگرنه «تمدید» عملاً به تستِ نامحدود تبدیل می‌شد.
    # === PATCH_UPGRADE_BACK_BUTTON_V1 ===
    # قبلاً این صفحه هیچ دکمهٔ برگشتی نداشت — کاربری که پشیمون می‌شد یا
    # اشتباه وارد شده بود، راهی جز /start نداشت.
    # === PATCH_ARCHIVED_UPGRADE_BACK_BUTTON_V1 ===
    # قبلاً برای رباتِ بایگانی‌شده هم دکمهٔ بازگشت به mb:{bot_id} (منویِ
    # کاملِ مدیریت، شاملِ تعویضِ توکن/حذف) می‌رفت. حالا اگه ربات در بایگانی
    # است، بازگشت به لیستِ بایگانی می‌رود، نه منویِ مدیریتِ کامل.
    if _mbup_origin == "plans":
        _mbup_back_cb = "plans:list"
    elif archived:
        _mbup_back_cb = "myarchive"
    else:
        _mbup_back_cb = f"mb:{bot_id}"
    b.button(text="⬅️ بازگشت", callback_data=_mbup_back_cb, style=ButtonStyle.DANGER)
    b.adjust(1)
    head = ("♻️ برای بازگردانی ربات از بایگانی، یک پلن را پرداخت کن:\n\n" + PURCHASE_TERMS if archived
            else "⭐️ برای تمدید یا ارتقای پلن، گزینه را انتخاب کن:\n\n" + PURCHASE_TERMS)
    if not paid:
        head = "🎁 <b>حالت تست فعال است</b> — همهٔ پلن‌ها رایگان‌اند."
        if cdown:
            head += f"\n⏳ فقط <b>{cdown}</b> دیگر! (تا {to_jalali(plans_paid_at())})"
        head += "\n\nپلن جدید را انتخاب کن:"
    try:
        await cb.message.edit_text(head, reply_markup=b.as_markup())
    except TelegramBadRequest as e:
        if "message is not modified" not in str(e).lower():
            raise
    await cb.answer()


@router.callback_query(F.data.startswith("mbdel:"))
async def my_bot_del(cb: CallbackQuery):
    bot_id = int(cb.data.split(":")[1])
    kb = InlineKeyboardMarkup(inline_keyboard=[[
        hx_button("✅ بله، حذف", callback_data=f"mbdelyes:{bot_id}", style=ButtonStyle.DANGER),
        hx_button("❌ خیر", callback_data=f"mb:{bot_id}", style=ButtonStyle.PRIMARY),
    ]])
    # === PATCH_DELETE_LIMIT_NOTICE_V1 ===
    # ادمین خواست: کسی که ربات حذف می‌کنه باید صریحاً بدونه که سقفِ تعدادِ
    # رباتِ قابل‌ساخت (شمارشِ کلِ رباتِ ساخته‌شده در طولِ عمرِ حساب، نه فقط
    # فعال‌ها) با حذفِ ربات آزاد/کم نمی‌شه.
    await cb.message.edit_text(
        "⚠️ <b>مطمئنی این ربات حذف بشه؟</b>\n\n"
        "نگهداری و مدیریتِ ربات (و تصمیم به حذفش) کاملاً بر عهده‌ی خودِ شماست. "
        "این ربات — در هر پلنی که باشه (پایه/رشد/حرفه‌ای) — با حذف شدن، "
        "<b>دیگر قابل بازگشت نیست</b>: کاربرها، کیف‌پول‌ها، سفارش‌ها و همه‌ی "
        "تنظیماتش برای همیشه از دست می‌رن.\n\n"
        "❗️ <b>توجه:</b> سقفِ تعدادِ ربات‌هایی که مجازی بسازی، بر اساسِ کلِ "
        "ربات‌هایی است که تا الان ساختی (چه فعال، چه حذف‌شده) — با حذفِ این "
        "ربات، جای خالی برای ساختِ ربات جدید باز <b>نمی‌شود</b>.",
        reply_markup=kb)
    await cb.answer()


@router.callback_query(F.data.startswith("mbdelyes:"))
async def my_bot_del_yes(cb: CallbackQuery, state: FSMContext):
    bot_id = int(cb.data.split(":")[1])
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r or r.owner_id != cb.from_user.id:
            await cb.answer("یافت نشد", show_alert=True)
            return
        token = r.token
        # === PATCH_BOTDEL_SOFT_ARCHIVE_V1 ===
        # قبلاً اینجا بلافاصله یه حذفِ فیزیکیِ کامل (ده‌ها DELETE روی همه‌ی
        # جدول‌های وابسته) اجرا می‌شد — یعنی اگه کاربر اشتباهی می‌زد یا نظرش
        # عوض می‌شد، هیچ راهی برای برگردوندن نبود. الان به‌جاش فقط بایگانی
        # می‌کنیم (دقیقاً مثلِ بایگانیِ ناشی از عدم‌تمدید/عدم‌فعالیت) و حذفِ
        # فیزیکیِ واقعی رو به همون چرخه‌ی پاک‌سازیِ خودکار (main.py:
        # subscription_loop) می‌سپاریم که بعد از USER_DELETED_ARCHIVE_DAYS
        # (۳۰ روز) انجامش می‌ده. تا اون‌موقع، فقط ادمینِ پلتفرم (نه خودِ
        # کاربر) از بخشِ «🗄 بایگانی» می‌تونه ببینتش و در صورت نیاز برگردونه؛
        # به‌خودِ کاربر عمداً گفته می‌شه غیرقابل‌برگشته تا این فرصت به‌عنوانِ
        # یه قابلیتِ رسمی سوءاستفاده نشه.
        r.status = "paused"
        r.archived_at = datetime.datetime.now()
        r.archive_reason = "user_deleted"
        await s.commit()
    # === PATCH_HOME_MENU_STUCK_STATE_V1 ===
    # اقدامِ ایمن: حذفِ ربات باید state رو هم پاک کنه — اگه کاربر وسطِ یه
    # ویزاردِ ناتمام (مثلاً ویرایشِ همین یا یه ربات دیگه) این ربات رو حذف
    # کرده باشه، دیگه نباید تویِ اون state گیر بمونه.
    await state.clear()
    try:
        # === PATCH_TENANT_STATUS_BUS_DIRECT_V1 ===
        # قبلاً از طریقِ main.invalidate_tenant_status صدا زده می‌شد که هم
        # کشِ محلیِ همون پروسه رو پاک می‌کرد هم NOTIFY می‌فرستاد. حالا که
        # main.py دیگه تنها نقطهٔ ورود نیست (main_platform.py/main_tenant.py)
        # و این کشِ وضعیت اصلاً سمتِ پلتفرم وجود نداره (فقط سمتِ مستأجره)،
        # مستقیم فقط NOTIFY می‌فرستیم — پروسه(های) مستأجر با listenerِ
        # tenant_status_bus فوری باخبر می‌شن.
        import tenant_status_bus
        await tenant_status_bus.publish_tenant_invalidate(token)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        async with _temp_bot(token) as tb:
            await tb.delete_webhook()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        await cb.message.edit_text(
            "🗑 ربات حذف شد و دیگر در دسترس نیست.\n"
            "این عمل قابل بازگشت نیست.\n\n"
            "❗️ یادآوری: این حذف، سقفِ تعدادِ ربات‌های قابل‌ساختِ حسابت رو تغییر "
            "نمی‌ده — سقف بر اساسِ کلِ رباتی است که تا الان ساختی."
        )
    except Exception:
        logger.exception("ویرایشِ پیامِ تاییدِ حذف ناموفق بود (خودِ حذف قبلاً انجام شده)")
        await cb.message.answer("🗑 ربات حذف شد و دیگر در دسترس نیست.")
    await cb.answer("حذف شد")


