# === PATCH_BLU_PLATFORM_V1 ===
async def _insufficient_balance(cb: CallbackQuery, need: int, note: str = "") -> None:
    """پیامِ «موجودی کافی نیست» + میان‌برِ شارژ.

    قبلاً فقط یک alert نشان داده می‌شد و کاربر باید خودش می‌رفت کیف پول را
    پیدا می‌کرد؛ حالا اگر درگاهِ کارت‌به‌کارتِ هوشمند برایِ «پرداختِ محصول»
    فعال باشد، همان‌جا دکمه‌اش را می‌بیند.
    """
    from platform_blu import is_available as _blu_ok, USER_LABEL as _BLU_LABEL
    rows = []
    # === PATCH_PLATFORM_APAY_V1 ===
    from platform_apay import is_available as _papay_ok, display_name as _papay_name
    if await _papay_ok("purchase"):
        rows.append([hx_button(await _papay_name() + " (شارژ کیف پول)",
                               callback_data="charge_papay_buy", style=ButtonStyle.SUCCESS)])
    if await _blu_ok("purchase"):
        rows.append([hx_button(_BLU_LABEL + " (شارژ کیف پول)",
                               callback_data="charge_blu_buy",
                               style=ButtonStyle.SUCCESS)])
    rows.append([hx_button("💰 رفتن به کیف پول", callback_data="go_wallet")])
    txt = (f"❌ <b>موجودی کافی نیست</b>\n\nلازم: <b>{rial(need)}</b>"
           + (f"\n{note}" if note else "")
           + "\n\nاول کیف پولت را شارژ کن، بعد دوباره خرید را ادامه بده.")
    try:
        await cb.message.answer(txt, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
    except Exception:
        logger.exception("insufficient balance prompt failed")
    await cb.answer("موجودی کافی نیست.", show_alert=True)


