async def _platform_wallet_kb() -> InlineKeyboardMarkup:
    rows = []
    # === PATCH_PLATFORM_MANUAL_CARD_TOGGLE_V1 ===
    if (await get_pset("platform_manual_card_enabled", "1")) == "1":
        rows.append([hx_button("💳 شارژ کارت‌به‌کارت", callback_data="charge", style=ButtonStyle.SUCCESS)])
    # زرین‌پال (درگاه آنلاین ریالی)
    zarinpal_mid = await get_pset("platform_zarinpal_merchant_id", "")
    if zarinpal_mid:
        rows.append([hx_button("🏦 شارژ با درگاه زرین‌پال", callback_data="charge_zarinpal",
                                          style=ButtonStyle.PRIMARY)])
    # === PATCH_PLATFORM_IDPAY_GATEWAY_V1 ===
    idpay_key = await get_pset("platform_idpay_api_key", "")
    if idpay_key:
        rows.append([hx_button("🏧 شارژ با درگاه آیدی‌پی", callback_data="charge_idpay",
                                          style=ButtonStyle.PRIMARY)])
    # === PATCH_PLATFORM_SMS_AUTOCHARGE_V1 ===
    # === PATCH_PLATFORM_APAY_V1 ===
    from platform_apay import is_available as _papay_ok, display_name as _papay_name
    if await _papay_ok("wallet"):
        rows.append([hx_button(await _papay_name(), callback_data="charge_papay",
                               style=ButtonStyle.SUCCESS)])
    sms_on = (await get_pset("platform_sms_enabled", "0")) == "1" and bool(await get_pset("platform_sms_secret", ""))
    if sms_on:
        rows.append([hx_button("📲 شارژِ خودکار کارت‌به‌کارت (تأییدِ آنی)", callback_data="charge_sms",
                                          style=ButtonStyle.PRIMARY)])
    # NOWPayments
    nowpay_key = await get_pset("platform_nowpay_api_key", "")
    if nowpay_key:
        rows.append([hx_button("🪙 شارژ با ارز دیجیتال (NOWPayments)",
                                          callback_data="charge_nowpay",
                                          style=ButtonStyle.PRIMARY)])
    addr_map = await _platform_swap_addr_map()
    swap_on = bool(await get_pset("swap_api_key", "")) and any(addr_map.values())
    if swap_on:
        rows.append([hx_button("🟦 شارژ با سواپ‌ولت", callback_data="charge_swap",
                                          style=ButtonStyle.PRIMARY)])
    # === PATCH_REMOVE_GENERIC_CRYPTO_BTN_V1 ===
    # دکمهٔ عمومیِ «شارژ با ارز دیجیتال» (charge_crypto) حذف شد؛ چون نه واسط
    # پرداختِ واقعی داشت نه تنظیماتی، فقط یه دکمهٔ اضافه/گمراه‌کننده بود.
    # روش‌های واقعیِ کریپتو (NOWPayments، سواپ‌ولت، تون‌پیز، TON مستقیم) هرکدوم
    # دکمهٔ اختصاصیِ خودشون رو دارن و فقط وقتی فعال باشن نشون داده می‌شن.
    # === PATCH_TONPAYS_PLATFORM_V1 ===
    from platform_tonpays import is_available as _ptonp_ok
    if await _ptonp_ok():
        rows.append([hx_button("💠 شارژ با تون‌پیز (کارت‌به‌کارت اتوماتیک)",
                               callback_data="charge_ptonpays",
                               style=ButtonStyle.PRIMARY)])
    # === PATCH_TON_DIRECT_PLATFORM_V1 ===
    from platform_ton_direct import is_available as _ptond_ok
    if await _ptond_ok():
        rows.append([hx_button("💎 شارژ با واریز مستقیم TON (بدونِ درگاه)",
                               callback_data="charge_pton_direct",
                               style=ButtonStyle.PRIMARY)])
    # === PATCH_BLU_PLATFORM_V1 ===
    from platform_blu import is_available as _blu_ok, USER_LABEL as _BLU_LABEL
    if await _blu_ok("wallet"):
        rows.append([hx_button(_BLU_LABEL, callback_data="charge_blu",
                               style=ButtonStyle.PRIMARY)])
    # === PATCH_WALLET_BACK_BUTTON_V1 ===
    rows.append([hx_button("⬅️ بازگشت", callback_data="wallet:back_main",
                           style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


