# === PATCH_WALLET_SCREEN_TOPUP_STATS_V1 ===
async def wallet(msg: Message):
    if (await get_pset("pwallet_enabled", "on")) == "off" and not is_admin(msg.from_user.id):
        await msg.answer("💰 کیف پول موقتاً غیرفعال است. بعداً دوباره سر بزن.")
        return
    async with Session() as s:
        u = await get_user(s, msg.from_user.id, msg.from_user.full_name, username=msg.from_user.username)
        await s.commit()
    # === PATCH_WALLET_REMOVE_CARD_TOTAL_V1 ===
        bal = u.balance
        last_txn = await s.scalar(
            select(PlatformTxn)
            .where(PlatformTxn.user_telegram_id == msg.from_user.id,
                   PlatformTxn.kind.in_(("charge", "zarinpal_charge", "nowpay_charge")))
            .order_by(PlatformTxn.created_at.desc())
            .limit(1)
        )
    last_amount = float(last_txn.amount) if last_txn else 0
    await msg.answer(
        "💰 <b>کیف پول</b>\n\n"
        f"🧾 آخرین مبلغ پرداختی: <b>{rial(last_amount)}</b>\n"
        f"💰 موجودی کیف پول شما: <b>{rial(bal)}</b>",
        reply_markup=await _platform_wallet_kb())


