# === PATCH_SECOND_CARD_ROTATE_V1 ===
async def _platform_cards() -> list[tuple[str, str]]:
    """فهرستِ کارت‌هایِ فعال — [(شماره، نامِ صاحب), ...]."""
    out = []
    c1 = (await get_pset("platform_card", "")).strip()
    if c1:
        out.append((c1, (await get_pset("card_holder", "")).strip()))
    c2 = (await get_pset("platform_card2", "")).strip()
    if c2:
        # اگر نامِ دومی ثبت نشده، از نامِ اول استفاده می‌شود.
        out.append((c2, (await get_pset("card_holder2", "")).strip()
                    or (await get_pset("card_holder", "")).strip()))
    return out


async def _pick_card() -> tuple[str, str]:
    """یک کارت به‌صورتِ تصادفی برایِ نمایش به کاربر.

    تأییدِ رسید همچنان *هر دو* کارت را قبول می‌کند (نه فقط کارتِ
    نمایش‌داده‌شده)، وگرنه کاربری که از پیامِ قبلی واریز کرده رسیدش رد
    می‌شد.
    """
    cards = await _platform_cards()
    if not cards:
        return "", ""
    return _random.choice(cards)


# === PATCH_BIG_CHARGE_APPROVAL_V1 ===
async def _big_charge_limit() -> int:
    try:
        return int(await get_pset("big_charge_limit", str(BIG_CHARGE_LIMIT_DEFAULT)) or 0)
    except ValueError:
        return BIG_CHARGE_LIMIT_DEFAULT


async def _big_charge_approved(uid: int, amount: int) -> "BigChargeRequest | None":
    """تأییدِ بازِ این کاربر برایِ مبلغی >= amount (اگر هست)."""
    from models import BigChargeRequest
    async with Session() as s:
        return await s.scalar(
            select(BigChargeRequest).where(
                BigChargeRequest.user_telegram_id == uid,
                BigChargeRequest.status == "approved",
                BigChargeRequest.amount >= amount,
            ).order_by(BigChargeRequest.id.desc()))


async def _consume_approval(req_id: int) -> None:
    from models import BigChargeRequest
    async with Session() as s:
        r = await s.get(BigChargeRequest, req_id)
        if r:
            r.status = "used"
            await s.commit()


async def _big_charge_gate(message: Message, state: FSMContext, amount: int,
                           kind: str = "wallet", subject: str = "") -> bool:
    """اگر مبلغ از سقف بیشتر بود، درخواستِ هماهنگی می‌سازد و برایِ مدیر
    می‌فرستد؛ تا وقتی مدیر تأیید نکند، ادامه نمی‌دهد.

    خروجی True یعنی «جلوی ادامه گرفته شد».
    """
    from models import BigChargeRequest
    limit = await _big_charge_limit()
    if limit <= 0 or amount <= limit:
        return False

    uid = message.chat.id
    approved = await _big_charge_approved(uid, amount)
    if approved:
        # تأییدِ مدیر گرفته شده — همین یک بار مصرف می‌شود.
        await _consume_approval(approved.id)
        return False

    async with Session() as s:
        pending = await s.scalar(select(BigChargeRequest).where(
            BigChargeRequest.user_telegram_id == uid,
            BigChargeRequest.status == "pending",
            BigChargeRequest.amount == amount))
        if pending is None:
            pending = BigChargeRequest(user_telegram_id=uid, amount=amount,
                                       kind=kind, subject=subject[:200])
            s.add(pending)
            await s.commit()
            await s.refresh(pending)
        req_id = pending.id

    chat_url = (await get_pset("big_charge_chat", "")) or BIG_CHARGE_CHAT_DEFAULT
    _draft = _url_quote(
        f"سلام 🌱\nدرخواست هماهنگی برای مبلغ {amount:,} تومان"
        + (f" ({subject})" if subject else "") + ".\n"
        f"🆔 آیدی عددی من: {uid}\n🔖 کد درخواست: {req_id}")
    _sep = "&" if "?" in chat_url else "?"

    await state.clear()
    await message.answer(
        f"⚠️ <b>مبلغِ درخواستی: {rial(amount)}</b>\n\n"
        f"واریزهایِ بالای <b>{rial(limit)}</b> باید با هماهنگیِ مدیرِ بات‌ساز "
        "انجام شود.\n\n"
        f"🔖 کدِ درخواست: <code>{req_id}</code>\n\n"
        "درخواستت همین الان برایِ مدیر ارسال شد. می‌توانی از دکمهٔ زیر هم "
        "مستقیم پیام بدهی.\n\n"
        "به‌محضِ تأییدِ مدیر، همین‌جا خبرت می‌کنیم و می‌توانی واریز کنی تا "
        "<b>بلافاصله</b> شارژ شود.\n\n"
        "🙏 این کار فقط برایِ این است که معطل نشوی و سوءتفاهمی پیش نیاید.",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="💬 هماهنگی با مدیرِ بات‌ساز",
                                  url=f"{chat_url}{_sep}text={_draft}",
                                  style=ButtonStyle.SUCCESS)],
        ]))

    # اطلاعِ کاملِ درخواست به مدیر + دکمه‌هایِ تأیید/رد
    _u = message.from_user
    _name = _html.escape((_u.full_name if _u else "") or "—")
    _uname = f"@{_u.username}" if (_u and _u.username) else "—"
    async with Session() as s:
        _row = await s.scalar(select(PlatformUser).where(
            PlatformUser.telegram_id == uid))
    _bal = rial(_row.balance) if _row else "—"
    _kind_fa = ("خریدِ رباتِ آماده" if kind.startswith("market")
                else "شارژِ کیف پول" if kind == "wallet" else kind)
    try:
        await message.bot.send_message(
            PLATFORM_ADMIN_ID,
            f"💰 <b>درخواستِ واریزِ سنگین</b>\n\n"
            f"🔖 کد: <code>{req_id}</code>\n"
            f"👤 {_name} — {_uname}\n"
            f"🆔 <code>{uid}</code>\n"
            f"💵 مبلغ: <b>{rial(amount)}</b>\n"
            f"🎯 بابتِ: {_kind_fa}"
            + (f" — {_html.escape(subject)}" if subject else "") + "\n"
            f"👛 موجودیِ فعلی: {_bal}\n\n"
            "اگر تأیید کنی، به کاربر خبر می‌دهیم که واریز کند.",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [hx_button("✅ تأیید جهتِ واریز", callback_data=f"bigreq:ok:{req_id}",
                           style=ButtonStyle.SUCCESS)],
                [hx_button("❌ رد درخواست", callback_data=f"bigreq:no:{req_id}",
                           style=ButtonStyle.DANGER)],
            ]))
    except Exception:
        logger.exception("ارسالِ درخواستِ واریزِ سنگین به مدیر ناموفق بود")
    return True


@router.callback_query(F.data.startswith("bigreq:"))
async def big_charge_decide(cb: CallbackQuery, bot: Bot):
    """تأیید/ردِ درخواستِ واریزِ سنگین توسطِ مدیر.

    # === PATCH_BIG_CHARGE_RESUME_V1 ===
    قبلاً تأیید فقط «اجازه» می‌داد و کاربر باید کلِ مسیر را از اول
    می‌رفت — که در عمل یعنی گیت دوباره فعال می‌شد و درخواستِ تکراری
    ساخته می‌شد. حالا تأیید، خودِ جریان را همان‌جا ادامه می‌دهد:
    برایِ کیف پول، شمارهٔ کارت فرستاده و FSMِ کاربر مستقیم روی مرحلهٔ
    «۴ رقمِ آخر» گذاشته می‌شود.
    """
    from models import BigChargeRequest
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    _, action, rid = cb.data.split(":")
    async with Session() as s:
        r = await s.get(BigChargeRequest, int(rid))
        if not r:
            await cb.answer("این درخواست پیدا نشد.", show_alert=True)
            return
        if r.status != "pending":
            await cb.answer(f"قبلاً رسیدگی شده (وضعیت: {r.status}).", show_alert=True)
            return
        r.status = "approved" if action == "ok" else "rejected"
        r.decided_at = datetime.datetime.now()
        await s.commit()
        uid, amount, st, kind = (r.user_telegram_id, r.amount, r.status, r.kind or "")

    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    if st != "approved":
        try:
            await bot.send_message(
                uid,
                "ℹ️ درخواستِ واریزت فعلاً تأیید نشد.\n"
                "لطفاً برایِ هماهنگی با پشتیبانی در تماس باش.")
        except Exception:
            logger.exception("اطلاعِ رد به کاربر ناموفق بود")
        await cb.answer("❌ رد شد.")
        return

    # === PATCH_BIG_CHARGE_RESUME_V1 ===
    if kind.startswith("market"):
        # خریدِ پروژه: یک دکمهٔ «ادامهٔ خرید» که مستقیم به همان مرحله برود.
        pid = kind.split(":", 1)[1] if ":" in kind else ""
        rows = []
        if pid:
            rows.append([hx_button("🛒 ادامهٔ خرید", callback_data=f"mk:buy:{pid}",
                                   style=ButtonStyle.SUCCESS)])
        try:
            await bot.send_message(
                uid,
                f"✅ <b>درخواستت تأیید شد</b>\n\n"
                f"💵 مبلغ: <b>{rial(amount)}</b>\n\n"
                "حالا می‌توانی خرید را کامل کنی 👇",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=rows) if rows else None)
        except Exception:
            logger.exception("اطلاعِ تأیید به کاربر ناموفق بود")
        await cb.answer("✅ تأیید شد و به کاربر اطلاع داده شد.")
        return

    # === PATCH_BIG_CHARGE_RESUME_V2 ===
    # کیف پول: به کاربر یک دکمهٔ «ادامهٔ واریز» می‌دهیم. عمداً FSMِ او را
    # از این‌جا دست‌کاری نمی‌کنیم: aiogram شیِ dispatcher را به هندلرها
    # تزریق نمی‌کند و دسترسی به storageِ کاربرِ دیگر شکننده است. با یک
    # دکمه، ادامهٔ کار در چتِ خودِ کاربر و با FSMContextِ خودش انجام
    # می‌شود — هم ساده‌تر، هم بی‌خطر.
    try:
        await bot.send_message(
            uid,
            f"✅ <b>درخواستت تأیید شد</b>\n\n"
            f"💵 مبلغ: <b>{rial(amount)}</b>\n\n"
            "برایِ دیدنِ شمارهٔ کارت و ادامهٔ واریز، دکمهٔ زیر را بزن 👇",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [hx_button("💳 ادامهٔ واریز", callback_data=f"bigok:{rid}",
                           style=ButtonStyle.SUCCESS)],
            ]))
    except Exception:
        logger.exception("اطلاعِ تأیید به کاربر ناموفق بود")
    await cb.answer("✅ تأیید شد و به کاربر اطلاع داده شد.")


# === PATCH_BIG_CHARGE_RESUME_V2 ===
@router.callback_query(F.data.startswith("bigok:"))
async def big_charge_resume(cb: CallbackQuery, state: FSMContext):
    """کاربر پس از تأییدِ مدیر، جریانِ کارت‌به‌کارت را از همین‌جا ادامه می‌دهد."""
    from models import BigChargeRequest
    rid = int(cb.data.split(":")[1])
    async with Session() as s:
        r = await s.get(BigChargeRequest, rid)
        if not r or r.user_telegram_id != cb.from_user.id:
            await cb.answer("این درخواست پیدا نشد.", show_alert=True)
            return
        if r.status == "used":
            await cb.answer("این تأیید قبلاً استفاده شده.", show_alert=True)
            return
        if r.status != "approved":
            await cb.answer("این درخواست هنوز تأیید نشده.", show_alert=True)
            return
        amount = r.amount

    card, holder = await _pick_card()
    if not card:
        await cb.answer("هنوز شمارهٔ کارت ثبت نشده؛ به پشتیبانی پیام بده.",
                        show_alert=True)
        return

    # === PATCH_BIG_CHARGE_RESUME_V2 ===
    # «used» فقط بعد از اینکه مطمئن شدیم کارت هست ثبت می‌شود؛ وگرنه با
    # هر خطایی تأییدِ کاربر می‌سوخت و گیر می‌کرد.
    from models import BigChargeRequest as _BCR
    async with Session() as s:
        r2 = await s.get(_BCR, rid)
        if r2:
            r2.status = "used"
            await s.commit()

    await state.clear()
    await state.set_state(Charge.sender_card)
    await state.update_data(amount=amount)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer(
        f"مبلغ <b>{rial(amount)}</b> را به کارت زیر واریز کن:\n\n"
        f"💳 <code>{card}</code>\n"
        f"🧑 {holder or '—'}\n\n"
        "💳 حالا <b>۴ رقمِ آخرِ کارتی</b> که از آن واریز می‌کنی را بفرست "
        "(برای بررسیِ سریع‌ترِ رسید).\n"
        "<i>اگر با شبا/شماره‌حساب واریز می‌کنی یا نمی‌دانی، دکمهٔ مربوطه را بزن.</i>",
        reply_markup=await smart_skip_kb())
    await cb.answer()


async def _charge_proceed(message: Message, state: FSMContext, amount: int, uid: int):
    """مرحلهٔ بعد از انتخاب مبلغ: نمایش کارت و درخواست ۴ رقمِ آخرِ کارتِ مبدأ."""
    # === PATCH_BIG_CHARGE_COORDINATE_V1 ===
    if await _big_charge_gate(message, state, amount):
        await message.answer("به منوی اصلی برگشتی.", reply_markup=await smart_home_kb(uid))
        return
    await state.update_data(amount=amount)
# === PATCH_SECOND_CARD_ROTATE_V1 ===
    card, holder = await _pick_card()
    support = await get_pset("support_contact", "")
    if card:
        await state.set_state(Charge.sender_card)
        # === PATCH_PLATFORM_CARD_MINIAPP_V1 ===
        from urllib.parse import quote
        webhook_base = await get_pset("platform_zarinpal_webhook_base", WEBHOOK_BASE or "")
        skip_kb = await smart_skip_kb()  # PATCH_PLATFORM_SMART_HOME_MENU_V1
        # === PATCH_PLATFORM_CARD_MINIAPP_TOGGLE_V1 ===
        miniapp_on = (await get_pset("platform_card_miniapp_enabled", "1")) == "1"
        if miniapp_on and webhook_base and webhook_base.startswith("https://"):
            miniapp_url = (f"{webhook_base}/pcard-view?card={quote(card)}"
                           f"&holder={quote(holder or '')}&amount={quote(str(amount))}")
            wa = WebAppInfo(url=miniapp_url)
            # هر دو حالت (inline/reply) را پشتیبانی می‌کنیم؛ دکمه به همون
            # کیبوردی که قراره زیرِ همین پیام بیاد اضافه می‌شه، نه یه پیامِ جدا.
            if isinstance(skip_kb, InlineKeyboardMarkup):
                skip_kb.inline_keyboard = (
                    [[InlineKeyboardButton(text="🌐 نمایشِ شماره‌کارت (مینی‌اپ)", web_app=wa)]]
                    + skip_kb.inline_keyboard)
            else:
                skip_kb.keyboard = (
                    [[KeyboardButton(text="🌐 نمایشِ شماره‌کارت (مینی‌اپ)", web_app=wa)]]
                    + skip_kb.keyboard)
        await message.answer(
            f"مبلغ <b>{rial(amount)}</b> را به کارت زیر واریز کن:\n\n"
            f"💳 <code>{card}</code>\n"
            f"🧑 {holder or '—'}\n\n"
            f"💳 حالا <b>۴ رقمِ آخرِ کارتی</b> که از آن واریز می‌کنی را بفرست "
            f"(برای بررسیِ سریع‌ترِ رسید).\n"
            f"<i>اگر با شبا/شماره‌حساب واریز می‌کنی یا نمی‌دانی، دکمهٔ مربوطه را بزن.</i>",
            reply_markup=skip_kb,
        )
    else:
        await state.clear()
        await message.answer(
            "💬 هنوز شماره کارت برای شارژ کارت‌به‌کارت ثبت نشده است.\n"
            "لطفاً برای پرداخت به پشتیبانی پیام بده.",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[support_btn_row(support)]),
        )
        await message.answer("به منوی اصلی برگشتی.", reply_markup=await smart_home_kb(uid))


@router.callback_query(F.data == "charge_crypto")
async def charge_crypto(cb: CallbackQuery):
    await cb.answer("شارژ با ارز دیجیتال به‌زودی اضافه می‌شود.", show_alert=True)


# ─────────── شارژ کیف پول پلتفرم با NOWPayments ───────────

class ChargeNowPay(StatesGroup):
    amount = State()    # مبلغ (به واحد انتخاب‌شده)


def _nowpay_unit_kb(selected: str = "") -> InlineKeyboardMarkup:
    """انتخاب واحد پرداخت: تومان یا دلار. واحد انتخاب‌شده با ✅ نشان داده می‌شود."""
    toman_txt = "✅ 💵 تومان" if selected == "toman" else "💵 تومان"
    usd_txt = "✅ 💲 دلار (USD)" if selected == "usd" else "💲 دلار (USD)"
    return InlineKeyboardMarkup(inline_keyboard=[
        [hx_button(toman_txt, callback_data="cnp:unit:toman",
                              style=ButtonStyle.SUCCESS),
         hx_button(usd_txt, callback_data="cnp:unit:usd",
                              style=ButtonStyle.SUCCESS)],
        [hx_button("⬅️ بازگشت", callback_data="cnp:back",
                              style=ButtonStyle.DANGER)],
    ])


async def _nowpay_unit_prompt_text() -> str:
    """متن پیام انتخاب واحد، شامل نرخ لحظه‌ای و حداقل مبلغ (بالای انتخاب واحد)."""
    from tenant.gateways.crypto_pay import get_rate_smart
    brsapi_key = await get_pset("brsapi_key", "")
    manual_rate = float(await get_pset("platform_nowpay_toman_per_usd", "0") or "0")

    # اولویت: اگر ادمین نرخ دستی گذاشته، همان استفاده می‌شود؛
    # وگرنه نرخ آنلاین؛ و اگر آنلاین هم نبود، پیش‌فرض ۱۷۲٬۰۰۰.
    if manual_rate > 10000:
        rate = manual_rate
        is_live = False  # دستی
    else:
        rate = await get_rate_smart(brsapi_key)
        is_live = bool(rate and rate > 10000)
        if not is_live:
            rate = 174000

    MIN_USD = 0.5
    min_toman = int(round(MIN_USD * rate))
    rate_label = "💱 نرخ لحظه‌ای" if is_live else "💱 نرخ دلار"
    info = (f"{rate_label}: <b>{rial(int(rate))}</b> = ۱ دلار\n"
            f"🔻 حداقل مبلغ: <b>{rial(min_toman)}</b> (معادل <b>${MIN_USD}</b>)\n\n")

    return (
        "🪙 <b>شارژ با ارز دیجیتال (NOWPayments)</b>\n\n"
        f"{info}"
        "مبلغ را به چه واحدی وارد می‌کنی؟")


@router.callback_query(F.data == "charge_nowpay")
async def charge_nowpay_start(cb: CallbackQuery, state: FSMContext):
    await state.clear()
    nowpay_key = await get_pset("platform_nowpay_api_key", "")
    if not nowpay_key:
        await cb.answer("درگاه ارز دیجیتال فعال نیست.", show_alert=True)
        return
    await cb.answer()
    # پیام موقت تا کاربر بفهمد در حال بارگذاری است (نرخ ممکن است چند ثانیه بگیرد)
    loading = await cb.message.answer("⏳ در حال دریافت نرخ لحظه‌ای...")
    text = await _nowpay_unit_prompt_text()
    try:
        await loading.edit_text(text, reply_markup=_nowpay_unit_kb())
    except Exception:
        await cb.message.answer(text, reply_markup=_nowpay_unit_kb())


@router.callback_query(F.data.startswith("cnp:unit:"))
async def charge_nowpay_unit(cb: CallbackQuery, state: FSMContext):
    unit = cb.data.split(":")[2]  # toman | usd
    await state.update_data(cnp_unit=unit)
    await state.set_state(ChargeNowPay.amount)
    await cb.answer()

    # تیک روی واحد انتخاب‌شده: پیام قبلی را با کیبورد تیک‌خورده ویرایش کن
    try:
        await cb.message.edit_reply_markup(reply_markup=_nowpay_unit_kb(selected=unit))
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    if unit == "usd":
        prompt = (
            "💲 <b>مبلغ را به دلار وارد کن</b>\n\n"
            "فقط عدد بفرست. مثال: <code>5</code> یا <code>10.5</code>")
    else:
        prompt = (
            "💵 <b>مبلغ را به تومان وارد کن</b>\n\n"
            "فقط عدد بفرست. مثال: <code>200000</code>")

    await cb.message.answer(
        prompt,
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            hx_button("❌ لغو", callback_data="cnp:back")]]))


