@router.message(ChargeNowPay.amount, F.text)
async def charge_nowpay_custom_amount(msg: Message, state: FSMContext):
    data = await state.get_data()
    unit = data.get("cnp_unit", "toman")
    raw = (msg.text or "").strip().replace(",", "").replace("،", "")
    fa_map = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")
    raw = raw.translate(fa_map)

    if unit == "usd":
        # ورودی دلاری (می‌تواند اعشاری باشد)
        try:
            usd = float(raw)
        except ValueError:
            await msg.answer("❌ مبلغ باید عدد باشد. مثال: 5 یا 10.5")
            return
        if usd < 0.5:
            await msg.answer("❌ حداقل مبلغ ۰.۵ دلار است. دوباره بفرست:")
            return
        await state.clear()
        await _nowpay_proceed(msg, msg.from_user.id, 0, usd_direct=round(usd, 2))
    else:
        if not raw.isdigit() or int(raw) < 50000:
            await msg.answer("❌ مبلغ باید عدد و حداقل ۵۰٬۰۰۰ تومان باشد. دوباره بفرست:")
            return
        await state.clear()
        await _nowpay_proceed(msg, msg.from_user.id, int(raw))


async def _nowpay_proceed(message, tg_id: int, amount_toman: int,
                          usd_direct: float = 0):
    """
    محاسبهٔ مبلغ + ساخت فاکتور با کد پیگیری + دکمهٔ پرداخت که سایت واسط را
    (به‌صورت WebApp) باز می‌کند. انتخاب ارز و پرداخت داخل سایت واسط انجام می‌شود
    (USDT/TON بالا می‌آید نه بیت‌کوین).

    اگر usd_direct داده شود، مبلغ مستقیم دلاری است؛ وگرنه amount_toman تومانی.
    """
    from tenant.gateways.crypto_pay import get_rate_smart
    api_key = await get_pset("platform_nowpay_api_key", "")
    brsapi_key = await get_pset("brsapi_key", "")
    manual_rate = float(await get_pset("platform_nowpay_toman_per_usd", "0") or "0")

    if not api_key:
        await message.answer("❌ درگاه ارز دیجیتال تنظیم نشده.")
        return

    # همان منطق نمایش: نرخ دستی اول، وگرنه آنلاین، وگرنه پیش‌فرض
    if manual_rate > 10000:
        rate = manual_rate
    else:
        rate = await get_rate_smart(brsapi_key)
        if not rate or rate < 10000:
            rate = 174000

    # محاسبهٔ مبلغ بر اساس واحد
    if usd_direct and usd_direct > 0:
        amount_usd = round(usd_direct, 2)
        amount_toman = int(round(amount_usd * rate))
    else:
        amount_usd = round(amount_toman / rate, 2)

    if amount_usd < 0.5:
        await message.answer("❌ مبلغ خیلی کم است. حداقل حدود ۰.۵ دلار.")
        return

    # WebApp فقط با https کار می‌کند
    webhook_base = await get_pset("webhook_base", WEBHOOK_BASE or "")
    if not webhook_base or not webhook_base.startswith("https://"):
        await message.answer(
            "❌ آدرس سایت پرداخت (https) تنظیم نشده. به پشتیبانی اطلاع بده.")
        return

    # ساخت چرک‌نویس با مبلغِ از‌قبل‌مشخص (نوع platform) + کد پیگیری
    from tenant.gateways.payment_page import create_draft
    tc = await create_draft(bot_id=0, user_telegram_id=tg_id,
                            amount_toman=amount_toman, amount_usd=amount_usd,
                            kind="platform")
    pay_url = f"{webhook_base}/pay/{tc}"

    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("💳 پرداخت با ارز دیجیتال",
                              web_app=WebAppInfo(url=pay_url))],
        [hx_button("🔍 بررسی پرداخت", callback_data=f"cnp:check:{tc}")],
        [hx_button("⬅️ بازگشت به کیف پول", callback_data="cnp:back")],
    ])
    await message.answer(
        "🪙 <b>فاکتور پرداخت آماده شد</b>\n\n"
        f"💵 مبلغ: <b>{rial(amount_toman)}</b>\n"
        f"📌 معادل دلار: <b>${amount_usd}</b>\n"
        f"💱 نرخ لحظه‌ای: <b>{rial(int(rate))}</b> = ۱ دلار\n"
        f"📮 کد پیگیری: <code>{tc}</code>\n\n"
        "روی دکمهٔ زیر بزن تا صفحهٔ پرداخت داخل تلگرام باز شود. "
        "آن‌جا ارز پرداخت (USDT/TON و...) را انتخاب می‌کنی.\n"
        "بعد از تأیید شبکه، کیف پولت خودکار شارژ می‌شود.\n"
        "اگر پرداخت کردی ولی چند دقیقه بعد شارژ نشد، روی «🔍 بررسی پرداخت» بزن.",
        reply_markup=kb)


@router.callback_query(F.data.startswith("cnp:check:"))
async def cnp_check_payment(cb: CallbackQuery):
    """دکمهٔ «بررسی پرداخت» زیر فاکتور کاربر: وقتی IPN نرسیده، خودِ کاربر می‌تواند
    با زدن این دکمه وضعیت را مستقیماً از NOWPayments استعلام بگیرد و در صورت
    finished/confirmed بودن، کیف پولش بلافاصله شارژ شود (بدون نیاز به ادمین)."""
    tc = cb.data.split(":", 2)[2]
    await cb.answer("⏳ در حال بررسی پرداخت...")

    from sqlalchemy import select as _select
    from tenant.gateways.payment_page import ChargeDraft, ensure_table, _active_check_platform

    await ensure_table()
    async with Session() as s:
        draft = await s.scalar(_select(ChargeDraft).where(ChargeDraft.tracking_code == tc))

    if not draft:
        await cb.message.answer("❌ این فاکتور پیدا نشد؛ با پشتیبانی تماس بگیر.")
        return

    if draft.user_telegram_id != cb.from_user.id:
        await cb.answer("این فاکتور مربوط به تو نیست.", show_alert=True)
        return

    if draft.status == "paid":
        await cb.message.answer("✅ این فاکتور قبلاً تأیید شده و کیف پولت شارژ شده است.")
        return

    try:
        paid_now = await _active_check_platform(draft)
    except Exception:
        paid_now = False

    if paid_now:
        async with Session() as s:
            d = await s.scalar(_select(ChargeDraft).where(ChargeDraft.tracking_code == tc))
            if d and d.status != "paid":
                d.status = "paid"
                await s.commit()
        # پیام «کیف پول شما شارژ شد» با مبلغ دقیق را خودِ تابع _active_check_platform
        # ارسال می‌کند؛ اینجا فقط برای اطمینان کاربر یک تأیید کوتاه اضافه می‌شود.
        await cb.message.answer("✅ پرداخت تأیید شد.")
    else:
        await cb.message.answer(
            "⏳ هنوز پرداخت تو روی شبکه تأیید یا ثبت نشده.\n"
            "اگر همین الان واریز کردی، چند دقیقه صبر کن (بسته به شبکه ممکنه طول بکشد) "
            "و دوباره روی «بررسی پرداخت» بزن.\n"
            "اگر مطمئنی پرداخت انجام شده و بعد از چند بار تلاش هم شارژ نشد، "
            "شناسهٔ تراکنش (Transaction Hash) را برای پشتیبانی بفرست.")


