@router.callback_query(F.data.startswith("pnp:set:"))
async def pnp_set_field(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    field = cb.data.split(":")[2]
    prompts = {
        "key":  ("🔑 API Key جدید از nowpayments.io را بفرست:", PlatformNowPaySettings.api_key),
        "ipn":  ("🔐 IPN Secret جدید از nowpayments.io را بفرست:", PlatformNowPaySettings.ipn_secret),
        "rate": ("💱 نرخ دلار به تومان را وارد کن (عدد، مثلاً 750000).\n"
                 "برای استفاده از نرخ خودکار عدد 0 بفرست:", PlatformNowPaySettings.rate),
        "fee":  ("💸 درصد کارمزد اضافه را وارد کن (مثلاً 5 برای ۵٪).\n"
                 "برای بدون کارمزد عدد 0 بفرست:", PlatformNowPaySettings.fee),
    }
    if field not in prompts:
        await cb.answer()
        return
    text, state_cls = prompts[field]
    await state.update_data(pnp_field=field)
    await state.set_state(state_cls)
    cancel = InlineKeyboardMarkup(inline_keyboard=[[
        hx_button("❌ لغو", callback_data="set:platform_nowpay")]])
    await cb.message.answer(text, reply_markup=cancel)
    await cb.answer()


@router.message(
    StateFilter(PlatformNowPaySettings.api_key, PlatformNowPaySettings.ipn_secret,
                PlatformNowPaySettings.rate, PlatformNowPaySettings.fee),
    F.text)
async def pnp_receive_value(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        return
    data = await state.get_data()
    field = data.get("pnp_field", "")
    value = (msg.text or "").strip()
    key_map = {
        "key":  "platform_nowpay_api_key",
        "ipn":  "platform_nowpay_ipn_secret",
        "rate": "platform_nowpay_toman_per_usd",
        "fee":  "platform_nowpay_fee_percent",
    }
    if field in ("rate", "fee"):
        fa_map = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")
        value = value.translate(fa_map).replace(",", "")
        if not value.isdigit():
            await msg.answer("❌ فقط عدد وارد کن:")
            return
    await set_pset(key_map[field], value)
    await state.clear()
    pset_key = await get_pset("platform_nowpay_api_key", "")
    kb = _nowpay_admin_kb(bool(pset_key))
    await msg.answer("✅ ذخیره شد.", reply_markup=kb)
    await msg.answer(await _nowpay_admin_text(), reply_markup=kb)


