# === PATCH_PLATFORM_IDPAY_GATEWAY_V1 ===
# ───── درگاهِ آیدی‌پی (IDPay) — شارژِ ریالیِ کیف‌پولِ خودِ پلتفرم ─────

async def _idpay_admin_text() -> str:
    api_key = await get_pset("platform_idpay_api_key", "")
    webhook_override = await get_pset("platform_idpay_webhook_base", "")
    webhook_base = webhook_override or WEBHOOK_BASE or ""
    cb_url = f"{webhook_base or 'آدرس سرور'}/idpay/platform/callback"
    override_line = (
        f"\n🔧 آدرسِ پایهٔ دلخواه (اورراید): <code>{webhook_override}</code>\n"
        if webhook_override else
        "\n🔧 آدرسِ پایهٔ دلخواه: ❌ تنظیم نشده (از آدرسِ پیش‌فرضِ سرور استفاده می‌شه)\n"
    )
    return (
        "🏧 <b>تنظیمات درگاه آنلاین ریالی آیدی‌پی</b>\n\n"
        f"🔑 API Key: {'✅ ثبت‌شده' if api_key else '❌ ثبت‌نشده'}\n"
        f"{override_line}\n"
        "🔑 API Key را از پنلِ وب‌سرویسِ آیدی‌پی (idpay.ir) بردار.\n\n"
        "آدرسِ بازگشتِ پرداخت (Callback URL) که باید در تنظیماتِ درگاهِ "
        "آیدی‌پیت هم مجاز باشد:\n"
        f"<code>{cb_url}</code>\n\n"
        "💡 اگه می‌خوای این آدرس فرق کنه، از دکمهٔ «🔧 تغییرِ آدرسِ پایه» استفاده کن."
    )


def _idpay_admin_kb(has_key: bool) -> InlineKeyboardMarkup:
    rows = [
        [hx_button("🔑 ثبت/تغییر API Key", callback_data="idp:set:key")],
        [hx_button("🔧 تغییرِ آدرسِ پایه (Callback)", callback_data="idp:set:webhookbase")],
    ]
    if has_key:
        rows.append([hx_button("🧪 تست اتصال (ساخت تراکنش نمونه)", callback_data="idp:test")])
        rows.append([hx_button("🗑 حذف تنظیمات", callback_data="idp:delete",
                                          style=ButtonStyle.DANGER)])
    rows.append([hx_button("⬅️ بازگشت", callback_data="set:hub_pay")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


