@router.message(PlatformIdpaySettings.webhook_base, F.text)
async def idp_receive_webhookbase(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        return
    from urllib.parse import urlparse
    value = (msg.text or "").strip().rstrip("/")
    if value == "/default":
        value = ""
    elif value:
        parsed = urlparse(value)
        if (parsed.scheme != "https" or not parsed.netloc or parsed.username or parsed.password
                or parsed.query or parsed.fragment or any(ch.isspace() for ch in value)):
            await msg.answer("❌ آدرس نامعتبر است. فقط یک آدرس HTTPS مانند https://pay.example.ir بفرست.")
            return
    await set_pset("platform_idpay_webhook_base", value)
    await state.clear()
    mid = await get_pset("platform_idpay_api_key", "")
    kb = _idpay_admin_kb(bool(mid))
    await msg.answer("✅ ذخیره شد.", reply_markup=kb)
    await msg.answer(await _idpay_admin_text(), reply_markup=kb)


