@router.message(ChargeIdpay.amount, F.text)
async def charge_idpay_amount(msg: Message, state: FSMContext):
    fa_map = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")
    raw = (msg.text or "").strip().translate(fa_map).replace(",", "").replace("،", "")
    if not raw.isdigit() or int(raw) < 10_000:
        await msg.answer("❌ مبلغ باید عدد و حداقل ۱۰٬۰۰۰ تومان باشد. دوباره بفرست:")
        return
    await state.clear()
    await _idpay_proceed(msg, msg.from_user.id, int(raw))


async def _idpay_proceed(message, tg_id: int, amount_toman: int):
    import platform_idpay
    import time as _time
    api_key = await get_pset("platform_idpay_api_key", "")
    if not api_key:
        await message.answer("❌ درگاه آیدی‌پی تنظیم نشده.")
        return
    webhook_base = await get_pset("platform_idpay_webhook_base", WEBHOOK_BASE or "")
    if not webhook_base or not webhook_base.startswith("https://"):
        await message.answer("❌ آدرس سرور (https) تنظیم نشده. به پشتیبانی اطلاع بده.")
        return
    cb_url = f"{webhook_base}/idpay/platform/callback"
    order_id = f"botsaz_{tg_id}_{int(_time.time() * 1000)}"
    ok, res, link = await platform_idpay.request_payment(
        api_key, order_id, amount_toman, f"شارژ کیف‌پول بات‌ساز — کاربر {tg_id}", cb_url)
    if not ok:
        await message.answer(f"❌ ساختِ پرداخت ناموفق بود:\n{res}")
        return
    tx_id = res
    async with Session() as s:
        s.add(PlatformTxn(user_telegram_id=tg_id, amount=float(amount_toman),
                          kind="idpay_pending",
                          note=f"idpay_id={tx_id}|order_id={order_id}|toman={amount_toman}"))
        await s.commit()
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("💳 پرداخت با آیدی‌پی", url=link, style=ButtonStyle.PRIMARY)],
        [hx_button("🔍 بررسی پرداخت", callback_data=f"idp:check:{order_id}")],
        [hx_button("⬅️ بازگشت به کیف پول", callback_data="idp:chg:back")],
    ])
    await message.answer(
        "🏧 <b>فاکتور پرداخت آیدی‌پی آماده شد</b>\n\n"
        f"💵 مبلغ: <b>{rial(amount_toman)}</b>\n\n"
        "روی «💳 پرداخت با آیدی‌پی» بزن، پرداخت را در همان صفحه انجام بده "
        "و به ربات برگرد.\nبعد از تأیید، کیف‌پولت خودکار شارژ می‌شود. اگر چند دقیقه "
        "بعد از پرداخت شارژ نشد، روی «🔍 بررسی پرداخت» بزن.",
        reply_markup=kb)


@router.callback_query(F.data.startswith("idp:check:"))
async def idp_check_payment(cb: CallbackQuery):
    """دکمهٔ «بررسی پرداخت»: برای وقتی که کالبکِ آیدی‌پی به هر دلیلی (شبکه،
    بستنِ زودهنگامِ مرورگر) به سرور نرسیده — همینجا مستقیم استعلام می‌گیریم."""
    import platform_idpay
    from sqlalchemy import select as _select
    order_id = cb.data.split(":", 2)[2]
    await cb.answer("⏳ در حال بررسی پرداخت...")

    async with Session() as s:
        pending = await s.scalar(
            _select(PlatformTxn).where(
                PlatformTxn.kind == "idpay_pending",
                PlatformTxn.note.contains(f"order_id={order_id}"),
            ))
        already = await s.scalar(
            _select(PlatformTxn).where(
                PlatformTxn.kind == "idpay_charge",
                PlatformTxn.note.contains(f"order_id={order_id}"),
            ))

    if already:
        await cb.message.answer("✅ این فاکتور قبلاً تأیید شده و کیف پولت شارژ شده است.")
        return
    if not pending:
        await cb.message.answer("❌ این فاکتور پیدا نشد؛ با پشتیبانی تماس بگیر.")
        return
    if pending.user_telegram_id != cb.from_user.id:
        await cb.answer("این فاکتور مربوط به تو نیست.", show_alert=True)
        return

    api_key = await get_pset("platform_idpay_api_key", "")
    note = pending.note or ""
    tx_id = ""
    for part in note.split("|"):
        if part.startswith("idpay_id="):
            tx_id = part[len("idpay_id="):]
    ok, res, verified_amount = await platform_idpay.verify_payment(api_key, tx_id, order_id)
    if not ok:
        await cb.message.answer(
            "⏳ هنوز پرداخت تأیید نشده.\n"
            "اگر همین الان پرداخت کردی، چند لحظه صبر کن و دوباره امتحان کن.\n"
            f"جزئیات: {res}")
        return
    amount_toman = verified_amount or int(float(pending.amount))
    new_bal = await _platform_idpay_credit(
        cb.from_user.id, amount_toman, f"order_id={order_id}|track_id={res}",
        marker=f"order_id={order_id}")
    if new_bal is None:
        await cb.message.answer("✅ این فاکتور قبلاً تأیید شده و کیف پولت شارژ شده است.")
        return
    async with Session() as s:
        p = await s.scalar(
            _select(PlatformTxn).where(
                PlatformTxn.kind == "idpay_pending",
                PlatformTxn.note.contains(f"order_id={order_id}"),
            ).with_for_update())
        if p:
            p.kind = "idpay_pending_done"
            await s.commit()
    await cb.message.answer(
        f"✅ پرداخت تأیید شد. کیف پولت به‌مقدار <b>{rial(amount_toman)}</b> شارژ شد.\n"
        f"💰 موجودی فعلی: <b>{rial(new_bal)}</b>")


# === PATCH_PLATFORM_SMS_AUTOCHARGE_V1 ===
# ───── شارژِ خودکار با مبلغِ اختصاصی (فورواردِ پیامکِ بانکی) ─────
# طرزِ کار: یه اپِ فورواردرِ پیامک (مثلِ «SMS Forwarder») رویِ گوشیِ متصل به
# حسابِ بانکی نصب می‌شه و متنِ خامِ پیامکِ واریزی رو به وبهوکِ زیر می‌فرسته.
# سرور مبلغ رو از متنِ پیامک استخراج می‌کنه و اگه دقیقاً با یکی از
# «مبلغ‌هایِ اختصاصیِ» درحالِ‌انتظار برابر بود، خودکار (بدونِ رسید) تایید
# می‌کنه. هیچ لاگین/رمزِ بانکی درکار نیست — فقط متنِ پیامک.

_SMS_PENDING_TTL_MIN = 15  # پیش‌فرض؛ از تنظیمات هم قابلِ‌تغییره (_sms_ttl_min)


async def _sms_ttl_min() -> int:
    """مهلتِ انقضایِ فاکتورِ شارژِ خودکار، به دقیقه — قابلِ‌تنظیم از پنل."""
    try:
        return max(2, min(int(await get_pset("platform_sms_ttl_min", str(_SMS_PENDING_TTL_MIN))), 120))
    except (TypeError, ValueError):
        return _SMS_PENDING_TTL_MIN
_SMS_OFFSET_MIN_DEFAULT = 100
_SMS_OFFSET_MAX_DEFAULT = 4999


def _sms_extract_rial_amounts(text: str) -> list[int]:
    """همه‌ی عددهایی که کنارِ کلمه‌ی «ریال» تویِ متنِ پیامک اومدن رو برمی‌گردونه
    (چون فرمتِ پیامکِ بانک‌هایِ مختلف فرق داره، این عمداً بازه — دنبالِ یه
    عددِ خاص با برچسبِ ثابت نمی‌گرده، هر عددِ کنارِ «ریال» رو کاندید می‌کنه)."""
    import re
    fa_map = str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789")
    norm = (text or "").translate(fa_map)
    out = []
    # === PATCH_SMS_DEPOSIT_HARDEN_V1 ===
    # خطِ «مانده/موجودی» و «برداشت» واریز نیست؛ قبلاً هر عددِ کنارِ «ریال» (از جمله
    # مانده‌حساب) کاندید می‌شد و اگر تصادفاً با مبلغِ یک فاکتورِ باز یکی بود، شارژ می‌شد.
    for line in norm.splitlines() or [norm]:
        if re.search(r"مانده|موجودی|برداشت|انتقال\s*از|خرید", line):
            continue
        for m in re.finditer(r"([\d,،٬]{4,})\s*ریال", line):
            if line[max(0, m.start() - 2):m.start()].strip().endswith("-"):
                continue   # مبلغِ منفی = برداشت
            digits = re.sub(r"[,،٬]", "", m.group(1))
            if digits.isdigit():
                out.append(int(digits))
    return out


async def _sms_admin_text() -> str:
    enabled = (await get_pset("platform_sms_enabled", "0")) == "1"
    secret = await get_pset("platform_sms_secret", "")
    webhook_base = await get_pset("platform_zarinpal_webhook_base", WEBHOOK_BASE or "")
    off_min = await get_pset("platform_sms_offset_min", str(_SMS_OFFSET_MIN_DEFAULT))
    off_max = await get_pset("platform_sms_offset_max", str(_SMS_OFFSET_MAX_DEFAULT))
    ttl = await _sms_ttl_min()  # === PATCH_PLATFORM_SMS_TTL_SETTING_V1 ===
    url_line = (f"<code>{webhook_base}/sms/platform/deposit/{secret}</code>"
               if secret else "❌ اول باید یه‌بار دکمهٔ «فعال‌سازی» رو بزنی تا یه کلیدِ امنیتی ساخته بشه.")
    return (
        "📲 <b>شارژِ خودکار با مبلغِ اختصاصی (فورواردِ پیامکِ بانکی)</b>\n\n"
        f"وضعیت: {'✅ فعال' if enabled else '❌ غیرفعال'}\n"
        f"بازه‌ی افزایشِ اختصاصی: {off_min} تا {off_max} تومان\n"
        f"مهلتِ فاکتور: {ttl} دقیقه\n\n"
        "📖 <b>راهنما:</b>\n"
        "۱) یه اپِ فورواردرِ پیامک (مثلِ «SMS Forwarder») رویِ گوشیِ متصل "
        "به حسابِ بانکیت نصب کن.\n"
        "۲) تویِ تنظیماتِ اون اپ، یه Webhook با آدرسِ زیر بساز که با هر "
        "پیامکِ واریزی صداش بزنه:\n"
        f"{url_line}\n"
        "۳) مطمئن شو متنِ خامِ پیامک (نه فقط بخشی از اون) تویِ بدنه‌ی "
        "درخواست فرستاده می‌شه (فیلدی به اسمِ text یا message).\n\n"
        "⚠️ این کلید محرمانه‌ست — اگه لو بره، دیگه‌ای می‌تونه با فرستادنِ "
        "متنِ جعلی کیفِ پول شارژ کنه. اگه شک کردی، «🔄 ساختِ کلیدِ تازه» رو بزن."
    )


def _sms_admin_kb(enabled: bool, has_secret: bool) -> InlineKeyboardMarkup:
    rows = [
        [hx_button(("🔴 غیرفعال کن" if enabled else "🟢 فعال‌سازی"), callback_data="pfsms:toggle",
                   style=(ButtonStyle.DANGER if enabled else ButtonStyle.SUCCESS))],
    ]
