@router.message(PlatformSmsSettings.offset_min, F.text)
async def pfsms_offset_min_save(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        return
    fa_map = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")
    raw = (msg.text or "").strip().translate(fa_map)
    # === PATCH_PLATFORM_SMS_OFFSET_CAP_V1 ===
    # این عدد فقط قراره «امضایِ» چندرقمیِ آخرِ مبلغ باشه تا هر سفارش یکتا
    # باشه — نه یه مبلغِ اضافیِ واقعی. سقفِ ۵۰هزار تومان می‌ذاریم تا یه
    # ورودیِ اشتباه (مثلاً چندمیلیون) باعثِ گیج‌شدنِ مشتری نشه.
    if not raw.isdigit() or int(raw) < 10 or int(raw) > 50_000:
        await msg.answer("❌ باید عددی بینِ ۱۰ تا ۵۰٬۰۰۰ باشد (این فقط یه امضایِ کوچیکه، نه مبلغِ اضافیِ واقعی). دوباره بفرست:")
        return
    await state.update_data(off_min=int(raw))
    await state.set_state(PlatformSmsSettings.offset_max)
    await msg.answer("🔢 حالا حداکثرِ مبلغِ افزایشی رو بفرست (بینِ ۱۰ تا ۵۰٬۰۰۰، مثلاً 4999):")


@router.message(PlatformSmsSettings.offset_max, F.text)
async def pfsms_offset_max_save(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        return
    fa_map = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")
    raw = (msg.text or "").strip().translate(fa_map)
    data = await state.get_data()
    off_min = data.get("off_min", _SMS_OFFSET_MIN_DEFAULT)
    # === PATCH_PLATFORM_SMS_OFFSET_CAP_V1 ===
    if not raw.isdigit() or int(raw) <= off_min or int(raw) > 50_000:
        await msg.answer(f"❌ باید عددی بینِ {off_min} تا ۵۰٬۰۰۰ باشد. دوباره بفرست:")
        return
    await set_pset("platform_sms_offset_min", str(off_min))
    await set_pset("platform_sms_offset_max", raw)
    await state.clear()
    enabled = (await get_pset("platform_sms_enabled", "0")) == "1"
    secret = await get_pset("platform_sms_secret", "")
    await msg.answer("✅ ذخیره شد.")
    await msg.answer(await _sms_admin_text(), reply_markup=_sms_admin_kb(enabled, bool(secret)))


