async def _sms_pick_unique_amount(base_toman: int) -> int:
    """یه مبلغِ اختصاصی (base + یه افزایشِ تصادفی) می‌سازه که بینِ
    مبلغ‌هایِ درحالِ‌انتظارِ فعلی (که هنوز منقضی نشدن) تکراری نباشه."""
    import random
    from sqlalchemy import select as _select
    from datetime import datetime, timedelta
    off_min = int(await get_pset("platform_sms_offset_min", str(_SMS_OFFSET_MIN_DEFAULT)))
    off_max = int(await get_pset("platform_sms_offset_max", str(_SMS_OFFSET_MAX_DEFAULT)))
    # === PATCH_PLATFORM_SMS_OFFSET_CAP_V1 ===
    # سقفِ دفاعی: حتی اگه یه‌جوری تنظیماتِ دیتابیس خرابیده باشه (مثلِ همون
    # موردی که قبلاً اتفاق افتاد)، این عدد هیچ‌وقت نباید بیشتر از چندده‌هزار
    # تومان بشه — این فقط قراره یه امضایِ چندرقمی باشه، نه مبلغِ اضافی.
    off_min = max(10, min(off_min, 50_000))
    off_max = max(off_min + 1, min(off_max, 50_000))
    cutoff = datetime.utcnow() - timedelta(minutes=await _sms_ttl_min())
    async with Session() as s:
        pending = (await s.scalars(_select(PlatformTxn).where(
            PlatformTxn.kind == "sms_pending", PlatformTxn.created_at >= cutoff))).all()
        taken = {int(float(p.amount)) for p in pending}
    for _ in range(30):
        candidate = base_toman + random.randint(off_min, off_max)
        if candidate not in taken:
            return candidate
    return base_toman + random.randint(off_min, off_max) + random.randint(1, 500)


