# === PATCH_PLATFORM_SMS_PRESET_AMOUNTS_V1 ===
async def _sms_create_order(msg: Message, tg_id: int, base: int):
    """هستهٔ مشترکِ ساختِ فاکتورِ شارژِ خودکار — چه از دکمه‌یِ مبلغِ آماده
    صدا زده بشه، چه از تایپِ عددِ دلخواه."""
    unique_amount = await _sms_pick_unique_amount(base)
    card = await get_pset("platform_card", "")
    holder = await get_pset("card_holder", "")
    ttl = await _sms_ttl_min()
    async with Session() as s:
        _txn = PlatformTxn(user_telegram_id=tg_id, amount=float(unique_amount),
                          kind="sms_pending", note=f"card={card}")
        s.add(_txn)
        await s.commit()
        await s.refresh(_txn)
        txn_id = _txn.id
    kb = InlineKeyboardMarkup(inline_keyboard=[
        # === PATCH_PLATFORM_SMS_REAL_COPY_V1 ===
        # قبلاً این دو تا دکمه فقط یه Alert نشون می‌دادن («... کپی کن ✅») —
        # هیچ کپیِ واقعی‌ای انجام نمی‌شد چون تلگرام اجازه نمی‌ده یه دکمه‌ی
        # معمولی مستقیم چیزی رو تویِ کلیپ‌بردِ کاربر بذاره؛ برایِ این کار
        # باید از نوعِ خاصِ copy_text استفاده بشه، نه callback_data.
        [hx_button("📋 کپی مبلغ (ریال)", copy_text=CopyTextButton(text=str(unique_amount * 10))),
         hx_button("📋 کپی شماره کارت", copy_text=CopyTextButton(text=card))],
        # === PATCH_PLATFORM_SMS_CHECK_BUTTON_V1 ===
        [hx_button("🔍 بررسیِ واریز", callback_data=f"pfsms:check:{txn_id}", style=ButtonStyle.SUCCESS)],
        # === PATCH_PLATFORM_SMS_SUPPORT_BUTTON_V1 ===
        # درخواستِ مدیر: اگه شارژ نشد، یه راهِ مستقیم به پشتیبانی زیرِ همین فاکتور باشه.
        [hx_button("💬 پیام به پشتیبانی (در صورت شارژ نشدن)", url="https://t.me/BaBotSaz?direct")],
        [hx_button("❌ لغو سفارش", callback_data="pfsms:chg:cancel", style=ButtonStyle.DANGER)],
    ])
    # === PATCH_PLATFORM_SMS_INVOICE_AUTODELETE_V1 ===
    # درخواستِ مدیر: بعداً که این سفارش با موفقیت شارژ شد، خودِ همین پیامِ
    # فاکتور پاک بشه. برای این کار شناسه‌ی پیام رو تویِ note ذخیره می‌کنیم
    # (به‌جایِ اضافه‌کردنِ ستونِ جدید به دیتابیس) تا موقعِ شارژ بتونیم پیداش کنیم.
    sent_invoice = await msg.answer(
        "📲 <b>شارژ خودکار کارت‌به‌کارت</b>\n\n"
        f"❗ برای تأییدِ خودکار، <b>دقیقاً</b> این مبلغ رو واریز کن:\n\n"
        f"💰 <code>{unique_amount:,}</code> تومان\n"
        f"🌐 <code>{unique_amount*10:,}</code> ریال\n\n"
        f"💳 <code>{card}</code>\n"
        f"🧑 {holder or '—'}\n\n"
        f"⏰ مهلت: {ttl} دقیقه. سه رقمِ آخرِ مبلغ، کدِ اختصاصیِ توئه. "
        "اگه مبلغ رو تغییر بدی، خودکار تأیید نمی‌شه. تمامِ همین مبلغ به کیفِ پول اضافه می‌شه.\n\n"
        "<i>💡 برایِ کپی، کافیه رویِ خودِ عددها (که آبی‌رنگ‌ان) بزنی، یا از دکمه‌هایِ زیر استفاده کنی.</i>",
        reply_markup=kb)
    try:
        async with Session() as s:
            _txn2 = await s.get(PlatformTxn, txn_id)
            if _txn2:
                _txn2.note = f"card={card}|mid={sent_invoice.message_id}|chat={sent_invoice.chat.id}"
                await s.commit()
    except Exception:
        logger.exception("ذخیره‌ی شناسه‌ی پیامِ فاکتور برایِ حذفِ خودکار ناموفق بود")


# === PATCH_PLATFORM_SMS_CHECK_BUTTON_V1 ===
@router.callback_query(F.data.startswith("pfsms:check:"))
async def pfsms_check_payment(cb: CallbackQuery):
    """بررسیِ وضعیتِ همین سفارشِ خاص. توجه: این دکمه با بانک تماس نمی‌گیره
    (چون هیچ APIای وصل نیست، فقط منتظرِ پیامکِ فورواردشده‌ایم) — فقط وضعیتِ
    فعلی‌ای که خودِ سیستم قبلاً (با پیامک) ثبت کرده رو نشون می‌ده. یه‌بار
    بیشتر شارژ نمی‌کنه، چون شارژِ واقعی فقط تویِ _sms_match_and_credit
    (موقعِ رسیدنِ پیامک) اتفاق می‌افته، نه اینجا."""
    from sqlalchemy import select as _select
    try:
        txn_id = int(cb.data.rsplit(":", 1)[1])
    except Exception:
        await cb.answer("شناسه نامعتبر است.", show_alert=True)
        return
    await cb.answer("⏳ در حال بررسی...")
    async with Session() as s:
        txn = await s.get(PlatformTxn, txn_id)
    if not txn or txn.user_telegram_id != cb.from_user.id:
        await cb.message.answer("❌ این سفارش پیدا نشد.")
        return
    if txn.kind in ("sms_pending_done",):
        await cb.message.answer(
            "✅ این سفارش قبلاً به‌صورتِ خودکار تأیید و کیفِ پولت شارژ شده — "
            "اگه پیامِ شارژ رو ندیدی، از «💰 موجودی کیف پول» چک کن.")
    elif txn.kind == "sms_pending":
        from datetime import datetime, timedelta
        expired = txn.created_at < datetime.utcnow() - timedelta(minutes=await _sms_ttl_min())
        if expired:
            await cb.message.answer(
                "⌛️ مهلتِ این سفارش تموم شده و هیچ واریزی‌ای براش ثبت نشد. "
                "یه سفارشِ تازه بساز و دقیقاً همون مبلغِ جدید رو واریز کن.")
        else:
            await cb.message.answer(
                "⏳ هنوز پیامکِ واریزیِ منطبق با این مبلغِ دقیق به سیستم نرسیده.\n"
                "مطمئن شو دقیقاً همون عددی که بالا نوشته شده (نه یه سفارشِ قدیمی‌تر) رو واریز کردی. "
                "اگه همین الان واریز کردی، چند ثانیه صبر کن و دوباره همین دکمه رو بزن.")
    elif txn.kind == "sms_expired":
        # === PATCH_PLATFORM_SMS_EXPIRY_NOTIFY_V1 ===
        await cb.message.answer(
            "⌛️ مهلتِ این سفارش تموم شده و هیچ واریزی‌ای براش ثبت نشد. "
            "یه سفارشِ تازه بساز و دقیقاً همون مبلغِ جدید رو واریز کن.")
    else:
        await cb.message.answer("⚠️ وضعیتِ این سفارش نامشخصه؛ با پشتیبانی تماس بگیر.")


# === PATCH_PLATFORM_SMS_EXPIRY_NOTIFY_V1 ===
async def sms_expiry_notify_loop(interval_sec: int = 60):
    """هر یه دقیقه فاکتورهایِ «sms_pending»یِ منقضی‌شده رو پیدا می‌کنه، به
    کاربر پیامِ «فاکتورت منقضی شد» می‌ده، و وضعیتشون رو به sms_expired
    تغییر می‌ده تا دوباره اطلاع داده نشن (idempotent)."""
    import asyncio
    from datetime import datetime, timedelta
    from sqlalchemy import select as _select, update as _update
    from main_platform import platform_bot as _pbot
    await asyncio.sleep(30)
    while True:
        try:
            ttl = await _sms_ttl_min()
            cutoff = datetime.utcnow() - timedelta(minutes=ttl)
            async with Session() as s:
                stale = (await s.scalars(_select(PlatformTxn).where(
                    PlatformTxn.kind == "sms_pending",
                    PlatformTxn.created_at < cutoff,
                ))).all()
                stale_ids = [(p.id, p.user_telegram_id, p.amount, p.created_at) for p in stale]
            for txn_id, tg_id, amount, order_created_at in stale_ids:
                async with Session() as s:
                    claim = await s.execute(_update(PlatformTxn).where(
                        PlatformTxn.id == txn_id, PlatformTxn.kind == "sms_pending",
                    ).values(kind="sms_expired"))
                    await s.commit()
                if claim.rowcount == 0:
                    continue  # یکی دیگه (مثلاً همزمان match شد) قبل از ما دستش رو برد

                # === PATCH_PARTNER_ORDER_SMS_AUTO_V1 ===
                # اگه این فاکتور مالِ خریدِ عمدهٔ همکار بوده، مسیرش کاملاً
                # جداست: خودِ سفارش از قبل تویِ PartnerStockOrder با وضعیتِ
                # pending وجود داره، پس نیازی به ساختنِ WalletCharge نیست؛
                # فقط باید به همکار و ادمین اطلاع بدیم و از ادمین بپرسیم آیا
                # واقعاً واریز شده — با دکمه‌هایِ مخصوصِ همین سفارش.
                _pp_order_id = None
                async with Session() as _s0:
                    _pend_row = await _s0.get(PlatformTxn, txn_id)
                    _note0 = (_pend_row.note if _pend_row else "") or ""
                for part in _note0.split("|"):
                    if part.startswith("pp_order="):
                        try:
                            _pp_order_id = int(part.split("=", 1)[1])
                        except ValueError:
                            _pp_order_id = None
                if _pp_order_id is not None:
                    try:
                        await _pbot.send_message(
                            tg_id,
                            "⌛️ <b>فاکتورِ خریدِ عمدهٔ خودکارت منقضی شد</b>\n\n"
                            f"مهلتِ زمانی برایِ مبلغِ <code>{int(float(amount)):,}</code> تومان تموم شد و "
                            "واریزی‌ای براش ثبت نشد.\n"
                            "این سفارش برایِ بررسیِ دستی برایِ مدیریت ارسال شد؛ اگه واقعاً واریز کرده باشی "
                            "و پیامکش به سیستم نرسیده باشه، به‌زودی بررسی و در صورتِ تاییدِ مدیریت به موجودیت اضافه می‌شود.")
                    except Exception:
                        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
                    try:
                        if PLATFORM_ADMIN_ID:
                            kb_pp_review = InlineKeyboardMarkup(inline_keyboard=[[
                                hx_button("✅ بله، همکار واریز کرده", callback_data=f"ppsmsexp:yes:{_pp_order_id}",
                                         style=ButtonStyle.SUCCESS),
                                hx_button("❌ خیر، واریز نکرده", callback_data=f"ppsmsexp:no:{_pp_order_id}",
                                         style=ButtonStyle.DANGER),
                            ]])
                            try:
                                async with Session() as s3:
                                    _u = await get_user(s3, tg_id)
                                    _uname_line = f"@{_u.username}" if _u and _u.username else (
                                        _u.full_name if _u and _u.full_name else "—")
                            except Exception:
                                _uname_line = "—"
                            try:
                                _dt_local = order_created_at.replace(tzinfo=ZoneInfo("UTC")).astimezone(IRAN_TZ)
                                try:
                                    import jdatetime
                                    _dt_txt = jdatetime.datetime.fromgregorian(
                                        datetime=_dt_local.replace(tzinfo=None)).strftime("%Y/%m/%d — %H:%M")
                                except ImportError:
                                    _dt_txt = _dt_local.strftime("%Y-%m-%d %H:%M")
                            except Exception:
                                _dt_txt = "—"
                            await _pbot.send_message(
                                PLATFORM_ADMIN_ID,
                                "⌛️ <b>فاکتورِ خریدِ عمدهٔ همکار منقضی شد و پیامکِ بانکی نرسید</b>\n\n"
                                f"👤 همکار: <code>{tg_id}</code> ({_uname_line})\n"
                                f"💵 مبلغِ فاکتور: {rial(amount)}\n"
                                f"🕒 تاریخ و ساعتِ سفارش: {_dt_txt}\n"
                                f"🔢 سفارشِ خریدِ عمده: #{_pp_order_id}\n\n"
                                "آیا این همکار واقعاً این مبلغ را واریز کرده؟ اگر بله را بزنید، "
                                "سفارش تایید و رشد/حرفه‌ای‌های خریداری‌شده به موجودیِ ربات همکار اضافه می‌شود.",
                                reply_markup=kb_pp_review)
                    except Exception:
                        logger.exception("ارسالِ گزارشِ بررسیِ دستیِ خریدِ عمدهٔ منقضی‌شده به ادمین ناموفق بود")
                    continue  # این سفارش دیگه به مسیرِ WalletCharge نره

                try:
                    await _pbot.send_message(
                        tg_id,
                        "⌛️ <b>فاکتورِ شارژِ خودکارت منقضی شد</b>\n\n"
                        f"مهلتِ ۱۵دقیقه‌ایِ مبلغِ <code>{int(float(amount)):,}</code> تومان تموم شد و "
                        "واریزی‌ای براش ثبت نشد.\n"
                        "اگه هنوز می‌خوای شارژ کنی، از «📲 شارژِ خودکار کارت‌به‌کارت» یه سفارشِ تازه بساز.\n\n"
                        "این سفارش برایِ بررسیِ دستی هم برایِ پشتیبانی ارسال شد؛ اگه واقعاً واریز کرده باشی "
                        "و پیامکش به سیستم نرسیده باشه، به‌زودی بررسی و در صورتِ تاییدِ ادمین شارژ می‌شود.")
                except Exception:
                    logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

                # === PATCH_PLATFORM_SMS_EXPIRY_ADMIN_MANUAL_REVIEW_V1 ===
                # درخواستِ مدیر: وقتی فاکتور منقضی می‌شه ولی پیامکِ خودکار نرسیده،
                # به ادمین اطلاع بده (با اطلاعاتِ کاربر/مبلغ) و بپرس آیا واقعاً
                # واریز انجام شده یا نه؛ با دو دکمهٔ تایید/رد. اگه تایید کرد، کیفِ
                # پولِ کاربر شارژ می‌شه و در گزارشِ ماه‌به‌ماهِ رسیدها (که از
                # WalletCharge با status=approved می‌خونه) هم ثبت می‌شه.
                try:
                    async with Session() as s2:
                        pend_ch = WalletCharge(
                            user_telegram_id=tg_id, amount=float(amount),
                            receipt_file_id=None,
                            receipt_text=f"شارژِ خودکارِ کارت‌به‌کارت (پیامکی) — سفارش #{txn_id} منقضی شد؛ "
                                        "بررسیِ دستیِ ادمین لازم است.",
                            sender_card4=None, status="pending")
                        s2.add(pend_ch)
                        await s2.flush()
                        wc_id = pend_ch.id
                        await s2.commit()
                    if PLATFORM_ADMIN_ID:
                        kb_review = InlineKeyboardMarkup(inline_keyboard=[[
                            hx_button("✅ بله، واریز کرده", callback_data=f"smsexp:yes:{wc_id}",
                                     style=ButtonStyle.SUCCESS),
                            hx_button("❌ خیر، واریز نکرده", callback_data=f"smsexp:no:{wc_id}",
                                     style=ButtonStyle.DANGER),
                        ]])
                        # === PATCH_PLATFORM_SMS_EXPIRY_ADMIN_USERNAME_TIME_V1 ===
                        # درخواستِ مدیر: یوزرنیمِ کاربر و تاریخ/ساعتِ سفارش هم
                        # تویِ پیامِ بررسیِ دستی به ادمین نشون داده بشه.
                        try:
                            async with Session() as s3:
                                _u = await get_user(s3, tg_id)
                                _uname_line = f"@{_u.username}" if _u and _u.username else (
                                    _u.full_name if _u and _u.full_name else "—")
                        except Exception:
                            _uname_line = "—"
                        try:
                            _dt_local = order_created_at.replace(tzinfo=ZoneInfo("UTC")).astimezone(IRAN_TZ)
                            try:
                                import jdatetime
                                _dt_txt = jdatetime.datetime.fromgregorian(
                                    datetime=_dt_local.replace(tzinfo=None)).strftime("%Y/%m/%d — %H:%M")
                            except ImportError:
                                _dt_txt = _dt_local.strftime("%Y-%m-%d %H:%M")
                        except Exception:
                            _dt_txt = "—"
                        await _pbot.send_message(
                            PLATFORM_ADMIN_ID,
                            "⌛️ <b>فاکتورِ شارژِ خودکار منقضی شد و پیامکِ بانکی نرسید</b>\n\n"
                            f"👤 کاربر: <code>{tg_id}</code> ({_uname_line})\n"
                            f"💵 مبلغِ فاکتور: {rial(amount)}\n"
                            f"🕒 تاریخ و ساعتِ سفارش: {_dt_txt}\n"
                            f"🔢 سفارش: #{txn_id}\n\n"
                            "آیا این کاربر واقعاً این مبلغ را واریز کرده؟ اگر بله را بزنید، "
                            "کیفِ پولش با همین مبلغ شارژ می‌شود.",
                            reply_markup=kb_review)
                except Exception:
                    logger.exception("ارسالِ گزارشِ بررسیِ دستیِ شارژِ منقضی‌شده به ادمین ناموفق بود")
        except Exception:
            import traceback
            print("sms_expiry_notify_loop error:\n" + traceback.format_exc())
        await asyncio.sleep(interval_sec)


async def _sms_match_and_credit(amount_rial: int) -> bool:
    """با یه مبلغِ ریالیِ ورودی (از پیامک)، دنبالِ یه سفارشِ درحالِ‌انتظارِ
    منقضی‌نشده می‌گرده که دقیقاً همین مبلغ رو (به تومان) داشته باشه؛ اگه
    پیدا شد، کیفِ پولِ همون کاربر رو شارژ می‌کنه. idempotent (وضعیت رو
    عوض می‌کنه تا دوباره match نشه)."""
    from sqlalchemy import select as _select, update as _update
    from datetime import datetime, timedelta
    amount_toman = round(amount_rial / 10)
    ttl_min = await _sms_ttl_min()
    cutoff = datetime.utcnow() - timedelta(minutes=ttl_min)
    async with Session() as s:
        pend = await s.scalar(_select(PlatformTxn).where(
            PlatformTxn.kind == "sms_pending",
            PlatformTxn.amount == float(amount_toman),
            PlatformTxn.created_at >= cutoff,
        ).with_for_update())
        from_grace = False
        if not pend:
            # === PATCH_SMS_LATE_MATCH_GRACE_V1 ===
            # اگه پیامکِ بانکی کمی دیر برسه (مثلاً فورواردر یا شبکه تاخیر
            # داشته) و فاکتور دقیقاً همون لحظه منقضی شده باشه، قبلاً این
            # واریزی برایِ همیشه گم می‌شد و فقط دستِ ادمین می‌موند که با
            # کلیکِ دستی تاییدش کنه. حالا تا ۶۰ دقیقهٔ اضافه بعدِ انقضا هم
            # دنبالِ یه فاکتورِ منقضی‌شدهٔ هم‌مبلغ می‌گرده و اگه پیدا شد،
            # بازم خودکار شارژ می‌کنه — دیگه نیازی به تاییدِ دستی نیست.
            grace_cutoff = datetime.utcnow() - timedelta(minutes=ttl_min + 60)
            pend = await s.scalar(_select(PlatformTxn).where(
                PlatformTxn.kind == "sms_expired",
                PlatformTxn.amount == float(amount_toman),
                PlatformTxn.created_at >= grace_cutoff,
            ).with_for_update())
            from_grace = True
        if not pend:
            return False
        tg_id = pend.user_telegram_id
        invoice_note = pend.note or ""
        claim = await s.execute(_update(PlatformTxn).where(
            PlatformTxn.id == pend.id,
            PlatformTxn.kind == ("sms_expired" if from_grace else "sms_pending"),
        ).values(kind="sms_pending_done"))
        if claim.rowcount == 0:
            await s.rollback()
            return False

        # === PATCH_PARTNER_ORDER_SMS_AUTO_V1 ===
        # اگه این فاکتورِ اختصاصی برایِ خریدِ عمدهٔ همکار بوده (نه شارژِ
        # کیف‌پولِ کاربر)، اصلاً کیف‌پول شارژ نمی‌شه — مسیرش کاملاً جداست:
        # خودِ سفارشِ pending تویِ PartnerStockOrder تاییدِ خودکار می‌خوره.
        pp_order_id = None
        for part in invoice_note.split("|"):
            if part.startswith("pp_order="):
                try:
                    pp_order_id = int(part.split("=", 1)[1])
                except ValueError:
                    pp_order_id = None
        if pp_order_id is not None:
            # ثبتِ گزارشِ مالی برایِ این تراکنش داخلِ خودِ pp_order_auto_approve
            # انجام می‌شود (کایندِ partner_purchase)، پس این‌جا فقط عبور می‌کنیم.
            await s.commit()
        else:
            u = await get_user(s, tg_id, for_update=True)
            u.balance = float(u.balance) + amount_toman
            s.add(PlatformTxn(user_telegram_id=tg_id, amount=float(amount_toman),
                              kind="sms_charge", note=f"sms_auto|rial={amount_rial}"))
            new_bal = u.balance
            uname = u.username
            ufull = u.full_name
            await s.commit()
            if from_grace:
                # === PATCH_SMS_LATE_MATCH_GRACE_V1 ===
                # این فاکتور قبلاً منقضی اعلام شده بود و حلقهٔ انقضا یک
                # WalletCharge در انتظارِ تاییدِ دستیِ ادمین برایش ساخته —
                # حالا که خودکار شارژ شد، اون درخواستِ دستی رو هم approved
                # علامت می‌زنیم تا نه دوباره کیف‌پول شارژ بشه (اگه ادمین
                # بعداً دستی تایید کنه) و نه بی‌خودی رویِ صفِ ادمین بمونه.
                try:
                    stale = await s.scalar(_select(WalletCharge).where(
                        WalletCharge.user_telegram_id == tg_id,
                        WalletCharge.status == "pending",
                        WalletCharge.receipt_text.contains(f"#{pend.id} منقضی شد")))
                    if stale:
                        stale.status = "approved"
                        await s.commit()
                except Exception:
                    logger.exception("همگام‌سازیِ WalletCharge پس از شارژِ دیرهنگامِ پیامکی ناموفق بود")

    if pp_order_id is not None:
        try:
            from platform_partner import pp_order_auto_approve
            await pp_order_auto_approve(pp_order_id)
        except Exception:
            logger.exception("تاییدِ خودکارِ سفارشِ خریدِ عمدهٔ همکار (بعدِ تطبیقِ پیامک) ناموفق بود")
        # === PATCH_PARTNER_ORDER_SMS_AUTO_INVOICE_DELETE_V1 ===
        # فاکتورِ خریدِ عمده تویِ خودِ رباتِ همکار (نه رباتِ مادر) فرستاده
        # شده بود، پس باید با توکنِ همون ربات پاک بشه، نه با platform_bot.
        try:
            _mid = _chat = None
            for part in invoice_note.split("|"):
                if part.startswith("mid="):
                    _mid = int(part.split("=", 1)[1])
                elif part.startswith("chat="):
                    _chat = int(part.split("=", 1)[1])
            if _mid and _chat:
                from models import PartnerStockOrder, PartnerBot as _PartnerBot, Bot as _BotRow
                async with Session() as s4:
                    _o = await s4.get(PartnerStockOrder, pp_order_id)
                    _pb = await s4.get(_PartnerBot, _o.partner_bot_id) if _o else None
                    _brow = await s4.get(_BotRow, _pb.bot_id) if _pb else None
                    _token = _brow.token if _brow else None
                if _token:
                    from aiogram import Bot as _AioBot
                    _tbot = _AioBot(token=_token)
                    try:
                        await _tbot.delete_message(chat_id=_chat, message_id=_mid)
                    finally:
                        await _tbot.session.close()
        except Exception:
            logger.exception("حذفِ خودکارِ فاکتورِ خریدِ عمدهٔ همکار بعدِ تایید ناموفق بود")
        return True

    try:
        # === PATCH_PLATFORM_BOT_NAME_FIX_V1 ===
        from main_platform import platform_bot
        await platform_bot.send_message(
            tg_id,
            "✅ <b>کیف پولت با موفقیت و به‌صورتِ خودکار شارژ شد!</b>\n"
            f"💰 مبلغ واریزی: <b>{amount_toman:,} تومان</b>\n"
            f"👛 موجودی فعلی: <b>{new_bal:,.0f} تومان</b>\n"
            "🧾 روش پرداخت: 📲 کارت‌به‌کارتِ خودکار (پیامکِ بانکی)")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    # === PATCH_PLATFORM_SMS_INVOICE_AUTODELETE_V1 ===
    # درخواستِ مدیر: بعدِ شارژِ موفق، خودِ پیامِ فاکتور (که شماره‌کارت و مبلغ
    # توش بود) پاک بشه که تویِ چتِ کاربر باقی نمونه.
    try:
        _mid = _chat = None
        for part in invoice_note.split("|"):
            if part.startswith("mid="):
                _mid = int(part.split("=", 1)[1])
            elif part.startswith("chat="):
                _chat = int(part.split("=", 1)[1])
        if _mid and _chat:
            from main_platform import platform_bot as _pbot_del
            await _pbot_del.delete_message(chat_id=_chat, message_id=_mid)
    except Exception:
        logger.exception("حذفِ خودکارِ پیامِ فاکتور بعدِ شارژ ناموفق بود")

    # === PATCH_PLATFORM_SMS_ADMIN_CHARGE_NOTIFY_V1 ===
    # درخواستِ مدیر: به محضِ اینکه کیفِ پولِ هر کاربری با این روش شارژ شد،
    # به ادمینِ پلتفرم اطلاع بده کدوم کاربر چقدر شارژ کرد.
    try:
        if PLATFORM_ADMIN_ID:
            from main_platform import platform_bot as _pbot_notify
            _uname_line = f"@{uname}" if uname else (ufull or "—")
            await _pbot_notify.send_message(
                PLATFORM_ADMIN_ID,
                "💳 <b>شارژِ خودکارِ کیفِ پول انجام شد</b>\n\n"
                f"👤 کاربر: <code>{tg_id}</code> ({_uname_line})\n"
                f"💰 مبلغ: <b>{amount_toman:,} تومان</b>\n"
                f"👛 موجودیِ جدید: <b>{new_bal:,.0f} تومان</b>\n"
                "🧾 روش: 📲 کارت‌به‌کارتِ خودکار (پیامکِ بانکی)")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    return True


async def _platform_zarinpal_credit(tg_id: int, credited: int, note: str,
                                         marker: str | None = None) -> float | None:
    """اعتبار زدنِ کیف‌پولِ کاربر بعدِ تأییدِ درگاه.

    === PATCH_GATEWAY_CREDIT_ONCE_V1 === اگر marker (مثلاً «order_id=…» یا
    «authority=…») داده شود، اول ردیفِ zarinpal_pendingِ همان فاکتور در *همین* تراکنش
    قفل و مصرف می‌شود؛ اگر قبلاً مصرف شده بود None برمی‌گردد و شارژ نمی‌شود.
    قبلاً دو کلیکِ هم‌زمانِ «بررسی پرداخت» (یا کلیک + کالبک) هر دو شارژ می‌کردند."""
    from sqlalchemy import select as _sel
    async with Session() as s:
        if marker:
            _p = await s.scalar(_sel(PlatformTxn).where(
                PlatformTxn.kind == "zarinpal_pending",
                PlatformTxn.note.contains(marker)).with_for_update())
            if _p is None:
                return None
            _p.kind = "zarinpal_pending_done"
        u = await get_user(s, tg_id, for_update=True)
        u.balance = float(u.balance) + credited
        s.add(PlatformTxn(user_telegram_id=tg_id, amount=float(credited),
                          kind="zarinpal_charge", note=note))
        await s.commit()
        return u.balance


