@router.message(ChargeZarinpal.amount, F.text)
async def charge_zarinpal_amount(msg: Message, state: FSMContext):
    fa_map = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")
    raw = (msg.text or "").strip().translate(fa_map).replace(",", "").replace("،", "")
    if not raw.isdigit() or int(raw) < 10_000:
        await msg.answer("❌ مبلغ باید عدد و حداقل ۱۰٬۰۰۰ تومان باشد. دوباره بفرست:")
        return
    await state.clear()
    await _zarinpal_proceed(msg, msg.from_user.id, int(raw))


async def _zarinpal_proceed(message, tg_id: int, amount_toman: int):
    import platform_zarinpal
    mid = await get_pset("platform_zarinpal_merchant_id", "")
    if not mid:
        await message.answer("❌ درگاه زرین‌پال تنظیم نشده.")
        return
    webhook_base = await get_pset("platform_zarinpal_webhook_base", WEBHOOK_BASE or "")
    if not webhook_base or not webhook_base.startswith("https://"):
        await message.answer("❌ آدرس سرور (https) تنظیم نشده. به پشتیبانی اطلاع بده.")
        return
    cb_url = f"{webhook_base}/zarinpal/platform/callback"
    ok, res = await platform_zarinpal.request_payment(
        mid, amount_toman, f"شارژ کیف‌پول بات‌ساز — کاربر {tg_id}", cb_url)
    if not ok:
        await message.answer(f"❌ ساختِ پرداخت ناموفق بود:\n{res}")
        return
    authority = res
    async with Session() as s:
        s.add(PlatformTxn(user_telegram_id=tg_id, amount=float(amount_toman),
                          kind="zarinpal_pending",
                          note=f"authority={authority}|toman={amount_toman}"))
        await s.commit()
    pay_url = platform_zarinpal.startpay_url(authority)
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("💳 پرداخت با زرین‌پال", url=pay_url, style=ButtonStyle.PRIMARY)],
        [hx_button("🔍 بررسی پرداخت", callback_data=f"zrp:check:{authority}")],
        [hx_button("⬅️ بازگشت به کیف پول", callback_data="zrp:chg:back")],
    ])
    await message.answer(
        "🏦 <b>فاکتور پرداخت زرین‌پال آماده شد</b>\n\n"
        f"💵 مبلغ: <b>{rial(amount_toman)}</b>\n\n"
        "روی «💳 پرداخت با زرین‌پال» بزن، پرداخت را در همان صفحه انجام بده "
        "و به ربات برگرد.\nبعد از تأیید، کیف‌پولت خودکار شارژ می‌شود. اگر چند دقیقه "
        "بعد از پرداخت شارژ نشد، روی «🔍 بررسی پرداخت» بزن.",
        reply_markup=kb)


@router.callback_query(F.data.startswith("zrp:check:"))
async def zrp_check_payment(cb: CallbackQuery):
    """دکمهٔ «بررسی پرداخت»: برای وقتی که کالبکِ زرین‌پال به هر دلیلی (شبکه،
    بستنِ زودهنگامِ مرورگر) به سرور نرسیده — همینجا مستقیم استعلام می‌گیریم."""
    import platform_zarinpal
    from sqlalchemy import select as _select
    authority = cb.data.split(":", 2)[2]
    await cb.answer("⏳ در حال بررسی پرداخت...")

    async with Session() as s:
        pending = await s.scalar(
            _select(PlatformTxn).where(
                PlatformTxn.kind == "zarinpal_pending",
                PlatformTxn.note.contains(f"authority={authority}"),
            ))
        already = await s.scalar(
            _select(PlatformTxn).where(
                PlatformTxn.kind == "zarinpal_charge",
                PlatformTxn.note.contains(f"authority={authority}"),
            ))

    if already:
        await cb.message.answer("✅ این فاکتور قبلاً تأیید شده و کیف پولت شارژ شده است.")
        return
    if not pending:
        await cb.message.answer("❌ این فاکتور پیدا نشد؛ با پشتیبانی تماس بگیر.")
        return
    if pending.user_telegram_id != cb.from_user.id:
        await cb.answer("این فاکتور مربوط به تو نیست.", show_alert=True)
        return

    mid = await get_pset("platform_zarinpal_merchant_id", "")
    amount_toman = int(float(pending.amount))
    ok, res = await platform_zarinpal.verify_payment(mid, amount_toman, authority)
    if not ok:
        await cb.message.answer(
            "⏳ هنوز پرداخت تأیید نشده.\n"
            "اگر همین الان پرداخت کردی، چند لحظه صبر کن و دوباره امتحان کن.\n"
            f"جزئیات: {res}")
        return
    new_bal = await _platform_zarinpal_credit(
        cb.from_user.id, amount_toman, f"authority={authority}|ref_id={res}",
        marker=f"authority={authority}")
    if new_bal is None:
        await cb.message.answer("✅ این فاکتور قبلاً تأیید شده و کیف پولت شارژ شده است.")
        return
    async with Session() as s:
        p = await s.scalar(
            _select(PlatformTxn).where(
                PlatformTxn.kind == "zarinpal_pending",
                PlatformTxn.note.contains(f"authority={authority}"),
            ).with_for_update())
        if p:
            p.kind = "zarinpal_pending_done"
            await s.commit()
    await cb.message.answer(
        f"✅ پرداخت تأیید شد. کیف پولت به‌مقدار <b>{rial(amount_toman)}</b> شارژ شد.\n"
        f"💰 موجودی فعلی: <b>{rial(new_bal)}</b>")


# ───── جستجوی واریزی با کد پیگیری (تطبیق دیتابیس ↔ NOWPayments) ─────

_FA_DIGITS = str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789")

_NP_STATUS_FA = {
    "waiting": "⏳ در انتظار واریز کاربر",
    "confirming": "🔄 در حال تأیید روی بلاکچین",
    "confirmed": "✅ تأیید شده روی بلاکچین (در صف نهایی‌سازی)",
    "sending": "📤 در حال ارسال به کیف پلتفرم",
    "partially_paid": "🟡 پرداخت ناقص (کمتر از مبلغ لازم)",
    "finished": "✅ نهایی‌شده و به کیف پلتفرم رسیده",
    "failed": "❌ ناموفق",
    "refunded": "↩️ بازگشت‌داده‌شده به کاربر",
    "expired": "⌛ منقضی‌شده (کاربر واریز نکرد)",
}


