    api_key = await get_pset("swap_api_key", "")
    addr_map = await _platform_swap_addr_map()
    if not api_key or not any(addr_map.values()):
        await cb.answer("درگاه سواپ‌ولت هنوز تنظیم نشده است.", show_alert=True)
        return

    enabled_coins_str = await get_pset("swap_enabled_coins", "USDT,TON,TRX")
    enabled_coins = [c.strip().upper() for c in enabled_coins_str.split(",")
                     if c.strip() and addr_map.get(c.strip().upper())]
