@router.message(Charge.swap_amount, F.text)
async def charge_swap_amount(msg: Message, state: FSMContext):
    import swappay
    from tenant.gateways import swap_charges
    from decimal import Decimal

    amount = fa_to_int(msg.text)
    swap_min = int(await get_pset("swap_min_toman", "10000") or "10000")
    swap_max_str = await get_pset("swap_max_toman", "0")
    swap_max = int(swap_max_str or "0")

    if not amount or amount < swap_min:
        await msg.answer(f"مبلغ نامعتبر است. حداقل {swap_min:,} تومان بفرست.")
        return
    if swap_max > 0 and amount > swap_max:
        await msg.answer(f"مبلغ وارد‌شده بیشتر از حداکثر مجاز ({swap_max:,} تومان) است.")
        return

    data = await state.get_data()
    coin = (data.get("swap_selected_coin") or await get_pset("swap_coin", "USDT") or "USDT").upper()
    await state.clear()

    api_key = await get_pset("swap_api_key", "")
    address = await get_pset(_SWAP_COIN_ADDR_KEY.get(coin, "swap_addr_usdt"), "")
    network = _SWAP_COIN_NETWORK.get(coin, coin)
    if not api_key or not address:
        await msg.answer("درگاه سواپ‌ولت درست تنظیم نشده. به پشتیبانی اطلاع بده.",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return

    client = swappay.SwapPayClient(api_key)
    try:
        prices = await client.get_prices()
        price_irt = Decimal(str(prices.get(f"{coin}/IRT", "0")))
    except swappay.SwapPayError as e:
        await msg.answer(f"❌ ارتباط با سواپ‌ولت ناموفق بود: {e}", reply_markup=await smart_home_kb(msg.from_user.id))
        return
    if price_irt <= 0:
        await msg.answer("❌ دریافت نرخ لحظه‌ای ناموفق بود. بعداً دوباره تلاش کن.",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return

    base_amount = Decimal(amount) / price_irt
    expected = await swap_charges.make_unique_amount(0, coin, base_amount)
    try:
        recent = await client.list_transactions(limit=1)
        last_seen = int(recent[0]["id"]) if recent else 0
    except swappay.SwapPayError:
        last_seen = 0

    charge_id = await swap_charges.create_charge(
        0, msg.from_user.id, amount, coin, network, expected, last_seen)

    import hashlib, urllib.parse
    _inv_raw = f"SWAP-0-{charge_id}-{msg.from_user.id}"
    invoice_number = hashlib.sha256(_inv_raw.encode()).hexdigest().upper()[:26]

    net_txt = network or SWAP_NETWORK_HINT.get(coin, "")
    coin_emoji = _SWAP_COIN_EMOJI.get(coin, "🪙")
    coin_label = {"USDT": "تتر (USDT)", "TON": "تون (TON)", "TRX": "ترون (TRX)"}.get(coin, coin)

    _express_net = _SWAP_COIN_NETWORK.get(coin, coin)
    express_url = (
        f"https://swapwallet.app/express-withdraw"
        f"?amount={urllib.parse.quote(str(expected))}&coin={coin}&network={_express_net}"
        f"&address={urllib.parse.quote(address)}"
    )

    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("💸 پرداخت سریع با سواپ‌ولت", url=express_url, style=ButtonStyle.SUCCESS)],
        [hx_button("❌ لغو", callback_data=f"psx:cancel:{charge_id}", style=ButtonStyle.DANGER)],
    ])
    await msg.answer(
        f"✅ <b>فاکتور با موفقیت ایجاد شد</b>\n\n"
        f"<b>#</b> شماره فاکتور:\n"
        f"<code>{invoice_number}</code>\n\n"
        f"<b>💳</b> مبلغ : <b>{expected} {coin_emoji} {coin_label}</b> - بدون احتساب کارمزد شبکه\n\n"
        f"لطفا مبلغ <b>{expected}</b> را به آدرس زیر واریز کنید.\n"
        f"{coin_emoji} آدرس کیف پول:\n"
        f"<code>{address}</code>\n\n"
        f"🔷 شبکه: <b>{net_txt}</b>\n\n"
        f"🚫 توجه: فیلد Memo را خالی بگذارید.\n\n"
        f"⚠️ این آدرس فقط تا <b>120 دقیقه</b> آینده معتبر است. ⏳\n"
        f"💡 اگر مبلغ پرداختی در صفحه سواپ‌ولت صفر نشان داد، نگران نباشید — مقدار رمزارز درست است و پرداخت انجام می‌شود.\n\n"
        f"✅ پس از پرداخت موفق، کیف پول شما به مقدار <b>{rial(amount)}</b> به طور "
        f"<b>خودکار</b> شارژ میگردد.",
        reply_markup=kb)


@router.callback_query(F.data.startswith("psx:cancel:"))
async def charge_swap_cancel(cb: CallbackQuery, state: FSMContext):
    from tenant.gateways import swap_charges
    cid = int(cb.data.split(":")[2])
    c = await swap_charges.get_charge(cid)
    if c and c.bot_id == 0 and c.status == "waiting":
        async with Session() as s:
            cc = await s.get(swap_charges.SwapCharge, cid)
            cc.status = "canceled"
            await s.commit()
    await state.clear()
    try:
        await cb.message.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    async with Session() as s:
        u = await get_user(s, cb.from_user.id, cb.from_user.full_name, username=cb.from_user.username)
        await s.commit()
        bal = u.balance
    await cb.message.answer(f"💰 موجودی کیف پول شما:\n<b>{rial(bal)}</b>",
                            reply_markup=await _platform_wallet_kb())
    await cb.answer("لغو شد.")


async def _platform_swap_credit(tg_id: int, credited: int, note: str) -> float:
    async with Session() as s:
        u = await get_user(s, tg_id, for_update=True)
        u.balance = float(u.balance) + credited
        s.add(PlatformTxn(user_telegram_id=tg_id, amount=float(credited),
                          kind="swap_charge", note=note))
        await s.commit()
        return u.balance


def _swap_match(incoming, coin, expected_dec):
    """اولین تراکنش موفقِ منطبق با مقدار را برمی‌گرداند (یا None)."""
    import swappay
    for tx in incoming:
        detail = tx.get("cryptoDeposit") or tx.get("transfer") or {}
        amt = swappay.Money.parse(detail.get("amount"))
        if not amt or amt.unit != coin or amt.number != expected_dec:
            continue
        yield tx, detail


async def _notify_admin_platform_swap_charge(bot_or_token, user_tg: int, credited: int,
                                             coin: str, new_bal=None):
    """اگر تنظیمِ «اطلاع از شارژ کریپتو» روشن باشد، به مدیر اصلی پلتفرم خبر می‌دهد."""
    try:
        notify = await get_pset("swap_notify_admin", "1")
        if notify == "0" or not PLATFORM_ADMIN_ID:
            return
        uname = ""
        async with Session() as s:
            u = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == user_tg))
            if u and getattr(u, "full_name", None):
                uname = f"\n👤 کاربر: {u.full_name}"
        bal_line = f"\n💰 موجودی جدید کاربر: {rial(new_bal)}" if new_bal is not None else ""
        text = (
            "🟦 <b>شارژ کیف پول پلتفرم با سواپ‌ولت</b>\n\n"
            f"✅ یک کاربر کیف پولش را شارژ کرد و تایید شد.\n"
            f"💵 مبلغ: <b>{rial(credited)}</b>\n"
            f"🪙 ارز: <b>{coin}</b>\n"
            f"🆔 آیدی عددی: <code>{user_tg}</code>{uname}{bal_line}"
        )
        if isinstance(bot_or_token, str):
            from aiogram import Bot as _Bot
            from aiogram.client.default import DefaultBotProperties
            from aiogram.enums import ParseMode
            tb = _Bot(token=bot_or_token, default=DefaultBotProperties(parse_mode=ParseMode.HTML))
            try:
                await tb.send_message(PLATFORM_ADMIN_ID, text)
            finally:
                try:
                    await tb.session.close()
                except Exception:
                    logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        else:
            await bot_or_token.send_message(PLATFORM_ADMIN_ID, text, parse_mode="HTML")
    except Exception as e:
        print("notify admin platform swap charge error:", e)


@router.callback_query(F.data.startswith("psx:check:"))
async def charge_swap_check(cb: CallbackQuery, bot: Bot):
    import swappay
    from tenant.gateways import swap_charges
    from decimal import Decimal

    cid = int(cb.data.split(":")[2])
    c = await swap_charges.get_charge(cid)
    if not c or c.bot_id != 0:
        await cb.answer("درخواست یافت نشد.", show_alert=True)
        return
    if c.status == "paid":
        await cb.answer("این شارژ قبلاً تایید و اعمال شده است.", show_alert=True)
        return
    if c.status != "waiting":
        await cb.answer("این درخواست دیگر معتبر نیست.", show_alert=True)
        return

    client = swappay.SwapPayClient(await get_pset("swap_api_key", ""))
    try:
        incoming = await client.detect_incoming(after_id=int(c.last_seen_id or 0), tokens=(c.coin,))
    except swappay.SwapPayError as e:
        await cb.answer(f"خطا در بررسی: {e}", show_alert=True)
        return

    want = Decimal(c.expected_amount)
    match = None
    for tx, detail in _swap_match(incoming, c.coin, want):
        if await swap_charges.is_tx_used(0, int(tx["id"])):
            continue
        match = (tx, detail)
        break
    if not match:
        await cb.answer("هنوز واریزی با این مقدار دیده نشد. اگر همین الان فرستادی، چند دقیقه بعد دوباره بزن.",
                        show_alert=True)
        return

    tx, detail = match
    irt = swappay.Money.parse(detail.get("userCurrencyValue"))
    credited = int(irt.number) if irt else int(c.amount_toman)
    if credited <= 0:
        credited = int(c.amount_toman)
    if not await swap_charges.mark_paid(cid, int(tx["id"]), credited):
        await cb.answer("این واریز قبلاً پردازش شده است.", show_alert=True)
        return
    new_bal = await _platform_swap_credit(
        cb.from_user.id, credited, f"شارژ با سواپ‌ولت ({c.expected_amount} {c.coin})")
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.message.answer(
        f"✅ پرداخت تایید شد و کیف پولت <b>{rial(credited)}</b> شارژ شد.\n"
        f"موجودی جدید: <b>{rial(new_bal)}</b>")
    await cb.answer("شارژ شد ✅")
    await _notify_admin_platform_swap_charge(bot, cb.from_user.id, credited, c.coin, new_bal)


async def swap_platform_poll_once(max_age_minutes: int = 180) -> list[tuple[int, int]]:
    """شارژهای سواپ‌ولتِ پلتفرم (bot_id=0) را بررسی و کیف پول پلتفرم را شارژ می‌کند.
    فهرست (telegram_id, تومان) برای اطلاع‌رسانی برمی‌گرداند."""
    import swappay
    from tenant.gateways import swap_charges
    from decimal import Decimal

    try:
        await swap_charges.expire_older_than(max_age_minutes)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    waiting = [c for c in await swap_charges.list_waiting(max_age_minutes=max_age_minutes)
               if c["bot_id"] == 0]
    if not waiting:
        return []
    api_key = await get_pset("swap_api_key", "")
    if not api_key:
        return []
    coins = tuple({c["coin"] for c in waiting})
    after = min(int(c["last_seen_id"] or 0) for c in waiting)
    client = swappay.SwapPayClient(api_key)
    try:
        incoming = await client.detect_incoming(after_id=after, tokens=coins)
    except swappay.SwapPayError:
        return []
    if not incoming:
        return []
    notifs: list[tuple[int, int]] = []
    for c in waiting:
        want = Decimal(c["expected_amount"])
        for tx, detail in _swap_match(incoming, c["coin"], want):
            if await swap_charges.is_tx_used(0, int(tx["id"])):
                continue
            irt = swappay.Money.parse(detail.get("userCurrencyValue"))
            credited = int(irt.number) if irt else int(c["amount_toman"])
            if credited <= 0:
                credited = int(c["amount_toman"])
            if not await swap_charges.mark_paid(c["id"], int(tx["id"]), credited):
                break
            new_bal = await _platform_swap_credit(
                c["user_telegram_id"], credited,
                f"شارژ با سواپ‌ولت ({c['expected_amount']} {c['coin']})")
            notifs.append((c["user_telegram_id"], credited))
            try:
                await _notify_admin_platform_swap_charge(
                    PLATFORM_BOT_TOKEN, c["user_telegram_id"], credited, c["coin"], new_bal)
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
            break
    return notifs


async def smart_skip_kb() -> "InlineKeyboardMarkup | ReplyKeyboardMarkup":
    """PATCH_PLATFORM_SMART_HOME_MENU_V1 — نسخهٔ مود-آگاهِ کیبوردِ میانبرهای «شبا»/«نمی‌دانم» در مرحلهٔ
    شارژِ کارت‌به‌کارتِ کیف‌پول."""
    if await get_pset("home_menu_mode", "reply") == "inline":
        return InlineKeyboardMarkup(inline_keyboard=[
            [hx_button("🏦 با شبا/شماره‌حساب واریز کردم", callback_data="hm:charge_iban", style=ButtonStyle.PRIMARY)],
            [hx_button("⏭ نمی‌دانم / رد کن", callback_data="hm:charge_skip", style=ButtonStyle.PRIMARY)],
            [hx_button("❌ لغو", callback_data="hm:fsm_cancel", style=ButtonStyle.DANGER)],
        ])
    return ReplyKeyboardMarkup(
        keyboard=[
            [KeyboardButton(text="🏦 با شبا/شماره‌حساب واریز کردم")],
            [KeyboardButton(text="⏭ نمی‌دانم / رد کن")],
            [KeyboardButton(text=BTN_CANCEL, style=ButtonStyle.DANGER)],
        ],
        resize_keyboard=True,
    )


