@router.message(Charge.sender_card, F.text)
async def charge_sender_card(msg: Message, state: FSMContext):
    raw = (msg.text or "").strip()
    # === PATCH_CANCEL_MATCH_V1 ===
    if is_cancel_text(raw):
        await state.clear()
        await msg.answer("لغو شد. به منوی اصلی برگشتی.",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return
    sender4 = None
    method = "card"
    if raw == "🏦 با شبا/شماره‌حساب واریز کردم":
        method = "iban"
    elif raw == "⏭ نمی‌دانم / رد کن":
        method = "unknown"
    else:
        # نرمال‌سازیِ ارقامِ فارسی/عربی به انگلیسی
        _trans = str.maketrans("۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩", "01234567890123456789")
        norm = raw.translate(_trans)
        only = "".join(ch for ch in norm if ch.isdigit())
        if len(only) >= 4:
            sender4 = only[-4:]
        elif len(only) >= 1:
            sender4 = only.rjust(4, "0")[-4:]
        else:
            await msg.answer(
                "لطفاً <b>۴ رقمِ آخرِ کارتِ مبدأ</b> را بفرست (فقط عدد)، "
                "یا یکی از دکمه‌های «شبا» / «نمی‌دانم» را بزن.")
            return
    await state.update_data(sender_card4=sender4, pay_method=method)
    await state.set_state(Charge.receipt)
    await msg.answer(
        "✅ ثبت شد.\n\n"
        "📸 حالا <b>عکس رسید</b> را بفرست، یا اگر رسید متنی داری همان <b>متن رسید</b> را ارسال کن.",
        reply_markup=await smart_cancel_kb(),
    )


