@router.callback_query(Charge.confirm, F.data == "rc:ok")
async def rc_ok(cb: CallbackQuery, state: FSMContext, bot: Bot):
    data = await state.get_data()
    amount = data["amount"]
    file_id = data.get("file_id")
    receipt_text = data.get("receipt_text")
    sender_card4 = data.get("sender_card4")
    async with Session() as s:
        ch = WalletCharge(user_telegram_id=cb.from_user.id, amount=amount,
                          receipt_file_id=file_id, receipt_text=receipt_text,
                          sender_card4=sender_card4)
        s.add(ch)
        await s.flush()
        cid = ch.id
        await s.commit()
    await state.clear()
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    # ── تلاش برای تأیید خودکار رسید (در صورت روشن‌بودن تنظیم پلتفرم) ──
    auto_reason = ""
    if (await get_pset("platform_auto_approve", "off")) == "on":
        try:
            ok, reason = await _try_auto_approve_platform_charge(bot, cid)
            if ok:
                await cb.message.answer(
                    "✅ رسید به‌صورت خودکار تأیید شد و کیف پولت شارژ شد.",
                    reply_markup=await smart_home_kb(cb.from_user.id))
                await cb.answer("خودکار تأیید شد ✅")
                return
            auto_reason = reason or "نامشخص"
        except Exception as e:
            auto_reason = f"خطا: {type(e).__name__}"

    await cb.message.answer("✅ رسید ثبت شد. بعد از تایید ادمین، کیف پولت شارژ می‌شود.",
                            reply_markup=await smart_home_kb(cb.from_user.id))
    kb = InlineKeyboardMarkup(inline_keyboard=[[
        hx_button("✅ تایید", callback_data=f"chg:ok:{cid}"),
        hx_button("❌ رد", callback_data=f"chg:no:{cid}"),
    ]])
    card4_line = f"\n💳 ۴ رقمِ کارتِ مبدأ: <code>{sender_card4}</code>" if sender_card4 else ""
    cap = (f"درخواست شارژ #{cid}\nکاربر: <code>{cb.from_user.id}</code>\n"
           f"مبلغ: {rial(amount)}{card4_line}")
    if auto_reason:
        cap += f"\n\n🤖 چرا خودکار تأیید نشد: {auto_reason}"
    if PLATFORM_ADMIN_ID:
        if file_id:
            await bot.send_photo(PLATFORM_ADMIN_ID, file_id, caption=cap, reply_markup=kb)
        else:
            # رسیدِ متنی: خودِ متن را هم به ادمین نشان بده
            body = cap + (f"\n\n📝 متنِ رسید:\n<blockquote>{(receipt_text or '')[:500]}</blockquote>"
                         if receipt_text else "")
            await bot.send_message(PLATFORM_ADMIN_ID, body, reply_markup=kb)
    await cb.answer("ثبت شد")


async def _try_auto_approve_platform_charge(bot: Bot, cid: int) -> tuple[bool, str]:
    """رسیدِ شارژ #cid را با OCR ارزیابی می‌کند؛ در صورتِ مطابقتِ کامل، کیف پول را
    خودکار شارژ کرده، به کاربر خبر می‌دهد و گزارشی همراهِ دکمهٔ «لغو» برای ادمین
    می‌فرستد. خروجی: (موفق؟, دلیلِ عدمِ‌موفقیت). اگر نامشخص/مغایر بود، هیچ کاری
    نمی‌کند و (False, دلیل) برمی‌گرداند تا مسیرِ تأیید دستی ادامه یابد."""
    from tenant.gateways.auto_receipt import evaluate_receipt
    async with Session() as s:
        ch = await s.get(WalletCharge, cid)
        if not ch or ch.status != "pending":
            return False, "درخواست یافت نشد یا قبلاً رسیدگی شده."
        expected_amount = float(ch.amount)
        file_id = ch.receipt_file_id
        receipt_text = ch.receipt_text
        sender_card4 = ch.sender_card4
        user_tg = ch.user_telegram_id
        created_at = ch.created_at

# === PATCH_SECOND_CARD_ROTATE_V1 ===
    # هر دو کارت پذیرفته می‌شود، نه فقط آنکه تصادفاً نشان داده شده.
    _cards = [c for c, _h in await _platform_cards()]
    card_number = _cards[0] if _cards else None
    check = await evaluate_receipt(
        bot, receipt_text=receipt_text, file_id=file_id,
        expected_amount=expected_amount, expected_card_number=card_number,
        order_created_at=created_at, expected_sender_last4=sender_card4)
    if not check.ok:
        return False, check.reason

    # جلوگیری از رسیدِ تکراری: اثرِ انگشتِ رسید (شمارهٔ پیگیری یا تاریخ+ساعت+مبلغ)
    from tenant.gateways.auto_receipt import (receipt_fingerprint, photo_fingerprint,
                                              claim_receipts, release_receipts)
    fp = receipt_fingerprint(check)
    # PATCH_RECEIPT_REQUIRE_FP_V1: رسیدی که نه شمارهٔ پیگیری دارد نه تاریخ/ساعتِ خواندنی (مثلاً عکسِ برش‌خورده)
    # را نمی‌شود از تکراری‌بودن سنجید؛ قبلاً بدونِ هیچ چکی پذیرفته می‌شد و همان رسید بی‌نهایت بار کیف‌پول را
    # شارژ می‌کرد. حالا به بررسیِ دستیِ ادمین می‌رود.
    if not fp:
        return False, ("رسید شمارهٔ پیگیری یا تاریخ/ساعتِ قابل‌خواندن ندارد؛ برایِ جلوگیری از استفادهٔ "
                       "تکراری به بررسیِ دستی رفت.")
    _fps = [fp]
    if file_id:                                       # اثرِ انگشتِ خودِ عکس هم (مثلِ ربات‌هایِ مستأجر)
        try:
            _pf = photo_fingerprint((await bot.get_file(file_id)).file_unique_id)
            if _pf:
                _fps.append(_pf)
        except Exception:  # noqa: BLE001
            logger.exception("platform receipt: file_unique_id خوانده نشد")
    # PATCH_RECEIPT_CLAIM_ATOMIC_V1: ثبتِ اتمیک *پیش* از شارژ — قبلاً چک و ثبت جدا بودند و
    # یک رسید در دو درخواستِ هم‌زمان دو بار کیف‌پولِ پلتفرم را شارژ می‌کرد.
    if not await claim_receipts("platform", _fps, amount=int(expected_amount),
                                user_telegram_id=user_tg):
        return False, ("این رسید قبلاً استفاده و شارژ شده است "
                       + (f"(پیگیری {check.tracking_no})" if check.tracking_no
                          else f"(تاریخ/ساعت {check.date_jalali or ''} {check.time_str or ''})")
                       + " — رسیدِ تکراری.")

    # مطابقتِ کامل → شارژ خودکار
    async with Session() as s:
        ch = await s.get(WalletCharge, cid, with_for_update=True)
        if not ch or ch.status != "pending":
            await release_receipts("platform", _fps)
            return False, "درخواست همزمان رسیدگی شد."
        ch.status = "approved"
        u = await get_user(s, user_tg, for_update=True)
        u.balance = float(u.balance) + expected_amount
        new_bal = float(u.balance)
        s.add(PlatformTxn(user_telegram_id=user_tg, amount=expected_amount,
                          kind="charge", note=f"AUTO:شارژ خودکار #{cid}"))
        await s.commit()


    try:
        await bot.send_message(user_tg, f"✅ کیف پول شما {rial(expected_amount)} شارژ شد.\nموجودی جدید: {rial(new_bal)}")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    # گزارش به ادمین با امکانِ لغو (اگر رسید فیک بود)
    detail_lines = [f"🔎 مبلغِ خوانده‌شده: {rial(check.amount)}" if check.amount else "🔎 مبلغ: —"]
    if check.card_last4:
        detail_lines.append(f"💳 ۴ رقمِ آخرِ کارت روی رسید: <code>{check.card_last4}</code>")
    if check.date_jalali:
        detail_lines.append(f"📅 تاریخِ رسید: {check.date_jalali}")
    report = (
        f"🤖 <b>تأیید خودکار رسید — شارژ کیف پول</b>\n\n"
        f"👤 کاربر: <code>{user_tg}</code>\n"
        f"💵 مبلغ: {rial(expected_amount)}\n"
        f"💼 موجودی جدید: {rial(new_bal)}\n"
        + "\n".join(detail_lines) + "\n"
        f"✅ نتیجهٔ بررسی: {check.reason}\n"
        f"شارژ: #{cid}\n\n"
        f"✅ به‌صورت خودکار تأیید و کیف پول کاربر شارژ شد.\n"
        f"⚠️ اگر این رسید فیک/مشکوک است، با دکمهٔ زیر لغو کنید."
    )
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("✅ تأیید (مشکلی نیست)", callback_data=f"chgok:{cid}")],
        [hx_button("🚫 لغو (رسید فیک بود)", callback_data=f"chgrev:{cid}")],
    ])
    if PLATFORM_ADMIN_ID:
        try:
            if file_id:
                await bot.send_photo(PLATFORM_ADMIN_ID, file_id, caption=report, reply_markup=kb)
            else:
                await bot.send_message(PLATFORM_ADMIN_ID, report, reply_markup=kb)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    return True, ""


@router.callback_query(F.data.startswith("chgok:"))
async def adm_charge_confirm_auto(cb: CallbackQuery, bot: Bot):
    """تأییدِ دستیِ یک شارژِ خودکار (وقتی ادمین می‌خواهد بگوید مشکلی نیست).
    شارژ از قبل انجام شده؛ این دکمه فقط پیام را نهایی و دکمه‌ها را حذف می‌کند."""
    if not await has_perm(cb.from_user.id, "adm:fin"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    try:
        original = cb.message.caption or cb.message.text or ""
        done = original + "\n\n✅ <b>تأیید شد.</b> (بدونِ مشکل)"
        if cb.message.caption is not None:
            await cb.message.edit_caption(caption=done, reply_markup=None)
        else:
            await cb.message.edit_text(done, reply_markup=None)
    except Exception:
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer("تأیید شد ✅")


@router.callback_query(F.data.startswith("chgrev:"))
async def adm_charge_revoke(cb: CallbackQuery, bot: Bot):
    """لغوِ یک شارژِ خودکارِ تأییدشده (اگر ادمین تشخیص دهد رسید فیک بوده)."""
    if not await has_perm(cb.from_user.id, "adm:fin"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    cid = int(cb.data.split(":")[1])
    async with Session() as s:
        ch = await s.get(WalletCharge, cid, with_for_update=True)   # دوبار کسر نشود
        if not ch or ch.status != "approved":
            await cb.answer("قابلِ لغو نیست (قبلاً رسیدگی شده).", show_alert=True)
            return
        ch.status = "rejected"
        u = await get_user(s, ch.user_telegram_id, for_update=True)
        u.balance = float(u.balance) - float(ch.amount)
        s.add(PlatformTxn(user_telegram_id=ch.user_telegram_id, amount=-float(ch.amount),
                          kind="charge", note=f"REVOKE:لغو شارژ خودکار #{cid}"))
        await s.commit()
        user_tg = ch.user_telegram_id
        amt = float(ch.amount)
    try:
        await bot.send_message(user_tg,
                               f"⚠️ شارژِ خودکارِ {rial(amt)} پس از بررسی لغو شد. "
                               f"در صورتِ سؤال با پشتیبانی تماس بگیرید.")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        original = cb.message.caption or cb.message.text or ""
        done = original + "\n\n🚫 <b>لغو شد.</b> مبلغ از کیف پول کاربر کسر شد."
        if cb.message.caption is not None:
            await cb.message.edit_caption(caption=done, reply_markup=None)
        else:
            await cb.message.edit_text(done, reply_markup=None)
    except Exception:
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer("لغو شد 🚫")


# === PATCH_PLATFORM_SMS_EXPIRY_ADMIN_MANUAL_REVIEW_V1 ===
@router.callback_query(F.data.startswith("smsexp:yes:"))
async def sms_expired_admin_confirm(cb: CallbackQuery, bot: Bot):
    """ادمین تایید کرد که کاربر واقعاً واریز کرده — کیفِ پول شارژ می‌شود و
    (چون از WalletCharge با status=approved استفاده می‌کنیم) در گزارشِ
    ماه‌به‌ماهِ رسیدها هم دیده می‌شود."""
    if not await has_perm(cb.from_user.id, "adm:fin"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    wc_id = int(cb.data.split(":")[2])
    async with Session() as s:
        ch = await s.get(WalletCharge, wc_id, with_for_update=True)
        if not ch or ch.status != "pending":
            await cb.answer("این درخواست قبلاً رسیدگی شده.", show_alert=True)
            return
        ch.status = "approved"
        u = await get_user(s, ch.user_telegram_id, for_update=True)
        u.balance = float(u.balance) + float(ch.amount)
        new_bal = float(u.balance)
        s.add(PlatformTxn(user_telegram_id=ch.user_telegram_id, amount=float(ch.amount),
                          kind="sms_charge", note=f"MANUAL:تاییدِ دستیِ ادمین پس از انقضایِ فاکتور #{wc_id}"))
        await s.commit()
        user_tg = ch.user_telegram_id
        amt = float(ch.amount)
    try:
        await bot.send_message(
            user_tg,
            "✅ <b>کیف پولت پس از بررسیِ ادمین شارژ شد!</b>\n"
            f"💰 مبلغ: <b>{rial(amt)}</b>\n"
            f"👛 موجودی فعلی: <b>{rial(new_bal)}</b>")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        done = (cb.message.text or "") + "\n\n✅ <b>تایید شد.</b> کیف پول کاربر شارژ گردید."
        await cb.message.edit_text(done, reply_markup=None)
    except Exception:
        try:
            await cb.message.edit_reply_markup(reply_markup=None)
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer("تایید و شارژ شد ✅")


