    users = await _referred_users(referrer_id)
    text, names = await _referral_text(referrer_id, bot, users)
    kb = _referral_list_kb(referrer_id, users, names, page=page)
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


