@router.callback_query(F.data.startswith("upg:"))
async def buyplan_confirm(cb: CallbackQuery):
    parts = cb.data.split(":")  # upg:{plan}:{bot_id}[:{months}]
    plan, bot_id = parts[1], parts[2]
    months = int(parts[3]) if len(parts) > 3 and parts[3] in ("1", "2") else 0
    async with Session() as _s_check:
        _row_check = await _s_check.get(BotRow, int(bot_id))
        _is_renewal = bool(_row_check and _row_check.owner_id == cb.from_user.id and _row_check.plan == plan)
    if not _is_renewal and not plan_enabled(plan):
        await cb.answer("این پلن فعلاً غیرفعال است.", show_alert=True)
        return
    paid = plans_paid_enabled()

    # قدم اول: انتخاب مدت (۱ یا ۲ ماه)
    if not months:
        if not paid:
            months = 1  # حالت تست/رایگان: مدت‌گزینی لازم نیست
        else:
            final1, _b, _d = plan_price_final(plan)
            # === PATCH_PTC_EVERYWHERE_V1 === قیمتِ منوی مدت باید همان قیمتِ واقعیِ بعد از تخفیف‌هایِ این کاربر باشد
            _dp, _df, _dnote = await display_plan_discount(cb.from_user.id, plan)
            final1 = price_after(final1, _dp, _df)
            kb = InlineKeyboardMarkup(inline_keyboard=[
                [hx_button(f"🗓 ۱ ماهه — {rial(final1)}",
                                      callback_data=f"upg:{plan}:{bot_id}:1",
                                      style=ButtonStyle.SUCCESS)],
                [hx_button(f"🗓🗓 ۲ ماهه — {rial(final1 * 2)}",
                                      callback_data=f"upg:{plan}:{bot_id}:2",
                                      style=ButtonStyle.PRIMARY)],
                [hx_button("⬅️ انصراف", callback_data=f"mb:{bot_id}",
                                      style=ButtonStyle.DANGER)],
            ])
            try:
                await cb.message.edit_text(
                    f"🗓 مدت تمدید/خرید پلن «{PLAN_INFO[Plan(plan)]['title']}» را انتخاب کن:"
                    + (f"\n\n{_dnote}" if _dnote else "")
                    + f"\n\n{PURCHASE_TERMS}",
                    reply_markup=kb, parse_mode="HTML")
            except Exception:
                await cb.message.answer(
                    f"🗓 مدت تمدید/خرید پلن «{PLAN_INFO[Plan(plan)]['title']}» را انتخاب کن:"
                    + (f"\n\n{_dnote}" if _dnote else "")
                    + f"\n\n{PURCHASE_TERMS}",
                    reply_markup=kb, parse_mode="HTML")
            await cb.answer()
            return

    async with Session() as s:
        u = await get_user(s, cb.from_user.id, cb.from_user.full_name, for_update=True, username=cb.from_user.username)
        refs = await s.scalar(
            select(func.count()).select_from(PlatformUser)
            .where(PlatformUser.referrer_id == cb.from_user.id)
        )
        disc = referral_discount(refs or 0)
        # === PATCH_PLATFORM_PROMOTER_V1 === تخفیفِ خریدِ اولِ معرف
        from platform_promoters import promo_for as _promo_for, pct_with_promo as _pwp
        _pinfo = await _promo_for(cb.from_user.id)
        disc, _promo_hit = _pwp(disc, _pinfo)
        # === PATCH_PLATFORM_USER_DISCOUNT_V1 ===
        from platform_user_discounts import percent_for as _ud_pct
        _udp = await _ud_pct(cb.from_user.id, plan)
        if _udp > disc:
            disc, _promo_hit = _udp, False
        ptc_mode, ptc_amt = await ptc_discount_for(cb.from_user.id)
        ptc_note = ""
        if ptc_mode == "percent" and ptc_amt > disc:
            disc = ptc_amt
            ptc_note = f" (شامل تخفیف نفرات برتر: {ptc_amt}٪)"
        base_after_plan_disc, _bse, _pd = plan_price_final(plan)
        price = 0 if not paid else (base_after_plan_disc * (100 - disc) // 100) * months
        if paid and ptc_mode == "flat" and ptc_amt > 0:
            price = max(0, price - ptc_amt * months)
            ptc_note = f" (شامل تخفیف نفرات برتر: {rial(ptc_amt)}/ماه)"
        if price and float(u.balance) < price:
            await _record_failed_purchase(cb.from_user.id, plan, price, bot_id=int(bot_id))
            await cb.answer(f"موجودی کافی نیست. لازم: {rial(price)} (تخفیف {disc}٪{ptc_note})", show_alert=True)
            return
        row = await s.get(BotRow, int(bot_id))
        if not row or row.owner_id != cb.from_user.id:
            await cb.answer("ربات یافت نشد.", show_alert=True)
            return
        # === PATCH_BLOCK_SELF_REACTIVATE_ADMIN_PAUSE_V1 ===
        # همون فیکسی که در my_bot_rehook (دکمهٔ «اتصال مجدد») زده شد، اینجا
        # هم لازم بود: قبلاً پرداختِ تمدید/ارتقایِ پلن، بدونِ چک، وضعیتِ بات
        # رو "active" می‌کرد — یعنی حتی اگه ادمینِ پلتفرم عمداً بات رو
        # admin_paused/locked کرده بود (مثلاً به‌خاطرِ تخلف)، خودِ مالک با
        # پرداختِ پول می‌تونست دورش بزنه. حالا در این حالت، پرداخت و تمدیدِ
        # سررسید انجام می‌شه (حقِ مالکه، پولش رو داده)، ولی وضعیتِ
        # admin_paused/locked دست‌نخورده می‌مونه.
        _was_admin_blocked = row.status in ("admin_paused", "locked")
        if price:
            u.balance = float(u.balance) - price
        was_archived = row.archived_at is not None
        # === PATCH_PLAN_UPGRADE_BANK_V1 ===
        # قبلاً: سررسیدِ پلنِ قبلی + ۳۰×ماهِ پلنِ جدید → باقی‌ماندهٔ «رشد» تبدیل به
        # زمانِ «حرفه‌ای» می‌شد (سوءاستفاده). حالا در ارتقا فقط ماهِ خریداری‌شده
        # حرفه‌ای است و باقی‌ماندهٔ پلنِ قبلی نگه‌داری می‌شود.
        from plan_bank import compute_purchase as _cp
        now = datetime.datetime.now()
        _res = _cp(old_plan=row.plan, new_plan=plan,
                   old_expires=row.plan_expires_at, was_archived=was_archived,
                   old_sub_months=row.sub_months, banked_plan=row.banked_plan,
                   banked_seconds=row.banked_seconds,
                   banked_months=row.banked_sub_months, months=months, now=now)
        row.plan = plan
        new_expiry = _res["expires"]
        row.plan_expires_at = new_expiry
        row.banked_plan = _res["banked_plan"]
        row.banked_seconds = _res["banked_seconds"]
        row.banked_sub_months = _res["banked_months"]
        _bank_note = ""
        if _res["banked_now"] and (_res["banked_seconds"] or 0) > 0:
            _bd = max(1, round(_res["banked_seconds"] / 86400))
            _bank_note = (
                f"\n\n⏳ {_bd} روز از پلنِ «{PLAN_INFO[Plan(_res['banked_plan'])]['title']}» "
                "شما نگه‌داری شد و بعد از پایانِ این دوره خودکار برمی‌گردد.")
        row.last_expiry_notice = None
        if not _was_admin_blocked:
            row.archived_at = None
            # === PATCH_ARCHIVE_RESTORE_WEBHOOK_V1 ===
            # archive_reason هم باید پاک شود، وگرنه ربات «فعال» است ولی
            # هنوز دلیلِ بایگانیِ قبلی رویش مانده و در گزارش‌ها بایگانی
            # به‌نظر می‌رسد.
            row.archive_reason = None
            row.status = "active"
        row.sub_months = months
        s.add(PlanOrder(user_telegram_id=cb.from_user.id, target_bot_id=row.id, plan=plan, amount=price))
        _promo_used = None
        if price:
            s.add(PlatformTxn(user_telegram_id=cb.from_user.id, amount=-price, kind="purchase",
                              note=f"ارتقای @{row.username} به {plan} ({months} ماهه)"))
            if _promo_hit:     # PATCH_PLATFORM_PROMOTER_V1
                from platform_promoters import finalize as _pfin
                _pd = await _pfin(s, cb.from_user.id, _pinfo, int(price))
                if _pd:
                    _promo_used = (_pinfo, int(price), _pd, row.username)
        await s.commit()
        if _promo_used:
            try:
                from platform_promoters import notify_admin as _pnotify
                await _pnotify(None, cb.from_user.id, _promo_used[0], _promo_used[1], _promo_used[2],
                               f"خرید/تمدید پلن {plan} برای @{_promo_used[3]}")
            except Exception:
                logger.exception("اطلاعِ مصرفِ کدِ معرف ناموفق بود")
        uname = row.username
        token = row.token
        _bank_admin_msg = None
        if _res["banked_now"] and (_res["banked_seconds"] or 0) > 0:
            _bank_admin_msg = (
                f"⬆️ ارتقا با نگه‌داریِ زمان: ربات @{uname} (مالک {cb.from_user.id})\n"
                f"به «{PLAN_INFO[Plan(plan)]['title']}» {months} ماهه ارتقا یافت؛ "
                f"{max(1, round(_res['banked_seconds'] / 86400))} روز از «"
                f"{PLAN_INFO[Plan(_res['banked_plan'])]['title']}» نگه‌داری شد.")
# === PATCH_ARCHIVE_RESTORE_WEBHOOK_V1 ===
    # موقعِ بایگانی‌شدن، وب‌هوکِ ربات حذف می‌شود. تا امروز هیچ مسیرِ
    # خروج‌از‌بایگانی آن را برنمی‌گرداند، پس ربات در دیتابیس «فعال» می‌شد
    # ولی تلگرام جایی برایِ تحویلِ آپدیت‌ها نداشت و کاربر می‌گفت «تمدید
    # کردم ولی کار نمی‌کند».
    if was_archived and not _was_admin_blocked:
        try:
            await set_tenant_webhook(token)
        except Exception:
            logger.exception("بازگرداندنِ وب‌هوکِ ربات پس از تمدید ناموفق بود")
        try:
            import tenant_status_bus
            await tenant_status_bus.publish_tenant_invalidate(token)
        except Exception:
            logger.exception("اعلامِ تغییرِ وضعیتِ مستأجر ناموفق بود")

    if _bank_admin_msg and PLATFORM_ADMIN_ID:
        try:
            await cb.bot.send_message(PLATFORM_ADMIN_ID, _bank_admin_msg)
        except Exception:
            logger.exception("اعلانِ ارتقای با نگه‌داری به مدیر ناموفق بود")
    # PATCH_REMOVE_BIO_LOCK_V1 — فقط پاک‌سازیِ تبلیغِ قدیمی (اگر مانده باشد)
    await apply_brand_bio(token, plan)
    restored = "♻️ ربات از بایگانی خارج و فعال شد.\n" if (was_archived and not _was_admin_blocked) else ""
    _admin_block_note = (
        "\n\n⚠️ توجه: این ربات توسط مدیریتِ پلتفرم غیرفعال/قفل شده و با این پرداخت "
        "دوباره فعال نمی‌شود؛ برای رفعِ این وضعیت با پشتیبانی تماس بگیر."
    ) if _was_admin_blocked else ""
    await cb.message.edit_text(
        f"✅ ربات @{uname} به پلن «{PLAN_INFO[Plan(plan)]['title']}» ({months} ماهه) ارتقا یافت.\n"
        f"{restored}📅 سررسید بعدی: {to_jalali(new_expiry)}{ptc_note}{_bank_note}{_admin_block_note}"
    )
    await cb.message.answer("🏠 منوی اصلی:", reply_markup=await smart_home_kb(cb.from_user.id))
    await cb.answer("انجام شد")


# ======================= پنل مدیریت (ادمین اصلی + فرعی) =======================

# تبدیل تاریخ میلادی به شمسی
def to_jalali(dt) -> str:
    """تبدیل datetime (ذخیره‌شده به UTC) به رشتهٔ شمسی، به وقت ایران (تهران).

    === PATCH_TO_JALALI_TEHRAN_OFFSET_V1 ===
    قبلاً این تابع بدون افزودنِ افستِ +۳:۳۰ مستقیم dt را فرمت می‌کرد، در حالی
    که مقادیرِ created_at/plan_expires_at به‌صورتِ UTC ذخیره می‌شوند. همین باعث
    می‌شد ساعتِ نمایش‌داده‌شده در پنلِ ادمین (تاریخ ساخت/سررسید) حدودِ ۳ ساعت و
    نیم عقب‌تر از ساعتِ واقعیِ ایران باشد. برای یکسان‌سازی با _jalali_date_time
    و _fmt_exp_jalali در tenant/__init__.py، همان افستِ +۳:۳۰ اینجا هم اضافه شد.
    """
    if dt is None:
        return "—"
    try:
        local = dt + datetime.timedelta(hours=3, minutes=30)
    except Exception:
        local = dt
    try:
        # تبدیل ساده بدون کتابخانهٔ خارجی (تقریبی برای نمایش)
        # اگر jdatetime نصب باشد از آن استفاده می‌کنیم
        import jdatetime
        jdt = jdatetime.datetime.fromgregorian(datetime=local)
        return jdt.strftime("%Y/%m/%d — %H:%M")
    except ImportError:
        return local.strftime("%Y-%m-%d %H:%M")


def admin_panel_kb(uid: int | None = None) -> InlineKeyboardMarkup:
    """پنل مدیریت بات‌ساز — دسته‌بندی‌شده.

    === PATCH_ADMIN_MENU_GROUPS_V1 ===
    چیدمان و نقشهٔ دسته‌ها به platform_admin_menu.py منتقل شد (پنل به ۲۰+
    دکمهٔ تخت رسیده بود). این تابع فقط یک نازک‌پوشِ سازگاری است تا همهٔ
    فراخوانی‌هایِ موجودِ admin_panel_kb(...) دست‌نخورده کار کنند.
    همهٔ callback_dataهایِ قبلی عیناً حفظ شده‌اند.
    """
# === PATCH_HOMEBTNS_IN_ROOT_PANEL_V1 ===
    # هر بار که ریشهٔ پنل ساخته می‌شود، حافظهٔ «آخرین دسته» پاک می‌شود.
    # وگرنه ورود از ریشه به صفحه‌ای مثلِ «مدیریت دکمه‌ها»، موقعِ بازگشت
    # کاربر را به دستهٔ قبلیِ بازدیدشده پرت می‌کرد.
    from platform_admin_menu import admin_panel_kb as _kb, _LAST_CAT
    if uid is not None:
        _LAST_CAT.pop(uid, None)
    return _kb(uid)


