# === PATCH_LOCK_FILE_LINK_FIELD_V1 ===
# ابزارِ یک‌بارمصرفِ ادمین: به همه‌ی صاحبانِ ربات‌هایی که با نوعِ (الان
# غیرفعالِ) «تبدیلِ فایل» ساخته بودن، پیام می‌فرسته که برن نوعِ رباتشون رو
# عوض کنن. اگه دوباره هم زده بشه اشکالی نداره (فقط دوباره یادآوری می‌شه).

@router.callback_query(F.data == "adm:notify_filelink")
async def adm_notify_filelink_confirm(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    async with Session() as s:
        rows = (await s.scalars(
            select(BotRow).where(BotRow.field == "file_link", BotRow.archived_at.is_(None))
        )).all()
    if not rows:
        await cb.answer("هیچ ربات فعالی با نوعِ «تبدیلِ فایل» پیدا نشد.", show_alert=True)
        return
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("✅ بله، پیام بفرست", callback_data="adm:notify_filelink_go", style=ButtonStyle.DANGER)],
        [hx_button("❌ انصراف", callback_data="adm:back", style=ButtonStyle.DANGER)],
    ])
    await cb.message.edit_text(
        f"⚠️ می‌خوای به {len(rows)} صاحبِ ربات با نوعِ «🔗 تبدیلِ فایل ↔ لینک» پیام بفرستی که "
        "برن نوعِ رباتشون رو عوض کنن؟",
        reply_markup=kb)
    await cb.answer()


@router.callback_query(F.data == "adm:notify_filelink_go")
async def adm_notify_filelink_go(cb: CallbackQuery, bot: Bot):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    async with Session() as s:
        rows = (await s.scalars(
            select(BotRow).where(BotRow.field == "file_link", BotRow.archived_at.is_(None))
        )).all()
    await cb.answer("در حالِ ارسال…")
    sent, failed = 0, 0
    for r in rows:
        try:
            await bot.send_message(
                r.owner_id,
                f"⚠️ ربات @{r.username} با نوعِ «🔗 تبدیل فایل ↔ لینک» ساخته شده بود، ولی این نوع "
                "موقتاً غیرفعال شده و دیگه پشتیبانی نمی‌شه.\n\n"
                "لطفاً از «🗂 ربات‌های من» → روی این ربات بزن → «✏️ ویرایش کامل ربات» → "
                "«🔒 تغییرِ نوعِ ربات» و یه نوعِ دیگه انتخاب کن — این تغییر برایِ تو <b>رایگانه</b>.")
            sent += 1
        except Exception:
            failed += 1
    await cb.message.answer(f"✅ پیام برایِ {sent} نفر فرستاده شد." + (f" ({failed} ناموفق.)" if failed else ""))


# === PATCH_ADM_REFCHECK_V1 ===
# بررسیِ دستیِ ادمین: برای یک آیدیِ تلگرامیِ مشخص، چند نفر واقعاً referrer_id
# آن‌ها برابر همین آیدی است (یعنی واقعاً به‌عنوانِ کاربرِ کاملاً جدید از طریق
# لینکِ دعوت وارد شده‌اند) + وضعیتش در طرح جایزهٔ ویژهٔ دعوت.
@router.callback_query(F.data == "adm:refcheck")
async def adm_refcheck_start(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    await state.set_state(AdmRefCheckFSM.tg_id)
    await cb.message.answer(
        "🔎 آیدیِ عددیِ تلگرامِ کاربر را بفرست تا دعوت‌های واقعاً ثبت‌شده‌اش را نشان بدهم.\n"
        "برای لغو بنویس: لغو")
    await cb.answer()


@router.message(AdmRefCheckFSM.tg_id)
async def adm_refcheck_result(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    raw = (msg.text or "").strip()
    if raw in ("لغو", "❌ لغو / بازگشت", BTN_CANCEL):
        await state.clear()
        await msg.answer("لغو شد.")
        return
    if not raw.isdigit():
        await msg.answer("❌ فقط آیدیِ عددیِ تلگرام را بفرست (یا بنویس «لغو»):")
        return
    tg_id = int(raw)
    await state.clear()

    async with Session() as s:
        owner = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == tg_id))
        referred = (await s.scalars(
            select(PlatformUser).where(PlatformUser.referrer_id == tg_id)
            .order_by(PlatformUser.created_at)
        )).all()
        entry = await s.scalar(select(InviteCampaignEntry).where(InviteCampaignEntry.telegram_id == tg_id))

    if not owner:
        await msg.answer(f"⚠️ کاربری با آیدیِ <code>{tg_id}</code> اصلاً در دیتابیسِ پلتفرم پیدا نشد.")
        return

    lines = [
        f"👤 کاربر: {owner.full_name or '—'} — <code>{tg_id}</code>",
        f"👥 تعداد دعوت‌شدگانِ واقعاً ثبت‌شده (referrer_id): <b>{len(referred)}</b>",
    ]
    if entry:
        lines.append(f"🎁 وضعیت در طرح جایزهٔ ویژه: <b>{entry.status}</b>"
                      + (f" (برنده در {entry.win_day})" if entry.win_day else ""))
    else:
        lines.append("🎁 این کاربر اصلاً وارد طرح جایزهٔ ویژه نشده (دکمهٔ «قبول دارم» را نزده).")

    if referred:
        lines.append("\n📋 لیست دعوت‌شدگان:")
        for u in referred:
            jdate = u.created_at.strftime("%Y-%m-%d %H:%M") if u.created_at else "—"
            lines.append(f"   • {u.full_name or '—'} — <code>{u.telegram_id}</code> — عضویت: {jdate}")
    await state.update_data(refcheck_owner_id=tg_id)
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="📋 مرورِ کاربرانِ تازه‌واردِ بدونِ معرف",
                             callback_data=f"adm:refcand:{tg_id}:0", style=ButtonStyle.PRIMARY)],
        [InlineKeyboardButton(text="➕ افزودنِ دستی با آیدیِ دقیق",
                             callback_data=f"adm:reffix:{tg_id}", style=ButtonStyle.SUCCESS)],
    ])
    await msg.answer("\n".join(lines), reply_markup=kb)


REFCAND_PAGE_SIZE = 8


async def _refcand_list() -> list["PlatformUser"]:
    """کاربرانی که هنوز هیچ معرفی ندارن (referrer_id خالیه)، از تازه‌ترین
    به قدیمی‌ترین — اینا کاندیدهایِ محتمل برایِ «دعوتِ گم‌شده»ان، چون اگه
    از قبل یه معرفِ درست داشتن، اصلاً نیازی به دستکاری ندارن."""
    async with Session() as s:
        rows = (await s.scalars(
            select(PlatformUser).where(PlatformUser.referrer_id.is_(None))
            .order_by(PlatformUser.created_at.desc()).limit(200)
        )).all()
    return list(rows)


def _refcand_kb(referrer_id: int, users: list["PlatformUser"], page: int) -> InlineKeyboardMarkup:
    start = page * REFCAND_PAGE_SIZE
    chunk = users[start:start + REFCAND_PAGE_SIZE]
    rows = []
    for u in chunk:
        when = u.created_at.strftime("%m-%d %H:%M") if u.created_at else "—"
        uname = f"@{u.username}" if getattr(u, "username", None) else ""
        label = f"👤 {u.full_name or '—'} {uname} — {when}".strip()
        rows.append([InlineKeyboardButton(
            text=label[:64], callback_data=f"adm:refattach:{referrer_id}:{u.telegram_id}", style=ButtonStyle.PRIMARY)])
    nav = []
    if page > 0:
        nav.append(InlineKeyboardButton(text="◀️ قبلی", callback_data=f"adm:refcand:{referrer_id}:{page-1}", style=ButtonStyle.PRIMARY))
    if start + REFCAND_PAGE_SIZE < len(users):
        nav.append(InlineKeyboardButton(text="بعدی ▶️", callback_data=f"adm:refcand:{referrer_id}:{page+1}", style=ButtonStyle.PRIMARY))
    if nav:
        rows.append(nav)
    rows.append([InlineKeyboardButton(text="⬅️ بازگشت", callback_data="adm:back", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


@router.callback_query(F.data.startswith("adm:refcand:"))
async def adm_refcand_page(cb: CallbackQuery):
    """PATCH_ADM_REFCAND_V1 — به‌جایِ اینکه ادمین مجبور باشه آیدیِ دقیقِ
    عددیِ دعوت‌شده رو از قبل بدونه (که خیلی‌وقت‌ها نمی‌دونه، فقط اسم/زمانِ
    تقریبیِ عضویتِ دوستش رو می‌دونه)، اینجا لیستِ کاربرانِ تازه‌واردِ
    بدونِ‌معرف رو نشون می‌ده تا بینشون بگرده و با یه تپ وصلش کنه."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")
    referrer_id, page = int(parts[2]), int(parts[3])
    users = await _refcand_list()
    if not users:
        await cb.answer("🎉 هیچ کاربرِ بدونِ‌معرفی وجود نداره — همه یا معرف دارن یا اصلاً کسی نیست.",
                        show_alert=True)
        return
    kb = _refcand_kb(referrer_id, users, page)
    text = (
        f"📋 <b>کاربرانِ تازه‌واردِ بدونِ معرف</b> ({len(users)} نفر)\n\n"
        f"داری برایِ معرفِ <code>{referrer_id}</code> می‌گردی. اسم/زمانِ عضویتِ دوستش رو پیدا کن و بزن روش:"
    )
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


@router.callback_query(F.data.startswith("adm:refattach:"))
async def adm_refattach(cb: CallbackQuery):
    """اتصالِ یک‌کلیکیِ کاربرِ انتخاب‌شده از لیست، به‌عنوانِ دعوت‌شده‌یِ
    همون معرف — با همون محافظت‌هایِ فیکسِ دستیِ آیدی (بدونِ بازنویسیِ
    رفرالِ از قبل‌موجود)."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")
    referrer_id, candidate_id = int(parts[2]), int(parts[3])
    if candidate_id == referrer_id:
        await cb.answer("❌ این خودِ معرفه، نمی‌شه دعوت‌شده‌ی خودش باشه.", show_alert=True)
        return
    async with Session() as s:
        referred = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == candidate_id))
        if not referred:
            await cb.answer("⚠️ این کاربر دیگه پیدا نشد.", show_alert=True)
            return
        if referred.referrer_id:
            await cb.answer(f"⚠️ این کاربر همین الان معرفِ دیگه‌ای گرفت ({referred.referrer_id}).",
                            show_alert=True)
            return
        referred.referrer_id = referrer_id
        referred_name = referred.full_name or "—"
        await s.commit()
    await cb.answer(f"✅ «{referred_name}» به‌عنوانِ دعوت‌شده‌ی {referrer_id} ثبت شد.", show_alert=True)
    # لیست رو دوباره بساز (این نفر دیگه نباید تو لیستِ بدونِ‌معرف باشه)
    users = await _refcand_list()
    kb = _refcand_kb(referrer_id, users, 0)
    text = (
        f"📋 <b>کاربرانِ تازه‌واردِ بدونِ معرف</b> ({len(users)} نفر)\n\n"
        f"داری برایِ معرفِ <code>{referrer_id}</code> می‌گردی. اسم/زمانِ عضویتِ دوستش رو پیدا کن و بزن روش:"
    )
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)


@router.callback_query(F.data.startswith("adm:reffix:"))
async def adm_refcheck_fix_start(cb: CallbackQuery, state: FSMContext):
    """PATCH_ADM_REFCHECK_FIX_V1 — فیکسِ دستیِ دعوتی که به‌خاطرِ باگِ قدیمیِ
    referrer_id (کاربرِ از قبل موجود، رفرالش ثبت نمی‌شد) گم شده بود. ادمین
    آیدیِ عددیِ همون دعوت‌شده رو می‌ده، اگه واقعاً هنوز معرف نداشته باشه،
    اینجا مستقیم بهش وصل می‌شه — دقیقاً همون کاری که خودِ ربات باید موقعِ
    /start می‌کرد."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    referrer_id = int(cb.data.split(":")[2])
    await state.set_state(AdmRefCheckFSM.fix_referred_id)
    await state.update_data(reffix_referrer_id=referrer_id)
    await cb.message.answer(
        f"➕ آیدیِ عددیِ کسی که باید به‌عنوانِ دعوت‌شده‌ی <code>{referrer_id}</code> ثبت بشه رو بفرست.\n"
        "برای لغو بنویس: لغو")
    await cb.answer()


@router.message(AdmRefCheckFSM.fix_referred_id)
async def adm_refcheck_fix_recv(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    raw = (msg.text or "").strip()
    if raw in ("لغو", "❌ لغو / بازگشت", BTN_CANCEL):
        await state.clear()
        await msg.answer("لغو شد.")
        return
    if not raw.isdigit():
        await msg.answer("❌ فقط آیدیِ عددیِ تلگرام را بفرست (یا بنویس «لغو»):")
        return
    referred_id = int(raw)
    data = await state.get_data()
    referrer_id = data.get("reffix_referrer_id")
    await state.clear()
    if not referrer_id:
        await msg.answer("❌ اطلاعاتِ عملیات منقضی شده؛ از اول با «🔎 بررسی دعوت‌های کاربر» شروع کن.")
        return
    if referred_id == referrer_id:
        await msg.answer("❌ آیدیِ دعوت‌شده نمی‌تونه همون آیدیِ معرف باشه.")
        return

    async with Session() as s:
        referred = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == referred_id))
        if not referred:
            await msg.answer(
                f"⚠️ کاربری با آیدیِ <code>{referred_id}</code> اصلاً در دیتابیسِ پلتفرم پیدا نشد "
                "(یعنی هنوز حتی یه‌بار هم با بات‌ساز /start نزده).")
            return
        if referred.referrer_id:
            if referred.referrer_id == referrer_id:
                await msg.answer("ℹ️ این کاربر از قبل دقیقاً با همین معرف ثبت شده؛ نیازی به کاری نیست.")
            else:
                await msg.answer(
                    f"⚠️ این کاربر از قبل معرفِ دیگه‌ای داره (<code>{referred.referrer_id}</code>) — "
                    "برای جلوگیری از سوءاستفاده، رفرالِ ثبت‌شده رو بازنویسی نمی‌کنم.")
            return
        referred.referrer_id = referrer_id
        referred_name = referred.full_name or "—"
        await s.commit()

    await msg.answer(
        f"✅ انجام شد. کاربر «{referred_name}» (<code>{referred_id}</code>) حالا به‌عنوانِ دعوت‌شده‌ی "
        f"<code>{referrer_id}</code> ثبت شد.")


