@router.callback_query(F.data == "adm:tutorial")
async def adm_tutorial(cb: CallbackQuery):
    """باز کردن صفحهٔ آموزش در حالت ویرایش (فقط ادمین اصلی)."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    from config import WEBHOOK_BASE
    # === PATCH_BOTRUNNER_APP_V1 ===
    # اپ روی دامنهٔ خودش نشسته (مثلاً botrunner.example.com)، نه دامنهٔ
    # وبهوکِ ربات؛ پس اگر RUNNER_BASE در .env باشد همان مبنا است.
    base = (os.getenv("RUNNER_BASE", "").strip() or WEBHOOK_BASE or "").rstrip("/")
    if not base.startswith("https://"):
        await cb.answer("WEBHOOK_BASE تنظیم نشده یا https نیست.", show_alert=True)
        return
    from tenant.shared.tutorial_page import _edit_token
    edit_url = f"{base}/tutorial?edit={_edit_token()}"
    public_url = f"{base}/tutorial"
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("✏️ باز کردن آموزش در حالت ویرایش",
                              web_app=WebAppInfo(url=edit_url),
                              style=ButtonStyle.SUCCESS)],
        [hx_button("⬅️ بازگشت", callback_data="adm:back",
                              style=ButtonStyle.DANGER)],
    ])
    await cb.message.edit_text(
        "✏️ <b>ویرایش صفحهٔ آموزش</b>\n\n"
        "با دکمهٔ زیر، صفحه با حالت ویرایش داخل تلگرام باز می‌شود؛ "
        "هر تغییری بدهی همان لحظه روی سرور ذخیره می‌شود و برای همه اعمال می‌گردد.\n\n"
        "🔗 لینک عمومی (برای دکمهٔ مینی‌اپ انجمن — بدون قابلیت ویرایش):\n"
        f"<code>{public_url}</code>\n\n"
        "⚠️ لینک ویرایش را جایی عمومی نگذار.",
        reply_markup=kb)
    await cb.answer()


@router.callback_query(F.data == "adm:stats")
async def adm_stats(cb: CallbackQuery):
    if not await has_perm(cb.from_user.id, "adm:stats"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    async with Session() as s:
        users = await s.scalar(select(func.count()).select_from(PlatformUser))
        bots = await s.scalar(select(func.count()).select_from(BotRow))
        orders = await s.scalar(select(func.count()).select_from(PlanOrder))
        revenue = await s.scalar(select(func.coalesce(func.sum(PlanOrder.amount), 0)))
        charged = await s.scalar(
            select(func.coalesce(func.sum(WalletCharge.amount), 0))
            .where(WalletCharge.status == "approved")
        )
    kb = InlineKeyboardMarkup(inline_keyboard=[
        # === PATCH_STATS_SHARE_V1 ===
        [hx_button("📣 آمارِ کلی (قابلِ‌اشتراک در کانال)",
                   callback_data="adm:share_stats", style=ButtonStyle.SUCCESS)],
        [hx_button("🧾 خریدهای دقیق و درآمد (امروز/هفته/ماه)",
                              callback_data="adm:stats_purchases", style=ButtonStyle.SUCCESS)],
        # === PATCH_MONTHLY_RECEIPTS_REPORT_V1 ===
        [hx_button("🗓 گزارشِ ماه‌به‌ماهِ رسیدها",
                   callback_data="adm:recyears", style=ButtonStyle.SUCCESS)],
        [hx_button("👥 وضعیتِ اعضا (عضویت در کانال + فعالیت)",
                              callback_data="adm:members_stats", style=ButtonStyle.PRIMARY)],
        [hx_button("⬅️ بازگشت", callback_data="adm:back", style=ButtonStyle.DANGER)]
    ])
    await cb.message.edit_text(
        f"📊 <b>آمار</b>\n\n"
        f"کاربران: {users}\nربات‌ها: {bots}\n"
        f"خرید پلن: {orders} (درآمد: {rial(revenue)})\n"
        f"مجموع شارژ تاییدشده: {rial(charged)}",
        reply_markup=kb,
    )
    await cb.answer()


# === PATCH_PURCHASE_STATS_REPORT_V1 ===
# گزارشِ دقیقِ خریدها و رسیدها برایِ سه بازهٔ زمانی: امروز، ۷ روزِ اخیر و
# ماهِ شمسیِ جاری. برایِ هر بازه: تعداد و مبلغِ خریدهایِ موفقِ پلن (به
# تفکیکِ پلنِ رشد/حرفه‌ای)، و وضعیتِ رسیدهایِ شارژِ کیف‌پول (تاییدشده،
# فیک/لغوشده، ردشده و هنوز تاییدنشده).
#
# نکته دربارهٔ تخفیف: مبلغِ ثبت‌شده روی هر PlanOrder همان مبلغِ نهایی
# (بعد از اعمالِ هر تخفیفی — رفرال یا نفراتِ برتر) است؛ یعنی درآمدِ این
# گزارش از اول با تخفیف حساب شده و نیازی به کسرِ جداگانه ندارد.
#
# نکته دربارهٔ کارت‌به‌کارت: خریدِ پلن همیشه از موجودیِ کیف‌پول کسر
# می‌شود، و کیف‌پول هم فقط از طریقِ تاییدِ رسیدِ کارت‌به‌کارت (WalletCharge)
# شارژ می‌شود؛ پس «جمعِ شارژِ تاییدشده» در این گزارش همان ورودیِ
# کارت‌به‌کارتِ مستقیم در همان بازه است.
#
# نکته دربارهٔ سود: در این سیستم هزینه‌ای (مثلاً هزینهٔ سرور/پنل) ثبت
# نمی‌شود، پس عددِ «درآمد» همان گردشِ ناخالص است، نه سودِ خالص.

def _purchase_report_period_bounds() -> dict:
    """مرزهایِ سه بازه (به وقتِ UTC، برایِ مقایسه با created_at که UTC ذخیره می‌شود)."""
    import jdatetime
    now_utc = datetime.datetime.utcnow()
    now_tehran = now_utc + datetime.timedelta(hours=3, minutes=30)
    today_start_tehran = now_tehran.replace(hour=0, minute=0, second=0, microsecond=0)
    week_start_tehran = today_start_tehran - datetime.timedelta(days=6)  # شاملِ خودِ امروز = ۷ روز
    try:
        jnow = jdatetime.datetime.fromgregorian(datetime=now_tehran)
        jmonth_start = jdatetime.datetime(jnow.year, jnow.month, 1, 0, 0, 0)
        month_start_tehran = jmonth_start.togregorian()
    except Exception:
        month_start_tehran = now_tehran.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    offset = datetime.timedelta(hours=3, minutes=30)
    return {
        "امروز": today_start_tehran - offset,
        "۷ روزِ اخیر": week_start_tehran - offset,
        "ماهِ جاری": month_start_tehran - offset,
    }


async def _purchase_breakdown(since: datetime.datetime) -> dict:
    """تعداد و مبلغِ خریدهایِ موفقِ پلن از since تا الان، به تفکیکِ پلن."""
    async with Session() as s:
        rows = (await s.execute(
            select(PlanOrder.plan, func.count(), func.coalesce(func.sum(PlanOrder.amount), 0))
            .where(PlanOrder.status == "paid", PlanOrder.created_at >= since)
            .group_by(PlanOrder.plan)
        )).all()
    out = {"growth_count": 0, "growth_sum": 0.0, "pro_count": 0, "pro_sum": 0.0,
           "other_count": 0, "other_sum": 0.0, "total_count": 0, "total_sum": 0.0}
    for plan, cnt, total in rows:
        cnt = int(cnt or 0)
        total = float(total or 0)
        out["total_count"] += cnt
        out["total_sum"] += total
        if plan == Plan.GROWTH.value:
            out["growth_count"] += cnt
            out["growth_sum"] += total
        elif plan == Plan.PRO.value:
            out["pro_count"] += cnt
            out["pro_sum"] += total
        else:
            out["other_count"] += cnt
            out["other_sum"] += total
    return out


async def _receipt_breakdown(since: datetime.datetime) -> dict:
    """وضعیتِ رسیدهایِ شارژِ کیف‌پول از since تا الان: تاییدشده، فیک/لغوشده،
    ردشدهٔ دیگر و هنوز تاییدنشده (در انتظار)."""
    async with Session() as s:
        approved_cnt = await s.scalar(
            select(func.count()).select_from(WalletCharge)
            .where(WalletCharge.status == "approved", WalletCharge.created_at >= since))
        approved_sum = await s.scalar(
            select(func.coalesce(func.sum(WalletCharge.amount), 0))
            .where(WalletCharge.status == "approved", WalletCharge.created_at >= since))
        rejected_cnt = await s.scalar(
            select(func.count()).select_from(WalletCharge)
            .where(WalletCharge.status == "rejected", WalletCharge.created_at >= since))
        rejected_sum = await s.scalar(
            select(func.coalesce(func.sum(WalletCharge.amount), 0))
            .where(WalletCharge.status == "rejected", WalletCharge.created_at >= since))
        pending_cnt = await s.scalar(
            select(func.count()).select_from(WalletCharge)
            .where(WalletCharge.status == "pending", WalletCharge.created_at >= since))
        pending_sum = await s.scalar(
            select(func.coalesce(func.sum(WalletCharge.amount), 0))
            .where(WalletCharge.status == "pending", WalletCharge.created_at >= since))
        # «فیک» = رسیدی که خودکار تایید شده بود ولی ادمین بعداً به‌عنوانِ فیک لغوش کرده
        # (دکمهٔ «لغو - رسید فیک بود»)؛ این‌ها با یادداشتِ REVOKE: روی PlatformTxn ردیابی می‌شوند.
        fake_cnt = await s.scalar(
            select(func.count()).select_from(PlatformTxn)
            .where(PlatformTxn.kind == "charge", PlatformTxn.note.like("REVOKE:%"),
                   PlatformTxn.created_at >= since))
        fake_sum = await s.scalar(
            select(func.coalesce(func.sum(-PlatformTxn.amount), 0))
            .where(PlatformTxn.kind == "charge", PlatformTxn.note.like("REVOKE:%"),
                   PlatformTxn.created_at >= since))
    rejected_cnt = int(rejected_cnt or 0)
    rejected_sum = float(rejected_sum or 0)
    fake_cnt = int(fake_cnt or 0)
    fake_sum = float(fake_sum or 0)
    other_rejected_cnt = max(0, rejected_cnt - fake_cnt)
    other_rejected_sum = max(0.0, rejected_sum - fake_sum)
    return {
        "approved_cnt": int(approved_cnt or 0), "approved_sum": float(approved_sum or 0),
        "fake_cnt": fake_cnt, "fake_sum": fake_sum,
        "other_rejected_cnt": other_rejected_cnt, "other_rejected_sum": other_rejected_sum,
        "pending_cnt": int(pending_cnt or 0), "pending_sum": float(pending_sum or 0),
    }


async def _purchase_report_text() -> str:
    bounds = _purchase_report_period_bounds()
    lines = ["🧾 <b>خریدهای دقیق و درآمد</b>\n"]
    for label, since in bounds.items():
        p = await _purchase_breakdown(since)
        r = await _receipt_breakdown(since)
        lines.append(f"📅 <b>{label}</b>")
        lines.append(
            f"💰 خریدِ پلن: {p['total_count']} فقره — {rial(p['total_sum'])}\n"
            f"  🌱 پلنِ رشد: {p['growth_count']} فقره — {rial(p['growth_sum'])}\n"
            f"  💼 پلنِ حرفه‌ای: {p['pro_count']} فقره — {rial(p['pro_sum'])}"
        )
        if p["other_count"]:
            lines.append(f"  ▪️ سایر: {p['other_count']} فقره — {rial(p['other_sum'])}")
        lines.append(
            f"💳 رسیدهایِ شارژِ کارت‌به‌کارت:\n"
            f"  ✅ تاییدشده: {r['approved_cnt']} فقره — {rial(r['approved_sum'])}\n"
            f"  🚫 فیک (بعداً لغوشده): {r['fake_cnt']} فقره — {rial(r['fake_sum'])}\n"
            f"  ❌ ردشدهٔ دیگر: {r['other_rejected_cnt']} فقره — {rial(r['other_rejected_sum'])}\n"
            f"  ⏳ هنوز تاییدنشده: {r['pending_cnt']} فقره — {rial(r['pending_sum'])}"
        )
        lines.append("")
    lines.append(
        "ℹ️ مبلغِ خریدها بعد از کسرِ تخفیف (رفرال/نفراتِ برتر) است. "
        "چون خریدِ پلن از موجودیِ کیف‌پول کسر می‌شود و کیف‌پول فقط از رسیدِ "
        "کارت‌به‌کارتِ تاییدشده شارژ می‌شود، «تاییدشده» بالا همان ورودیِ "
        "مستقیمِ کارت‌به‌کارت در همان بازه است. این عدد درآمدِ ناخالص است؛ "
        "چون هزینه‌ای (سرور/پنل و غیره) در سیستم ثبت نمی‌شود، سودِ خالص محاسبه نشده."
    )
    return "\n".join(lines)


# ═══════ PATCH_MONTHLY_RECEIPTS_REPORT_V1 — گزارشِ ماه‌به‌ماهِ رسیدها ═══════
# درخواستِ مدیر: سال را بزند، ۱۲ ماهِ شمسی را ببیند، رویِ هر ماه بزند و
# رسیدهایِ تاییدشدهٔ همان ماه را با مبلغ و تاریخِ دقیقِ تهران ببیند.
#
# قاعدهٔ زمانی که همه‌جایِ این بخش رعایت می‌شود: created_at در دیتابیس
# UTC است ولی مرزهایِ ماه شمسی/تهرانی‌اند، پس مرزها با کسرِ ۳:۳۰ به UTC
# تبدیل می‌شوند — همان کاری که _purchase_report_period_bounds می‌کند.
#
# === PATCH_MONTHLY_REPORT_ALL_CHARGE_METHODS_V1 ===
# باگِ گزارش‌شده: این گزارش فقط جدولِ WalletCharge (شارژِ دستی با آپلودِ
# رسید) را می‌خواند. اما راه‌هایِ دیگرِ شارژِ کیف‌پول — آیدی‌پی، زرین‌پال،
# کارت‌به‌کارتِ خودکار (پیامکِ بانکی)، سواپ/کریپتو — اصلاً ردیفی در
# WalletCharge نمی‌سازند؛ فقط در دفترِ مشترکِ PlatformTxn (با kindِ
# مخصوصِ همان روش) ثبت می‌شوند. پس هرکسی با این روش‌ها شارژ می‌کرد، توی
# این گزارش دیده نمی‌شد. الان گزارش رویِ همان دفترِ مشترک (PlatformTxn)
# حساب می‌کند که همهٔ روش‌ها — حتی شارژهایِ دستیِ قبلی — دقیقاً یک ردیف
# آنجا دارند، پس تکراری هم شمرده نمی‌شود.
_CHARGE_TXN_KINDS = ("charge", "idpay_charge", "sms_charge", "zarinpal_charge", "swap_charge",
                     "partner_purchase")
_CHARGE_KIND_LABELS = {
    "charge": "🧾 رسیدِ دستی", "idpay_charge": "💳 آیدی‌پی",
    "sms_charge": "📲 کارت‌به‌کارتِ خودکار", "zarinpal_charge": "🅿️ زرین‌پال",
    "swap_charge": "🔄 سواپ/کریپتو", "partner_purchase": "🤝 خریدِ عمدهٔ همکار",
}
_TEHRAN_OFFSET = datetime.timedelta(hours=3, minutes=30)
_JMONTHS = ["فروردین", "اردیبهشت", "خرداد", "تیر", "مرداد", "شهریور",
            "مهر", "آبان", "آذر", "دی", "بهمن", "اسفند"]


def _jnow():
    import jdatetime
    return jdatetime.datetime.fromgregorian(
        datetime=datetime.datetime.utcnow() + _TEHRAN_OFFSET)


def _jmonth_bounds_utc(year: int, month: int) -> tuple:
    """(شروع، پایان) یک ماهِ شمسی به‌صورتِ UTC، برایِ مقایسه با created_at."""
    import jdatetime
    start_t = jdatetime.datetime(year, month, 1, 0, 0, 0).togregorian()
    if month == 12:
        nxt = jdatetime.datetime(year + 1, 1, 1, 0, 0, 0)
    else:
        nxt = jdatetime.datetime(year, month + 1, 1, 0, 0, 0)
    return start_t - _TEHRAN_OFFSET, nxt.togregorian() - _TEHRAN_OFFSET


def _to_tehran_str(dt) -> str:
    """created_atِ UTC → رشتهٔ شمسیِ دقیق به وقتِ تهران."""
    if dt is None:
        return "—"
    local = dt + _TEHRAN_OFFSET
    try:
        import jdatetime
        return jdatetime.datetime.fromgregorian(datetime=local).strftime("%Y/%m/%d %H:%M")
    except ImportError:
        return local.strftime("%Y-%m-%d %H:%M")


@router.callback_query(F.data == "adm:recyears")
async def adm_receipt_years(cb: CallbackQuery):
    """انتخابِ سال."""
    if not await has_perm(cb.from_user.id, "adm:stats"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    cur = _jnow().year
    rows = [[hx_button(f"📅 سال {y}", callback_data=f"adm:recyear:{y}",
                       style=ButtonStyle.PRIMARY if y == cur else None)]
            for y in range(cur, cur - 3, -1)]
    rows.append([hx_button("⬅️ بازگشت", callback_data="adm:stats",
                           style=ButtonStyle.DANGER)])
    await cb.message.edit_text(
        "🗓 <b>گزارشِ ماه‌به‌ماهِ رسیدها</b>\n\n"
        "یک سال را انتخاب کن تا ماه‌هایش را ببینی.\n"
        "همهٔ تاریخ‌ها و ساعت‌ها به وقتِ تهران است.",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
    await cb.answer()


async def _month_totals(year: int, month: int) -> tuple[int, float]:
    """(تعداد، مبلغِ) شارژهایِ موفقِ یک ماهِ شمسی، از همهٔ روش‌ها."""
    a, b = _jmonth_bounds_utc(year, month)
    async with Session() as s:
        cnt = await s.scalar(
            select(func.count()).select_from(PlatformTxn).where(
                PlatformTxn.kind.in_(_CHARGE_TXN_KINDS),
                ~PlatformTxn.note.like("جایزهٔ بازی%"),
                PlatformTxn.created_at >= a, PlatformTxn.created_at < b))
        total = await s.scalar(
            select(func.coalesce(func.sum(PlatformTxn.amount), 0)).where(
                PlatformTxn.kind.in_(_CHARGE_TXN_KINDS),
                ~PlatformTxn.note.like("جایزهٔ بازی%"),
                PlatformTxn.created_at >= a, PlatformTxn.created_at < b))
    return int(cnt or 0), float(total or 0)


@router.callback_query(F.data.startswith("adm:recyear:"))
async def adm_receipt_months(cb: CallbackQuery):
    """۱۲ ماهِ یک سال، با جمعِ هر ماه رویِ خودِ دکمه."""
    if not await has_perm(cb.from_user.id, "adm:stats"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    year = int(cb.data.split(":")[2])
    await cb.answer("در حال محاسبه…")
    jn = _jnow()
    last_month = jn.month if year == jn.year else 12
    rows, grand_cnt, grand_sum = [], 0, 0.0
    for m in range(1, last_month + 1):
        cnt, total = await _month_totals(year, m)
        grand_cnt += cnt
        grand_sum += total
        mark = "🟢" if cnt else "⚪️"
        rows.append([hx_button(
            f"{mark} {_JMONTHS[m-1]} — {cnt} فقره · {rial(total)}",
            callback_data=f"adm:recmonth:{year}:{m}")])
    rows.append([hx_button("⬅️ بازگشت", callback_data="adm:recyears",
                           style=ButtonStyle.DANGER)])
    await cb.message.edit_text(
        f"🗓 <b>سال {year}</b>\n\n"
        f"جمعِ کلِ سال: <b>{grand_cnt}</b> شارژِ موفق (همهٔ روش‌ها) — "
        f"<b>{rial(grand_sum)}</b>\n\n"
        "روی هر ماه بزن تا فهرستِ رسیدهایش را ببینی.",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))


_REC_PAGE_SIZE = 8


@router.callback_query(F.data.startswith("adm:recmonth:"))
async def adm_receipt_month_detail(cb: CallbackQuery):
    """فهرستِ رسیدهایِ تاییدشدهٔ یک ماه؛ هر رسید یک دکمهٔ شیشه‌ایِ جداست،
    با زدنش پروندهٔ کاملِ همان کاربر (ربات‌ها و خریدهایش) باز می‌شود."""
    if not await has_perm(cb.from_user.id, "adm:stats"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")
    year, month = int(parts[2]), int(parts[3])
    offset_param = int(parts[4]) if len(parts) > 4 else None
    await cb.answer("در حال خواندن…")
    a, b = _jmonth_bounds_utc(year, month)
    async with Session() as s:
        rows_db = (await s.scalars(
            select(PlatformTxn).where(
                PlatformTxn.kind.in_(_CHARGE_TXN_KINDS),
                ~PlatformTxn.note.like("جایزهٔ بازی%"),
                PlatformTxn.created_at >= a, PlatformTxn.created_at < b)
            .order_by(PlatformTxn.created_at.asc()))).all()
        names = {}
        if rows_db:
            ids = {r.user_telegram_id for r in rows_db}
            us = (await s.scalars(select(PlatformUser).where(
                PlatformUser.telegram_id.in_(ids)))).all()
            names = {u.telegram_id: (("@" + u.username) if u.username
                                     else (u.full_name or str(u.telegram_id)))
                     for u in us}

    total = sum(float(r.amount or 0) for r in rows_db)
    # پیش‌فرض (بدون offset صریح): آخرین صفحه، یعنی جدیدترین پرداختی‌ها —
    # همان‌طور که داخلِ صفحه هم صعودی چیده می‌شوند، جدیدترین همیشه پایینِ
    # پایین می‌افتد، دقیقاً چیزی که خواسته شده.
    offset = (max(0, len(rows_db) - _REC_PAGE_SIZE)
              if offset_param is None else offset_param)
    head = (f"🗓 <b>{_JMONTHS[month-1]} {year}</b>\n"
            f"✅ شارژهایِ موفق: <b>{len(rows_db)}</b> فقره\n"
            f"💰 مجموع: <b>{rial(total)}</b>\n"
            "┈┅━━⊷⊰✨⊱⊶━━┅┈\n"
            "روی هر ردیف بزن تا حسابِ کاربری، اطلاعاتِ ربات و خریدهایش باز شود:"
            if rows_db else
            f"🗓 <b>{_JMONTHS[month-1]} {year}</b>\n\nدر این ماه رسیدِ تاییدشده‌ای نیست.")

    page = rows_db[offset:offset + _REC_PAGE_SIZE]
    rows = []
    for r in page:
        who = names.get(r.user_telegram_id, str(r.user_telegram_id))
        method = _CHARGE_KIND_LABELS.get(r.kind, r.kind)
        uid_cb = r.user_telegram_id
        ret = f"{year}:{month}:{offset}"
        # ردیفِ اول: یوزرنیم + تاریخ‌وساعت، آبی، کنارِ هم — سرِ هر تراکنش
        rows.append([
            hx_button(f"👤 {who}"[:40], callback_data=f"usr:back:{uid_cb}:{ret}",
                      style=ButtonStyle.PRIMARY),
            hx_button(_to_tehran_str(r.created_at), callback_data=f"usr:back:{uid_cb}:{ret}",
                      style=ButtonStyle.PRIMARY),
        ])
        # ردیفِ دوم: مبلغ | روش، دو دکمهٔ سبزِ کنارِ هم، همان تراکنش
        rows.append([
            hx_button(rial(float(r.amount or 0)), callback_data=f"usr:back:{uid_cb}:{ret}",
                      style=ButtonStyle.SUCCESS),
            hx_button(method, callback_data=f"usr:back:{uid_cb}:{ret}",
                      style=ButtonStyle.SUCCESS),
        ])

    nav = []
    if offset > 0:
        nav.append(hx_button("◀️ قبلی", callback_data=f"adm:recmonth:{year}:{month}:{max(0, offset - _REC_PAGE_SIZE)}"))
    if offset + _REC_PAGE_SIZE < len(rows_db):
        nav.append(hx_button("بعدی ▶️", callback_data=f"adm:recmonth:{year}:{month}:{offset + _REC_PAGE_SIZE}"))
    if nav:
        rows.append(nav)
    rows.append([hx_button("⬅️ بازگشت به ماه‌ها", callback_data=f"adm:recyear:{year}",
                           style=ButtonStyle.DANGER)])

    kb = InlineKeyboardMarkup(inline_keyboard=rows)
    try:
        await cb.message.edit_text(head, reply_markup=kb)
    except Exception:
        await cb.message.answer(head, reply_markup=kb)


@router.callback_query(F.data == "adm:stats_purchases")
async def adm_stats_purchases(cb: CallbackQuery):
    if not await has_perm(cb.from_user.id, "adm:stats"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("🔄 بروزرسانی", callback_data="adm:stats_purchases", style=ButtonStyle.SUCCESS)],
        [hx_button("⬅️ بازگشت", callback_data="adm:stats", style=ButtonStyle.DANGER)],
    ])
    text = await _purchase_report_text()
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


# === PATCH_MEMBER_STATS_V1 ===
_MEMBER_STATS_INACTIVE_DAYS = 14  # بیش از این تعداد روز بدون تعامل = «بدونِ فعالیت»
_member_refresh_progress: dict[int, str] = {}  # admin_telegram_id -> متنِ وضعیتِ فعلیِ بروزرسانی


async def _member_stats_counts() -> dict:
    inactive_cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=_MEMBER_STATS_INACTIVE_DAYS)
    async with Session() as s:
        joined = await s.scalar(select(func.count()).select_from(PlatformUser).where(
            PlatformUser.channel_status == "joined", PlatformUser.is_banned == False))
        left = await s.scalar(select(func.count()).select_from(PlatformUser).where(
            PlatformUser.channel_status == "not_joined", PlatformUser.ever_joined == True,
            PlatformUser.is_banned == False))
        not_joined = await s.scalar(select(func.count()).select_from(PlatformUser).where(
            PlatformUser.channel_status == "not_joined", PlatformUser.ever_joined == False,
            PlatformUser.is_banned == False))
        unchecked = await s.scalar(select(func.count()).select_from(PlatformUser).where(
            PlatformUser.channel_status.is_(None), PlatformUser.is_banned == False))
        inactive = await s.scalar(select(func.count()).select_from(PlatformUser).where(
            or_(PlatformUser.last_active_at.is_(None), PlatformUser.last_active_at < inactive_cutoff),
            PlatformUser.is_banned == False))
        last_check = await s.scalar(select(func.max(PlatformUser.channel_checked_at)))
    return {"joined": joined or 0, "left": left or 0, "not_joined": not_joined or 0,
            "unchecked": unchecked or 0, "inactive": inactive or 0, "last_check": last_check}


def _member_stats_kb(counts: dict) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(inline_keyboard=[
        [hx_button(f"✅ عضوِ کانال ({counts['joined']})",
                              callback_data="adm:members_list:joined:0", style=ButtonStyle.SUCCESS)],
        [hx_button(f"🚪 لفت‌داده ({counts['left']})",
                              callback_data="adm:members_list:left:0", style=ButtonStyle.PRIMARY)],
        [hx_button(f"🔴 هنوز عضو نشده ({counts['not_joined']})",
                              callback_data="adm:members_list:not_joined:0", style=ButtonStyle.DANGER)],
        [hx_button(f"💤 بدونِ فعالیت (بیش از {_MEMBER_STATS_INACTIVE_DAYS} روز) ({counts['inactive']})",
                              callback_data="adm:members_list:inactive:0", style=ButtonStyle.PRIMARY)],
        [hx_button("🔄 بروزرسانیِ وضعیتِ عضویت در کانال",
                              callback_data="adm:members_refresh", style=ButtonStyle.SUCCESS)],
        [hx_button("⬅️ بازگشت", callback_data="adm:stats", style=ButtonStyle.DANGER)],
    ])


async def _member_stats_text(counts: dict) -> str:
    last = to_jalali(counts["last_check"]) if counts["last_check"] else "هنوز بررسی نشده"
    return (
        "👥 <b>وضعیتِ اعضایِ ربات</b>\n\n"
        f"✅ عضوِ کانال: <b>{counts['joined']}</b>\n"
        f"🚪 لفت‌داده (قبلاً عضو بوده): <b>{counts['left']}</b>\n"
        f"🔴 هنوز عضو نشده: <b>{counts['not_joined']}</b>\n"
        f"❔ هنوز بررسی نشده: {counts['unchecked']}\n\n"
        f"💤 بدونِ فعالیت (بیش از {_MEMBER_STATS_INACTIVE_DAYS} روز): <b>{counts['inactive']}</b>\n\n"
        f"🕓 آخرین بروزرسانیِ وضعیتِ عضویت: {last}\n\n"
        "برایِ دیدنِ لیستِ کاملِ هر بخش (با پروفایل و ربات، اگه داشته باشن)، روی همون بخش بزن."
    )


@router.callback_query(F.data == "adm:members_stats")
async def adm_members_stats(cb: CallbackQuery):
    if not await has_perm(cb.from_user.id, "adm:stats"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    counts = await _member_stats_counts()
    await cb.message.edit_text(await _member_stats_text(counts), reply_markup=_member_stats_kb(counts))
    await cb.answer()


@router.callback_query(F.data == "adm:members_refresh")
async def adm_members_refresh(cb: CallbackQuery, bot: Bot):
    """PATCH_MEMBER_STATS_V1 — بررسیِ وضعیتِ عضویتِ همهٔ کاربرها در کانالِ
    اجباریِ پلتفرم، به‌صورتِ پس‌زمینه و با محدودیتِ نرخ (تا به ریت‌لیمیتِ
    تلگرام نخوریم). چون ممکنه صدها/هزاران کاربر باشه، این کار می‌تونه چند
    دقیقه طول بکشه؛ به‌جای قفل‌کردنِ کاربر پشتِ یه پیام، به‌صورتِ تسکِ پس‌زمینه
    اجرا می‌شه و کاربر می‌تونه هر وقت خواست دوباره بیاد وضعیت رو ببینه."""
    if not await has_perm(cb.from_user.id, "adm:stats"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    target = await get_pset("fj_target", "")
    if not target:
        await cb.answer("کانالِ اجباریِ پلتفرم تنظیم نشده — چیزی برایِ بررسی نیست.", show_alert=True)
        return
    admin_id = cb.from_user.id
    if _member_refresh_progress.get(admin_id) == "running":
        await cb.answer("یه بروزرسانی از قبل درحالِ اجراست، صبر کن تموم بشه.", show_alert=True)
        return
    await cb.answer("🔄 بروزرسانی در پس‌زمینه شروع شد؛ چند دقیقه طول می‌کشه.", show_alert=True)
    asyncio.create_task(_member_refresh_task(bot, admin_id))


async def _member_refresh_task(bot: Bot, admin_id: int) -> None:
    _member_refresh_progress[admin_id] = "running"
    target = await get_pset("fj_target", "")
    checked = 0
    try:
        async with Session() as s:
            ids = (await s.scalars(select(PlatformUser.id).where(PlatformUser.is_banned == False))).all()
        for uid in ids:
            async with Session() as s:
                u = await s.get(PlatformUser, uid)
                if not u:
                    continue
                joined = await is_channel_member(bot, target, u.telegram_id)
                u.channel_status = "joined" if joined else "not_joined"
                u.channel_checked_at = datetime.datetime.utcnow()
                if joined:
                    u.ever_joined = True
                await s.commit()
            checked += 1
            await asyncio.sleep(0.1)  # جلوگیری از ریت‌لیمیتِ get_chat_member
    except Exception as e:
        print("member_refresh_task error:", e)
    finally:
        _member_refresh_progress[admin_id] = "done"
    try:
        counts = await _member_stats_counts()
        await bot.send_message(
            admin_id,
            f"✅ بروزرسانیِ وضعیتِ اعضا تمام شد ({checked} کاربر بررسی شد).\n\n"
            + await _member_stats_text(counts),
            reply_markup=_member_stats_kb(counts),
        )
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


_MEMBER_CAT_TITLES = {
    "joined": "✅ عضوِ کانال",
    "left": "🚪 لفت‌داده",
    "not_joined": "🔴 هنوز عضو نشده",
    "inactive": "💤 بدونِ فعالیت",
}
_MEMBER_LIST_PAGE_SIZE = 10


@router.callback_query(F.data.startswith("adm:members_list:"))
async def adm_members_list(cb: CallbackQuery):
    if not await has_perm(cb.from_user.id, "adm:stats"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    _, _, cat, page_s = cb.data.split(":")
    page = int(page_s)
    inactive_cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=_MEMBER_STATS_INACTIVE_DAYS)
    async with Session() as s:
        q = select(PlatformUser).where(PlatformUser.is_banned == False)
        if cat == "joined":
            q = q.where(PlatformUser.channel_status == "joined")
        elif cat == "left":
            q = q.where(PlatformUser.channel_status == "not_joined", PlatformUser.ever_joined == True)
        elif cat == "not_joined":
            q = q.where(PlatformUser.channel_status == "not_joined", PlatformUser.ever_joined == False)
        elif cat == "inactive":
            q = q.where(or_(PlatformUser.last_active_at.is_(None),
                            PlatformUser.last_active_at < inactive_cutoff))
        total = await s.scalar(select(func.count()).select_from(q.subquery()))
        rows = (await s.scalars(
            q.order_by(PlatformUser.id).offset(page * _MEMBER_LIST_PAGE_SIZE).limit(_MEMBER_LIST_PAGE_SIZE)
        )).all()
        tg_ids = [u.telegram_id for u in rows]
        bot_by_owner: dict[int, BotRow] = {}
        if tg_ids:
            brs = (await s.scalars(select(BotRow).where(BotRow.owner_id.in_(tg_ids)))).all()
            for br in brs:
                bot_by_owner.setdefault(br.owner_id, br)  # اولین باتِ هر مالک

    title = _MEMBER_CAT_TITLES.get(cat, cat)
    lines = [f"{title} — صفحهٔ {page + 1} (مجموع {total})\n"]
    for u in rows:
        bot_line = ""
        br = bot_by_owner.get(u.telegram_id)
        if br:
            bot_line = f"\n   🤖 ربات: @{br.username or '—'} ({br.plan}, {br.status})"
        last_act = to_jalali(u.last_active_at) if u.last_active_at else "—"
        lines.append(
            f"👤 <b>{(u.full_name or '—')}</b>\n"
            f"   آیدی: <code>{u.telegram_id}</code>\n"
            f"   آخرین فعالیت: {last_act}"
            f"{bot_line}"
        )
    nav = []
    if page > 0:
        nav.append(hx_button("⬅️ قبلی", callback_data=f"adm:members_list:{cat}:{page-1}", style=ButtonStyle.PRIMARY))
    if (page + 1) * _MEMBER_LIST_PAGE_SIZE < (total or 0):
        nav.append(hx_button("بعدی ➡️", callback_data=f"adm:members_list:{cat}:{page+1}", style=ButtonStyle.PRIMARY))
    kb_rows = ([nav] if nav else []) + [
        [hx_button("⬅️ بازگشت به وضعیتِ اعضا", callback_data="adm:members_stats", style=ButtonStyle.DANGER)]
    ]
    text = "\n\n".join(lines) if rows else f"{title} — کسی توی این بخش نیست."
    try:
        await cb.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows))
    except Exception:
        await cb.message.answer(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows))
    await cb.answer()


