@router.callback_query(F.data.startswith("chg:"))
async def adm_charge_decide(cb: CallbackQuery, bot: Bot):
    if not await has_perm(cb.from_user.id, "adm:fin"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")
    if len(parts) != 3:
        await cb.answer()
        return
    _, action, cid = parts
    try:
        cid_int = int(cid)
    except ValueError:
        await cb.answer("شناسهٔ نامعتبر", show_alert=True)
        return
    try:
        async with Session() as s:
            # FOR UPDATE: هم‌زمان با تأییدِ خودکار، دوبار شارژ نشود
            ch = await s.get(WalletCharge, cid_int, with_for_update=True)
            if not ch or ch.status != "pending":
                await cb.answer("قبلاً رسیدگی شده.", show_alert=True)
                return
            if action == "ok":
                ch.status = "approved"
                u = await get_user(s, ch.user_telegram_id, for_update=True)
                u.balance = float(u.balance) + float(ch.amount)
                new_bal = float(u.balance)
                s.add(PlatformTxn(user_telegram_id=ch.user_telegram_id, amount=float(ch.amount),
                                  kind="charge", note=f"شارژ #{cid_int}"))
                await s.commit()
                amt = float(ch.amount)
                utg = ch.user_telegram_id
                try:
                    await bot.send_message(utg, f"✅ کیف پول شما {rial(amt)} شارژ شد.\nموجودی جدید: {rial(new_bal)}")
                except Exception:
                    logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
                await cb.answer(f"✅ تایید شد — موجودی جدید: {rial(new_bal)}", show_alert=True)
            else:
                ch.status = "rejected"
                await s.commit()
                utg = ch.user_telegram_id
                # === PATCH_CHARGE_REJECT_SUPPORT_BTN_V1 ===
                # قبلاً وقتی رسید رد می‌شد، کاربر فقط یک متنِ خشک می‌گرفت و
                # هیچ راهی برایِ پیگیری (اگر واقعاً واریز کرده ولی رسیدش
                # اشتباه خوانده شده) نداشت. الان دکمهٔ «ارسال پیام به
                # پشتیبانی» هم زیرش می‌آید — همان الگویِ support_btn_row که
                # جایِ دیگری از همین فایل هم استفاده می‌شود.
                support = await get_pset("support_contact", "")
                try:
                    await bot.send_message(
                        utg, "❌ رسید شارژ شما تایید نشد.\n\n"
                             "اگه فکر می‌کنی اشتباهی رخ داده یا واقعاً واریز کردی، "
                             "با پشتیبانی در تماس باش:",
                        reply_markup=InlineKeyboardMarkup(inline_keyboard=[support_btn_row(support)]))
                except Exception:
                    logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
                await cb.answer("رد شد")
    except Exception as e:
        import traceback
        print("adm_charge_decide error:\n" + traceback.format_exc())
        await cb.answer(f"❌ خطا در پردازش: {type(e).__name__}", show_alert=True)
        return
    try:
        if cb.message.caption is not None:
            done = (cb.message.caption or "") + ("\n\n✅ تایید و شارژ شد." if action == "ok" else "\n\n❌ رد شد.")
            await cb.message.edit_caption(caption=done, reply_markup=None)
        else:
            await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


# === PATCH_ADM_ORDERS_INLINE_V1 ===
# قبلاً «آخرین خریدها» فقط یه لیستِ متنیِ ساده (بدونِ صفحه‌بندی، بدونِ
# جزئیات) بود. الان هر خرید یه دکمهٔ اینلاینِ جداست، با صفحه‌بندیِ عقب/جلو،
# و تیترِ بالا تاریخِ امروز رو نشون می‌ده؛ با زدنِ هر دکمه، اطلاعاتِ کاملِ
# کاربر + خرید + رباتی که براش خریداری شده باز می‌شه.
ADM_ORDERS_PAGE_SIZE = 8
_ADM_ORDERS_RANGE_LBL = {"all": "همه", "today": "امروز", "week": "۱ هفته", "month": "۱ ماه"}


def _adm_orders_range_start_utc(rng: str):
    """ابتدایِ بازهٔ موردنظر را برحسبِ UTC برمی‌گرداند (created_at با UTC ذخیره می‌شود).

    مبنا ساعتِ تهران است (افستِ +۳:۳۰، هم‌راستا با to_jalali)."""
    if rng == "all":
        return None
    tehran_now = datetime.datetime.now() + datetime.timedelta(hours=3, minutes=30)
    start_today_tehran = tehran_now.replace(hour=0, minute=0, second=0, microsecond=0)
    start_today_utc = start_today_tehran - datetime.timedelta(hours=3, minutes=30)
    if rng == "today":
        return start_today_utc
    if rng == "week":
        return start_today_utc - datetime.timedelta(days=6)
    if rng == "month":
        return start_today_utc - datetime.timedelta(days=29)
    return None


@router.callback_query(F.data.startswith("adm:orders:"))
@router.callback_query(F.data == "adm:orders")
async def adm_orders(cb: CallbackQuery):
    if not await has_perm(cb.from_user.id, "adm:orders"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")
    try:
        page = int(parts[2])
    except (IndexError, ValueError):
        page = 0
    rng = parts[3] if len(parts) > 3 and parts[3] in _ADM_ORDERS_RANGE_LBL else "all"
    range_start = _adm_orders_range_start_utc(rng)
    async with Session() as s:
        q = select(PlanOrder).order_by(PlanOrder.id.desc())
        if range_start is not None:
            q = q.where(PlanOrder.created_at >= range_start)
        orders = (await s.scalars(q.limit(300))).all()
    total = len(orders)
    pages = max(1, (total + ADM_ORDERS_PAGE_SIZE - 1) // ADM_ORDERS_PAGE_SIZE)
    page = max(0, min(page, pages - 1))
    chunk = orders[page * ADM_ORDERS_PAGE_SIZE: (page + 1) * ADM_ORDERS_PAGE_SIZE]
    today_j = to_jalali(datetime.datetime.now()).split(" ")[0]
    txt = (f"🛒 <b>آخرین خریدها</b> — {_ADM_ORDERS_RANGE_LBL[rng]}\nتاریخِ امروز: {today_j}\n\n"
           f"صفحه {page + 1}/{pages} — {total} خرید")
    kb_rows = []
    range_row = []
    for r_key, r_lbl in _ADM_ORDERS_RANGE_LBL.items():
        lbl = f"• {r_lbl} •" if r_key == rng else r_lbl
        range_row.append(hx_button(lbl, callback_data=f"adm:orders:0:{r_key}",
                                    style=ButtonStyle.SUCCESS if r_key == rng else ButtonStyle.PRIMARY))
    kb_rows.append(range_row)
    if not orders:
        txt = f"خریدی در این بازه ({_ADM_ORDERS_RANGE_LBL[rng]}) ثبت نشده."
    for o in chunk:
        plan_lbl = PLAN_INFO.get(Plan(o.plan), {}).get("title", o.plan) if o.plan in (p.value for p in Plan) else o.plan
        kb_rows.append([hx_button(
            f"#{o.id} | {plan_lbl} | {rial(o.amount)} | 👤{o.user_telegram_id}",
            callback_data=f"adm:orderview:{o.id}:{page}:{rng}", style=ButtonStyle.PRIMARY)])
    nav = []
    if page > 0:
        nav.append(hx_button("◀️ قبلی", callback_data=f"adm:orders:{page - 1}:{rng}", style=ButtonStyle.PRIMARY))
    if page < pages - 1:
        nav.append(hx_button("بعدی ▶️", callback_data=f"adm:orders:{page + 1}:{rng}", style=ButtonStyle.PRIMARY))
    if nav:
        kb_rows.append(nav)
    kb_rows.append([hx_button("⬅️ بازگشت", callback_data="adm:back", style=ButtonStyle.DANGER)])
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    try:
        await cb.message.edit_text(txt, reply_markup=kb)
    except Exception:
        await cb.message.answer(txt, reply_markup=kb)
    await cb.answer()


@router.callback_query(F.data.startswith("adm:orderview:"))
async def adm_order_view(cb: CallbackQuery):
    if not await has_perm(cb.from_user.id, "adm:orders"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")
    oid, page = int(parts[2]), int(parts[3])
    rng = parts[4] if len(parts) > 4 and parts[4] in _ADM_ORDERS_RANGE_LBL else "all"
    async with Session() as s:
        o = await s.get(PlanOrder, oid)
        if not o:
            await cb.answer("سفارش یافت نشد (شاید حذف شده).", show_alert=True)
            return
        u = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == o.user_telegram_id))
        target_bot = await s.get(BotRow, o.target_bot_id) if o.target_bot_id else None

    plan_lbl = PLAN_INFO.get(Plan(o.plan), {}).get("title", o.plan) if o.plan in (p.value for p in Plan) else o.plan
    status_lbl = {"paid": "🟢 پرداخت‌شده", "pending": "🟡 در انتظار", "failed": "🔴 ناموفق"}.get(o.status, o.status)

    lines = [
        "🧾 <b>جزئیاتِ خرید</b>\n",
        f"🆔 شمارهٔ سفارش: <b>#{o.id}</b>",
        f"📦 پلن: <b>{plan_lbl}</b>",
        f"💰 مبلغ: <b>{rial(o.amount)}</b>",
        f"📌 وضعیت: {status_lbl}",
        f"📅 تاریخ: {to_jalali(o.created_at)}",
        "",
        "👤 <b>اطلاعاتِ کاربر</b>",
        f"آیدیِ عددی: <code>{o.user_telegram_id}</code>",
    ]
    if u:
        lines.append(f"نام: {u.full_name or '—'}")
        lines.append(f"یوزرنیم: {('@' + u.username) if u.username else '—'}")
        lines.append(f"موجودیِ کیف‌پول: {rial(u.balance)}")
    else:
        lines.append("(اطلاعاتِ بیشتری از این کاربر تو دیتابیسِ پلتفرم ثبت نشده)")
    lines.append("")
    lines.append("🤖 <b>رباتی که برایش خریداری شده</b>")
    if target_bot:
        field_lbl = FIELDS.get(target_bot.field, target_bot.field)
        lines.append(f"یوزرنیم: @{target_bot.username}")
        lines.append(f"نوع: {field_lbl}")
        lines.append(f"پلنِ فعلی: {PLAN_INFO.get(Plan(target_bot.plan), {}).get('title', target_bot.plan)}")
        lines.append(f"مالک: <code>{target_bot.owner_id}</code>")
    else:
        lines.append("(ربات یافت نشد — شاید بعداً حذف شده)")

    kb_rows = []
    if target_bot:
        kb_rows.append([hx_button(f"🤖 مشاهدهٔ ربات @{target_bot.username}",
                                  callback_data=f"abot:{target_bot.id}:all")])
    kb_rows.append([hx_button("🧾 نمایشِ رسیدِ پرداختِ کاربر",
                              callback_data=f"adm:orderreceipt:{oid}:{page}:{rng}")])
    kb_rows.append([hx_button("⬅️ بازگشت به لیستِ خریدها", callback_data=f"adm:orders:{page}:{rng}",
                              style=ButtonStyle.DANGER)])
    text = "\n".join(lines)
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


# === PATCH_ADM_ORDER_RECEIPT_V1 ===
# نمایشِ رسیدِ شارژِ کیف‌پولی که این خرید از محلِ آن پرداخت شده. چون
# PlanOrder خودش رسید ذخیره نمی‌کند (رسید مالِ WalletCharge است)، نزدیک‌ترین
# شارژِ تأییدشدهٔ همان کاربر (نزدیک به زمانِ ثبتِ سفارش) پیدا می‌شود.
@router.callback_query(F.data.startswith("adm:orderreceipt:"))
async def adm_order_receipt(cb: CallbackQuery, bot: Bot):
    if not await has_perm(cb.from_user.id, "adm:orders"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    _, _, oid_s, page_s, rng = cb.data.split(":")
    oid, page = int(oid_s), int(page_s)
    async with Session() as s:
        o = await s.get(PlanOrder, oid)
        if not o:
            await cb.answer("سفارش یافت نشد.", show_alert=True)
            return
        charges = (await s.scalars(
            select(WalletCharge)
            .where(WalletCharge.user_telegram_id == o.user_telegram_id,
                   WalletCharge.status == "approved")
            .order_by(WalletCharge.id.desc())
        )).all()
    if not charges:
        await cb.answer("رسیدِ تأییدشده‌ای برایِ این کاربر ثبت نشده.", show_alert=True)
        return
    # نزدیک‌ترین شارژ به زمانِ ثبتِ سفارش (قبل یا بعدش)
    ch = min(charges, key=lambda c: abs((c.created_at - o.created_at).total_seconds()))
    kb = InlineKeyboardMarkup(inline_keyboard=[[
        hx_button("⬅️ بازگشت به جزئیاتِ خرید", callback_data=f"adm:orderview:{oid}:{page}:{rng}",
                  style=ButtonStyle.DANGER)
    ]])
    cap = (
        f"🧾 <b>رسیدِ شارژِ کیف‌پول</b>\n\n"
        f"🆔 شمارهٔ شارژ: #{ch.id}\n"
        f"👤 کاربر: <code>{ch.user_telegram_id}</code>\n"
        f"💰 مبلغ: {rial(ch.amount)}\n"
        f"📅 تاریخ: {to_jalali(ch.created_at)}\n"
        + (f"💳 ۴ رقمِ آخرِ کارت: {ch.sender_card4}\n" if ch.sender_card4 else "")
        + (f"\n📝 متنِ رسید:\n{ch.receipt_text}" if ch.receipt_text else "")
        + f"\n\n(مرتبط با سفارشِ #{oid} — نزدیک‌ترین شارژِ تأییدشدهٔ همین کاربر)"
    )
    try:
        if ch.receipt_file_id:
            await bot.send_photo(cb.from_user.id, ch.receipt_file_id, caption=cap, reply_markup=kb)
        else:
            await cb.message.answer(cap, reply_markup=kb)
    except Exception:
        await cb.message.answer(cap, reply_markup=kb)
    await cb.answer()


# ======== مدیریت کاربران (کامل) ========

@router.callback_query(F.data == "adm:users")
async def adm_users(cb: CallbackQuery, state: FSMContext):
    if not await has_perm(cb.from_user.id, "adm:users"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    await state.set_state(AdminFSM.search_user)
    await cb.message.answer(
        "شناسهٔ عددی یا یوزرنیمِ کاربر را بفرست (مثلاً <code>123456789</code> یا <code>@username</code>):",
        reply_markup=await smart_cancel_kb())
    await cb.answer()


async def _build_user_profile(uid: int, return_cb: str = "adm:back") -> tuple[str, InlineKeyboardMarkup] | None:
    """متن + کیبوردِ پروفایلِ کاربر را می‌سازد. اگر کاربر یافت نشد None برمی‌گرداند."""
    async with Session() as s:
        u = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == uid))
        if not u:
            return None
        bots = (await s.scalars(select(BotRow).where(BotRow.owner_id == uid))).all()
        orders = (await s.scalars(
            select(PlanOrder).where(PlanOrder.user_telegram_id == uid)
            .order_by(PlanOrder.created_at))).all()
        charges_ok = await s.scalar(
            select(func.coalesce(func.sum(WalletCharge.amount), 0))
            .where(WalletCharge.user_telegram_id == uid, WalletCharge.status == "approved")
        )
        refs = await s.scalar(
            select(func.count()).select_from(PlatformUser).where(PlatformUser.referrer_id == uid)
        )
        banned = u.is_banned
        bal = u.balance
        full_name = u.full_name or "—"
        created_at = u.created_at
        referrer_id = u.referrer_id

    joined_str = to_jalali(created_at)
    refs = refs or 0

    active_trials = await plan_trials.active_or_used_trials_for_user(uid)
    revoked_trials = await plan_trials.revoked_trials_for_user(uid)

    lines = [
        "👤 <b>پروفایل کاربر</b>\n",
        f"🆔 شناسه: <code>{uid}</code>",
        f"📛 نام: {full_name}",
        f"📅 تاریخ عضویت: {joined_str}",
        f"💰 موجودی کیف پول: {rial(bal)}",
        f"💳 مجموع شارژ تاییدشده: {rial(charges_ok or 0)}",
        f"👥 زیرمجموعه‌ها: {refs}",
        f"🔗 معرف: <code>{referrer_id}</code>" if referrer_id else "🔗 معرف: ندارد",
        f"🚦 وضعیت: {'🔴 بن‌شده' if banned else '🟢 فعال'}",
    ]

    orders_by_bot: dict[int, list] = {}
    for o in orders:
        orders_by_bot.setdefault(o.target_bot_id, []).append(o)

    if bots:
        lines.append(f"\n🤖 <b>ربات‌های ساخته‌شده ({len(bots)} عدد):</b>")
        for r in bots:
            lock_tag = ""
            if r.status == "locked":
                reason = (r.lock_reason or "").strip()
                lock_tag = f" — 🔒 قفل ({reason})" if reason else " — 🔒 قفل"
            exp_txt = to_jalali(r.plan_expires_at) if r.plan_expires_at else "بدون سررسید"
            lines.append(
                f"• @{r.username} — {PLAN_INFO[Plan(r.plan)]['title']}{lock_tag}\n"
                f"   📅 ساخته‌شده: {to_jalali(r.created_at)}  •  ⏳ سررسید: {exp_txt}"
            )
            bot_orders = orders_by_bot.get(r.id, [])
            if bot_orders:
                lines.append(f"   🧾 خریدهای این ربات ({len(bot_orders)}):")
                for o in bot_orders:
                    st_tag = "" if o.status == "paid" else f" ({o.status})"
                    lines.append(
                        f"     ↳ {PLAN_INFO[Plan(o.plan)]['title']} — {rial(o.amount)} — "
                        f"{to_jalali(o.created_at)}{st_tag}")

    if active_trials:
        lines.append("\n🎁 <b>تست‌های فعال/مصرف‌شده:</b>")
        for t in active_trials:
            title = PLAN_INFO[Plan(t["plan"])]["title"]
            st_txt = "مصرف‌شده (روی یک ربات فعال است)" if t["status"] == "used" else "تاییدشده"
            exp_txt = to_jalali(t["expires_at"]) if t["expires_at"] else "—"
            lines.append(f"• {title} — {st_txt} — سررسید: {exp_txt}")

    if revoked_trials:
        lines.append("\n🚫 <b>تست‌های لغوشده (توسط ادمین):</b>")
        for t in revoked_trials:
            title = PLAN_INFO[Plan(t["plan"])]["title"]
            when_txt = to_jalali(t["revoked_at"]) if t["revoked_at"] else "—"
            note_txt = f" — یادداشت: {_html.escape(t['revoke_note'])}" if t["revoke_note"] else ""
            lines.append(f"• {title} — لغو شده در {when_txt}{note_txt}")

    # سفارش‌های خرید پلن که به رباتِ حذف‌شده تعلق دارند (اگر باشد)
    known_bot_ids = {r.id for r in bots}
    orphan_orders = [o for o in orders if o.target_bot_id not in known_bot_ids]
    if orphan_orders:
        lines.append(f"\n🧾 <b>خریدهای مربوط به ربات‌های حذف‌شده ({len(orphan_orders)}):</b>")
        for o in orphan_orders:
            lines.append(f"• {PLAN_INFO[Plan(o.plan)]['title']} — {rial(o.amount)} — {to_jalali(o.created_at)}")

    # === PATCH_BOT_AUDIT_LOG_V1 ===
    # سابقهٔ انتقال و حذف — از جدولِ bot_audit_log. فقط رویدادهایی که
    # بعد از نصبِ این قابلیت افتاده‌اند اینجا دیده می‌شوند.
    from models import BotAuditLog
    async with Session() as s:
        audit = list((await s.scalars(
            select(BotAuditLog).where(
                (BotAuditLog.from_owner == uid) | (BotAuditLog.to_owner == uid))
            .order_by(BotAuditLog.id.desc()).limit(20))).all())
    audit_rows = []
    _sent = [a for a in audit if a.action == "transfer" and a.from_owner == uid]
    _recv = [a for a in audit if a.action == "transfer" and a.to_owner == uid]
    _del = [a for a in audit if a.action == "delete"]
    if _sent:
        lines.append(f"\n🔄 <b>ربات‌های منتقل‌شده به دیگری ({len(_sent)}):</b>")
        for a in _sent:
            lines.append(f"• @{a.username or '؟'} ← <code>{a.to_owner}</code>"
                         f" — {to_jalali(a.created_at)}")
            audit_rows.append([hx_button(f"🔄 @{a.username or a.bot_id}",
                                         callback_data=f"usr:audit:{a.id}")])
    if _recv:
        lines.append(f"\n📥 <b>ربات‌های دریافت‌شده از دیگری ({len(_recv)}):</b>")
        for a in _recv:
            lines.append(f"• @{a.username or '؟'} ← از <code>{a.from_owner}</code>"
                         f" — {to_jalali(a.created_at)}")
            audit_rows.append([hx_button(f"📥 @{a.username or a.bot_id}",
                                         callback_data=f"usr:audit:{a.id}")])
    if _del:
        lines.append(f"\n🗑 <b>ربات‌های حذف‌شده ({len(_del)}):</b>")
        for a in _del:
            lines.append(f"• @{a.username or '؟'} — {to_jalali(a.created_at)}")
            audit_rows.append([hx_button(f"🗑 @{a.username or a.bot_id}",
                                         callback_data=f"usr:audit:{a.id}")])

    # دکمه‌های بخش مالی
    # === PATCH_BOT_AUDIT_LOG_V1 ===
    wallet_row = [
        hx_button("➕ شارژ", callback_data=f"usr:add:{uid}"),
        hx_button("➖ کسر", callback_data=f"usr:sub:{uid}"),
    ]
    days_row = [
        hx_button("⏳ افزودن/کسر روزِ ربات‌های کاربر", callback_data=f"usr:days:{uid}"),
    ]
    # === PATCH_WALLET_TRANSFER_V1 ===
    move_row = [
        hx_button("🔄 انتقال کلِ موجودی به کاربرِ دیگر",
                  callback_data=f"usr:move:{uid}"),
    ]
    # دکمهٔ بن/آنبن
    ban_row = [
        hx_button("🔓 آنبن کاربر" if banned else "🚫 بن کاربر",
            callback_data=f"usr:ban:{uid}"
        )
    ]
    # دکمهٔ لغوِ تستِ فعال (فقط اگر تستِ تاییدشده/مصرف‌نشده‌ای وجود داشته باشد)
    trial_rows = []
    if active_trials:
        trial_rows.append([
            hx_button("❌ لغو تست فعال", callback_data=f"usr:trialrevoke:{uid}",
                       style=ButtonStyle.DANGER),
        ])
    # دکمه‌های ربات‌های کاربر
    bot_rows = []
    for r in bots:
        is_locked = r.status == "locked"
        bot_rows.append([
            hx_button(f"🤖 @{r.username}", callback_data=f"usr_bot_detail:{r.id}:{uid}"),
            hx_button("🗑 حذف", callback_data=f"usr_bot_del:{r.id}:{uid}"),
        ])
        bot_rows.append([
            hx_button(("🔓 رفع قفلِ @" + r.username) if is_locked else ("🔒 قفلِ @" + r.username),
                callback_data=(f"usr_bot_unlock:{r.id}:{uid}" if is_locked
                               else f"usr_bot_lock:{r.id}:{uid}")),
        ])
    # ارجاع به پشتیبانی و ارسال پیام
    support_row = [
        hx_button("🎫 ارجاع به پشتیبانی", callback_data=f"usr:ticket:{uid}"),
        hx_button("📨 ارسال پیام", callback_data=f"usr:sendmsg:{uid}"),
    ]
    # === PATCH_USER_RECEIPTS_LIST_V1 ===
    # ادمین می‌خواست ببیند کاربر با پول‌هایی که شارژ کرده چیکار کرده —
    # قبلاً فقط جمعِ شارژِ تاییدشده در متن بود، ولی خودِ رسیدها
    # (عکس/متن) و رسیدهای رد/در‌انتظار جایی قابل‌دیدن نبودند.
    receipts_row = [
        hx_button("🧾 رسیدهای ارسالی کاربر", callback_data=f"usr:receipts:{uid}:0"),
    ]
    back_row = [
        hx_button("⬅️ بازگشت", callback_data=return_cb, style=ButtonStyle.DANGER)
    ]

    kb = InlineKeyboardMarkup(inline_keyboard=[
        wallet_row, days_row, move_row, ban_row, *trial_rows, *bot_rows,
        # === PATCH_BOT_AUDIT_LOG_V1 ===
        *audit_rows,
        receipts_row, support_row, back_row
    ])
    text = "\n".join(lines)
    if len(text) > 3900:
        text = text[:3850] + "\n\n… (خلاصه شد؛ برای جزئیات کامل هر ربات از دکمهٔ آن ربات استفاده کن)"
    return text, kb


# === PATCH_USER_RECEIPTS_LIST_V1 ===
_UR_PAGE_SIZE = 8
_UR_STATUS_EMOJI = {"approved": "✅", "pending": "⏳", "rejected": "❌"}


async def _render_user_receipts(cb: CallbackQuery, uid: int, offset: int) -> None:
    async with Session() as s:
        total = await s.scalar(
            select(func.count()).select_from(WalletCharge)
            .where(WalletCharge.user_telegram_id == uid)) or 0
        charges = (await s.scalars(
            select(WalletCharge).where(WalletCharge.user_telegram_id == uid)
            .order_by(WalletCharge.created_at.desc())
            .offset(offset).limit(_UR_PAGE_SIZE))).all()

    if not charges and offset == 0:
        text = "🧾 این کاربر هیچ رسیدی ارسال نکرده."
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [hx_button("⬅️ بازگشت به پروفایل", callback_data=f"usr:back:{uid}", style=ButtonStyle.DANGER)]])
        try:
            await cb.message.edit_text(text, reply_markup=kb)
        except Exception:
            await cb.message.answer(text, reply_markup=kb)
        await cb.answer()
        return

    rows = []
    for ch in charges:
        emj = _UR_STATUS_EMOJI.get(ch.status, "❔")
        rows.append([hx_button(
            f"{emj} {rial(ch.amount)} — {to_jalali(ch.created_at)}",
            callback_data=f"usr:receipt:{ch.id}:{uid}:{offset}")])

    nav = []
    if offset > 0:
        nav.append(hx_button("◀️ قبلی", callback_data=f"usr:receipts:{uid}:{max(0, offset - _UR_PAGE_SIZE)}"))
    if offset + _UR_PAGE_SIZE < total:
        nav.append(hx_button("بعدی ▶️", callback_data=f"usr:receipts:{uid}:{offset + _UR_PAGE_SIZE}"))
    if nav:
        rows.append(nav)
    rows.append([hx_button("⬅️ بازگشت به پروفایل", callback_data=f"usr:back:{uid}", style=ButtonStyle.DANGER)])

    text = f"🧾 <b>رسیدهای ارسالی کاربر</b> ({total} مورد)\n\nروی هرکدام بزن تا رسید را ببینی:"
    kb = InlineKeyboardMarkup(inline_keyboard=rows)
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


# === PATCH_BOT_AUDIT_LOG_V1 ===
_AUDIT_FA = {"transfer": "🔄 انتقالِ مالکیت", "delete": "🗑 حذفِ ربات"}


@router.callback_query(F.data.startswith("usr:audit:"))
async def usr_audit_detail(cb: CallbackQuery):
    if not await has_perm(cb.from_user.id, "adm:users"):
        await cb.answer("دسترسی نداری", show_alert=True)
        return
    from models import BotAuditLog
    aid = int(cb.data.split(":")[2])
    async with Session() as s:
        a = await s.get(BotAuditLog, aid)
        if not a:
            await cb.answer("این سابقه پیدا نشد.", show_alert=True)
            return
        names = {}
        for _uid in (a.from_owner, a.to_owner):
            if not _uid:
                continue
            _u = await s.scalar(select(PlatformUser).where(
                PlatformUser.telegram_id == _uid))
            names[_uid] = (_u.full_name if _u and _u.full_name else "") or str(_uid)

    lines = [f"{_AUDIT_FA.get(a.action, a.action)}\n",
             f"🤖 ربات: @{a.username or '؟'}"]
    if a.plan:
        try:
            lines.append(f"💼 پلن: {PLAN_INFO[Plan(a.plan)]['title']}")
        except Exception:
            lines.append(f"💼 پلن: {a.plan}")
    if a.from_owner:
        lines.append(f"👤 از: {_html.escape(names.get(a.from_owner, ''))} "
                     f"— <code>{a.from_owner}</code>")
    if a.to_owner:
        lines.append(f"👥 به: {_html.escape(names.get(a.to_owner, ''))} "
                     f"— <code>{a.to_owner}</code>")
    if a.note:
        _note = {"user_deleted": "خودِ مالک حذف کرده",
                 "nonpayment": "عدم تمدید", "inactivity": "عدم فعالیت"}.get(
                     a.note, a.note)
        lines.append(f"📝 توضیح: {_html.escape(_note)}")
    lines.append(f"🗓 تاریخ: {to_jalali(a.created_at)}")

    rows = []
    for _uid in (a.from_owner, a.to_owner):
        if _uid and _uid != cb.from_user.id:
            rows.append([hx_button(f"👤 پروندهٔ {names.get(_uid, _uid)}",
                                   callback_data=f"usr:back:{_uid}")])
    rows.append([hx_button("⬅️ بستن", callback_data="adm:back",
                           style=ButtonStyle.DANGER)])
    await cb.message.answer("\n".join(lines),
                            reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
    await cb.answer()


