@router.callback_query(F.data.startswith("usr:receipt:"))
async def usr_receipt_detail(cb: CallbackQuery, bot: Bot):
    if not await has_perm(cb.from_user.id, "adm:users"):
        await cb.answer("دسترسی نداری", show_alert=True)
        return
    _, _, cid_s, uid_s, off_s = cb.data.split(":")
    cid, uid, offset = int(cid_s), int(uid_s), int(off_s)

    async with Session() as s:
        ch = await s.get(WalletCharge, cid)
    if not ch or ch.user_telegram_id != uid:
        await cb.answer("رسید پیدا نشد.", show_alert=True)
        return

    emj = _UR_STATUS_EMOJI.get(ch.status, "❔")
    status_fa = {"approved": "تاییدشده", "pending": "در انتظار بررسی", "rejected": "ردشده"}.get(ch.status, ch.status)
    caption = (
        f"🧾 <b>رسیدِ شارژ</b>\n\n"
        f"💰 مبلغ: {rial(ch.amount)}\n"
        f"{emj} وضعیت: {status_fa}\n"
        f"📅 تاریخ: {to_jalali(ch.created_at)}"
        + (f"\n💳 ۴ رقم آخر کارت: {ch.sender_card4}" if ch.sender_card4 else "")
    )
    back_kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("⬅️ بازگشت به فهرست رسیدها", callback_data=f"usr:receipts:{uid}:{offset}", style=ButtonStyle.DANGER)]])

    try:
        if ch.receipt_file_id:
            await cb.message.answer_photo(ch.receipt_file_id, caption=caption, reply_markup=back_kb)
        elif ch.receipt_text:
            await cb.message.answer(
                caption + f"\n\n📝 متنِ رسید:\n<blockquote>{_html.escape(ch.receipt_text)[:1000]}</blockquote>",
                reply_markup=back_kb)
        else:
            await cb.message.answer(caption + "\n\n(بدون فایل یا متنِ رسید ثبت‌شده)", reply_markup=back_kb)
    except Exception:
        logger.exception("نمایشِ رسیدِ کاربر برای ادمین ناموفق بود")
        await cb.answer("نمایش رسید با خطا مواجه شد.", show_alert=True)
        return
    await cb.answer()


@router.callback_query(F.data.startswith("usr:back:"))
async def usr_back_to_profile(cb: CallbackQuery):
    if not await has_perm(cb.from_user.id, "adm:users"):
        await cb.answer("دسترسی نداری", show_alert=True)
        return
    parts = cb.data.split(":")
    uid = int(parts[2])
    # اگر این دکمه از فهرستِ رسیدهایِ یک ماه باز شده باشد، سه بخشِ اضافه
    # (سال، ماه، آفست) همراهش می‌آید تا «بازگشت» دقیقاً به همان صفحه برود
    # نه به منویِ کلیِ ادمین.
    return_cb = "adm:back"
    if len(parts) >= 7 and parts[4].isdigit() and parts[5].isdigit() and parts[6].lstrip("-").isdigit():
        return_cb = f"adm:recmonth:{parts[4]}:{parts[5]}:{parts[6]}"
    res = await _build_user_profile(uid, return_cb)
    if not res:
        await cb.answer("کاربر پیدا نشد.", show_alert=True)
        return
    text, kb = res
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


@router.message(AdminFSM.search_user)
async def adm_user_profile(msg: Message, state: FSMContext, bot: Bot):
    if not await has_perm(msg.from_user.id, "adm:users"):
        return
    raw = (msg.text or "").strip()
    await state.clear()
    if not raw:
        await msg.answer("ورودی نامعتبر است.", reply_markup=await smart_home_kb(msg.from_user.id))
        return

    uid = fa_to_int(raw)
    if not uid:
        # اگه عدد نبود، به‌عنوان یوزرنیم تفسیرش کن
        uname = raw.lstrip("@").strip()
        if not uname:
            await msg.answer("ورودی نامعتبر است.", reply_markup=await smart_home_kb(msg.from_user.id))
            return
        # === PATCH_PLATFORM_USER_USERNAME_V1 ===
        # قبلاً فقط از طریقِ bot.get_chat("@username") (API زندهٔ تلگرام)
        # جستجو می‌شد که تلگرام هرچه بیشتر محدودش می‌کنه (فقط برای
        # کاربرهایی که اخیراً تعامل داشتن/یوزرنیمِ عمومی دارن کار می‌کنه) —
        # همون چیزی که باعث شد جستجو دیگه برای خیلی‌ها کار نکنه. الان اول
        # از دیتابیسِ خودمون (که هر بار get_user صدا زده می‌شه تازه می‌شه)
        # می‌گردیم؛ فقط اگه اونجا نبود، به API زنده fallback می‌کنیم.
        async with Session() as s:
            u_local = await s.scalar(select(PlatformUser).where(
                func.lower(PlatformUser.username) == uname.lower()))
        if u_local:
            uid = u_local.telegram_id
        else:
            try:
                chat = await bot.get_chat(f"@{uname}")
                uid = chat.id
            except Exception:
                await msg.answer(
                    f"❌ کاربری با یوزرنیم @{uname} پیدا نشد.\n"
                    "توجه: این کاربر هنوز هیچ‌وقت با ربات بات‌ساز تعامل نداشته "
                    "(نه در دیتابیسِ خودمون بود، نه تلگرام اجازهٔ جستجوی زنده داد).",
                    reply_markup=await smart_home_kb(msg.from_user.id))
                return

    result = await _build_user_profile(uid)
    if not result:
        await msg.answer("کاربری با این شناسه/یوزرنیم در دیتابیس پلتفرم یافت نشد.",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return
    text, kb = result
    await msg.answer(text, reply_markup=kb)


@router.callback_query(F.data.startswith("usr:"))
async def adm_user_action(cb: CallbackQuery, state: FSMContext, bot: Bot):
    if not await has_perm(cb.from_user.id, "adm:users"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")
    action = parts[1]
    uid = int(parts[2])

    # === PATCH_WALLET_TRANSFER_V1 ===
    # حتماً همین‌جا، نه در یک هندلرِ جدا: این هندلر با startswith("usr:")
    # ثبت شده و زودتر از هر هندلرِ اختصاصیِ usr:move: اجرا می‌شود، پس
    # هندلرِ جدا هیچ‌وقت نوبتش نمی‌رسید.
    if action == "move":
        async with Session() as s:
            u = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == uid))
        if not u:
            await cb.answer("کاربر یافت نشد", show_alert=True)
            return
        bal = float(u.balance or 0)
        if bal <= 0:
            await cb.answer("موجودیِ این کاربر صفر است؛ چیزی برای انتقال نیست.",
                            show_alert=True)
            return
        await state.set_state(AdminFSM.wallet_move_target)
        await state.update_data(from_uid=uid)
        await cb.message.answer(
            f"🔄 <b>انتقالِ کلِ موجودی</b>\n\n"
            f"از کاربر: <code>{uid}</code>\n"
            f"مبلغ: {rial(bal)}\n\n"
            "حالا آی‌دیِ عددیِ تلگرامِ کاربرِ <b>مقصد</b> را بفرست:",
            reply_markup=await smart_cancel_kb())
        await cb.answer()
        return

    if action == "ban":
        async with Session() as s:
            u = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == uid))
            if u:
                u.is_banned = not u.is_banned
                state_txt = "بن شد 🔴" if u.is_banned else "آنبن شد 🟢"
                await s.commit()
        await cb.answer(state_txt, show_alert=True)
        return

    if action == "ticket":
        # ارجاع به پشتیبانی: ادمین یک تیکت برای کاربر ثبت می‌کند
        async with Session() as s:
            t = Ticket(user_telegram_id=uid, text="📌 ارجاع از طرف ادمین به پشتیبانی")
            s.add(t)
            await s.commit()
        try:
            await bot.send_message(uid, "📌 از طرف مدیریت به پشتیبانی ارجاع داده شدید. به‌زودی با شما تماس می‌گیریم.")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.answer("تیکت ارجاع ثبت شد.", show_alert=True)
        return

    if action == "sendmsg":
        await state.set_state(AdminFSM.send_msg_user)
        await state.update_data(target_id=uid)
        await cb.message.answer("متن پیام برای ارسال به کاربر را بفرست:", reply_markup=await smart_cancel_kb())
        await cb.answer()
        return

    if action == "trialrevoke":
        trials = await plan_trials.active_or_used_trials_for_user(uid)
        if not trials:
            await cb.answer("تستی برای لغو یافت نشد (شاید قبلاً لغو/منقضی شده).", show_alert=True)
            return
        req_id = trials[0]["id"]  # جدیدترینِ فعال/مصرف‌شده
        await state.set_state(TrialAdminFSM.revoke_note)
        await state.update_data(trial_revoke_id=req_id, trial_revoke_uid=uid)
        await cb.message.answer(
            "📝 اگر می‌خوای دلیل لغوِ تست رو بنویس و بفرست؛ برای لغو بدون دلیل «0» یا /skip بفرست.",
            reply_markup=await smart_cancel_kb())
        await cb.answer()
        return

    if action == "days":
        # افزودن/کسر روزِ اعتبار ربات‌های این کاربر — اول انتخاب ربات
        async with Session() as s:
            bots = (await s.scalars(
                select(BotRow).where(BotRow.owner_id == uid).order_by(BotRow.id)
            )).all()
            items = [(r.id, r.username, r.plan_expires_at, r.archived_at) for r in bots]
        if not items:
            await cb.answer("این کاربر رباتی ندارد.", show_alert=True)
            return
        rows = []
        for bid, uname, exp, arch in items:
            tag = " 🗄" if arch else ""
            exp_txt = to_jalali(exp) if exp else "بدون سررسید"
            rows.append([hx_button(f"🤖 @{uname}{tag} — {exp_txt}",
                callback_data=f"usrdays:{bid}:{uid}")])
        rows.append([hx_button("⬅️ بازگشت به پروفایل",
                                          callback_data=f"usr_back:{uid}",
                                          style=ButtonStyle.DANGER)])
        await cb.message.edit_text(
            "⏳ <b>افزودن/کسر روزِ اعتبار</b>\n\nروی رباتِ موردنظر بزن:",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
        await cb.answer()
        return

    # شارژ یا کسر دستی
    await state.set_state(AdminFSM.adjust_amount)
    await state.update_data(target_id=uid, sign=(1 if action == "add" else -1))
    await cb.message.answer("مبلغ را به تومان بفرست:", reply_markup=await smart_cancel_kb())
    await cb.answer()


