async def _adm_user_bot_detail_render(cb: CallbackQuery, bot_id: int, back_uid: int) -> None:
    """رندرِ صفحهٔ جزئیاتِ رباتِ کاربر — بدونِ خواندن از cb.data (نگاه کن به
    PATCH_CB_DATA_FROZEN_FIX_V1 در tenant/smm.py برایِ توضیحِ کاملِ باگ)."""
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r:
            await cb.answer("یافت نشد", show_alert=True)
            return
        # === PATCH_USER_BOT_DETAIL_FULL_INFO_V1 ===
        # قبلاً اینجا فقط پلن/نوع/تاریخِ ساخت/وضعیت نشون داده می‌شد — نه
        # سررسید نه تاریخچهٔ خریدهای همین ربات؛ کاربر باید برمی‌گشت به
        # پروفایلِ کلی و از اونجا (که همه‌چیز به‌صورتِ متنِ خامِ طولانی بود)
        # پیدا می‌کرد. الان همه‌چیز همین‌جا هست.
        bot_orders = (await s.scalars(
            select(PlanOrder).where(PlanOrder.target_bot_id == bot_id)
            .order_by(PlanOrder.created_at))).all()
    is_locked = r.status == "locked"
    lock_btn = (hx_button("🔓 رفع قفلِ ربات", callback_data=f"usr_bot_unlock:{bot_id}:{back_uid}")
                if is_locked else
                hx_button("🔒 قفلِ ربات (با دلیل)", callback_data=f"usr_bot_lock:{bot_id}:{back_uid}"))
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [lock_btn],
        [hx_button("🎚 تغییر پلن ربات (دستی)", callback_data=f"usr_bot_plan:{bot_id}:{back_uid}")],
        [hx_button("🗑 حذف این ربات", callback_data=f"usr_bot_del:{bot_id}:{back_uid}")],
        [hx_button("⬅️ بازگشت به پروفایل", callback_data=f"usr_back:{back_uid}", style=ButtonStyle.DANGER)],
    ])
    lock_line = ""
    if is_locked:
        reason = (r.lock_reason or "—").strip() or "—"
        lock_line = f"\n🔒 قفل‌شده — دلیل: {reason}"

    # === PATCH_USER_BOT_DETAIL_FULL_INFO_V1 ===
    exp_line = ""
    if r.plan_expires_at:
        exp_line = f"\n⏳ سررسید: {to_jalali(r.plan_expires_at)}"
        days_left = (r.plan_expires_at - datetime.datetime.now()).days
        if days_left >= 0:
            exp_line += f" ({days_left} روز مانده)"
        else:
            exp_line += f" (منقضی‌شده — {abs(days_left)} روز پیش)"
    else:
        exp_line = "\n⏳ سررسید: بدون سررسید"
    duration_line = ""
    if r.plan_expires_at:
        total_days = (r.plan_expires_at - r.created_at).days
        duration_line = f"\n📆 مدتِ کل: {total_days} روز"

    orders_block = ""
    if bot_orders:
        orders_block = f"\n\n🧾 <b>خریدهای این ربات ({len(bot_orders)}):</b>"
        for o in bot_orders:
            st_tag = "" if o.status == "paid" else f" ({o.status})"
            orders_block += (
                f"\n• {PLAN_INFO[Plan(o.plan)]['title']} — {rial(o.amount)} — "
                f"{to_jalali(o.created_at)}{st_tag}")
    else:
        orders_block = "\n\n🧾 خریدهای این ربات: ثبت نشده"

    # === PATCH_NOT_MODIFIED_GUARD_V1 ===
    # اگه ادمین دوبار پشتِ سرِ هم روی همین ربات بزنه (یا بعدِ تغییرِ پلن به
    # همون پلنِ قبلی برگرده)، متن/کیبورد ممکنه دقیقاً با چیزی که همین الان
    # روی پیامه یکی باشه؛ تلگرام اینجا خطای «message is not modified» می‌ده
    # که قبلاً گرفته نمی‌شد و به ERR-XXXXXX می‌رسید.
    try:
        await cb.message.edit_text(
            f"🤖 @{r.username}\n"
            f"مالک: <code>{r.owner_id}</code>\n"
            f"پلن: {PLAN_INFO[Plan(r.plan)]['title']}\n"
            f"نوع: {FIELDS.get(r.field, r.field)}\n"
            f"تاریخ ساخت: {to_jalali(r.created_at)}"
            f"{exp_line}"
            f"{duration_line}\n"
            f"وضعیت: {r.status}{lock_line}"
            f"{orders_block}",
            reply_markup=kb,
        )
    except TelegramBadRequest as e:
        if "message is not modified" not in str(e).lower():
            raise
    await cb.answer()


