@router.callback_query(F.data.startswith("usr_bot_plan:"))
async def adm_user_bot_plan_menu(cb: CallbackQuery):
    """منوی تغییرِ دستیِ پلنِ یک ربات توسط ادمینِ پلتفرم — بدون نیاز به
    پرداخت (مثلاً برای جبران، تست، یا موارد استثنایی)."""
    if not await has_perm(cb.from_user.id, "adm:users"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")
    bot_id, back_uid = int(parts[1]), int(parts[2])
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
    if not r:
        await cb.answer("یافت نشد", show_alert=True)
        return
    cur = r.plan
    rows = []
    for plan in (Plan.FREE, Plan.GROWTH, Plan.PRO):
        mark = "✅ " if plan.value == cur else ""
        rows.append([hx_button(f"{mark}{PLAN_INFO[plan]['title']}",
                               callback_data=f"usr_bot_plan_set:{bot_id}:{back_uid}:{plan.value}")])
    rows.append([hx_button("⬅️ بازگشت", callback_data=f"usr_bot_detail:{bot_id}:{back_uid}",
                          style=ButtonStyle.DANGER)])
    try:
        await cb.message.edit_text(
            f"🎚 <b>تغییرِ دستیِ پلنِ ربات @{r.username}</b>\n\n"
            f"پلنِ فعلی: <b>{PLAN_INFO[Plan(cur)]['title']}</b>\n\n"
            "⚠️ این تغییر بدون پرداخت اعمال می‌شود و مستقیماً پلنِ ربات را عوض می‌کند "
            "(برای موارد استثنایی/جبران استفاده کن). یک پلن را انتخاب کن:",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
    except TelegramBadRequest as e:
        if "message is not modified" not in str(e).lower():
            raise
    await cb.answer()


@router.callback_query(F.data.startswith("usr_bot_plan_set:"))
async def adm_user_bot_plan_set(cb: CallbackQuery, bot: Bot):
    if not await has_perm(cb.from_user.id, "adm:users"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")
    bot_id, back_uid, new_plan = int(parts[1]), int(parts[2]), parts[3]
    if new_plan not in (Plan.FREE.value, Plan.GROWTH.value, Plan.PRO.value):
        await cb.answer("پلن نامعتبر", show_alert=True)
        return
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r:
            await cb.answer("یافت نشد", show_alert=True)
            return
        old_plan = r.plan
        was_archived = r.archived_at is not None
        r.plan = new_plan
        # === PATCH_PLAN_UPGRADE_BANK_V1 === تغییرِ دستیِ ادمین، زمانِ نگه‌داری‌شده را پاک می‌کند
        r.banked_plan = None
        r.banked_seconds = None
        r.banked_sub_months = None
        # اگر ربات به‌خاطرِ عدم‌تمدید/عدم‌فعالیت در بایگانی بود، تغییرِ دستیِ
        # پلن توسطِ ادمین یعنی همین الان باید دوباره فعال شود — وگرنه ادمین
        # فکر می‌کند پلن را عوض کرده ولی ربات همچنان بایگانی می‌ماند.
        if was_archived:
            r.archived_at = None
            r.status = "active"
            r.inactivity_warned_at = None
        owner_id, uname = r.owner_id, r.username
        await s.commit()
    await cb.answer("✅ پلن تغییر کرد")
    # === PATCH_CB_DATA_FROZEN_FIX_V1 ===
    await _adm_user_bot_detail_render(cb, bot_id, back_uid)
    if old_plan != new_plan:
        try:
            await bot.send_message(
                owner_id,
                f"🎚 پلنِ ربات @{uname} توسط مدیریتِ بات‌ساز از «{PLAN_INFO[Plan(old_plan)]['title']}» "
                f"به «{PLAN_INFO[Plan(new_plan)]['title']}» تغییر کرد."
                + ("\n✅ ربات از بایگانی هم خارج و فعال شد." if was_archived else ""),
            )
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")



