@router.message(AdminFSM.lock_bot_reason, F.text)
async def adm_user_bot_lock_save(msg: Message, state: FSMContext, bot: Bot):
    if not await has_perm(msg.from_user.id, "adm:users"):
        await state.clear()
        return
    data = await state.get_data()
    bot_id = data.get("target_bot_id")
    back_uid = data.get("target_uid")
    reason = (msg.text or "").strip()
    await state.clear()
    if not bot_id:
        await msg.answer("نامعتبر بود.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    if reason in ("❌ لغو", "لغو"):
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    if not reason:
        await msg.answer("دلیل نمی‌تواند خالی باشد. دوباره بفرست:", reply_markup=await smart_cancel_kb())
        await state.set_state(AdminFSM.lock_bot_reason)
        await state.update_data(target_bot_id=bot_id, target_uid=back_uid)
        return
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r:
            await msg.answer("ربات یافت نشد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
            return
        r.status = "locked"
        r.lock_reason = reason
        owner_id, uname = r.owner_id, r.username
        await s.commit()
    try:
        await bot.send_message(
            owner_id,
            f"🔒 ربات شما (@{uname}) توسط مدیریتِ بات‌ساز قفل شد.\n"
            f"📝 دلیل: {reason}\n\n"
            "تا رفعِ قفل، این ربات برای کاربرانش در دسترس نخواهد بود.")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await msg.answer(
        f"✅ ربات @{uname} قفل شد و دلیل ذخیره شد.",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
            hx_button("⬅️ بازگشت به پروفایل کاربر", callback_data=f"usr_back:{back_uid}"),
        ]]))


