@router.message(AdminFSM.del_bot_reason, F.text)
# === PATCH_ADMIN_BOT_DELETE_REASON_V1 ===
async def adm_bot_del_reason_save(msg: Message, state: FSMContext, bot: Bot):
    if not await has_perm(msg.from_user.id, "adm:users") and not await has_perm(msg.from_user.id, "adm:bots"):
        await state.clear()
        return
    data = await state.get_data()
    bot_id = data.get("target_bot_id")
    flow = data.get("flow", "user")
    raw = (msg.text or "").strip()
    await state.clear()
    if not bot_id:
        await msg.answer("نامعتبر بود.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    if raw in ("❌ لغو", "لغو"):
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    reason = "" if raw == "-" else raw
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r:
            await msg.answer("ربات یافت نشد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
            return
        owner = r.owner_id
        uname = r.username
    # قبلاً اینجا فقط ۳ جدول (MainButton/ButtonSetting/Setting) دستی پاک
    # می‌شد و بقیهٔ جدول‌های وابسته (از جمله bot_users) دست‌نخورده
    # می‌موند → ForeignKeyViolationError. الان از همون purge_bot()ِ
    # مشترک استفاده می‌کنیم که همهٔ جدول‌های وابسته رو درست پاک می‌کنه.
    # === PATCH_NOTIFY_TENANT_BOTS_ON_PARTNER_DELETE_V1 ===
    # اگر این ربات یک «ربات همکار» بوده (partner_bots)، قبل از حذف باید
    # لیستِ ربات‌های مستأجرِ زیرِ آن را نگه داریم تا بعداً به مالک هرکدام
    # از طریقِ خودِ همان ربات مستأجر اطلاع بدهیم که همکاری قطع شده.
    tenant_bot_rows = []
    try:
        async with Session() as s2:
            from sqlalchemy import text as _text2
            pb2 = await s2.execute(
                _text2("SELECT id FROM partner_bots WHERE bot_id = :bid"),
                {"bid": bot_id},
            )
            pb2_id = pb2.scalar()
            if pb2_id is not None:
                rows2 = await s2.execute(_text2("""
                    SELECT b.id, b.owner_id, b.token, b.username
                    FROM partner_sales ps
                    JOIN bots b ON b.id = ps.sold_bot_id
                    WHERE ps.partner_bot_id = :pid
                """), {"pid": pb2_id})
                tenant_bot_rows = rows2.fetchall()
    except Exception:
        logger.exception("خطا در واکشیِ لیستِ ربات‌های مستأجرِ همکارِ حذف‌شونده")

    try:
        token = await purge_bot(bot_id)
    except Exception as e:
        await msg.answer(f"❌ حذفِ ربات با خطا مواجه شد:\n{e}", reply_markup=back_to_admin_kb())
        return

    # اطلاع‌رسانیِ خودکار به مالکِ هر ربات مستأجر، از طریقِ خودِ همان ربات
    if tenant_bot_rows:
        from aiogram.client.default import DefaultBotProperties
        from aiogram.enums import ParseMode
        _notify_text = (
            "🔔 ربات همکاری که ربات شما زیر آن ثبت شده بود، حذف شد و همکاری "
            "با آن قطع شده است.\n"
            "ربات شما همچنان فعال است؛ از این پس برای تمدید یا مدیریتِ آن "
            "مستقیماً به ربات اصلیِ بات‌ساز مراجعه کنید — بخشِ «ربات‌های من»."
        )
        # === PATCH_NOTIFY_TENANT_BOTS_BABOTSAZ_LINK_V1 ===
        # یه دکمهٔ شیشه‌ای زیرِ همین پیام که مستقیم کاربر رو به ربات اصلیِ
        # بات‌ساز می‌بره، تا لازم نباشه خودش دنبالِ آدرسش بگرده.
        _notify_kb = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="🤖 ورود به ربات اصلی بات‌ساز",
                                 url="https://t.me/BaBotSazBot")
        ]])
        for _tb_id, _tb_owner, _tb_token, _tb_uname in tenant_bot_rows:
            _tmp = None
            try:
                _tmp = Bot(token=_tb_token,
                           default=DefaultBotProperties(parse_mode=ParseMode.HTML))
                await _tmp.send_message(_tb_owner, _notify_text, reply_markup=_notify_kb)
            except Exception:
                logger.exception(
                    f"اطلاع‌رسانیِ حذفِ همکار به مالکِ رباتِ مستأجر {_tb_id} ناموفق بود")
            finally:
                if _tmp is not None:
                    try:
                        await _tmp.session.close()
                    except Exception:
                        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        async with _temp_bot(token) as tb:
            await tb.delete_webhook()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        note = f"🗑 ربات شما (@{uname}) توسط ادمین حذف شد."
        if reason:
            note += f"\n📝 دلیل: {reason}"
        await bot.send_message(owner, note)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    if flow == "user":
        await msg.answer(
            "🗑 ربات حذف شد.\n\n⬅️ برای بازگشت به پروفایل کاربر دوباره آیدی را جستجو کنید.",
            reply_markup=back_to_admin_kb()
        )
    else:
        await msg.answer("🗑 ربات توسط ادمین حذف شد.", reply_markup=back_to_admin_kb())


