# === PATCH_WALLET_TRANSFER_V1 ===
@router.message(AdminFSM.wallet_move_target)
async def adm_wallet_move_target(msg: Message, state: FSMContext):
    if not await has_perm(msg.from_user.id, "adm:users"):
        await state.clear()
        return
    raw = (msg.text or "").strip()
    if raw in ("❌ لغو", "لغو"):
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id))
        return
    data = await state.get_data()
    from_uid = data.get("from_uid")
    to_uid = fa_to_int(raw)
    if from_uid is None:
        await state.clear()
        await msg.answer("⚠️ این عملیات منقضی شده. دوباره از پنلِ کاربر شروع کن.",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return
    if not to_uid:
        await msg.answer("آی‌دی نامعتبر است. فقط عددِ آی‌دیِ تلگرام را بفرست:")
        return
    if int(to_uid) == int(from_uid):
        await msg.answer("مبدأ و مقصد یکی هستند. آی‌دیِ دیگری بفرست:")
        return
    async with Session() as s:
        src = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == from_uid))
        dst = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == to_uid))
    if not src:
        await state.clear()
        await msg.answer("کاربرِ مبدأ یافت نشد.",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return
    if not dst:
        await msg.answer(
            "کاربرِ مقصد در پلتفرم ثبت نشده است — باید حداقل یک‌بار ربات را "
            "استارت کرده باشد. آی‌دیِ دیگری بفرست یا «لغو» بزن:")
        return
    amount = float(src.balance or 0)
    if amount <= 0:
        await state.clear()
        await msg.answer("موجودیِ مبدأ صفر شده؛ انتقالی انجام نشد.",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return
    await state.set_state(AdminFSM.wallet_move_confirm)
    await state.update_data(from_uid=from_uid, to_uid=int(to_uid), amount=amount)
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("✅ تأیید و انتقال", callback_data="usrmove:go",
                   style=ButtonStyle.SUCCESS)],
        [hx_button("❌ انصراف", callback_data="usrmove:cancel",
                   style=ButtonStyle.DANGER)],
    ])
    await msg.answer(
        "🔄 <b>تأییدِ انتقال</b>\n\n"
        f"از: <code>{from_uid}</code> (موجودی: {rial(amount)})\n"
        f"به: <code>{to_uid}</code> (موجودی فعلی: {rial(float(dst.balance or 0))})\n\n"
        f"بعد از انتقال، موجودیِ مبدأ صفر و موجودیِ مقصد "
        f"{rial(float(dst.balance or 0) + amount)} می‌شود.\n\n"
        "این کار برگشت‌پذیر نیست. مطمئنی؟",
        reply_markup=kb)


@router.callback_query(F.data == "usrmove:cancel")
async def adm_wallet_move_cancel(cb: CallbackQuery, state: FSMContext):
    await state.clear()
    await cb.message.edit_text("انتقال لغو شد.")
    await cb.answer()


@router.callback_query(F.data == "usrmove:go")
async def adm_wallet_move_go(cb: CallbackQuery, state: FSMContext, bot: Bot):
    if not await has_perm(cb.from_user.id, "adm:users"):
        await cb.answer("دسترسی نداری", show_alert=True)
        return
    data = await state.get_data()
    from_uid, to_uid = data.get("from_uid"), data.get("to_uid")
    await state.clear()
    if from_uid is None or to_uid is None:
        await cb.answer("این عملیات منقضی شده.", show_alert=True)
        return
    await cb.answer("در حال انتقال…")
    async with Session() as s:
        src = await s.scalar(select(PlatformUser).where(
            PlatformUser.telegram_id == from_uid).with_for_update())
        dst = await s.scalar(select(PlatformUser).where(
            PlatformUser.telegram_id == to_uid).with_for_update())
        if not src or not dst:
            await cb.message.answer("یکی از کاربران یافت نشد؛ انتقال انجام نشد.")
            return
        # مبلغ دوباره از دیتابیس خوانده می‌شود، نه از state — ممکن است بینِ
        # تأیید و اجرا تغییر کرده باشد.
        amount = float(src.balance or 0)
        if amount <= 0:
            await cb.message.answer("موجودیِ مبدأ صفر است؛ انتقالی انجام نشد.")
            return
        src.balance = 0.0
        dst.balance = float(dst.balance or 0) + amount
        s.add(PlatformTxn(user_telegram_id=from_uid, amount=-amount, kind="admin",
                          note=f"انتقالِ کلِ موجودی به کاربر {to_uid} (توسط ادمین)"))
        s.add(PlatformTxn(user_telegram_id=to_uid, amount=amount, kind="admin",
                          note=f"انتقالِ کلِ موجودی از کاربر {from_uid} (توسط ادمین)"))
        await s.commit()
        new_dst = dst.balance
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("⬅️ بازگشت به پنل", callback_data="adm:back", style=ButtonStyle.DANGER)]
    ])
    await cb.message.answer(
        f"✅ انتقال انجام شد.\n\n"
        f"از <code>{from_uid}</code> → <code>{to_uid}</code>\n"
        f"مبلغ: {rial(amount)}\n"
        f"موجودیِ جدیدِ مقصد: {rial(new_dst)}", reply_markup=kb)
    wallet_kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("💰 کیف پول", callback_data="hm:wallet", style=ButtonStyle.PRIMARY)]
    ])
    for _uid, _txt in (
        (from_uid, f"موجودیِ کیف پولِ شما ({rial(amount)}) توسط ادمین به حسابِ دیگری منتقل شد."),
        (to_uid, f"مبلغ {rial(amount)} توسط ادمین به کیف پولِ شما منتقل شد."),
    ):
        try:
            await bot.send_message(_uid, _txt, reply_markup=wallet_kb)
        except Exception:
            logger.exception("اطلاع‌رسانیِ انتقالِ موجودی به %s ناموفق بود", _uid)


# === PATCH_VIP_ADMIN_V1 ===
# تنظیماتِ «سرور فعال‌سازی ربات» (مینی‌اپِ میزبانی). مقادیر در همان
# جدولِ تنظیماتِ پلتفرم (bot_id=0) می‌نشینند تا سرویسِ botsazvip که به
# همین دیتابیس وصل است بتواند بخواندشان.
VIP_DEFAULTS = {
    "vip_price": "300000",       # تومان در ماه
    "vip_discount": "0",         # درصد
    "vip_free_uses": "1",        # چند بار تستِ رایگان برایِ هر کاربر
    "vip_free_minutes": "60",    # مدتِ هر تستِ رایگان
}


async def _vip_cfg() -> dict[str, int]:
    out = {}
    for k, d in VIP_DEFAULTS.items():
        raw = await get_pset(k, d)
        try:
            out[k] = int(float(raw))
        except (TypeError, ValueError):
            out[k] = int(d)
    return out


async def _vip_screen() -> tuple[str, InlineKeyboardMarkup]:
    c = await _vip_cfg()
    price = c["vip_price"]
    off = c["vip_discount"]
    final = int(price * (100 - off) / 100) if off else price
    txt = (
        "⚡️ <b>سرور فعال‌سازی ربات</b>\n\n"
        f"💵 قیمت ماهانه: <b>{price:,}</b> تومان\n"
        f"🏷 تخفیف: <b>{off}٪</b>\n"
        f"💳 پرداختیِ کاربر: <b>{final:,}</b> تومان\n\n"
        f"🎁 تستِ رایگان: <b>{c['vip_free_uses']}</b> بار برای هر کاربر\n"
        f"⏳ مدتِ هر تست: <b>{c['vip_free_minutes']}</b> دقیقه\n"
        f"💬 پشتیبانی: <b>{('@' + _sup) if (_sup := await get_pset('vip_support', '')) else 'غیرفعال'}</b>\n\n"
        "این مقادیر بلافاصله در مینی‌اپ اعمال می‌شوند."
    )
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("💵 تغییر قیمت ماهانه", callback_data="vip:set:price",
                   style=ButtonStyle.PRIMARY)],
        [hx_button("🏷 تغییر درصد تخفیف", callback_data="vip:set:discount",
                   style=ButtonStyle.PRIMARY)],
        [hx_button("🎁 تعداد تستِ رایگان هر کاربر", callback_data="vip:set:uses",
                   style=ButtonStyle.PRIMARY)],
        [hx_button("⏳ مدتِ تستِ رایگان (دقیقه)", callback_data="vip:set:minutes",
                   style=ButtonStyle.PRIMARY)],
        # === PATCH_VIP_USERS_V1 ===
        [hx_button("👥 کاربران و ربات‌ها", callback_data="vip:users:0",
                   style=ButtonStyle.SUCCESS)],
        # === PATCH_SUPPORT_V1 ===
        [hx_button("💬 پشتیبانی مینی‌اپ", callback_data="vip:set:support",
                   style=ButtonStyle.PRIMARY)],
        # === PATCH_VIP_IN_ROOT_PANEL_V1 === بازگشت به ریشهٔ پنلِ مدیریت
        [hx_button("⬅️ بازگشت", callback_data="adm:back",
                   style=ButtonStyle.DANGER)],
    ])
    return txt, kb


# === PATCH_VIP_USERS_V1 ===
# فهرستِ ربات‌هایِ میزبانی‌شده و مدیریتشان. تغییرات مستقیم در دیتابیس
# انجام می‌شود و سرویسِ botsazvip (ناظرش هر ۲ دقیقه) آن‌ها را اعمال
# می‌کند — پس لازم نیست این پروسه به داکر دسترسی داشته باشد.
_VIP_PAGE = 8


def _vip_state_fa(app) -> str:
    return {
        "running": "🟢 روشن",
        "stopped": "⚪️ خاموش",
        "failed": "🔴 خطا",
        "suspended": "⏸ مهلت تمام",
        "created": "📄 بدون فایل",
        "archived": "🗄 بایگانی",
    }.get(app.status, app.status)


async def _vip_users_screen(page: int = 0):
    from models import HostedApp
    async with Session() as s:
        total = await s.scalar(
            select(func.count()).select_from(HostedApp)) or 0
        apps = (await s.scalars(
            select(HostedApp).order_by(HostedApp.id.desc())
            .offset(page * _VIP_PAGE).limit(_VIP_PAGE))).all()
    if not apps:
        txt = "👥 <b>کاربران سرور فعال‌سازی</b>\n\nهنوز کسی رباتی نساخته."
        kb = InlineKeyboardMarkup(inline_keyboard=[[
            hx_button("⬅️ بازگشت", callback_data="vip:menu", style=ButtonStyle.DANGER)]])
        return txt, kb

    now = datetime.datetime.now()
    paid = sum(1 for a in apps if a.paid_until and a.paid_until > now)
    # === PATCH_VIP_OWNER_NAME_V1 === نامِ مالک کنارِ نامِ ربات
    async with Session() as s:
        _names = await _owner_names(s, [a.owner_id for a in apps])
    lines = [f"👥 <b>کاربران سرور فعال‌سازی</b>",
             f"مجموع ربات‌ها: <b>{total}</b>\n"]
    rows = []
    for a in apps:
        exp = (to_jalali(a.paid_until) if a.paid_until else "—")
        own = _names.get(a.owner_id) or f"#{a.owner_id}"
        # === PATCH_VIP_APP_SCREEN_ESCAPE_V1 === نامِ اپ ممکن است < یا & داشته باشد
        lines.append(f"• <code>{_html.escape(a.name or '')}</code> — "
                     f"{_html.escape(own)} — {_vip_state_fa(a)} · تا {exp}")
        rows.append([hx_button(f"{a.name} — {own} — {_vip_state_fa(a)}",
                               callback_data=f"vip:app:{a.id}",
                               style=ButtonStyle.PRIMARY)])
    # === PATCH_VIP_USER_SEARCH_V1 ===
    rows.append([hx_button("🔍 جستجو (کاربر یا ربات)", callback_data="vip:usersearch",
                           style=ButtonStyle.SUCCESS)])
    nav = []
    if page > 0:
        nav.append(hx_button("◀️ قبلی", callback_data=f"vip:users:{page-1}",
                             style=ButtonStyle.PRIMARY))
    if (page + 1) * _VIP_PAGE < total:
        nav.append(hx_button("بعدی ▶️", callback_data=f"vip:users:{page+1}",
                             style=ButtonStyle.PRIMARY))
    if nav:
        rows.append(nav)
    rows.append([hx_button("⬅️ بازگشت", callback_data="vip:menu",
                           style=ButtonStyle.DANGER)])
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)


@router.callback_query(F.data.startswith("vip:users:"))
async def vip_users(cb: CallbackQuery):
    if not await has_perm(cb.from_user.id, "adm:settings"):
        await cb.answer("دسترسی نداری", show_alert=True)
        return
    page = int(cb.data.split(":")[2])
    txt, kb = await _vip_users_screen(page)
    try:
        await cb.message.edit_text(txt, reply_markup=kb)
    except Exception:
        await cb.message.answer(txt, reply_markup=kb)
    await cb.answer()


# === PATCH_ADMIN_MINIAPP_VIEW_V1 ===
async def _vip_app_screen(app_id: int, cb_user_id: int = 0):
    from models import HostedApp
    async with Session() as s:
        a = await s.get(HostedApp, app_id)
        if not a:
            return None, None
        u = await s.scalar(select(PlatformUser).where(
            PlatformUser.telegram_id == a.owner_id))
    now = datetime.datetime.now()
    left = ""
    if a.paid_until and a.paid_until > now:
        left = f" ({(a.paid_until - now).days} روز مانده)"
    # === PATCH_VIP_APP_SCREEN_ESCAPE_V1 ===
    # باگ: نامِ اپ، نامِ مالک و متنِ «آخرین خطا» خام داخلِ HTML می‌رفتند.
    # لاگِ خطایِ داکر معمولاً خودش تگ‌هایی مثل </code> یا < و > دارد، پس
    # تلگرام کلِ پیام را رد می‌کرد: «can't parse entities: Unmatched end
    # tag» — و صفحهٔ ربات اصلاً باز نمی‌شد (همان ERR-XXXXXX).
    _name = _html.escape(a.name or "")
    _owner_name = _html.escape(u.full_name) if (u and u.full_name) else ""
    txt = (
        f"⚡️ <b>{_name}</b>\n\n"
        f"وضعیت: {_vip_state_fa(a)}\n"
        f"👤 مالک: <code>{a.owner_id}</code>"
        + (f" — {_owner_name}" if _owner_name else "") + "\n"
        # === PATCH_VIP_APP_SCREEN_NO_USER_FIX_V1 ===
        # باگ: شرطِ «if u else» به‌خاطرِ اولویتِ عملگرها به کلِ زنجیرهٔ بالا
        # می‌چسبید، پس اگر مالک در جدولِ PlatformUser نبود، نام و وضعیت و
        # مالکِ ربات کلاً حذف می‌شد و صفحه ناقص می‌آمد.
        + (f"👛 موجودی مالک: {int(float(u.balance or 0)):,} تومان\n" if u else "")
    )
    txt += (
        f"📅 ساخت: {to_jalali(a.created_at) if a.created_at else '—'}\n"
        f"⏳ سررسید: {to_jalali(a.paid_until) if a.paid_until else 'پرداخت‌نشده'}{left}\n"
        f"🚀 اولین اجرا: {to_jalali(a.first_started_at) if a.first_started_at else '—'}\n"
        f"📦 نوع: {a.runtime}\n"
    )
    if a.last_error:
        txt += ("\n⚠️ آخرین خطا: <code>"
                + _html.escape(a.last_error[:180]) + "</code>")

    rows = [
        [hx_button("➕ ۳۰ روز", callback_data=f"vipapp:day:{app_id}:30",
                   style=ButtonStyle.SUCCESS),
         hx_button("➕ ۷ روز", callback_data=f"vipapp:day:{app_id}:7",
                   style=ButtonStyle.SUCCESS)],
        [hx_button("➖ ۷ روز", callback_data=f"vipapp:day:{app_id}:-7",
                   style=ButtonStyle.DANGER),
         hx_button("➖ ۳۰ روز", callback_data=f"vipapp:day:{app_id}:-30",
                   style=ButtonStyle.DANGER)],
        # === PATCH_VIP_HOURS_V1 === تمدیدِ کوتاه، برایِ تست و مهلتِ چندساعته
        [hx_button("➕ ۶ ساعت", callback_data=f"vipapp:hour:{app_id}:6",
                   style=ButtonStyle.SUCCESS),
         hx_button("➕ ۱ ساعت", callback_data=f"vipapp:hour:{app_id}:1",
                   style=ButtonStyle.SUCCESS)],
        [hx_button("➖ ۱ ساعت", callback_data=f"vipapp:hour:{app_id}:-1",
                   style=ButtonStyle.DANGER),
         hx_button("➖ ۶ ساعت", callback_data=f"vipapp:hour:{app_id}:-6",
                   style=ButtonStyle.DANGER)],
        [hx_button("⏱ روز/ساعتِ دلخواه", callback_data=f"vipapp:custom:{app_id}",
                   style=ButtonStyle.PRIMARY)],
    ]
    if a.status == "archived":
        rows.append([hx_button("♻️ خروج از بایگانی",
                               callback_data=f"vipapp:unarch:{app_id}",
                               style=ButtonStyle.SUCCESS)])
    else:
        rows.append([
            hx_button("⏸ خاموش‌کردن", callback_data=f"vipapp:off:{app_id}",
                      style=ButtonStyle.DANGER),
            hx_button("▶️ اجازهٔ روشن‌شدن", callback_data=f"vipapp:on:{app_id}",
                      style=ButtonStyle.SUCCESS)])
        rows.append([hx_button("🗄 بایگانی", callback_data=f"vipapp:arch:{app_id}",
                               style=ButtonStyle.DANGER)])
    # === PATCH_VIP_ADMIN_TOOLS_V1 ===
    rows.append([
        hx_button("🔑 متغیرهای .env", callback_data=f"vipenv:list:{app_id}",
                  style=ButtonStyle.PRIMARY),
        hx_button("📂 فایل‌ها", callback_data=f"vipfile:list:{app_id}:0",
                  style=ButtonStyle.PRIMARY)])
    rows.append([
        hx_button("♻️ ری‌استارت", callback_data=f"vipctl:restart:{app_id}",
                  style=ButtonStyle.SUCCESS),
        hx_button("📜 لاگ", callback_data=f"vipctl:logs:{app_id}",
                  style=ButtonStyle.PRIMARY)])
    rows.append([
        hx_button("🔗 مشاهدهٔ ربات", callback_data=f"vipctl:link:{app_id}",
                  style=ButtonStyle.PRIMARY),
        hx_button("🗑 حذفِ کامل", callback_data=f"vipctl:delask:{app_id}",
                  style=ButtonStyle.DANGER)])
    # === PATCH_HOSTED_AI_FIX_V1 === بررسیِ هوشمندِ پروژه + اصلاح با هوش مصنوعی (Grok)
    rows.append([
        hx_button("🔍 بررسیِ هوشمند", callback_data=f"vipfix:chk:{app_id}", style=ButtonStyle.PRIMARY),
        hx_button("🛠 اصلاح با هوش مصنوعی", callback_data=f"vipfix:plan:{app_id}", style=ButtonStyle.SUCCESS)])
    rows.append([hx_button("✉️ ارسال پیام به مالک",
                           callback_data=f"vipapp:msg:{app_id}",
                           style=ButtonStyle.PRIMARY)])
    # === PATCH_VIP_TRANSFER_OWNER_V1 ===
    rows.append([hx_button("🔄 انتقال مالکیت",
                           callback_data=f"viptr:ask:{app_id}",
                           style=ButtonStyle.PRIMARY)])
    # === PATCH_ADMIN_MINIAPP_VIEW_V1 ===
    # بازکردنِ همین ربات داخلِ مینی‌اپِ میزبانی با نمایِ مالک — مدیر
    # همان چیزی را می‌بیند که کاربر می‌بیند (فایل‌ها، env، لاگ، روشن/خاموش)
    # و می‌تواند همان‌جا درستش کند. توکنِ امضاشده لازم است چون وب‌اپِ
    # بازشده از دکمهٔ شیشه‌ای هم باید کاربر را بشناسد.
    _mini = (WEBHOOK_BASE or "").rstrip("/")
    if _mini:
        try:
            from miniapp_token import make_token
            _url = (f"{_mini}/vip?t={make_token(int(cb_user_id))}&a={app_id}"
                    if cb_user_id else f"{_mini}/vip?a={app_id}")
            rows.append([hx_button("🪟 باز کردن در مینی‌اپ",
                                   web_app=WebAppInfo(url=_url),
                                   style=ButtonStyle.SUCCESS)])
        except Exception:
            logger.exception("ساختِ لینکِ مینی‌اپِ ادمین ناموفق بود")
    rows.append([hx_button("⬅️ بازگشت", callback_data="vip:users:0",
                           style=ButtonStyle.DANGER)])
    return txt, InlineKeyboardMarkup(inline_keyboard=rows)


# === PATCH_VIP_ADMIN_TOOLS_V1 ===
# ابزارهایِ ادمین برایِ راه‌انداختنِ رباتِ میزبانی‌شدهٔ یک کاربر:
# ویرایشِ .env، مرورِ فایل‌ها، لاگ، ری‌استارت، لینکِ ربات و حذفِ کامل.
#
# ⚠️ چرا از HTTP استفاده می‌کنیم و نه مستقیم از دیتابیس: متغیرهایِ محیطی در
# دو جا زندگی می‌کنند — جدولِ HostedAppEnv و فایلِ .env داخلِ پوشهٔ اپ. اگر
# فقط دیتابیس به‌روز شود، کانتینر تغییر را نمی‌بیند (باگِ نسخهٔ اولِ همین
# قابلیت). سرویسِ botsazvip هر دو را با هم می‌نویسد، پس همه‌چیز از مسیرِ
# /api/hosting/admin/... او می‌رود. حذف و مرورِ فایل هم به داکر و فایل‌سیستم
# نیاز دارند که فقط آن سرویس دسترسی‌شان را دارد.
VIP_API_BASE = os.getenv("VIP_API_BASE", "http://127.0.0.1:8002")


async def _vip_api(method: str, path: str, **kw):
    """تماس با API داخلیِ سرویسِ میزبانی. خروجی: (ok, data | پیامِ خطا)"""
    import aiohttp
    secret = os.getenv("VIP_ADMIN_SECRET", "").strip()
    if not secret:
        return False, ("VIP_ADMIN_SECRET در .env تنظیم نشده؛ بدونِ آن "
                       "ابزارهایِ ادمین غیرفعال‌اند.")
    url = f"{VIP_API_BASE}{path}"
    headers = {"X-Admin-Secret": secret}
    try:
        timeout = aiohttp.ClientTimeout(total=60, sock_connect=6)
        async with aiohttp.ClientSession(timeout=timeout) as sess:
            async with sess.request(method, url, headers=headers, **kw) as r:
                if r.status != 200:
                    try:
                        detail = (await r.json()).get("detail", "")
                    except Exception:
                        detail = (await r.text())[:200]
                    return False, f"خطای {r.status}: {detail}"
                return True, await r.json()
    except Exception as e:
        return False, f"ارتباط با سرویسِ میزبانی برقرار نشد: {type(e).__name__}"


_VIP_SECRET_HINTS = ("token", "key", "secret", "pass", "pwd")


def _vip_mask(key: str, value: str) -> str:
    v = value or ""
    if any(h in (key or "").lower() for h in _VIP_SECRET_HINTS) and len(v) > 8:
        return v[:4] + "…" + v[-4:]
    return v[:60] + ("…" if len(v) > 60 else "")


async def _vip_env_screen(app_id: int):
    ok, data = await _vip_api("GET", f"/api/hosting/admin/{app_id}/env")
    if not ok:
        return f"⚠️ {data}", InlineKeyboardMarkup(inline_keyboard=[[
            hx_button("⬅️ بازگشت", callback_data=f"vip:app:{app_id}",
                      style=ButtonStyle.DANGER)]])
    envs = data.get("env") or []
    lines = [f"🔑 <b>متغیرهای .env — {data.get('name', '')}</b>\n"]
    rows = []
    if not envs:
        lines.append("هنوز متغیری ثبت نشده.")
    for i, e in enumerate(envs):
        lines.append(f"• <code>{e['key']}</code> = "
                     f"<code>{_vip_mask(e['key'], e['value'])}</code>")
        rows.append([
            hx_button(f"✏️ {e['key']}", callback_data=f"vipenv:edit:{app_id}:{i}",
                      style=ButtonStyle.PRIMARY),
            hx_button("🗑", callback_data=f"vipenv:del:{app_id}:{i}",
                      style=ButtonStyle.DANGER)])
    have = {e["key"] for e in envs}
    absent = [k for k in (data.get("needed") or []) if k not in have]
    if absent:
        lines.append("\n⚠️ کدِ ربات این‌ها را می‌خواهد ولی ثبت نشده‌اند: "
                     + "، ".join(f"<code>{k}</code>" for k in absent))
    if data.get("only_in_file"):
        lines.append("\n📄 فقط در فایلِ .env هست (نه دیتابیس): "
                     + "، ".join(data["only_in_file"]))
    lines.append("\n♻️ بعد از تغییر، «ری‌استارت» را بزن تا اعمال شود.")
    rows.append([hx_button("➕ افزودن متغیر", callback_data=f"vipenv:add:{app_id}",
                           style=ButtonStyle.SUCCESS)])
    rows.append([hx_button("⬅️ بازگشت", callback_data=f"vip:app:{app_id}",
                           style=ButtonStyle.DANGER)])
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)


async def _vip_env_save(app_id: int, key: str, value: str | None):
    """یک کلید را اضافه/ویرایش (value) یا حذف (value=None) می‌کند."""
    ok, data = await _vip_api("GET", f"/api/hosting/admin/{app_id}/env")
    if not ok:
        return False, data
    env = {e["key"]: e["value"] for e in (data.get("env") or [])}
    if value is None:
        env.pop(key, None)
    else:
        env[key] = value
    ok, data = await _vip_api("POST", f"/api/hosting/admin/{app_id}/env",
                              data={"payload": json.dumps(env)})
    return (True, "") if ok else (False, data)


@router.callback_query(F.data.startswith("vipenv:"))
async def vip_env_action(cb: CallbackQuery, state: FSMContext):
    if not await has_perm(cb.from_user.id, "adm:settings"):
        await cb.answer("دسترسی نداری", show_alert=True)
        return
    parts = cb.data.split(":")
    action, app_id = parts[1], int(parts[2])

    if action == "add":
        await state.set_state(AdminFSM.vip_env_add)
        await state.update_data(vip_app_id=app_id)
        await cb.message.answer(
            "🔑 متغیر را به شکلِ <code>KEY=VALUE</code> بفرست.\n"
            "مثال: <code>BOT_TOKEN=123456:AA…</code>",
            reply_markup=await smart_cancel_kb())
        await cb.answer()
        return

    if action in ("edit", "del"):
        ok, data = await _vip_api("GET", f"/api/hosting/admin/{app_id}/env")
        if not ok:
            await cb.answer(str(data)[:180], show_alert=True)
            return
        envs = data.get("env") or []
        idx = int(parts[3])
        if idx >= len(envs):
            await cb.answer("پیدا نشد", show_alert=True)
            return
        e = envs[idx]
        if action == "edit":
            await state.set_state(AdminFSM.vip_env_val)
            await state.update_data(vip_app_id=app_id, vip_env_key=e["key"])
            await cb.message.answer(
                f"مقدارِ فعلیِ <code>{e['key']}</code>:\n<code>{e['value']}</code>\n\n"
                "مقدارِ تازه را بفرست:", reply_markup=await smart_cancel_kb())
            await cb.answer()
            return
        good, err = await _vip_env_save(app_id, e["key"], None)
        if not good:
            await cb.answer(str(err)[:180], show_alert=True)
            return

    txt, kb = await _vip_env_screen(app_id)
    try:
        await cb.message.edit_text(txt, reply_markup=kb)
    except Exception:
        await cb.message.answer(txt, reply_markup=kb)
    await cb.answer()


@router.message(AdminFSM.vip_env_add, F.text)
async def vip_env_add_save(msg: Message, state: FSMContext):
    raw = (msg.text or "").strip()
    if "=" not in raw:
        await msg.answer("قالب درست نیست. به شکلِ <code>KEY=VALUE</code> بفرست.")
        return
    key, _, value = raw.partition("=")
    key, value = key.strip(), value.strip()
    if not key:
        await msg.answer("نامِ متغیر خالی است.")
        return
    data = await state.get_data()
    app_id = int(data.get("vip_app_id") or 0)
    await state.clear()
    good, err = await _vip_env_save(app_id, key, value)
    await msg.answer(f"✅ <code>{key}</code> ذخیره شد." if good else f"❌ {err}")
    txt, kb = await _vip_env_screen(app_id)
    await msg.answer(txt, reply_markup=kb)


@router.message(AdminFSM.vip_env_val, F.text)
async def vip_env_val_save(msg: Message, state: FSMContext):
    data = await state.get_data()
    app_id = int(data.get("vip_app_id") or 0)
    key = data.get("vip_env_key") or ""
    await state.clear()
    good, err = await _vip_env_save(app_id, key, (msg.text or "").strip())
    await msg.answer(f"✅ مقدارِ <code>{key}</code> به‌روز شد." if good else f"❌ {err}")
    txt, kb = await _vip_env_screen(app_id)
    await msg.answer(txt, reply_markup=kb)


