_VIP_FILES_PAGE = 10


async def _vip_files_screen(app_id: int, page: int = 0):
    ok, data = await _vip_api("GET", f"/api/hosting/admin/{app_id}/files")
    if not ok:
        return f"⚠️ {data}", InlineKeyboardMarkup(inline_keyboard=[[
            hx_button("⬅️ بازگشت", callback_data=f"vip:app:{app_id}",
                      style=ButtonStyle.DANGER)]])
    files = data.get("files") or []
    total = len(files)
    chunk = files[page * _VIP_FILES_PAGE:(page + 1) * _VIP_FILES_PAGE]
    lines = [f"📂 <b>فایل‌های پروژه</b> ({total} فایل)\n"]
    rows = []
    for i, f in enumerate(chunk):
        gi = page * _VIP_FILES_PAGE + i
        lines.append(f"• <code>{f['path']}</code> — {f.get('size', 0):,} بایت")
        rows.append([hx_button(f"📄 {f['path'][:40]}",
                               callback_data=f"vipfile:view:{app_id}:{gi}",
                               style=ButtonStyle.PRIMARY)])
    nav = []
    if page > 0:
        nav.append(hx_button("◀️ قبلی", callback_data=f"vipfile:list:{app_id}:{page-1}",
                             style=ButtonStyle.PRIMARY))
    if (page + 1) * _VIP_FILES_PAGE < total:
        nav.append(hx_button("بعدی ▶️", callback_data=f"vipfile:list:{app_id}:{page+1}",
                             style=ButtonStyle.PRIMARY))
    if nav:
        rows.append(nav)
    rows.append([hx_button("⬅️ بازگشت", callback_data=f"vip:app:{app_id}",
                           style=ButtonStyle.DANGER)])
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)


@router.callback_query(F.data.startswith("vipfile:"))
async def vip_file_action(cb: CallbackQuery, state: FSMContext):
    if not await has_perm(cb.from_user.id, "adm:settings"):
        await cb.answer("دسترسی نداری", show_alert=True)
        return
    parts = cb.data.split(":")
    action, app_id = parts[1], int(parts[2])

    if action == "list":
        txt, kb = await _vip_files_screen(app_id, int(parts[3]))
        try:
            await cb.message.edit_text(txt, reply_markup=kb)
        except Exception:
            await cb.message.answer(txt, reply_markup=kb)
        await cb.answer()
        return

