@router.message(AdminFSM.vip_user_search, F.text)
async def vip_user_search_result(msg: Message, state: FSMContext):
    if not await has_perm(msg.from_user.id, "adm:settings"):
        await state.clear()
        return
    from models import HostedApp
    await state.clear()
    term = (msg.text or "").strip()
    home = await smart_home_kb(msg.from_user.id)
    if not term:
        await msg.answer("ورودی خالی بود.", reply_markup=home)
        return
    like = f"%{term}%"
    async with Session() as s:
        owners = []
        if term.isdigit():
            owners = [int(term)]
        else:
            users = (await s.scalars(select(PlatformUser).where(
                or_(PlatformUser.full_name.ilike(like),
                    PlatformUser.username.ilike(like))).limit(20))).all()
            owners = [u.telegram_id for u in users]
        cond = [HostedApp.name.ilike(like)]
        if owners:
            cond.append(HostedApp.owner_id.in_(owners))
        apps = (await s.scalars(select(HostedApp).where(or_(*cond))
                                .order_by(HostedApp.id.desc()).limit(40))).all()
        names = await _owner_names(s, [a.owner_id for a in apps])
    if not apps:
        await msg.answer(f"❌ چیزی با «{term}» پیدا نشد.", reply_markup=home)
        return
    rows = [[hx_button(
        f"{a.name} — {names.get(a.owner_id) or ('#' + str(a.owner_id))}"
        f" — {_vip_state_fa(a)}", callback_data=f"vip:app:{a.id}",
        style=ButtonStyle.PRIMARY)] for a in apps]
    rows.append([hx_button("⬅️ بازگشت", callback_data="vip:users:0",
                           style=ButtonStyle.DANGER)])
    await msg.answer("منوی اصلی:", reply_markup=home)
    await msg.answer(f"🔍 نتیجهٔ جستجویِ «{_html.escape(term)}» — {len(apps)} ربات:",
                     reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))


@router.callback_query(F.data.startswith("vipapp:"))
async def vip_app_action(cb: CallbackQuery, state: FSMContext, bot: Bot):
    if not await has_perm(cb.from_user.id, "adm:settings"):
        await cb.answer("دسترسی نداری", show_alert=True)
        return
    from models import HostedApp
    parts = cb.data.split(":")
    action, app_id = parts[1], int(parts[2])

    # === PATCH_VIP_HOURS_V1 === پرسیدنِ مقدارِ دلخواه (روز یا ساعت)
    if action == "custom":
        await state.set_state(AdminFSM.vip_custom_time)
        await state.update_data(vip_app_id=app_id)
        await cb.message.answer(
            "⏱ چقدر به سررسید اضافه/کم شود؟ نمونه‌ها:\n"
            "<code>+10 روز</code> · <code>-3 روز</code> · "
            "<code>+12 ساعت</code> · <code>-2 ساعت</code>",
            reply_markup=await smart_cancel_kb())
        await cb.answer()
        return

    if action == "msg":
        await state.set_state(AdminFSM.vip_msg)
        await state.update_data(vip_app_id=app_id)
        await cb.message.answer("✉️ متنِ پیام برایِ مالکِ این ربات را بفرست:",
                                reply_markup=await smart_cancel_kb())
        await cb.answer()
        return

    note = ""
    async with Session() as s:
        a = await s.get(HostedApp, app_id)
        if not a:
            await cb.answer("پیدا نشد", show_alert=True)
            return
        now = datetime.datetime.now()
        if action == "day":
            days = int(parts[3])
            base = a.paid_until if (a.paid_until and a.paid_until > now) else now
            a.paid_until = base + datetime.timedelta(days=days)
            if a.paid_until < now:
                a.paid_until = None
            a.notice_sent = None
            note = f"{abs(days)} روز {'اضافه' if days > 0 else 'کم'} شد"
        elif action == "hour":
            # === PATCH_VIP_HOURS_V1 === همان منطقِ «day»، با واحدِ ساعت
            hours = int(parts[3])
            base = a.paid_until if (a.paid_until and a.paid_until > now) else now
            a.paid_until = base + datetime.timedelta(hours=hours)
            if a.paid_until < now:
                a.paid_until = None
            a.notice_sent = None
            note = f"{abs(hours)} ساعت {'اضافه' if hours > 0 else 'کم'} شد"
        elif action == "off":
            # ناظرِ سرویس ظرفِ ۲ دقیقه کانتینر را متوقف می‌کند
            a.status = "suspended"
            note = "خاموش شد"
        elif action == "on":
            a.status = "stopped"
            a.last_error = None
            note = "اجازهٔ روشن‌شدن داده شد"
        elif action == "arch":
            a.status = "archived"
            note = "به بایگانی رفت"
        elif action == "unarch":
            a.status = "stopped"
            note = "از بایگانی خارج شد"
        await s.commit()
        owner = a.owner_id
        name = a.name

    txt, kb = await _vip_app_screen(app_id, cb.from_user.id)
    try:
        await cb.message.edit_text(txt, reply_markup=kb)
    except Exception:
        logger.exception("به‌روزرسانیِ صفحهٔ اپ ناموفق بود")
    await cb.answer(f"✅ {note}")

    if action in ("day", "off", "on", "arch"):
        _fa = {"day": f"⏳ سررسیدِ ربات «{name}» تغییر کرد.",
               "off": f"⏸ ربات «{name}» توسط مدیر خاموش شد.",
               "on": f"▶️ ربات «{name}» دوباره فعال شد.",
               "arch": f"🗄 ربات «{name}» بایگانی شد."}[action]
        try:
            await bot.send_message(owner, _fa)
        except Exception:
            logger.exception("اطلاع‌رسانی به مالکِ اپ ناموفق بود")


