async def _vip_save(msg: Message, state: FSMContext, key: str,
                    lo: int, hi: int) -> None:
    raw = (msg.text or "").strip()
    if raw in ("❌ لغو", "لغو"):
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id))
        return
    val = fa_to_int(raw.replace(",", "").replace("،", ""))
    if val is None or not (lo <= val <= hi):
        await msg.answer(f"عدد نامعتبر است. مقداری بین {lo:,} و {hi:,} بفرست:")
        return
    await state.clear()
    await set_pset(key, str(val))
    txt, kb = await _vip_screen()
    await msg.answer("✅ ذخیره شد.", reply_markup=await smart_home_kb(msg.from_user.id))
    await msg.answer(txt, reply_markup=kb)


