# === PATCH_ADM_BOTS_SEARCH_BY_USER_V1 ===
async def _adm_bots_search_by_user(msg: Message, term: str, scope: str | None = None):
    """ربات‌هایِ یک کاربر را پیدا می‌کند: با آیدیِ عددی، یوزرنیم، یا نام."""
    term = (term or "").strip()
    home_kb = await smart_home_kb(msg.from_user.id)
    owners: list = []
    async with Session() as s:
        if term.isdigit():
            owners = [int(term)]
        else:
            like = f"%{term}%"
            users = (await s.scalars(select(PlatformUser).where(
                or_(PlatformUser.full_name.ilike(like),
                    PlatformUser.username.ilike(like))).limit(20))).all()
            owners = [u.telegram_id for u in users]
        if not owners:
            await msg.answer(
                f"❌ نه رباتی با یوزرنیمِ «{term}» پیدا شد، نه کاربری با این نام.",
                reply_markup=home_kb)
            return
        q = select(BotRow).where(BotRow.owner_id.in_(owners))
        if scope == "archive":
            q = q.where(BotRow.archived_at.is_not(None))
        bots = (await s.scalars(q.order_by(BotRow.id.desc()).limit(60))).all()
        names = await _owner_names(s, owners)
    if not bots:
        await msg.answer(f"کاربر پیدا شد ولی رباتی برایش ثبت نیست ({term}).",
                         reply_markup=home_kb)
        return
    src = "arch" if scope == "archive" else "bots"
    rows = [[hx_button(
        f"{_bot_status_icon(b)} @{b.username} • {names.get(b.owner_id) or ('#' + str(b.owner_id))}"
        f" • {b.plan}", callback_data=f"abot:{b.id}")] for b in bots]
    rows.append([hx_button("⬅️ بازگشت", callback_data="adm:bots", style=ButtonStyle.DANGER)])
    await msg.answer("منوی اصلی:", reply_markup=home_kb)
    await msg.answer(f"🔍 نتیجهٔ جستجویِ «{term}» — {len(bots)} ربات:",
                     reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))


@router.message(AdmBotSearchFSM.username)
async def adm_bots_search_result(msg: Message, state: FSMContext):
    if not await has_perm(msg.from_user.id, "adm:bots"):
        await state.clear()
        return
    data = await state.get_data()
    scope = data.get("scope")
    await state.clear()
    uname = (msg.text or "").strip().lstrip("@")
    if not uname:
        await msg.answer("یوزرنیم نامعتبر است.", reply_markup=await smart_home_kb(msg.from_user.id))
        return
    async with Session() as s:
        r = await s.scalar(select(BotRow).where(func.lower(BotRow.username) == uname.lower()))
    if not r:
        # === PATCH_ADM_BOTS_SEARCH_BY_USER_V1 ===
        # اگر یوزرنیمِ ربات نبود، همان ورودی را به‌عنوانِ کاربر می‌گیریم:
        # آیدیِ عددی، یوزرنیم، یا بخشی از نام — و ربات‌هایش را فهرست می‌کنیم.
        await _adm_bots_search_by_user(msg, uname, scope)
        return
    if scope == "archive" and not r.archived_at:
        await msg.answer(f"❌ ربات @{uname} پیدا شد ولی در بایگانی نیست.",
                         reply_markup=await smart_home_kb(msg.from_user.id))
        return
    src = "arch" if scope == "archive" else "bots"
    built = await _build_bot_detail(r.id, src)
    await msg.answer("منوی اصلی:", reply_markup=await smart_home_kb(msg.from_user.id))
    if not built:
        await msg.answer("یافت نشد.")
        return
    text, kb = built
    await msg.answer(text, reply_markup=kb)


@router.callback_query(F.data.startswith("abotpause:"))
async def adm_bot_pause(cb: CallbackQuery, state: FSMContext):
    # === PATCH_BOT_OFF_REASON_V1 ===
    # قبلاً بی‌درنگ غیرفعال می‌کرد و هیچ دلیلی ثبت نمی‌شد؛ حالا مثلِ
    # فلوی قفل‌کردن، اول دلیل را می‌پرسد و در lock_reason ذخیره می‌کند.
    if not await has_perm(cb.from_user.id, "adm:bots"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    bot_id = int(cb.data.split(":")[1])
    await state.set_state(AdminFSM.pause_bot_reason)
    await state.update_data(target_bot_id=bot_id)
    await cb.message.answer(
        "📝 دلیلِ غیرفعال‌سازیِ این ربات را بنویس؛ این متن در پروفایلِ ربات "
        "ذخیره و به مالکِ ربات هم اطلاع داده می‌شود:",
        reply_markup=await smart_cancel_kb())
    await cb.answer()


@router.message(AdminFSM.pause_bot_reason, F.text)
async def adm_bot_pause_reason(msg: Message, state: FSMContext, bot: Bot):
    # === PATCH_BOT_OFF_REASON_V1 ===
    if not await has_perm(msg.from_user.id, "adm:bots"):
        await state.clear()
        return
    data = await state.get_data()
    bot_id = data.get("target_bot_id")
    reason = (msg.text or "").strip()
    if reason in ("❌ لغو", "لغو"):
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    if not reason:
        await msg.answer("دلیل نمی‌تواند خالی باشد. دوباره بفرست:", reply_markup=await smart_cancel_kb())
        await state.set_state(AdminFSM.pause_bot_reason)
        await state.update_data(target_bot_id=bot_id)
        return
    await state.clear()
    admin_name = msg.from_user.full_name or str(msg.from_user.id)
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r:
            await msg.answer("ربات یافت نشد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
            return
        r.status = "admin_paused"
        r.lock_reason = f"غیرفعال‌سازیِ دستی توسط ادمین «{admin_name}» (آیدی {msg.from_user.id})؛ دلیل: {reason}"
        owner, uname = r.owner_id, r.username
        token = r.token
        await s.commit()
    try:
        import tenant_status_bus
        await tenant_status_bus.publish_tenant_invalidate(token)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        await bot.send_message(owner, f"🔴 ربات @{uname} توسط مدیریت غیرفعال شد.\n📋 دلیل: {reason}")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    built = await _build_bot_detail(bot_id)
    await msg.answer("منوی اصلی:", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
    if built:
        text, kb = built
        await msg.answer(text, reply_markup=kb)


# ═══════════════════ اخطارِ تخلف به مالکِ ربات ═══════════════════
# === PATCH_BOT_VIOLATION_WARN_V1 ===
# مدیر دلیلِ اخطار را می‌نویسد؛ بات‌ساز به مالکِ ربات پیامِ رسمیِ «اخطار n از ۲»
