@router.callback_query(F.data.startswith("abotresume:"))
async def adm_bot_resume(cb: CallbackQuery, bot: Bot):
    if not await has_perm(cb.from_user.id, "adm:bots"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    bot_id = int(cb.data.split(":")[1])
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r:
            await cb.answer("یافت نشد", show_alert=True)
            return
        # === PATCH_RELEASED_TOKEN_TWIN_V1 ===
        # رکوردی که توکنش به رکوردِ جدیدتر داده شده نباید فعال شود؛ قبلاً
        # فعال می‌شد و یک رباتِ «زامبی» با توکنِ نامعتبر می‌ساخت که فقط
        # خطا تولید می‌کرد (trial_cleanup: Token is invalid).
        from bot_utils import is_released_token
        if is_released_token(r.token):
            await cb.answer("⚠️ این رکوردِ قدیمی است و توکنش به ربات جدیدِ همین "
                            "مالک داده شده؛ قابلِ فعال‌سازی نیست. رکوردِ فعال را باز کن.",
                            show_alert=True)
            return
        was_archived = r.archived_at is not None
        r.status = "active"
        r.lock_reason = None  # === PATCH_BOT_OFF_REASON_V1 === پاک‌کردنِ دلیلِ خاموشیِ قبلی
        if was_archived:
            # خروج از بایگانی + یک دورهٔ اعتبار تازه تا بلافاصله دوباره بایگانی نشود
            r.archived_at = None
            r.archive_reason = None
            r.last_expiry_notice = None
            r.plan_expires_at = plan_expiry_from_now(r.plan)
        owner, uname = r.owner_id, r.username
        token = r.token
        await s.commit()
    try:
        # === PATCH_TENANT_STATUS_BUS_DIRECT_V1 ===
        # قبلاً از طریقِ main.invalidate_tenant_status صدا زده می‌شد که هم
        # کشِ محلیِ همون پروسه رو پاک می‌کرد هم NOTIFY می‌فرستاد. حالا که
        # main.py دیگه تنها نقطهٔ ورود نیست (main_platform.py/main_tenant.py)
        # و این کشِ وضعیت اصلاً سمتِ پلتفرم وجود نداره (فقط سمتِ مستأجره)،
        # مستقیم فقط NOTIFY می‌فرستیم — پروسه(های) مستأجر با listenerِ
        # tenant_status_bus فوری باخبر می‌شن.
        import tenant_status_bus
        await tenant_status_bus.publish_tenant_invalidate(token)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    # === PATCH_ARCHIVE_RESTORE_WEBHOOK_V1 ===
    if was_archived:
        try:
            await set_tenant_webhook(token)
        except Exception:
            logger.exception("بازگرداندنِ وب‌هوکِ ربات پس از خروج از بایگانی ناموفق بود")
    try:
        note = ("🟢 ربات @{u} از بایگانی خارج و فعال شد." if was_archived
                else "🟢 ربات @{u} توسط مدیریت فعال شد.").format(u=uname)
        await bot.send_message(owner, note)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer("ربات فعال شد")
    await _render_bot_detail(cb, bot_id)


