@router.callback_query(F.data.startswith("abotbackup:"))
async def adm_bot_backup(cb: CallbackQuery):
    """ساخت و ارسال فایل بک‌اپ کامل یک ربات (تمام جدول‌های مستأجر)."""
    if not await has_perm(cb.from_user.id, "adm:bots"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    bot_id = int(cb.data.split(":")[1])
    await cb.answer("⏳ در حال آماده‌سازی بک‌اپ…")
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r:
            await cb.answer("یافت نشد", show_alert=True)
            return
        uname = r.username
        data = {
            "magic": "BOTSAZ_BOT_BACKUP_V1",
            "bot": {
                "id": r.id, "owner_id": r.owner_id, "username": r.username,
                "field": r.field, "plan": r.plan, "status": r.status,
                "created_at": r.created_at.isoformat() if r.created_at else None,
            },
            "tables": {},
        }
        for M in TENANT_OWNED_MODELS:
            tname = getattr(M, "__tablename__", M.__name__)
            try:
                objs = (await s.scalars(select(M).where(M.bot_id == bot_id))).all()
                rows_out = []
                for o in objs:
                    row_dict = {}
                    for col in M.__table__.columns:
                        val = getattr(o, col.name)
                        if isinstance(val, (datetime.datetime, datetime.date)):
                            val = val.isoformat()
                        row_dict[col.name] = val
                    rows_out.append(row_dict)
                data["tables"][tname] = rows_out
            except Exception as e:
                print(f"adm_bot_backup: skip {tname}:", e)
    payload = json.dumps(data, ensure_ascii=False, indent=2, default=str).encode("utf-8")
    total_rows = sum(len(v) for v in data["tables"].values())
    doc = BufferedInputFile(payload, filename=f"bot_{bot_id}_backup.botsaz")
    await cb.message.answer_document(
        doc,
        caption=(f"📦 <b>بک‌اپ کامل ربات</b> @{uname}\n"
                 f"تعداد جدول: {len(data['tables'])}\n"
                 f"تعداد کل رکورد: {total_rows}"),
    )


@router.callback_query(F.data.startswith("abotswapreq:"))
async def adm_bot_swap_request(cb: CallbackQuery):
    """شروع درخواست تعویض توکن — به مالک ربات، داخل خودِ ربات او، پیام می‌رود."""
    if not await has_perm(cb.from_user.id, "adm:bots"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    bot_id = int(cb.data.split(":")[1])
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r:
            await cb.answer("یافت نشد", show_alert=True)
            return
        existing = await s.scalar(select(TokenSwapRequest).where(
            TokenSwapRequest.old_bot_id == bot_id,
            TokenSwapRequest.status.in_(["pending_token", "pending_admin"]),
        ))
        if existing:
            await cb.answer("یک درخواست تعویض توکن برای این ربات از قبل در جریان است.", show_alert=True)
            return
        swap = TokenSwapRequest(old_bot_id=bot_id, requested_by=r.owner_id, status="pending_token")
        s.add(swap)
        await s.commit()
        swap_id = swap.id
        token, owner, uname = r.token, r.owner_id, r.username
    try:
        async with _temp_bot(token) as tb:
            kb = InlineKeyboardMarkup(inline_keyboard=[[
                hx_button("🔁 ارسال توکن جدید", callback_data=f"tkswap:start:{swap_id}")
            ]])
            await tb.send_message(
                owner,
                "🔁 <b>درخواست تعویض توکن ربات</b>\n\n"
                f"مدیریت بات‌ساز درخواست کرده توکن ربات @{uname} با یک توکن جدید جایگزین شود "
                "(مثلاً به‌علت ساخت ربات تازه در بات‌فادر).\n\n"
                "اگر این درخواست را تایید می‌کنی، روی دکمهٔ زیر بزن و سپس توکن جدید را برایم بفرست.",
                reply_markup=kb,
            )
        sent = True
    except Exception as e:
        sent = False
        print("adm_bot_swap_request: send failed:", e)
    if sent:
        await cb.answer("درخواست برای مالک ربات ارسال شد ✅", show_alert=True)
    else:
        await cb.answer("ارسال پیام به مالک ربات ناموفق بود (شاید ربات استارت نشده).", show_alert=True)


async def _apply_token_migration(old_bot_id: int, new_token: str) -> tuple[bool, str, int | None, str | None]:
    """PATCH_SELF_SERVICE_TOKEN_OWNER_V1 — قلبِ واقعیِ «تعویضِ توکن»: توکنِ
    جدید رو اعتبارسنجی می‌کنه، رباتِ جدید رو می‌سازه (یا اگه از قبل ساخته
    شده، همونو برمی‌داره)، تمامِ دیتایِ رباتِ قدیم رو منتقل می‌کنه، همه‌ی
    ارجاع‌های bot_id (شاملِ ستون‌هایِ دوگانه مثلِ old_bot_id/new_bot_id) رو
    ری‌دایرکت می‌کنه، رباتِ قدیم رو حذف (یا در صورتِ خطا آرشیو) می‌کنه، و
    وب‌هوک رو از روی توکنِ قدیم برمی‌داره و رویِ توکنِ جدید می‌ذاره.

    این تابع از داخلِ adm_token_swap_decide (مسیرِ قدیمی، با تاییدِ دستیِ
    ادمین) استخراج شده تا هم اونجا هم مسیرِ جدیدِ خودسرویس (بدونِ نیاز به
    تاییدِ دستی، فقط با محدودیتِ ماهانه) از دقیقاً همون منطقِ آزمایش‌شده
    استفاده کنن — نه یک نسخهٔ دوبارهٔ جداگانه‌ی مستعدِ باگ.

    خروجی: (موفق؟, پیامِ خطا در صورتِ شکست, آیدیِ رباتِ جدید, یوزرنیمِ رباتِ جدید)
    """
    try:
        async with _temp_bot(new_token) as check_bot:
            me = await check_bot.get_me()
    except Exception:
        return False, "توکنِ جدید معتبر نیست یا بات‌فادر جوابی نداد.", None, None

    async with Session() as s:
        old_row2 = await s.get(BotRow, old_bot_id)
        if not old_row2:
            return False, "ربات قدیم یافت نشد.", None, None
        old_token = old_row2.token
        # === PATCH_TOKEN_SWAP_IDEMPOTENT_CREATE_V1 ===
        new_row = await s.scalar(select(BotRow).where(BotRow.token == new_token))
        if new_row is None:
            new_row = BotRow(
                owner_id=old_row2.owner_id, token=new_token, username=me.username,
                field=old_row2.field, plan=old_row2.plan, status="active",
                plan_expires_at=old_row2.plan_expires_at,
            )
            s.add(new_row)
            await s.flush()
        new_bot_id = new_row.id
        await s.commit()

    await migrate_bot_data(old_bot_id, new_bot_id)

    from config import redirect_all_bot_id_references
    await redirect_all_bot_id_references(old_bot_id, new_bot_id)

    async with Session() as s:
        from sqlalchemy import update as _sa_update
        from models import TENANT_DUAL_REF_MODELS
        for _M, _c_old, _c_new in TENANT_DUAL_REF_MODELS:
            try:
                await s.execute(_sa_update(_M).where(
                    getattr(_M, _c_old) == old_bot_id).values(**{_c_old: new_bot_id}))
                await s.execute(_sa_update(_M).where(
                    getattr(_M, _c_new) == old_bot_id).values(**{_c_new: new_bot_id}))
            except Exception:
                logger.exception("token swap: dual-ref redirect failed")
        old_row3 = await s.get(BotRow, old_bot_id)
        if old_row3:
            try:
                await s.delete(old_row3)
                await s.flush()
                await s.commit()
            except Exception:
                logger.exception("token swap: حذفِ رباتِ قدیم شکست خورد — آرشیو می‌شود")
                await s.rollback()
                async with Session() as s2:
                    old_row4 = await s2.get(BotRow, old_bot_id)
                    if old_row4:
                        old_row4.status = "archived"
                        old_row4.archive_reason = "token_swapped"
                    await s2.commit()

    try:
        async with _temp_bot(old_token) as ob:
            await ob.delete_webhook()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    try:
        async with _temp_bot(new_token) as nb:
            await nb.set_webhook(f"{WEBHOOK_BASE}/webhook/{new_token}", drop_pending_updates=True,
                                 allowed_updates=__import__("webhook_utils").TENANT_ALLOWED_UPDATES)
    except Exception as e:
        print("_apply_token_migration: activate new bot webhook failed:", e)

    return True, "", new_bot_id, me.username


# === PATCH_TKSWAP_DECORATOR_FIX_V1 ===
# این دکوریتور اشتباهاً رویِ تابعِ کمکیِ _apply_token_migration نشسته بود
# (احتمالاً هنگامِ استخراجِ آن تابع از همین هندلر جابه‌جا شده). نتیجه:
# با هر کلیکِ ادمین رویِ «تایید/ردِ تعویضِ توکن»، aiogram تابعِ کمکی را با
# یک CallbackQuery به‌جایِ old_bot_id صدا می‌زد → TypeError و پیامِ
# ERR-XXXX برایِ ادمین؛ و خودِ این هندلر هیچ‌وقت اجرا نمی‌شد.
@router.callback_query(F.data.startswith("tkswapdecide:"))
async def adm_token_swap_decide(cb: CallbackQuery):
    """تایید/رد نهایی انتقال اطلاعات ربات قدیم به ربات جدید — فقط ادمین کل پلتفرم."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")
    req_id, decision = int(parts[1]), parts[2]
    async with Session() as s:
        swap = await s.get(TokenSwapRequest, req_id)
        if not swap or swap.status != "pending_admin":
            await cb.answer("این درخواست دیگر معتبر نیست.", show_alert=True)
            return
        old_row = await s.get(BotRow, swap.old_bot_id)
        if not old_row:
            await cb.answer("ربات قدیم یافت نشد.", show_alert=True)
            return
        old_token, requested_by, new_token = old_row.token, swap.requested_by, swap.new_token

    if decision == "n":
        async with Session() as s:
            swap2 = await s.get(TokenSwapRequest, req_id)
            swap2.status = "rejected"
            swap2.decided_at = datetime.datetime.now()
            await s.commit()
        try:
            async with _temp_bot(old_token) as tb:
                await tb.send_message(requested_by, "❌ درخواست تعویض توکن ربات شما رد شد.")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        try:
            await cb.message.edit_text("❌ درخواست تعویض توکن رد شد.")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.answer("رد شد")
        return

    # ── تایید: استفاده از منطقِ مشترکِ اعمالِ تعویض ──
    ok, err, new_bot_id, new_username = await _apply_token_migration(swap.old_bot_id, new_token)
    if not ok:
        async with Session() as s:
            swap2 = await s.get(TokenSwapRequest, req_id)
            swap2.status = "rejected"
            swap2.decided_at = datetime.datetime.now()
            await s.commit()
        await cb.answer(err or "خطا در اعمالِ تعویض. درخواست لغو شد.", show_alert=True)
        return

    async with Session() as s:
        swap3 = await s.get(TokenSwapRequest, req_id)
        swap3.status = "approved"
        swap3.new_bot_id = new_bot_id
        swap3.decided_at = datetime.datetime.now()
        await s.commit()

    try:
        async with _temp_bot(new_token) as nb:
            await nb.send_message(requested_by, "✅ اطلاعات ربات شما با موفقیت منتقل و فعال شد.")
    except Exception as e:
        print("adm_token_swap_decide: notify owner failed:", e)

    try:
        await cb.message.edit_text(
            f"✅ تعویض توکن انجام شد.\nربات قدیم → ربات جدید (@{new_username}) با موفقیت منتقل شد."
        )
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await cb.answer("انجام شد ✅")


# ═══════════════════ PATCH_SELF_SERVICE_TOKEN_OWNER_V1 ═══════════════════
# درخواستِ خودسرویسِ تعویضِ توکن / واگذاریِ مالکیتِ ربات — برخلافِ سیستمِ
# قدیمیِ بالا (TokenSwapRequest که با تاییدِ دستیِ ادمین کار می‌کنه)، این
# یکی کاملاً خودکاره: فقط پلن رشد/حرفه‌ای، فقط ۲ بار در ماه برایِ هر
# کاربر (مدیرِ اصلیِ پلتفرم نامحدود)، و بعدِ تاییدِ خودِ کاربر بلافاصله
# اعمال می‌شه — فقط برایِ اطلاع، به مدیرِ اصلی خبر داده می‌شه.

SELF_SERVICE_MONTHLY_LIMIT = 2


class SelfServiceSwapFSM(StatesGroup):
    new_token = State()
    new_owner_id = State()


async def _ssbc_uses_this_month(requesting_id: int) -> int:
    cutoff = datetime.datetime.now() - datetime.timedelta(days=30)
    async with Session() as s:
        return await s.scalar(select(func.count()).select_from(SelfServiceBotChange).where(
            SelfServiceBotChange.requested_by == requesting_id,
            SelfServiceBotChange.created_at >= cutoff)) or 0


async def _ssbc_remaining(requesting_id: int) -> int | None:
    """None یعنی نامحدود (مدیرِ اصلیِ پلتفرم)."""
    if requesting_id == PLATFORM_ADMIN_ID:
        return None
    used = await _ssbc_uses_this_month(requesting_id)
    return max(0, SELF_SERVICE_MONTHLY_LIMIT - used)


@router.callback_query(F.data.startswith("ssbc:menu:"))
async def ssbc_menu(cb: CallbackQuery):
    bot_id = int(cb.data.split(":")[2])
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
    if not r or r.owner_id != cb.from_user.id:
        await cb.answer("ربات یافت نشد", show_alert=True)
        return
    # === PATCH_SELF_OWNERSHIP_LOCK_V1 ===
    # گیتِ مشترک: رباتِ در دورهٔ تست (چه تستِ بات‌ساز، چه تستِ ۲ روزهٔ همکار)
    # و پلنِ رایگان اجازهٔ تعویضِ توکن/واگذاریِ مالکیت ندارند. چکِ سرورساید
    # لازم است چون دکمه پنهان‌کردن کافی نیست (دکمه‌های قدیمی در چتِ کاربر
    # هنوز کار می‌کنند).
    from bot_utils import owner_swap_lock_reason
    async with Session() as s:
        _lock = await owner_swap_lock_reason(s, r)
    if _lock:
        await cb.answer(_lock.replace("<b>", "").replace("</b>", ""), show_alert=True)
        return
    remaining = await _ssbc_remaining(cb.from_user.id)
    if remaining is not None and remaining <= 0:
        await cb.answer(
            f"❌ سقفِ ماهانه (حداکثر {SELF_SERVICE_MONTHLY_LIMIT} بار) رو استفاده کردی. "
            "ماهِ بعد دوباره در دسترس می‌شه.", show_alert=True)
        return
    remain_txt = "نامحدود" if remaining is None else f"{remaining} بار دیگه از {SELF_SERVICE_MONTHLY_LIMIT} بار در این ماه"
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("🔑 تعویضِ توکن", callback_data=f"ssbc:pick:{bot_id}:token")],
        [hx_button("👤 واگذاریِ مالکیت", callback_data=f"ssbc:pick:{bot_id}:owner")],
        [hx_button("⬅️ بازگشت", callback_data=f"mb:{bot_id}", style=ButtonStyle.DANGER)],
    ])
    text = (
        f"🔁 <b>تعویضِ توکن / واگذاریِ مالکیتِ ربات</b>\n\n"
        f"🤖 ربات: @{r.username}\n"
        f"📊 سهمیهٔ باقی‌مانده: {remain_txt}\n\n"
        "⚠️ هردو عمل فوری و بلافاصله اعمال می‌شن؛ برگشت‌ناپذیرن. "
        "کدوم رو می‌خوای انجام بدی؟"
    )
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


@router.callback_query(F.data.startswith("ssbc:pick:"))
async def ssbc_pick(cb: CallbackQuery, state: FSMContext):
    _, _, bot_id_s, kind = cb.data.split(":")
    bot_id = int(bot_id_s)
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
    if not r or r.owner_id != cb.from_user.id:
        await cb.answer("ربات یافت نشد", show_alert=True)
        return
    # === PATCH_SELF_OWNERSHIP_LOCK_V1 ===
    # گیتِ مشترک: رباتِ در دورهٔ تست (چه تستِ بات‌ساز، چه تستِ ۲ روزهٔ همکار)
    # و پلنِ رایگان اجازهٔ تعویضِ توکن/واگذاریِ مالکیت ندارند. چکِ سرورساید
    # لازم است چون دکمه پنهان‌کردن کافی نیست (دکمه‌های قدیمی در چتِ کاربر
    # هنوز کار می‌کنند).
    from bot_utils import owner_swap_lock_reason
    async with Session() as s:
        _lock = await owner_swap_lock_reason(s, r)
    if _lock:
        await cb.answer(_lock.replace("<b>", "").replace("</b>", ""), show_alert=True)
        return
    cancel_kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("❌ لغو", callback_data=f"ssbc:menu:{bot_id}", style=ButtonStyle.DANGER)]])
    if kind == "token":
        await state.set_state(SelfServiceSwapFSM.new_token)
        await state.update_data(ssbc_bot_id=bot_id)
        await cb.message.answer(
            "🔑 توکنِ جدید رو از بات‌فادر (BotFather) بگیر و همین‌جا بفرست:",
            reply_markup=cancel_kb)
    elif kind == "owner":
        await state.set_state(SelfServiceSwapFSM.new_owner_id)
        await state.update_data(ssbc_bot_id=bot_id)
        await cb.message.answer(
            "👤 آیدیِ عددیِ تلگرامِ مالکِ جدید رو بفرست (یا یه پیام از همون فرد "
            "برام فوروارد کن).\n\n⚠️ بعدِ این، خودت دیگه دسترسیِ مدیریتی به این "
            "ربات نخواهی داشت.",
            reply_markup=cancel_kb)
    else:
        await cb.answer()
        return
    await cb.answer()


@router.message(SelfServiceSwapFSM.new_token, F.text)
async def ssbc_receive_token(msg: Message, state: FSMContext):
    data = await state.get_data()
    bot_id = data.get("ssbc_bot_id")
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
    if not r or r.owner_id != msg.from_user.id:
        await state.clear()
        return
    new_token = (msg.text or "").strip()
    if not new_token or ":" not in new_token:
        await msg.answer("توکن نامعتبره. دوباره بفرست یا «❌ لغو» رو بزن.")
        return
    try:
        async with _temp_bot(new_token) as check_bot:
            me = await check_bot.get_me()
    except Exception:
        await msg.answer("❌ این توکن معتبر نیست یا بات‌فادر جواب نداد. دوباره بفرست:")
        return
    await state.update_data(ssbc_new_token=new_token, ssbc_new_username=me.username)
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("✅ تایید و اعمالِ فوری", callback_data=f"ssbc:confirm:{bot_id}:token",
                              style=ButtonStyle.SUCCESS)],
        [hx_button("❌ انصراف", callback_data=f"ssbc:menu:{bot_id}", style=ButtonStyle.DANGER)],
    ])
    await msg.answer(
        f"⚠️ مطمئنی می‌خوای توکنِ رباتِ @{r.username} رو با توکنِ جدید (رباتِ @{me.username}) "
        "عوض کنی؟ این کار فوری و برگشت‌ناپذیره — تمامِ اطلاعاتِ ربات (کاربرها، سفارش‌ها، "
        "تنظیمات) به رباتِ جدید منتقل می‌شه.",
        reply_markup=kb)


@router.message(SelfServiceSwapFSM.new_owner_id, F.text)
async def ssbc_receive_owner(msg: Message, state: FSMContext):
    data = await state.get_data()
    bot_id = data.get("ssbc_bot_id")
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
    if not r or r.owner_id != msg.from_user.id:
        await state.clear()
        return
    new_owner_id = None
    fwd_origin = getattr(msg, "forward_origin", None)
    if fwd_origin is not None and getattr(fwd_origin, "sender_user", None):
        new_owner_id = fwd_origin.sender_user.id
    elif msg.forward_from:
        new_owner_id = msg.forward_from.id
    else:
        txt = (msg.text or "").strip()
        if txt.isdigit():
            new_owner_id = int(txt)
    if not new_owner_id:
        await msg.answer("❌ آیدیِ عددیِ معتبر بفرست، یا یه پیام از همون فرد فوروارد کن.")
        return
    if new_owner_id == msg.from_user.id:
        await msg.answer("❌ این که همون آیدیِ خودتِه. یه آیدیِ دیگه بفرست:")
        return
    await state.update_data(ssbc_new_owner_id=new_owner_id)
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("✅ تایید و اعمالِ فوری", callback_data=f"ssbc:confirm:{bot_id}:owner",
                              style=ButtonStyle.SUCCESS)],
        [hx_button("❌ انصراف", callback_data=f"ssbc:menu:{bot_id}", style=ButtonStyle.DANGER)],
    ])
    await msg.answer(
        f"⚠️ مطمئنی می‌خوای مالکیتِ رباتِ @{r.username} رو به آیدیِ <code>{new_owner_id}</code> "
        "واگذار کنی؟ این کار فوری و برگشت‌ناپذیره — بعدِ این، خودت دیگه دسترسیِ مدیریتی "
        "به این ربات نخواهی داشت.",
        reply_markup=kb)


async def _ssbc_notify_admin(bot: Bot, kind: str, requesting_id: int, bot_id: int,
                              old_username: str, extra_line: str = "") -> None:
    """اطلاعِ مدیرِ اصلیِ پلتفرم — با پروفایلِ درخواست‌دهنده (لینکِ مستقیمِ
    تلگرام، نه یه صفحهٔ داخلی که هنوز ساخته نشده) و لینکِ رباتِ مربوطه."""
    if requesting_id == PLATFORM_ADMIN_ID:
        return  # خودِ ادمین نیازی به اطلاع‌رسانی به خودش نداره
    try:
        used = await _ssbc_uses_this_month(requesting_id)
        kind_label = "تعویضِ توکن" if kind == "token" else "واگذاریِ مالکیت"
        text = (
            f"✅ <b>{kind_label}ِ ربات با موفقیت توسطِ خودِ کاربر انجام شد</b>\n\n"
            f"🤖 ربات: @{old_username} (#{bot_id})\n"
            f"👤 درخواست‌دهنده: <code>{requesting_id}</code>\n"
            f"{extra_line}"
            f"📊 مصرفِ این ماه: {used}/{SELF_SERVICE_MONTHLY_LIMIT}"
        )
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="👤 پروفایلِ کاربر",
                                  url=f"tg://user?id={requesting_id}")],
            [hx_button("🤖 مشاهدهٔ ربات", callback_data=f"abot:{bot_id}:all")],
        ])
        await bot.send_message(PLATFORM_ADMIN_ID, text, reply_markup=kb)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده در _ssbc_notify_admin")


@router.callback_query(F.data.startswith("ssbc:confirm:"))
async def ssbc_confirm(cb: CallbackQuery, bot: Bot, state: FSMContext):
    _, _, bot_id_s, kind = cb.data.split(":")
    bot_id = int(bot_id_s)
    requesting_id = cb.from_user.id
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
    if not r or r.owner_id != requesting_id:
        await cb.answer("ربات یافت نشد", show_alert=True)
        return
    # === PATCH_SELF_OWNERSHIP_LOCK_V1 ===
    # گیتِ مشترک: رباتِ در دورهٔ تست (چه تستِ بات‌ساز، چه تستِ ۲ روزهٔ همکار)
    # و پلنِ رایگان اجازهٔ تعویضِ توکن/واگذاریِ مالکیت ندارند. چکِ سرورساید
    # لازم است چون دکمه پنهان‌کردن کافی نیست (دکمه‌های قدیمی در چتِ کاربر
    # هنوز کار می‌کنند).
    from bot_utils import owner_swap_lock_reason
    async with Session() as s:
        _lock = await owner_swap_lock_reason(s, r)
    if _lock:
        await cb.answer(_lock.replace("<b>", "").replace("</b>", ""), show_alert=True)
        return
    # === بازچکِ محدودیت — ضدِ ریس (دو تپِ سریع/دو تب) ===
    remaining = await _ssbc_remaining(requesting_id)
    if remaining is not None and remaining <= 0:
        await cb.answer("❌ سقفِ ماهانه پُر شده.", show_alert=True)
        return
    data = await state.get_data()
    await state.clear()
    old_username = r.username

    if kind == "token":
        new_token = data.get("ssbc_new_token")
        if not new_token:
            await cb.answer("❌ اطلاعات منقضی شده؛ از اول امتحان کن.", show_alert=True)
            return
        await cb.answer("⏳ در حالِ اعمال...")
        ok, err, new_bot_id, new_username = await _apply_token_migration(bot_id, new_token)
        if not ok:
            await cb.message.answer(f"❌ تعویضِ توکن ناموفق بود: {err}")
            return
        async with Session() as s:
            s.add(SelfServiceBotChange(requested_by=requesting_id, bot_id=new_bot_id, kind="token"))
            await s.commit()
        try:
            async with _temp_bot(new_token) as nb:
                await nb.send_message(requesting_id, "✅ توکنِ رباتت با موفقیت عوض شد و ربات فعاله.")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await cb.message.answer(f"✅ توکنِ ربات با موفقیت عوض شد. رباتِ جدید: @{new_username}")
        await _ssbc_notify_admin(bot, "token", requesting_id, new_bot_id, old_username)

    elif kind == "owner":
        new_owner_id = data.get("ssbc_new_owner_id")
        if not new_owner_id:
            await cb.answer("❌ اطلاعات منقضی شده؛ از اول امتحان کن.", show_alert=True)
            return
        await cb.answer("⏳ در حالِ اعمال...")
        async with Session() as s:
            r2 = await s.get(BotRow, bot_id)
            if not r2 or r2.owner_id != requesting_id:
                await cb.message.answer("❌ ربات یافت نشد یا دیگه مالِ تو نیست.")
                return
            r2.owner_id = new_owner_id
            await s.commit()
            s.add(SelfServiceBotChange(requested_by=requesting_id, bot_id=bot_id, kind="owner"))
            await s.commit()
        await cb.message.answer(
            f"✅ مالکیتِ رباتِ @{old_username} با موفقیت به آیدیِ <code>{new_owner_id}</code> واگذار شد.")
        try:
            await bot.send_message(
                new_owner_id,
                f"🎁 مالکیتِ ربات @{old_username} به آیدیِ تلگرامِ تو واگذار شد. "
                "از «🗂 ربات‌های من» می‌تونی مدیریتش کنی.")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        await _ssbc_notify_admin(
            bot, "owner", requesting_id, bot_id, old_username,
            extra_line=f"👤 مالکِ جدید: <code>{new_owner_id}</code>\n")


_ARCHIVE_FILTERS = {
    "all":          "🗂 همه",
    "free":         "🆓 رایگان",
    "growth":       "🚀 رشد",
    "pro":          "💎 حرفه‌ای",
    "user_deleted": "🗑 حذف‌شده توسط کاربر",
}

# === PATCH_ADMIN_ARCHIVE_PAGINATION_V1 ===
# باگ: وقتی تعداد ربات‌های بایگانی‌شده زیاد می‌شد (مثلاً چند ده‌تا)، کل
# لیست یک‌جا توی متنِ پیام ساخته می‌شد و از سقفِ ۴۰۹۶ کاراکترِ تلگرام رد
# می‌شد → «Bad Request: MESSAGE_TOO_LONG». چون هم edit_text و هم مسیرِ
# fallback با answer() همون متنِ طولانی رو می‌فرستادن، هردو با همین خطا
# شکست می‌خوردن و کل استثنا مدیریت‌نشده بالا می‌رفت — یعنی دکمهٔ «🗄 بایگانی»
# عملاً هیچ‌کاری نمی‌کرد (نه خطای روشن، نه لیست). راه‌حل: دقیقاً مثلِ لیستِ
# «adm:bots»، اینجا هم صفحه‌بندی (۸ تا در هر صفحه) اضافه شد.
ARCHIVE_PAGE_SIZE = 8


@router.callback_query(F.data == "adm:archive")
async def adm_archive(cb: CallbackQuery):
    await _show_archive(cb, "all", 0)


@router.callback_query(F.data.startswith("admarch:filter:"))
async def adm_archive_filter(cb: CallbackQuery):
    parts = cb.data.split(":")
    filt = parts[2]
    try:
        page = int(parts[3]) if len(parts) > 3 else 0
    except ValueError:
        page = 0
    await _show_archive(cb, filt, page)


async def _show_archive(cb: CallbackQuery, filt: str, page: int = 0):
    if not await has_perm(cb.from_user.id, "adm:bots"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    from config import archive_retention_days
    async with Session() as s:
        rows = (await s.scalars(
            select(BotRow).where(BotRow.archived_at.is_not(None)).order_by(BotRow.archived_at)
        )).all()

    def _cat(r):
        if r.archive_reason == "user_deleted":
            return "user_deleted"
        return (r.plan or "free")

    counts = {"free": 0, "growth": 0, "pro": 0, "user_deleted": 0}
    for r in rows:
        c = _cat(r)
        if c in counts:
            counts[c] += 1
    if filt == "all":
        filtered = rows
    else:
        filtered = [r for r in rows if _cat(r) == filt]

    filter_row = []
    for key, label in _ARCHIVE_FILTERS.items():
        n = len(rows) if key == "all" else counts.get(key, 0)
        mark = "▶️ " if key == filt else ""
        filter_row.append(hx_button(f"{mark}{label} ({n})", callback_data=f"admarch:filter:{key}:0"))

    total = len(filtered)
    pages = max(1, (total + ARCHIVE_PAGE_SIZE - 1) // ARCHIVE_PAGE_SIZE)
    page = max(0, min(page, pages - 1))
    chunk = filtered[page * ARCHIVE_PAGE_SIZE: (page + 1) * ARCHIVE_PAGE_SIZE]

    lines = [f"🗄 <b>بایگانی ربات‌ها</b> — {_ARCHIVE_FILTERS.get(filt, filt)} "
             f"({total} مورد) — صفحه {page+1}/{pages}", ""]
    kb_rows = [filter_row[:3], filter_row[3:]]
    if not filtered:
        lines.append("چیزی در این دسته نیست.")
    else:
        now = datetime.datetime.now()
        for r in chunk:
            retention = archive_retention_days(r.plan, r.archive_reason)
            left = max(retention - (now - r.archived_at).days, 0)
            lines.append(f"• @{r.username} — مالک <code>{r.owner_id}</code> — ⏳ {left} روز تا حذف")
            kb_rows.append([
                hx_button(f"@{r.username}", callback_data=f"abot:{r.id}:arch"),
                hx_button("♻️ بازگردانی", callback_data=f"abotresume:{r.id}",
                                     style=ButtonStyle.SUCCESS),
            ])
    nav = []
    if page > 0:
        nav.append(hx_button("◀️ قبلی", callback_data=f"admarch:filter:{filt}:{page-1}"))
    if page < pages - 1:
        nav.append(hx_button("بعدی ▶️", callback_data=f"admarch:filter:{filt}:{page+1}"))
    if nav:
        kb_rows.append(nav)
    kb_rows.append([hx_button("🔍 جستجو با یوزرنیم", callback_data="admarch:search")])
    kb_rows.append([hx_button("⬅️ بازگشت به پنل", callback_data="adm:back",
                                         style=ButtonStyle.DANGER)])
    try:
        await cb.message.edit_text("\n".join(lines),
                                   reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows))
    except Exception:
        await cb.message.answer("\n".join(lines),
                                reply_markup=InlineKeyboardMarkup(inline_keyboard=kb_rows))
    await cb.answer()


@router.callback_query(F.data == "admarch:search")
async def adm_archive_search_start(cb: CallbackQuery, state: FSMContext):
    """جستجوی یوزرنیم مخصوصِ داخلِ بایگانی (نتیجه فقط اگر واقعاً بایگانی باشد نشان داده می‌شود)."""
