@router.message(AdminFSM.sub_admin_add)
async def adm_sa_add_id(msg: Message, state: FSMContext):
    if not is_admin(msg.from_user.id):
        return
    uid = fa_to_int(msg.text)
    if not uid:
        await msg.answer("آیدی نامعتبر است.")
        return
    async with Session() as s:
        existing = await s.scalar(select(SubAdmin).where(SubAdmin.telegram_id == uid))
        if existing:
            await msg.answer("این کاربر قبلاً ادمین فرعی است.", reply_markup=await smart_home_kb(msg.from_user.id))
            await state.clear()
            return
        # نام را از PlatformUser بگیریم اگر موجود باشد
        pu = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == uid))
        fname = pu.full_name if pu else str(uid)
        sa = SubAdmin(telegram_id=uid, full_name=fname, permissions="[]")
        s.add(sa)
        await s.flush()
        sa_id = sa.id
        await s.commit()
    await state.clear()
    # نمایش صفحهٔ دسترسی‌ها برای این ادمین جدید
    await _show_sa_perms(msg, sa_id, uid, fname)


@router.callback_query(F.data.startswith("sa:") & ~F.data.startswith("sa:new") & ~F.data.startswith("sa:perm") & ~F.data.startswith("sa:del") & ~F.data.startswith("sa:tog"))
async def adm_sa_detail(cb: CallbackQuery):
    if not is_admin(cb.from_user.id):
        return
    sa_id = int(cb.data.split(":")[1])
    async with Session() as s:
        sa = await s.get(SubAdmin, sa_id)
        if not sa:
            await cb.answer("یافت نشد", show_alert=True)
            return
        perms = json.loads(sa.permissions) if sa.permissions else []
        name = sa.full_name or str(sa.telegram_id)
        uid = sa.telegram_id
        is_active = sa.is_active

    perm_lines = [f"✅ {SUB_ADMIN_PERMISSIONS[p]}" for p in perms if p in SUB_ADMIN_PERMISSIONS]
    perm_text = "\n".join(perm_lines) if perm_lines else "هیچ دسترسی‌ای تنظیم نشده"

    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("⚙️ تنظیم دسترسی‌ها", callback_data=f"sa:perm:{sa_id}")],
        [hx_button("🔴 غیرفعال کردن" if is_active else "🟢 فعال کردن",
            callback_data=f"sa:tog:{sa_id}"
        )],
        [hx_button("🗑 حذف", callback_data=f"sa:del:{sa_id}")],
        [hx_button("⬅️ بازگشت", callback_data="adm:sub_admins", style=ButtonStyle.DANGER)],
    ])
    await cb.message.edit_text(
        f"👑 ادمین فرعی: <b>{name}</b>\n"
        f"🆔 آیدی: <code>{uid}</code>\n"
        f"🚦 وضعیت: {'🟢 فعال' if is_active else '🔴 غیرفعال'}\n\n"
        f"<b>دسترسی‌های فعلی:</b>\n{perm_text}",
        reply_markup=kb
    )
    await cb.answer()


async def _show_sa_perms(target, sa_id: int, uid: int, name: str):
    """نمایش صفحهٔ تنظیم دسترسی‌ها برای ادمین فرعی."""
    async with Session() as s:
        sa = await s.get(SubAdmin, sa_id)
        current_perms = json.loads(sa.permissions) if sa and sa.permissions else []

    b = InlineKeyboardBuilder()
    for key, label in SUB_ADMIN_PERMISSIONS.items():
        icon = "✅" if key in current_perms else "⬜️"
        b.button(text=f"{icon} {label}", callback_data=f"sa:perm:tog:{sa_id}:{key}")
    b.button(text="⬅️ بازگشت به پروفایل", callback_data=f"sa:{sa_id}", style=ButtonStyle.DANGER)
    b.adjust(1)

    text = f"⚙️ <b>دسترسی‌های ادمین «{name}»</b>\n\nبرای فعال/غیرفعال کردن هر بخش روی آن بزنید:"
    try:
        if hasattr(target, 'message'):
            await target.message.edit_text(text, reply_markup=b.as_markup())
        else:
            await target.answer(text, reply_markup=b.as_markup())
    except Exception:
        if hasattr(target, 'message'):
            await target.message.answer(text, reply_markup=b.as_markup())
        else:
            await target.answer(text, reply_markup=b.as_markup())


@router.callback_query(F.data.startswith("sa:perm:tog:"))
async def adm_sa_perm_toggle(cb: CallbackQuery):
    if not is_admin(cb.from_user.id):
        return
    _, _, _, sa_id_str, perm_key = cb.data.split(":", 4)
    sa_id = int(sa_id_str)
    async with Session() as s:
        sa = await s.get(SubAdmin, sa_id)
        if not sa:
            await cb.answer("یافت نشد", show_alert=True)
            return
        perms = json.loads(sa.permissions) if sa.permissions else []
        if perm_key in perms:
            perms.remove(perm_key)
        else:
            perms.append(perm_key)
        sa.permissions = json.dumps(perms)
        await s.commit()
        uid = sa.telegram_id
        name = sa.full_name or str(uid)
    await _show_sa_perms(cb, sa_id, uid, name)
    await cb.answer()


