@router.callback_query(F.data.startswith("pf:tog:"))
async def adm_pf_toggle(cb: CallbackQuery):
    if not is_admin(cb.from_user.id):
        # === PATCH_PLAN_FEATURES_NO_RESPONSE_FIX_V1 ===
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    parts = cb.data.split(":")
    plan_str = parts[2]
    feat_key = parts[3]
    back_cat = parts[4] if len(parts) > 4 else ""
    try:
        plan = Plan(plan_str)
        feat = Feature(feat_key)
    except ValueError:
        await cb.answer("داده نامعتبر", show_alert=True)
        return

    async with Session() as s:
        existing = await s.scalar(
            select(PlanFeatureOverride)
            .where(PlanFeatureOverride.plan == plan_str, PlanFeatureOverride.feature_key == feat_key)
        )
        # وضعیت فعلی از PLAN_FEATURES (که از override لود شده)
        await reload_plan_features(s)
        currently_enabled = feat in PLAN_FEATURES[plan]
        new_state = not currently_enabled

        if existing:
            existing.enabled = new_state
        else:
            s.add(PlanFeatureOverride(plan=plan_str, feature_key=feat_key, enabled=new_state))
        await s.commit()
        # بارگذاری مجدد
        await reload_plan_features(s)

    icon = "✅ فعال" if new_state else "⬜️ غیرفعال"
    feat_label = FEATURE_LABELS.get(feat, feat_key)
    await cb.answer(f"{feat_label}: {icon}", show_alert=False)
    # رفرش صفحه (برگشت به همان دسته)
    cb.data = f"pf:{plan_str}:{back_cat}" if back_cat else f"pf:{plan_str}"
    await adm_pf_plan(cb)


