@router.callback_query(F.data == "adm:health")
async def adm_health(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    async with Session() as s:
        total_active   = await s.scalar(select(func.count(BotRow.id)).where(BotRow.status == "active")) or 0
        total_paused   = await s.scalar(select(func.count(BotRow.id)).where(BotRow.status == "paused")) or 0
        total_bad_tok  = await s.scalar(select(func.count(BotRow.id)).where(BotRow.status == "disabled_bad_token")) or 0
        total_archived = await s.scalar(select(func.count(BotRow.id)).where(BotRow.archived_at.is_not(None))) or 0
        from models import Order as _OrdH
        cutoff_h = datetime.datetime.utcnow() - datetime.timedelta(hours=24)
        stuck_h  = await s.scalar(select(func.count(_OrdH.id)).where(
            _OrdH.status == "awaiting_admin", _OrdH.created_at < cutoff_h)) or 0
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button(f"🚀 بررسی، فیکس و فعال‌سازیِ کاملِ همهٔ ربات‌ها ({total_active + total_paused + total_bad_tok})",
                              callback_data="adm:health_full_all", style=ButtonStyle.PRIMARY)],
        [hx_button("🔍 اسکن کامل همه ربات‌ها (توکن + وبهوک)",
                              callback_data="adm:health_scan", style=ButtonStyle.PRIMARY)],
        [hx_button("🔎 بررسی عمیقِ یک ربات (با یوزرنیم)",
                              callback_data="adm:health_one", style=ButtonStyle.PRIMARY)],
        [hx_button(f"⏳ سفارش‌های گیر کرده ({stuck_h})",
                              callback_data="adm:health_orders", style=ButtonStyle.PRIMARY)],
        *([[hx_button(f"❌ ربات‌های با توکن نامعتبر ({total_bad_tok})",
                                  callback_data="adm:health_bad_list", style=ButtonStyle.DANGER)]] if total_bad_tok else []),
        [hx_button(f"🟢 فعال‌سازی / اتصال مجدد ({total_paused + total_bad_tok} ربات)",
                              callback_data="adm:health_reconnect", style=ButtonStyle.SUCCESS)],
        [hx_button("⬅️ بازگشت", callback_data="adm:back", style=ButtonStyle.DANGER)],
    ])
    status_lines = (
        f"🟢 فعال: <b>{total_active}</b>   "
        f"🔴 متوقف: <b>{total_paused}</b>   "
        f"❌ توکن باطل: <b>{total_bad_tok}</b>   "
        f"🗄 آرشیو: <b>{total_archived}</b>"
    )
    await cb.message.edit_text(
        "🩺 <b>مرکز سلامت ربات‌ها</b>\n\n"
        f"{status_lines}\n"
        f"⏳ سفارش گیر کرده: <b>{stuck_h}</b>\n\n"
        "یک عملیات را انتخاب کن:",
        reply_markup=kb)
    await cb.answer()


@router.callback_query(F.data == "adm:health_full_all")
async def adm_health_full_all(cb: CallbackQuery, bot: Bot):
    """PATCH_HEALTH_FULL_ALL_V1 — برخلافِ «اتصال مجدد همهٔ مشکل‌دارها»
    (`adm:hrc_all`) که فقط ربات‌های از قبل paused/bad_token را هدف می‌گیرد،
    این دکمه واقعاً هر ربات (فعال + متوقف + توکن‌باطل، به‌جز آرشیوشده‌ها) را
    یک‌جا و تک‌تک بررسی، فیکسِ وبهوک، و فعال می‌کند — دقیقاً همان چیزی که در
    «مرکز سلامت» به‌صورتِ چند دکمهٔ جدا (اسکن، اتصال مجدد، فعال‌سازی) پخش
    شده بود، حالا در یک کلیک."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer()
        return
    await cb.answer("⏳ در حال بررسی و فعال‌سازیِ همهٔ ربات‌ها…")
    await cb.message.edit_text(
        "⏳ <b>بررسی، فیکسِ وبهوک و فعال‌سازیِ همهٔ ربات‌ها در حال انجام…</b>\n"
        "این ممکنه بسته به تعدادِ ربات‌ها چند ثانیه تا چند دقیقه طول بکشد.")
    async with Session() as s:
        bots = (await s.scalars(select(BotRow).where(
            BotRow.status.in_(["active", "paused", "disabled_bad_token"]),
            BotRow.archived_at.is_(None)))).all()
    if not bots:
        await cb.message.edit_text(
            "هیچ ربات (غیرِ آرشیوشده‌ای) پیدا نشد.",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [hx_button("⬅️ بازگشت", callback_data="adm:health", style=ButtonStyle.DANGER)]]))
        return
    ok, fail = await _do_reconnect(bot, bots)
    kb_rows = []
    if fail:
        kb_rows.append([hx_button("🔄 دوباره امتحانِ ناموفق‌ها",
                                             callback_data="adm:health_full_all", style=ButtonStyle.SUCCESS)])
    kb_rows.append([hx_button("⬅️ بازگشت به مرکز سلامت", callback_data="adm:health", style=ButtonStyle.DANGER)])
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    await cb.message.edit_text(
        _reconnect_report(ok, fail, f"🚀 نتیجهٔ بررسی و فعال‌سازیِ کاملِ همهٔ {len(bots)} ربات"),
        reply_markup=kb)


