@router.callback_query(F.data == "adm:health_disable_bad")
async def adm_health_disable_bad(cb: CallbackQuery):
    """بررسی مجدد و غیرفعال‌سازی ربات‌های با توکن نامعتبر (پس از اسکن کامل)."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer()
        return
    await cb.answer("در حال بررسی…")
    await cb.message.edit_text("⏳ در حال بررسی و غیرفعال‌سازی توکن‌های نامعتبر…")
    async with Session() as s:
        bots = (await s.scalars(
            select(BotRow).where(BotRow.status == "active")
            .order_by(BotRow.id))).all()
    import asyncio as _aio3
    bad = []

    async def _chk_tok(b):
        tb = Bot(b.token)
        try:
            await _aio3.wait_for(tb.get_me(), timeout=8)
        except Exception as e:
            # === PATCH_BOT_SELFHEAL_V1 === یک 401 لحظه‌ای نباید ربات را خاموش کند: دوباره بپرس
            _really_bad = "unauthorized" in str(e).lower()
            if _really_bad:
                await _aio3.sleep(4)
                try:
                    await _aio3.wait_for(Bot(b.token).get_me(), timeout=8)
                    _really_bad = False
                except Exception as e2:
                    _really_bad = "unauthorized" in str(e2).lower()
            if _really_bad:
                bad.append((int(b.id), b.username))
                async with Session() as s:
                    br = await s.get(BotRow, b.id)
                    if br:
                        br.status = "disabled_bad_token"
                        await s.commit()
        try:
            await tb.session.close()
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    for i in range(0, len(bots), 15):
        await _aio3.gather(*[_chk_tok(b) for b in bots[i:i+15]])
    kb_rows = []
    if bad:
        _PENDING_PURGE_BAD[cb.from_user.id] = [bid for bid, _u in bad]
        for bid, uname in bad:
            label = f"🗑 حذف @{uname}" if uname else f"🗑 حذف ربات #{bid}"
            kb_rows.append([hx_button(label, callback_data=f"adm:health_purge_one:{bid}", style=ButtonStyle.PRIMARY)])
        kb_rows.append([hx_button("🗑 حذف همه", callback_data="adm:health_purge_bad", style=ButtonStyle.DANGER)])
    kb_rows.append([hx_button("⬅️ بازگشت", callback_data="adm:health", style=ButtonStyle.DANGER)])
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    if bad:
        lines = [f"• @{u or bid} (ID:{bid})" for bid, u in bad]
        await cb.message.edit_text(
            f"❌ <b>ربات‌های با توکن نامعتبر ({len(bad)})</b>\n\n"
            + "\n".join(lines) + "\n\n"
            "⚠️ این ربات‌ها غیرفعال شدند تا مشکل ایجاد نکنند.\n"
            "می‌توانید هرکدام را تکی حذف کنید یا همه را با هم پاک کنید.",
            reply_markup=kb)
    else:
        await cb.message.edit_text(
            "✅ <b>همه توکن‌ها معتبرند!</b>",
            reply_markup=kb)


# نگهداری موقت لیست ربات‌های آماده حذف دسته‌جمعی (کلید: آیدی ادمین)
_PENDING_PURGE_BAD: dict[int, list[int]] = {}


async def _do_purge_one(bot_id: int) -> tuple[bool, str | None]:
    """حذف کامل یک ربات به همراه وب‌هوکش. (موفق بود؟, پیام خطا در صورت شکست)."""
    import asyncio as _aio_purge
    import traceback as _tb_purge
    try:
        token = await _aio_purge.wait_for(purge_bot(bot_id), timeout=20)
    except _aio_purge.TimeoutError:
        print(f"_do_purge_one: timeout deleting bot {bot_id}")
        return False, "حذف از دیتابیس بیش از حد طول کشید (timeout)"
    except Exception as e:
        print(f"_do_purge_one: error deleting bot {bot_id}:")
        _tb_purge.print_exc()
        return False, str(e)
    if not token:
        return False, "ربات یافت نشد (شاید قبلاً حذف شده)"
    try:
        tb = Bot(token=token)
        await _aio_purge.wait_for(tb.delete_webhook(), timeout=8)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    finally:
        try:
            await tb.session.close()
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    return True, None


