@router.callback_query(F.data.startswith("adm:health_purge_one_yes:"))
async def adm_health_purge_one_yes(cb: CallbackQuery, bot: Bot):
    """اجرای حذف تکی یک ربات پس از تاییدیه."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer()
        return
    bot_id = int(cb.data.split(":")[2])
    await cb.answer("در حال حذف…")
    ok, err = await _do_purge_one(bot_id)
    pending = _PENDING_PURGE_BAD.get(cb.from_user.id)
    if pending and bot_id in pending:
        pending.remove(bot_id)
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("⬅️ بازگشت", callback_data="adm:health", style=ButtonStyle.DANGER)]])
    if ok:
        text = f"🗑 ربات #{bot_id} حذف شد."
    else:
        import html as _html
        err_safe = _html.escape(str(err))[:500]
        text = f"⚠️ حذف ربات #{bot_id} با خطا مواجه شد:\n<code>{err_safe}</code>"
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        # اگر HTML خطا داشت یا متن خیلی طولانی بود، بدون فرمت بفرست
        try:
            await cb.message.edit_text(
                text.replace("<code>", "").replace("</code>", ""), reply_markup=kb)
        except Exception as e2:
            await bot.send_message(cb.from_user.id, f"نتیجه حذف #{bot_id}:\n{text}\n\n(خطای نمایش: {e2})")


