    """اتصال مجدد همه ربات‌های مشکل‌دار (paused + bad_token)."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer(); return
    await cb.answer("⏳ در حال اتصال مجدد…")
    await cb.message.edit_text("⏳ <b>اتصال مجدد در حال انجام…</b>\nلطفاً صبر کنید.")
    async with Session() as s:
        bots = (await s.scalars(select(BotRow).where(
            BotRow.status.in_(["paused", "disabled_bad_token"]),
            BotRow.archived_at.is_(None)))).all()
    if not bots:
        await cb.message.edit_text("✅ ربات مشکل‌داری یافت نشد.",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [hx_button("⬅️ بازگشت", callback_data="adm:health_reconnect", style=ButtonStyle.DANGER)]]))
        return
    ok, fail = await _do_reconnect(bot, bots)
    kb_rows = []
    if fail:
        kb_rows.append([hx_button("🔄 دوباره امتحان ناموفق‌ها", callback_data="adm:hrc_all", style=ButtonStyle.SUCCESS)])
    kb_rows.append([hx_button("⬅️ بازگشت", callback_data="adm:health_reconnect", style=ButtonStyle.DANGER)])
    kb = InlineKeyboardMarkup(inline_keyboard=kb_rows)
    await cb.message.edit_text(_reconnect_report(ok, fail), reply_markup=kb)


