@router.callback_query(F.data == "adm:update_mode")
async def adm_update_mode(cb: CallbackQuery, bot: Bot):
    global _UPDATE_MODE
    if not is_admin(cb.from_user.id):
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    _UPDATE_MODE = not _UPDATE_MODE
    if _UPDATE_MODE:
        await cb.answer("🔧 حالت آپدیت فعال شد", show_alert=True)
        try:
            await bot.set_my_description("🔧 ربات بات‌ساز در حال آپدیت و بهبود است. به‌زودی برمی‌گردیم! ⏳")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    else:
        await cb.answer("✅ ربات به حالت عادی برگشت", show_alert=True)
        try:
            await bot.set_my_description("🤖 بات‌ساز — ربات خودت رو بساز!")
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await adm_back(cb)


# میدل‌ور حالت آپدیت: قبل از همهٔ هندلرها اجرا می‌شود و فقط در حالت آپدیت
# کاربران غیرادمین را متوقف می‌کند (بدون بلعیدن پیام بقیهٔ هندلرها).
@router.message.outer_middleware
async def update_mode_mw(handler, event, data):
    if _UPDATE_MODE and getattr(event, "from_user", None) and not is_admin(event.from_user.id):
        await event.answer(
            "🔧 <b>ربات بات‌ساز در حال آپدیت است</b>\n\n"
            "⏳ به‌زودی با امکانات جدید برمی‌گردیم!\nلطفاً کمی صبور باشید. 🙏"
        )
        return
    return await handler(event, data)


