async def _ptc_admin_text() -> str:
    enabled = await ptc_is_enabled()
    mode, amt = await ptc_settings()
    mode_fa = "درصدی" if mode == "percent" else "مبلغ ثابت"
    amt_fa = f"{amt}٪" if mode == "percent" else rial(amt)
    rank_mode = await ptc_rank_enabled_flag()
    ranking = await ptc_ranking(PTC_DISCOUNT_N)
    lines = [
        "🏆 <b>تنظیمات نفرات برتر بات‌ساز</b>\n",
        f"وضعیت: {'🟢 فعال' if enabled else '🔴 غیرفعال'}",
        f"نوع تخفیف: {mode_fa}",
        f"مقدار تخفیف {PTC_DISCOUNT_N} نفر برتر: {amt_fa}",
        f"بازهٔ محاسبه: {PTC_WINDOW_DAYS} روز اخیر",
        f"حالت تخفیف بر اساس رتبه: {'🟢 فعال' if rank_mode else '🔴 غیرفعال'}\n",
    ]
    if rank_mode:
        lines.append("⚠️ چون حالت رتبه‌ای فعال است، تخفیف بالا نادیده گرفته می‌شود و "
                     "درصد اختصاصی هر رتبه (بخش «🏅 تخفیف بر اساس رتبه») اعمال می‌شود.\n")
    if ranking:
        lines.append(f"👑 {PTC_DISCOUNT_N} نفر برتر فعلی:")
        for i, (tg_id, total) in enumerate(ranking, start=1):
            name = await _ptc_name(tg_id)
            lines.append(f"{_PTC_MEDALS.get(i, f'{i}.')} {name} — {rial(total)}")
    else:
        lines.append("هنوز خریدی در این بازه ثبت نشده.")
    return "\n".join(lines)


def _ptc_admin_kb(mode: str, enabled: bool) -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(inline_keyboard=[
        [hx_button(("⛔️ غیرفعال‌سازی" if enabled else "✅ فعال‌سازی"),
            callback_data="ptc:toggle",
            style=(ButtonStyle.DANGER if enabled else ButtonStyle.SUCCESS))],
        [hx_button(("🔘 درصدی" if mode != "percent" else "✅ درصدی"),
                              callback_data="ptc:mode:percent"),
         hx_button(("🔘 مبلغ ثابت" if mode != "flat" else "✅ مبلغ ثابت"),
                              callback_data="ptc:mode:flat")],
        [hx_button("🏅 تخفیف بر اساس رتبه (۱ تا ۵)", callback_data="ptc:ranks")],
        [hx_button("⬅️ بازگشت به پنل", callback_data="adm:back", style=ButtonStyle.DANGER)],
    ])


@router.callback_query(F.data == "adm:ptc")
async def adm_ptc(cb: CallbackQuery, state: FSMContext):
    if not (cb.from_user.id == PLATFORM_ADMIN_ID or await has_perm(cb.from_user.id, "adm:stats")):
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    await state.clear()
    mode, _amt = await ptc_settings()
    enabled = await ptc_is_enabled()
    try:
        await cb.message.edit_text(await _ptc_admin_text(), reply_markup=_ptc_admin_kb(mode, enabled))
    except Exception:
        await cb.message.answer(await _ptc_admin_text(), reply_markup=_ptc_admin_kb(mode, enabled))
    await cb.answer()


@router.callback_query(F.data == "ptc:toggle")
async def ptc_toggle(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    enabled = await ptc_is_enabled()
    await set_pset("ptc_enabled", "off" if enabled else "on")
    mode, _amt = await ptc_settings()
    await cb.message.edit_text(await _ptc_admin_text(), reply_markup=_ptc_admin_kb(mode, not enabled))
    await cb.answer("انجام شد")


@router.callback_query(F.data.startswith("ptc:mode:"))
async def ptc_mode_set(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    mode = cb.data.split(":")[2]
