    tog = "🔴 غیرفعال کردن حالت رتبه‌ای" if enabled else "🟢 فعال کردن حالت رتبه‌ای"
    rows = [[hx_button(tog, callback_data="ptc:rank_toggle")]]
    for n in range(1, PTC_DISCOUNT_N + 1):
        medal = _PTC_MEDALS.get(n, f"{n}.")
        rows.append([hx_button(f"{medal} رتبهٔ {n}: {percents[n - 1]}٪", callback_data=f"ptc:rank:{n}")])
    rows.append([hx_button("⬅️ بازگشت", callback_data="adm:ptc", style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


