@router.callback_query(F.data.startswith("ptc:rank:"))
async def ptc_rank_start(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    n = int(cb.data.split(":")[2])
    await state.set_state(SettingsFSM.ptc_rank_amt)
    await state.update_data(ptc_rank_n=n)
    await cb.message.answer(f"🏅 درصد تخفیف رتبهٔ {n} را بفرست (عددی بین 0 تا 90):",
                            reply_markup=await smart_cancel_kb())
    await cb.answer()


@router.message(SettingsFSM.ptc_rank_amt, F.text)
async def ptc_rank_save(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    raw = (msg.text or "").strip()
    if raw == BTN_CANCEL:
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    n = fa_to_int(raw)
    if n is None or n < 0 or n > 90:
        await msg.answer("عدد نامعتبر است. یک عدد بین 0 تا 90 بفرست:")
        return
    data = await state.get_data()
    rank_n = data.get("ptc_rank_n", 1)
    await state.clear()
    await set_pset(f"ptc_rank_{rank_n}_percent", str(n))
    await msg.answer("✅ درصد تخفیف این رتبه بروزرسانی شد.",
                     reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
    enabled = await ptc_rank_enabled_flag()
    percents = [await ptc_rank_percent(k) for k in range(1, PTC_DISCOUNT_N + 1)]
    await msg.answer(await _ptc_ranks_text(), reply_markup=_ptc_ranks_kb(enabled, percents))


