async def _settings_text() -> str:
    paid = plans_paid_enabled()
    cdown = plans_countdown_text()
    wallet_on = (await get_pset("pwallet_enabled", "on")) != "off"
    miniapp_on = (await get_pset("miniapp_feature_enabled", "on")) != "off"
    selfsaz_admin_only = (await get_pset("hbtn:self_saz:admin_only", "off")) == "on"
    txt = ("⚙️ <b>تنظیمات پلتفرم</b>\n\n"
           f"📦 وضعیت پلن‌ها: {'💰 پولی' if paid else '🎁 رایگان (تست)'}")
    if cdown:
        txt += f"\n⏳ پولی‌شدن خودکار: {cdown} دیگر ({to_jalali(plans_paid_at())})"
    txt += f"\n💰 کیف پول کاربران: {'✅ فعال' if wallet_on else '❌ غیرفعال'}"
    txt += f"\n🛍 مینی‌اپ فروشگاهی (مستأجرها): {'✅ فعال' if miniapp_on else '❌ غیرفعال'}"
    txt += "\n\nیک بخش را انتخاب کن 👇"
    return txt


