@router.message(SettingsFSM.selfsaz_price, F.text)
async def selfsaz_price_save(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    raw = (msg.text or "").strip()
    if raw in ("لغو", BTN_CANCEL):
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    value = fa_to_int(raw)
    if value is None or value < 0 or value > 1_000_000_000:
        await msg.answer("⚠️ قیمت نامعتبر است. عددی بین صفر تا یک میلیارد تومان بفرستید:")
        return
    from platform_selfsaz import selfsaz_api
    result = await selfsaz_api("PUT", "/v1/config/price", {"price": value})
    if not result:
        await state.clear()
        await msg.answer("❌ ذخیرهٔ قیمت انجام نشد؛ سرویس سلف‌ساز در دسترس نیست.")
        return
    await state.clear()
    await msg.answer("✅ قیمت اشتراک سلف‌ساز ذخیره شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
    await msg.answer(await _selfsaz_admin_text(), reply_markup=await _selfsaz_admin_kb())

async def _selfsaz_account_row(account: dict) -> list:
    account_id = int(account.get("id", 0) or 0)
    state = "🟢 فعال" if account.get("enabled") else "🔴 غیرفعال"
    status = _html.escape(str(account.get("status") or "نامشخص"))
    price = int(account.get("price", 0) or 0)
    expires = _html.escape(str(account.get("expires_at") or "بدون انقضا"))
    return [
        f"• حساب <code>{account_id}</code> — {state} — {status} — {price:,} تومان",
        f"  انقضا: <code>{expires}</code>",
    ]

@router.callback_query(F.data == "set:selfsaz_accounts")
async def selfsaz_accounts_panel(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    _config, accounts = await _selfsaz_admin_data()
    if not accounts:
        body = "👥 <b>حساب‌های سلف‌ساز</b>\n\nهنوز حسابی ثبت نشده است."
        rows = []
    else:
        lines = ["👥 <b>حساب‌های سلف‌ساز</b>", ""]
        rows = []
        for account in accounts[:50]:
            lines.extend(await _selfsaz_account_row(account))
            account_id = int(account.get("id", 0) or 0)
            if account_id:
                rows.append([hx_button(f"📊 جزئیات حساب {account_id}", callback_data=f"set:selfsaz_account:{account_id}")])
        body = "\n".join(lines)
    rows.extend([
        [hx_button("🔄 بروزرسانی فهرست", callback_data="set:selfsaz_accounts")],
        [hx_button("⬅️ مدیریت سلف‌ساز", callback_data="set:selfsaz_admin", style=ButtonStyle.DANGER)],
    ])
    await _selfsaz_safe_edit(cb, body, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
    await cb.answer()

async def _selfsaz_find_account(account_id: int) -> dict | None:
    _config, accounts = await _selfsaz_admin_data()
    for account in accounts:
        try:
            if int(account.get("id", 0)) == account_id:
                return account
        except (TypeError, ValueError):
            continue
    return None

@router.callback_query(F.data.regexp(r"^set:selfsaz_account:\d+$"))
async def selfsaz_account_detail(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    account_id = int(cb.data.rsplit(":", 1)[1])
    account = await _selfsaz_find_account(account_id)
    if not account:
        await cb.answer("حساب پیدا نشد", show_alert=True)
        return
    owner_id = int(account.get("owner_id", 0) or 0)
    from platform_selfsaz import selfsaz_api
    runtime = await selfsaz_api("GET", f"/v1/accounts/{owner_id}/runtime-status") if owner_id else None
    worker_alive = bool(runtime and runtime.get("worker_alive"))
    control = runtime.get("control") if runtime else {}
    status = _html.escape(str(account.get("status") or "نامشخص"))
    error = _html.escape(str(account.get("last_error") or "بدون خطا"))
    expires = _html.escape(str(account.get("expires_at") or "بدون انقضا"))
    text = (
        f"📊 <b>جزئیات حساب سلف‌ساز {account_id}</b>\n\n"
        f"مالک: <code>{owner_id}</code>\n"
        f"وضعیت حساب: {'🟢 فعال' if account.get('enabled') else '🔴 غیرفعال'}\n"
        f"وضعیت سرویس: <b>{status}</b>\n"
        f"وضعیت worker: {'🟢 در حال اجرا' if worker_alive else '🔴 متوقف/نامشخص'}\n"
        f"قیمت: <b>{int(account.get('price', 0) or 0):,} تومان</b>\n"
        f"انقضا: <code>{expires}</code>\n"
        f"آخرین خطا: <code>{error[:300]}</code>\n"
        f"کنترل‌های ذخیره‌شده: {'✅ موجود' if control else '—'}"
    )
    enabled = bool(account.get("enabled"))
    rows = [
        [hx_button("🔄 بروزرسانی وضعیت", callback_data=f"set:selfsaz_account:{account_id}")],
        [hx_button("⏹ غیرفعال‌کردن حساب" if enabled else "▶️ فعال‌کردن حساب", callback_data=f"set:selfsaz_account_confirm_toggle:{account_id}", style=ButtonStyle.DANGER if enabled else ButtonStyle.SUCCESS)],
        [hx_button("🔁 راه‌اندازی مجدد worker", callback_data=f"set:selfsaz_account_confirm_restart:{account_id}")],
        [hx_button("⬅️ فهرست حساب‌ها", callback_data="set:selfsaz_accounts", style=ButtonStyle.PRIMARY)],
    ]
    await _selfsaz_safe_edit(cb, text, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
    await cb.answer()

