@router.callback_query(F.data.startswith("set:selfsaz_brand:"))
async def selfsaz_branding_edit_start(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    key = cb.data.rsplit(":", 1)[1]
    prompts = {
        "name": (SelfsazBrandFSM.name, "نام نمایشی جدید سلف‌ساز را بفرستید (حداکثر ۶۴ نویسه):"),
        "title": (SelfsazBrandFSM.title, "عنوان جدید پنل را بفرستید (حداکثر ۱۲۰ نویسه):"),
        "caption": (SelfsazBrandFSM.caption, "متن جدید پنل را بفرستید (حداکثر ۷۰۰ نویسه؛ /default برای پیش‌فرض):"),
        "image": (SelfsazBrandFSM.image, "تصویر جدید پنل را به‌صورت عکس ارسال کنید؛ برای لغو «لغو» بنویسید:"),
    }
    if key == "clear_image":
        await set_pset("selfsaz:panel_image_file_id", "")
        await _selfsaz_safe_edit(cb, await _selfsaz_branding_text(), reply_markup=await _selfsaz_branding_kb())
        await cb.answer("✅ تصویر پنل حذف شد")
        return
    item = prompts.get(key)
    if not item:
        await cb.answer("گزینه نامعتبر است", show_alert=True)
        return
    await state.set_state(item[0])
    await cb.message.answer(item[1], reply_markup=InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("🔴 لغو", callback_data="set:selfsaz_branding", style=ButtonStyle.DANGER)],
    ]))
    await cb.answer()

async def _selfsaz_branding_finish(msg: Message, state: FSMContext, key: str, value: str):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    value = value.strip()
    limits = {"name": 64, "title": 120, "caption": 700}
    if value == "/default" and key == "caption":
        value = "پنل مدیریت حساب و قابلیت‌های سلف‌ساز"
    if not value or len(value) > limits[key]:
        await msg.answer(f"⚠️ مقدار نامعتبر است؛ مقدار باید بین ۱ تا {limits[key]} نویسه باشد.")
        return
    await set_pset(f"selfsaz:brand_{key}", value)
    await state.clear()
    await msg.answer("✅ تنظیم برندینگ ذخیره شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
    await msg.answer(await _selfsaz_branding_text(), reply_markup=await _selfsaz_branding_kb())

