@router.callback_query(F.data == "set:toggle_miniapp_feature")
async def set_toggle_miniapp_feature(cb: CallbackQuery):
    """سوییچِ سراسریِ قابلیتِ مینی‌اپ: وقتی خاموشه، هیچ مستأجری (حتی اگه
    قبلاً برای خودش روشنش کرده باشه) نمی‌تونه مینی‌اپش رو ببینه یا روشن کنه.
    وقتی روشن می‌کنی، گزینهٔ روشن‌کردنِ مینی‌اپ به همهٔ مستأجرها (تو ربات
    خودشون، دستور /miniapp) نمایش داده و قابل‌استفاده می‌شه."""
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    cur_on = (await get_pset("miniapp_feature_enabled", "on")) != "off"
    new_on = not cur_on
    await set_pset("miniapp_feature_enabled", "on" if new_on else "off")
    await cb.message.edit_text(await _settings_text(), reply_markup=await settings_kb())
    await cb.answer("مینی‌اپ برای همهٔ مستأجرها روشن شد ✅" if new_on else "مینی‌اپ برای همهٔ مستأجرها خاموش شد ❌",
                     show_alert=True)


