async def _pay_hub_text() -> str:
    card = await get_pset("platform_card", "")
    holder = await get_pset("card_holder", "")
    addr_map = await _platform_swap_addr_map()
    swap_ok = bool(await get_pset("swap_api_key", "")) and any(addr_map.values())
    nowpay_key = await get_pset("platform_nowpay_api_key", "")
    nowpay_status = "✅ تنظیم‌شده" if nowpay_key else "❌ تنظیم‌نشده"
    zarinpal_mid = await get_pset("platform_zarinpal_merchant_id", "")
    zarinpal_status = "✅ تنظیم‌شده" if zarinpal_mid else "❌ تنظیم‌نشده"
    auto_ap = (await get_pset("platform_auto_approve", "off")) == "on"
    # === PATCH_SECOND_CARD_ROTATE_V1 ===
    _card2 = await get_pset("platform_card2", "")
    _card2_line = f"💳 کارت دوم: <code>{_card2}</code> (چرخشی)\n" if _card2 else ""
    return ("💳 <b>پرداخت و کیف پول</b>\n\n"
            f"💳 کارت: <code>{card or '—'}</code>\n"
            f"{_card2_line}"
            f"🧑 صاحب کارت: {holder or '—'}\n"
            f"🤖 تأیید خودکار رسید: {'✅ فعال' if auto_ap else '❌ غیرفعال'}\n"
            f"🏦 زرین‌پال: {zarinpal_status}\n"
            f"🪙 NOWPayments: {nowpay_status}\n"
            f"🟦 سواپ‌ولت: {'✅ تنظیم‌شده' if swap_ok else '❌ تنظیم‌نشده'}\n\n"
            "کیف پول را غیرفعال کنی، دکمهٔ «💰 کیف پول» برای کاربران از کار می‌افتد.")


