# ═══════════════════════════════════════════
#  تجربهٔ ورودِ حرفه‌ای — قوانین + خوش‌آمدگوییِ تایپ‌شونده
#  === PATCH_PLATFORM_ONBOARDING_V1 ===
# ═══════════════════════════════════════════
# پورتِ همان قابلیتِ tenant/smm.py (PATCH_VS_ONBOARDING_V1) برایِ خودِ
# ربات اصلیِ بات‌ساز — عمداً این‌جا (نه importشده از tenant) نوشته شده،
# چون تنانت و پلتفرم دو پروسسِ جدا هستند (architecture.md، «هرگز
# سرویس‌ها را جفت نکن»)؛ importِ tenant/smm.py یعنی اجرایِ کاملِ
# tenant/__init__.py داخلِ پروسسِ platform_bot.py. تنظیمات با
# get_pset/set_pset (سطحِ پلتفرم، نه هر ربات) ذخیره می‌شود.

class OnboardingFSM(StatesGroup):
    rules_text = State()
    welcome_text = State()


async def _pvso_content() -> tuple[str, InlineKeyboardMarkup]:
    rules_required = (await get_pset("pvso_rules_required", "0")) == "1"
    rules_text = await get_pset("pvso_rules_text", "")
    welcome_text = await get_pset("pvso_welcome_text", "")
    typewriter_on = (await get_pset("pvso_typewriter_enabled", "1")) == "1"

    lines = [
        "🎓 <b>تجربهٔ ورودِ حرفه‌ای</b>\n",
        "همان چیزی که برایِ ربات‌هایِ مستأجر ساختیم، برایِ خودِ ربات اصلیِ "
        "بات‌ساز: اول قوانین را پین می‌کند و می‌گیرد کاربر تاییدشان کند، "
        "بعد یک خوش‌آمدگوییِ زیبا را جلویِ چشمش «تایپ می‌کند».\n",
        f"وضعیتِ قوانین: {'✅ اجباری است' if rules_required else '❌ خاموش'}",
        f"متنِ قوانین: {'تنظیم‌شده ✅' if rules_text else 'هنوز تنظیم نشده ❌'}",
        f"خوش‌آمدگوییِ تایپ‌شونده: {'✅ روشن' if typewriter_on else '❌ خاموش (یک‌جا نمایش داده می‌شود)'}",
        f"متنِ خوش‌آمد: {'تنظیم‌شده ✅' if welcome_text else 'هنوز تنظیم نشده — پیامِ خوش‌آمدِ معمولیِ ربات استفاده می‌شود'}",
    ]
    rows = [
        [hx_button(
            ("🔴 خاموش‌کردنِ اجباریِ قوانین" if rules_required else "🟢 اجباری‌کردنِ تاییدِ قوانین"),
            callback_data="pvso:togrules",
            style=(ButtonStyle.DANGER if rules_required else ButtonStyle.SUCCESS))],
        [hx_button("✏️ ویرایشِ متنِ قوانین", callback_data="pvso:setrules")],
        [hx_button(
            ("🔴 خاموش‌کردنِ جلوهٔ تایپ‌شونده" if typewriter_on else "🟢 روشن‌کردنِ جلوهٔ تایپ‌شونده"),
            callback_data="pvso:togtype",
            style=(ButtonStyle.DANGER if typewriter_on else ButtonStyle.SUCCESS))],
        [hx_button("✏️ ویرایشِ متنِ خوش‌آمد", callback_data="pvso:setwelcome")],
        [hx_button("🔍 پیش‌نمایشِ تجربهٔ ورود", callback_data="pvso:preview")],
        [hx_button("⬅️ بازگشت", callback_data="adm:settings", style=ButtonStyle.DANGER)],
    ]
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)


@router.callback_query(F.data == "pvso:menu")
async def pvso_menu(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    text, kb = await _pvso_content()
    try:
        await cb.message.edit_text(text, reply_markup=kb, parse_mode="HTML")
    except Exception:
        await cb.message.answer(text, reply_markup=kb, parse_mode="HTML")
    await cb.answer()


@router.callback_query(F.data == "pvso:togrules")
async def pvso_toggle_rules(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    cur = (await get_pset("pvso_rules_required", "0")) == "1"
    if not cur:
        rules_text = await get_pset("pvso_rules_text", "")
        if not rules_text:
            await cb.answer("❌ اول باید متنِ قوانین را بنویسی.", show_alert=True)
            return
    await set_pset("pvso_rules_required", "0" if cur else "1")
    text, kb = await _pvso_content()
    await cb.message.edit_text(text, reply_markup=kb, parse_mode="HTML")
    await cb.answer("✅ روشن شد" if not cur else "خاموش شد")


@router.callback_query(F.data == "pvso:togtype")
async def pvso_toggle_typewriter(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    cur = (await get_pset("pvso_typewriter_enabled", "1")) == "1"
    await set_pset("pvso_typewriter_enabled", "0" if cur else "1")
    text, kb = await _pvso_content()
    await cb.message.edit_text(text, reply_markup=kb, parse_mode="HTML")
