async def _pvso_show_rules_gate(msg: Message, bot: Bot) -> bool:
    """اگر قوانین اجباری باشد، پیامِ قوانین را نشان (و پین) می‌کند و True
    برمی‌گرداند (یعنی start باید همین‌جا return کند)."""
    rules_required = (await get_pset("pvso_rules_required", "0")) == "1"
    if not rules_required:
        return False
    rules_text = await get_pset("pvso_rules_text", "")
    if not rules_text:
        return False
    kb = InlineKeyboardMarkup(inline_keyboard=[[hx_button(
        "✅ تایید قوانین", callback_data="pvso:accept", style=ButtonStyle.SUCCESS)]])
    sent = await msg.answer(f"📖 <b>قوانینِ استفاده از ربات</b>\n\n{rules_text}",
                            reply_markup=kb, parse_mode="HTML")
    try:
        await bot.pin_chat_message(msg.chat.id, sent.message_id, disable_notification=True)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده هنگامِ پین‌کردنِ قوانین")
    return True


@router.callback_query(F.data == "pvso:accept")
async def pvso_accept_rules(cb: CallbackQuery, bot: Bot):
    async with Session() as s:
        await get_user(s, cb.from_user.id, cb.from_user.full_name, username=cb.from_user.username)
        await s.commit()
        u = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == cb.from_user.id))
        u.rules_accepted = True
        u.rules_accepted_at = datetime.datetime.now()
        await s.commit()
    await cb.answer("✅ قوانین تایید شد")
    try:
        # === PATCH_UNPIN_CHAT_MESSAGE_KWARG_FIX_V1 ===
        # aiogram 3.29.1 ترتیبِ پارامترهای unpin_chat_message رو عوض کرده
        # (پارامترِ دوم الان business_connection_id هست، نه message_id)؛
        # با کیورد صدا می‌زنیم تا مستقل از ترتیب درست کار کنه.
        await bot.unpin_chat_message(cb.message.chat.id, message_id=cb.message.message_id)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده هنگامِ آنپین‌کردنِ قوانین")
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده هنگامِ پاک‌کردنِ دکمهٔ «تایید قوانین»")

    welcome_text = await get_pset("pvso_welcome_text", "")
    custom = welcome_text or await get_pset("welcome_msg", "")
    if not custom:
        first_name = cb.from_user.first_name or cb.from_user.full_name or "دوست عزیز"
        custom = (
            f"✨ درود <b>{first_name}</b> عزیز! ✨\n\n"
            f"🎉 به ربات <b>بات‌ساز</b> خوش اومدی!\n\n"
            f"از منوی زیر شروع کن 👇")
    else:
        custom = apply_welcome_placeholders(custom, cb.from_user)
    typewriter_on = (await get_pset("pvso_typewriter_enabled", "1")) == "1"
    await _pvso_play_typewriter(cb.message, custom, typewriter_on)

    async with Session() as s:
        sa = await get_sub_admin(s, cb.from_user.id)
    show_admin = sa is not None
    _is_private = getattr(cb.message.chat, "type", "private") == "private"
    if await get_pset("home_menu_mode", "reply") == "inline":
        await cb.message.answer("🏠 منوی اصلی:", reply_markup=home_inline_kb(cb.from_user.id, show_admin))
    else:
        await cb.message.answer("🏠 منوی اصلی:", reply_markup=await smart_home_kb(
            cb.from_user.id, show_admin=show_admin, private=_is_private))


