# === PATCH_WELCOME_TYPEWRITER_SMOOTH_V1 ===
def _platform_plain_word_progress(text: str, word_limit: int) -> str:
    """برای فریم‌های میانی، قالب HTML را حذف می‌کند تا هیچ tag ناقصی دیده نشود.
    (دیگر در typewriter اصلی استفاده نمی‌شود — نگه‌داشته شده برای سازگاری
    اگر جایِ دیگری اضافه شود.)"""
    import html as _html
    import re as _re
    plain = _html.unescape(_re.sub(r"<[^>]*>", "", text))
    tokens = _re.findall(r"\S+|\s+", plain, _re.DOTALL)
    out, words = [], 0
    for tok in tokens:
        if tok.isspace():
            if words:
                out.append(tok)
            continue
        if words >= word_limit:
            break
        out.append(tok)
        words += 1
    return "".join(out).rstrip()


def _platform_plain_char_progress(plain: str, char_limit: int) -> str:
    """فریمِ میانیِ کاراکتر-به-کاراکتر (روی متنِ بدونِ تگ)."""
    return plain[:char_limit]


async def _pvso_play_typewriter(target: Message, text: str, enabled: bool = True,
                                chunk: int = 1, delay: float = 0.15) -> Message:
    # === PATCH_WELCOME_TYPEWRITER_FIX_V2: تأخیر از ۰.۰۶ به ۰.۱۵ افزایش یافت تا تلگرام همهٔ فریم‌ها را بپذیرد ===
    """نمایشِ نرمِ کاراکتر-به-کاراکتر (شبیهِ تایپِ واقعی)؛ قالبِ کاملِ HTML
    فقط در فریمِ پایانی اعمال می‌شود تا هیچ tag ناقصی دیده نشود."""
    import asyncio as _asyncio
    import html as _html
    import math as _math
    import re as _re
    if not enabled:
        return await target.answer(text, parse_mode="HTML")
    plain = _html.unescape(_re.sub(r"<[^>]*>", "", text)).rstrip()
    total = len(plain)
    if total <= 6:
        return await target.answer(text, parse_mode="HTML")
    max_frames = 35  # سقفِ تعدادِ ادیت‌ها تا رویِ متن‌هایِ بلند به فلادِ تلگرام نخوریم
    step = max(1, _math.ceil(total / max_frames))
    msg = await target.answer("…")
    try:
        i = 0
        while i < total:
            i = min(total, i + step)
            preview = _platform_plain_char_progress(plain, i)
            try:
                await msg.edit_text(preview)
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (ادیتِ کاراکتری Platform)")
            await _asyncio.sleep(delay)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده در typewriter کاراکتری Platform")
    try:
        await msg.edit_text(text, parse_mode="HTML")
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (ادیتِ نهاییِ typewriter Platform)")
    return msg


