_ANTISPAM_PAGE_SIZE = 15


async def _render_banlist(cb: CallbackQuery, offset: int):
    async with Session() as s:
        total = await s.scalar(
            select(func.count()).select_from(PlatformUser).where(PlatformUser.is_banned == True)) or 0
        rows = (await s.scalars(
            select(PlatformUser).where(PlatformUser.is_banned == True)
            .order_by(PlatformUser.id).offset(offset).limit(_ANTISPAM_PAGE_SIZE))).all()

    if not rows:
        text = "🚫 <b>نفراتِ بن‌شده</b>\n\nهیچ کاربرِ بن‌شده‌ای وجود ندارد. ✅"
    else:
        lines = [f"🚫 <b>نفراتِ بن‌شده</b> ({total} نفر)\n"]
        for u in rows:
            lines.append(f"• <code>{u.telegram_id}</code> — {u.full_name or '—'} "
                        f"(اخطار: {u.spam_warnings or 0})")
        text = "\n".join(lines)

    btn_rows = [[hx_button(f"✅ آنبن {u.telegram_id}", callback_data=f"as:unban:{u.telegram_id}:{offset}")]
                for u in rows]
    nav_row = []
    if offset > 0:
        nav_row.append(hx_button("⬅️ قبلی",
                                            callback_data=f"as:banlist:{max(0, offset - _ANTISPAM_PAGE_SIZE)}"))
    if offset + _ANTISPAM_PAGE_SIZE < total:
        nav_row.append(hx_button("بعدی ➡️",
                                            callback_data=f"as:banlist:{offset + _ANTISPAM_PAGE_SIZE}"))
    if nav_row:
        btn_rows.append(nav_row)
    btn_rows.append([hx_button("⬅️ بازگشت", callback_data="set:antispam", style=ButtonStyle.DANGER)])

    try:
        await cb.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=btn_rows))
    except Exception:
        await cb.message.answer(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=btn_rows))


@router.callback_query(F.data.startswith("as:banlist:"))
async def antispam_banlist(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    offset = int(cb.data.split(":")[2])
    await _render_banlist(cb, offset)
    await cb.answer()


@router.callback_query(F.data.startswith("as:unban:"))
async def antispam_unban(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    parts = cb.data.split(":")
    target_uid = int(parts[2])
    offset = int(parts[3]) if len(parts) > 3 else 0
    async with Session() as s:
        u = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == target_uid))
        if u:
            u.is_banned = False
            u.spam_warnings = 0
            await s.commit()
    await cb.answer("✅ آنبن شد")
    await _render_banlist(cb, offset)


