# ── کنترل محدودیت (سقف) ساخت ربات به‌ازای هر پلن ──
_CAP_PLAN_FA = {Plan.FREE.value: "🆓 پلن پایه", Plan.GROWTH.value: "🚀 پلن رشد",
                Plan.PRO.value: "💎 پلن حرفه‌ای"}


async def _caps_hub_text() -> str:
    lines = [
        "📊 <b>۳) سقفِ هر پلن</b>\n",
        "برای هر پلن یک سقف تعیین کن. با رسیدن تعداد ربات‌های فعالِ آن پلن به سقف، "
        "ساخت/فروش آن پلن برای کاربران جدید بسته می‌شود و پیام «فعلاً فروش بسته است» "
        "نشان داده می‌شود؛ کاربرانی که قبلاً خریده‌اند همچنان می‌توانند تمدید کنند.\n",
    ]
    for p in (Plan.FREE.value, Plan.GROWTH.value, Plan.PRO.value):
        cap = plan_cap(p)
        built = await plan_built_count(p)
        cap_txt = str(cap) if cap > 0 else "نامحدود"
        lines.append(f"{_CAP_PLAN_FA[p]}: {built} ساخته‌شده / سقف: {cap_txt}")
    return "\n".join(lines)


def _caps_hub_kb() -> InlineKeyboardMarkup:
    rows = [[hx_button(f"⚙️ سقف {_CAP_PLAN_FA[p]}", callback_data=f"set:cap:{p}")]
            for p in (Plan.FREE.value, Plan.GROWTH.value, Plan.PRO.value)]
    # === PATCH_CAP_LABELS_HELP_V1 ===
    rows.append([hx_button("❓ این سقف‌ها چه فرقی دارند؟", callback_data="set:caps_help",
                           style=ButtonStyle.PRIMARY)])
    rows.append([hx_button("⬅️ بازگشت به پلن‌ها", callback_data="set:hub_plans",
                                      style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


