@router.message(SettingsFSM.plan_cap, F.text)
async def set_cap_apply(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    raw = (msg.text or "").strip().translate(str.maketrans("۰۱۲۳۴۵۶۷۸۹", "0123456789"))
    if raw == BTN_CANCEL:
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    if not raw.isdigit():
        await msg.answer("یک عدد صحیح بفرست (0 برای نامحدود):")
        return
    data = await state.get_data()
    p = data.get("cap_plan")
    await state.clear()
    if p not in _CAP_PLAN_FA:
        await msg.answer("نامعتبر.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    n = int(raw)
    _PLAN_CAP[p] = n
    await set_pset(f"plan_cap_{p}", str(n))
    await msg.answer(
        f"✅ سقف {_CAP_PLAN_FA[p]} روی {(n if n > 0 else 'نامحدود')} تنظیم شد.",
        reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
    await msg.answer(await _caps_hub_text(), reply_markup=_caps_hub_kb())


