@router.message(SettingsFSM.plan_price, F.text)
async def set_plan_price_save(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    raw = (msg.text or "").strip()
    if raw == BTN_CANCEL:
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    n = fa_to_int(raw.replace(",", "").replace("،", ""))
    if n is None or n <= 0:
        await msg.answer("یک عدد معتبر به ریال بفرست (مثلاً 5000000):")
        return
    data = await state.get_data()
    p = data.get("cfg_plan")
    await state.clear()
    if p not in _PLAN_FA:
        return
    PLAN_PRICE[p] = n
    await set_pset(f"plan_price_{p}", str(n))
    await msg.answer(f"✅ قیمت {_PLAN_FA[p]} روی {rial(n)}/ماه تنظیم شد.",
                     reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
    await msg.answer(_plan_menu_text(p), reply_markup=_plan_menu_kb(p))


