# ── خرید و فعال‌سازی پلن‌ها (فروش + زمان‌بندی + ربات اضافه با استارز) ──
async def _sale_hub_kb() -> InlineKeyboardMarkup:
    paid_manual = _PLANS_PAID
    bot_limit_on = (await get_pset("bot_limit_enabled", "on")) != "off"
    global_cap_on = (await get_pset("global_bot_cap_enabled", "off")) == "on"
    rows = [
        [hx_button(("💰 فروش پلن‌ها: پولی ✅" if paid_manual else "🎁 فروش پلن‌ها: رایگان (تست)"),
            callback_data="set:paid_toggle",
            style=(ButtonStyle.SUCCESS if paid_manual else ButtonStyle.DANGER))],
        [hx_button("⏰ زمان‌بندی پولی‌شدن خودکار", callback_data="set:paid_at")],
    ]
    if _PLANS_PAID_AT:
        rows.append([hx_button("🗑 حذف زمان‌بندی", callback_data="set:paid_at_del",
                                          style=ButtonStyle.DANGER)])
    rows += [
# === PATCH_CAP_LABELS_HELP_V1 ===
        # نام‌ها عمداً با پیشوندِ «۱) هر کاربر» و «۲) کلِ پلتفرم» شماره‌گذاری
        # شده‌اند؛ سه نوع سقفِ متفاوت وجود دارد و اسم‌هایِ قبلی («محدودیت
        # ساخت ربات» / «سقف کل ساخت ربات») چنان شبیه هم بودند که تشخیص
        # داده نمی‌شدند.
        [hx_button("❓ این سقف‌ها چه فرقی دارند؟", callback_data="set:caps_help",
                   style=ButtonStyle.PRIMARY)],
        [hx_button(("🟢 ۱) سقفِ هر کاربر: روشن" if bot_limit_on else "🔴 ۱) سقفِ هر کاربر: خاموش"),
            callback_data="set:toggle_bot_limit",
            style=(ButtonStyle.SUCCESS if bot_limit_on else ButtonStyle.DANGER))],
        [hx_button("👤 ۱) هر کاربر چند رباتِ رایگان بسازد", callback_data="set:bot_limit")],
        [hx_button("⭐ قیمتِ رباتِ اضافه برایِ کاربر (استارز)", callback_data="set:bot_slot_price")],
        [hx_button(("🟢 ۲) سقفِ کلِ پلتفرم: روشن" if global_cap_on else "🔴 ۲) سقفِ کلِ پلتفرم: خاموش"),
            callback_data="set:toggle_global_bot_cap",
            style=(ButtonStyle.SUCCESS if global_cap_on else ButtonStyle.DANGER))],
        [hx_button("🌐 ۲) کلِ پلتفرم چند ربات داشته باشد", callback_data="set:global_bot_cap")],
        [hx_button("⬅️ بازگشت به پلن‌ها", callback_data="set:hub_plans",
                              style=ButtonStyle.DANGER)],
    ]
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _sale_hub_text() -> str:
    paid = plans_paid_enabled()
    cdown = plans_countdown_text()
    bot_limit = await get_pset("bot_free_limit", "3")
    bot_stars = await get_pset("bot_stars_per_extra", "30")
    global_cap_on = (await get_pset("global_bot_cap_enabled", "off")) == "on"
    global_cap_max = await get_pset("global_bot_cap_max", "500")
    async with Session() as s:
        total_bots_now = await s.scalar(select(func.count(BotRow.id))) or 0
    txt = ("🛒 <b>خرید و فعال‌سازی پلن‌ها</b>\n\n"
           f"وضعیت فعلی: {'💰 پولی' if paid else '🎁 رایگان (حالت تست)'}\n")
    if _PLANS_PAID_AT:
        if cdown:
            txt += f"⏰ زمان‌بندی: {to_jalali(_PLANS_PAID_AT)}\n⏳ مانده: <b>{cdown}</b>\n"
        else:
            txt += f"⏰ زمان‌بندی: {to_jalali(_PLANS_PAID_AT)} (رسیده — پلن‌ها پولی‌اند)\n"
    txt += (f"\n👤 <b>۱) سقفِ هر کاربر</b> — رباتِ رایگان به‌ازای هر نفر: {bot_limit}\n"
            f"⭐ هر ربات اضافه: {bot_stars} استارز\n\n"
            f"🌐 <b>۲) سقفِ کلِ پلتفرم</b> — مجموعِ ربات‌هایِ همهٔ کاربران: "
            f"{('✅ روشن — ' + global_cap_max + ' ربات') if global_cap_on else '❌ خاموش'}\n"
            f"📊 تعداد کل ربات‌های ساخته‌شده تا الان: <b>{total_bots_now}</b>\n\n"
            "💡 با زمان‌بندی، کاربران تا رسیدن آن تاریخ پلن‌ها را رایگان می‌سازند و شمارش معکوس "
            "روی دکمه‌های خرید نمایش داده می‌شود؛ سرِ ساعت، فروش خودکار پولی می‌شود.")
    return txt


