@router.message(SettingsFSM.paid_at, F.text)
async def set_paid_at_save(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    raw = (msg.text or "").strip()
    if raw == BTN_CANCEL:
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    dt = parse_fa_datetime(raw)
    if not dt:
        await msg.answer("❌ فرمت نامعتبر. نمونه: <code>1405/04/20 00:00</code>\nدوباره بفرست:")
        return
    if dt <= datetime.datetime.now():
        await msg.answer("❌ این زمان گذشته است! یک زمان در آینده بفرست:")
        return
