# ═══════════ PATCH_TIMED_DISCOUNT_V1 — تخفیف‌های زمان‌دار ═══════════
# سه هدف: پلنِ رشد، پلنِ حرفه‌ای، و خریدِ عمدهٔ ربات همکار. برایِ هرکدام
# یک درصد و یک بازهٔ زمانی (به وقتِ تهران). خارج از بازه، خودکار به
# قیمتِ عادی برمی‌گردد — بدونِ نیازی به کارِ دستی.

async def sched_discount_notify_loop(platform_bot=None):
    """هر دقیقه چک می‌کند آیا وقتِ اعلانی رسیده.

    === PATCH_TIMED_DISCOUNT_NOTIFY_V2 ===
    اعلان‌ها کلی‌اند: همهٔ تخفیف‌هایی که هم‌زمان یک رویداد دارند (شروع،
    یک ساعت مانده، پایان) در **یک پیام** به کانال می‌روند.
    «نشانِ ارسال» در دیتابیس ذخیره می‌شود تا ری‌استارتِ سرویس باعثِ ارسالِ
    دوباره نشود، و چون نشان شاملِ خودِ بازه‌هاست، تخفیفِ بعدی دوباره
    اعلان می‌گیرد.
    """
    import asyncio as _aio
    while True:
        try:
            await _aio.sleep(60)
            await load_plans_paid()
            chat = (await get_pset("sched_disc_channel", "")).strip()
            if not chat:
                continue
            now = _sched_now()
            for kind in SCHED_MSG_KINDS:
                if (await get_pset(f"sched_msg_{kind}_on", "off")) != "on":
                    continue
                due_targets, stamps = [], []
                for t in SCHED_TARGETS:
                    cfg = _SCHED_DISC.get(t) or {}
                    pct = int(cfg.get("pct") or 0)
                    if pct <= 0:
                        continue
                    f, to = cfg.get("from"), cfg.get("to")
                    if kind == "start":
                        due = (f is None) or (f <= now)
                    elif kind == "soon":
                        due = bool(to) and (to - datetime.timedelta(hours=1)) <= now < to
                    else:
                        due = bool(to) and now >= to
                    if not due:
                        continue
                    due_targets.append(t)
                    stamps.append(f"{t}:{pct}:{f.isoformat() if f else ''}"
                                  f":{to.isoformat() if to else ''}")
                if not due_targets:
                    continue
                stamp = "|".join(sorted(stamps))
                mark_key = f"sched_sent_{kind}"
                if (await get_pset(mark_key, "")) == stamp:
                    continue
                txt = (await get_pset(f"sched_msg_{kind}", "")).strip() \
                    or SCHED_MSG_DEFAULT[kind]
                try:
                    # === PATCH_PLATFORM_BOT_NAME_FIX_V1 ===
                    from main_platform import platform_bot
                    await platform_bot.send_message(
                        chat, txt.format(**_sched_msg_vars(due_targets)))
                    await set_pset(mark_key, stamp)
                except Exception:
                    logger.exception("ارسالِ اعلانِ تخفیف به کانال ناموفق بود (نوع=%s)",
                                     kind)
        except Exception:
            logger.exception("حلقهٔ اعلانِ تخفیف خطا داد؛ ادامه می‌دهد")


def _sched_kb() -> InlineKeyboardMarkup:
    rows = []
    for t in SCHED_TARGETS:
        pct = sched_disc_pct(t)
        mark = "🟢" if pct else "⚪️"
        rows.append([hx_button(f"{mark} {SCHED_LABEL[t]}"
                               + (f" — {pct}٪ فعال" if pct else ""),
                               callback_data=f"set:sched:{t}",
                               style=ButtonStyle.SUCCESS if pct else ButtonStyle.PRIMARY)])
    # === PATCH_TIMED_DISCOUNT_NOTIFY_V1 ===
    rows.append([hx_button("📢 کانالِ اعلانِ تخفیف", callback_data="set:schedch",
                           style=ButtonStyle.PRIMARY)])
    # === PATCH_TIMED_DISCOUNT_NOTIFY_V2 === اعلان‌ها کلی‌اند، نه per-target
    rows.append([hx_button("📣 اعلان‌های کانال", callback_data="set:schedmsg",
                           style=ButtonStyle.SUCCESS)])
    rows.append([hx_button("⬅️ بازگشت به تنظیمات", callback_data="adm:settings",
                           style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def _sched_text() -> str:
    now = _sched_now()
    lines = ["🏷 <b>تخفیف‌های زمان‌دار</b>\n",
             f"🕒 ساعتِ فعلیِ تهران: <b>{_sched_fmt(now)}</b>\n"]
    for t in SCHED_TARGETS:
        lines.append(f"{SCHED_LABEL[t]}: {sched_window_text(t)}")
    lines.append("\nروی هر مورد بزن تا درصد و بازهٔ زمانی‌اش را تنظیم کنی.")
    lines.append("خارج از بازه، قیمت خودکار به حالتِ عادی برمی‌گردد.")
    return "\n".join(lines)


