async def _sched_time_save(msg: Message, state: FSMContext, field: str):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    raw = (msg.text or "").strip()
    t = (await state.get_data()).get("sched_target")
    if raw in ("حذف", "-", "خالی"):
        await state.clear()
        await set_pset(f"sched_disc_{t}_{field}", "")
        await load_plans_paid()
        await msg.answer("✅ حذف شد.\n\n" + _sched_text(), reply_markup=_sched_kb())
        return
    dt = parse_fa_datetime(raw)
    if not dt:
        await msg.answer("❌ فرمت نامعتبر. نمونه: <code>1405/06/10 18:00</code>\n"
                         "برایِ حذف، کلمهٔ <code>حذف</code> را بفرست:")
        return
    await state.clear()
    await set_pset(f"sched_disc_{t}_{field}", dt.isoformat())
    await load_plans_paid()
    await msg.answer("✅ ثبت شد.\n\n" + _sched_text(), reply_markup=_sched_kb())


