@router.message(AdminFSM.sched_channel)
async def set_sched_channel_save(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    # فورواردِ یک پیام از کانال، ساده‌ترین راهِ گرفتنِ آیدی است
    chat = ""
    fwd = getattr(msg, "forward_from_chat", None)
    if fwd is not None:
        chat = str(fwd.id)
    else:
        chat = (msg.text or "").strip()
    if chat in ("حذف", "-"):
        await state.clear()
        await set_pset("sched_disc_channel", "")
        await msg.answer("🚫 اعلانِ تخفیف در کانال خاموش شد.",
                         reply_markup=_sched_kb())
        return
    if not chat:
        await msg.answer("آیدیِ کانال را بفرست یا پیامی از آن فوروارد کن:")
        return
    try:
        await msg.bot.send_message(chat, "✅ این کانال برای اعلانِ تخفیف‌ها تنظیم شد.")
    except Exception as e:
        await msg.answer("❌ نتوانستم به این کانال پیام بفرستم.\n"
                         f"<code>{_html.escape(str(e)[:150])}</code>\n\n"
                         "مطمئن شو ربات آنجا ادمین است، بعد دوباره بفرست:")
        return
    await state.clear()
    await set_pset("sched_disc_channel", chat)
    await msg.answer("✅ کانال ثبت شد.\n\n" + _sched_text(), reply_markup=_sched_kb())


def _sched_msg_kb(flags: dict) -> InlineKeyboardMarkup:
    rows = []
    for kind in SCHED_MSG_KINDS:
        on = flags.get(kind) == "on"
        rows.append([hx_button(f"{'🟢' if on else '⚪️'} {SCHED_MSG_LABEL[kind]}",
                               callback_data=f"set:schedmsgtg:{kind}",
                               style=ButtonStyle.SUCCESS if on else ButtonStyle.PRIMARY),
                     hx_button("✏️ متن", callback_data=f"set:schedmsgtxt:{kind}")])
    rows.append([hx_button("⬅️ بازگشت", callback_data="set:sched",
                           style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def _sched_msg_screen() -> tuple[str, InlineKeyboardMarkup]:
    flags = {k: await get_pset(f"sched_msg_{k}_on", "off") for k in SCHED_MSG_KINDS}
    ch = (await get_pset("sched_disc_channel", "")).strip()
    txt = ("📣 <b>اعلان‌های کانال</b>\n\n"
           f"کانال: <code>{ch or '⚠️ تنظیم نشده'}</code>\n\n"
           "این اعلان‌ها <b>کلی</b> هستند: همهٔ تخفیف‌هایی که هم‌زمان شروع "
           "یا تمام می‌شوند، در یک پیام به کانال می‌روند.\n\n"
           "متغیرهایی که می‌توانی در متن بگذاری:\n"
           "<code>{list}</code> فهرستِ تخفیف‌ها با درصدشان\n"
           "<code>{until}</code> نزدیک‌ترین زمانِ پایان · "
           "<code>{pct}</code> بیشترین درصد · <code>{label}</code> نامِ بخش‌ها")
    if not ch:
        txt += "\n\n⚠️ تا وقتی کانال تنظیم نشود، هیچ اعلانی فرستاده نمی‌شود."
    return txt, _sched_msg_kb(flags)


