@router.message(AdminFSM.sched_msgtext, F.text)
async def set_sched_msg_text_save(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    kind = (await state.get_data()).get("sched_kind")
    raw = (msg.text or "").strip()
    if raw in ("پیش‌فرض", "پیشفرض", "-"):
        await set_pset(f"sched_msg_{kind}", "")
        await state.clear()
        txt, kb = await _sched_msg_screen()
        await msg.answer("✅ به متنِ پیش‌فرض برگشت.")
        await msg.answer(txt, reply_markup=kb)
        return
    # پیش‌نمایش با تخفیف‌هایِ تنظیم‌شده؛ اگر هیچ‌کدام درصد ندارند، با
    # همهٔ هدف‌ها نمونه می‌سازیم تا متغیرها تست شوند.
    _sample = [t for t in SCHED_TARGETS if int((_SCHED_DISC.get(t) or {}).get("pct") or 0) > 0] \
        or list(SCHED_TARGETS)
    try:
        preview = raw.format(**_sched_msg_vars(_sample))
    except (KeyError, IndexError, ValueError):
        await msg.answer("❌ یکی از متغیرها اشتباه نوشته شده. فقط این‌ها مجازند: "
                         "<code>{list}</code> <code>{until}</code> "
                         "<code>{pct}</code> <code>{label}</code>\n\n"
                         "دوباره بفرست:")
        return
    await set_pset(f"sched_msg_{kind}", raw)
    await state.clear()
    await msg.answer("✅ ذخیره شد. پیش‌نمایش:")
    await msg.answer(preview)
    txt, kb = await _sched_msg_screen()
    await msg.answer(txt, reply_markup=kb)


