# ───────────────── ارسال پست به کانال (پنل مدیر اصلی) ─────────────────
# استخراج شده به platform_chpost.py — روتر در همین فایل بالا ثبت شده (chpost_router)

# ───── تنظیم درگاه سواپ‌ولت پلتفرم ─────
# پورتِ همان منوی مدیریتِ درگاه سواپ‌ولتِ ربات‌های مستأجر (چندارزی، حداقل/حداکثر،
# ارزهای فعال، اطلاع‌رسانی و حذف تنظیمات) برای کیف پول خودِ پلتفرم.

async def _swap_admin_content(note: str | None = None) -> tuple[str, InlineKeyboardMarkup]:
    api_key = await get_pset("swap_api_key", "")
    addr_usdt = await get_pset("swap_addr_usdt", "")
    addr_ton  = await get_pset("swap_addr_ton", "")
    addr_trx  = await get_pset("swap_addr_trx", "")
    min_v = int(await get_pset("swap_min_toman", "10000") or "10000")
    max_v = int(await get_pset("swap_max_toman", "0") or "0")
    coins = await get_pset("swap_enabled_coins", "USDT,TON,TRX")
    notify_on = await get_pset("swap_notify_admin", "1") != "0"

    def _fmt(addr): return f"<code>{addr[:10]}…</code>" if addr else "❌ تنظیم‌نشده"

    txt = (
        ((note + "\n\n") if note else "") +
        "🟦 <b>مدیریت درگاه سواپ‌ولت (کیف پول پلتفرم)</b>\n\n"
        f"🔑 کلید API: {'✅ ثبت‌شده' if api_key else '❌ ثبت‌نشده'}\n"
        f"💵 آدرس USDT: {_fmt(addr_usdt)}\n"
        f"💎 آدرس TON:  {_fmt(addr_ton)}\n"
        f"⚡ آدرس TRX:  {_fmt(addr_trx)}\n"
        f"💰 حداقل: {min_v:,} | حداکثر: {'بدون محدودیت' if max_v == 0 else f'{max_v:,} تومان'}\n"
        f"🪙 ارزهای فعال: {coins}\n"
        f"🔔 اطلاع از شارژ: {'✅ روشن' if notify_on else '❌ خاموش'}"
    )
    kb = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("🔑 ویرایش کلید API", callback_data="swadm:edit:api")],
        [hx_button("💵 آدرس USDT", callback_data="swadm:edit:usdt"),
         hx_button("💎 آدرس TON", callback_data="swadm:edit:ton"),
         hx_button("⚡ آدرس TRX", callback_data="swadm:edit:trx")],
        [hx_button("💰 حداقل/حداکثر", callback_data="swadm:edit:limits")],
        [hx_button("🪙 ارزهای فعال", callback_data="swadm:edit:coins")],
        [hx_button(f"🔔 اطلاع از شارژ: {'✅ روشن' if notify_on else '❌ خاموش'}",
            callback_data="swadm:notify")],
        [hx_button("🗑 حذف تمام تنظیمات سواپ", callback_data="swadm:delete",
                              style=ButtonStyle.DANGER)],
        [hx_button("🔙 بازگشت", callback_data="set:hub_pay")],
    ])
    return txt, kb


async def _swap_admin_menu(target, *, answer=False):
    txt, kb = await _swap_admin_content()
    if answer:
        await target.message.answer(txt, reply_markup=kb)
    else:
        try:
            await target.message.edit_text(txt, reply_markup=kb)
        except Exception:
            await target.message.answer(txt, reply_markup=kb)


async def _swap_admin_menu_msg(bot: Bot, *, chat_id=None, msg_id=None, note: str | None = None):
    """نمایش/به‌روزرسانی منوی سواپ. اگر chat_id/msg_id داده شود همان پیام ادیت می‌شود."""
    txt, kb = await _swap_admin_content(note=note)
    if chat_id and msg_id:
        try:
            await bot.edit_message_text(txt, chat_id=chat_id, message_id=msg_id, reply_markup=kb)
            return
        except Exception:
            try:
                await bot.delete_message(chat_id=chat_id, message_id=msg_id)
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
            await bot.send_message(chat_id, txt, reply_markup=kb)
            return
    raise RuntimeError("_swap_admin_menu_msg requires chat_id/msg_id")


