@router.callback_query(F.data.startswith("swadm:edit:"))
async def swap_edit_dispatch(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    field = cb.data.split(":")[2]
    await cb.answer()

    async def _edit(text):
        await cb.message.answer(text, reply_markup=await smart_cancel_kb())

    if field == "api":
        await state.update_data(swap_edit_field="api", swap_menu_chat_id=cb.message.chat.id,
                                  swap_menu_msg_id=cb.message.message_id)
        await state.set_state(SettingsFSM.swap_edit_field)
        cur = await get_pset("swap_api_key", "")
        await _edit(
            f"🔑 <b>ویرایش کلید API سواپ‌ولت</b>\n"
            f"فعلی: {'ثبت‌شده ✅' if cur else 'ندارد'}\n\n"
            "کلید جدید را بفرست (apikey-...):")

    elif field == "usdt":
        await state.update_data(swap_edit_field="usdt", swap_menu_chat_id=cb.message.chat.id,
                                  swap_menu_msg_id=cb.message.message_id)
        await state.set_state(SettingsFSM.swap_edit_field)
        cur = await get_pset("swap_addr_usdt", "")
        await _edit(
            f"💵 <b>آدرس واریز USDT (شبکه TRON/TRC20)</b>\n"
            f"فعلی: {cur or 'ندارد'}\n\n"
            "آدرس جدید را بفرست (برای حذف عدد 0 بفرست):")

    elif field == "ton":
        await state.update_data(swap_edit_field="ton", swap_menu_chat_id=cb.message.chat.id,
                                  swap_menu_msg_id=cb.message.message_id)
        await state.set_state(SettingsFSM.swap_edit_field)
        cur = await get_pset("swap_addr_ton", "")
        await _edit(
            f"💎 <b>آدرس واریز TON</b>\n"
            f"فعلی: {cur or 'ندارد'}\n\n"
            "آدرس جدید را بفرست (برای حذف عدد 0 بفرست):")

    elif field == "trx":
        await state.update_data(swap_edit_field="trx", swap_menu_chat_id=cb.message.chat.id,
                                  swap_menu_msg_id=cb.message.message_id)
        await state.set_state(SettingsFSM.swap_edit_field)
        cur = await get_pset("swap_addr_trx", "")
        await _edit(
            f"⚡ <b>آدرس واریز TRX (شبکه TRON)</b>\n"
            f"فعلی: {cur or 'ندارد'}\n\n"
            "آدرس جدید را بفرست (برای حذف عدد 0 بفرست):")

    elif field == "limits":
        await state.update_data(swap_menu_chat_id=cb.message.chat.id,
                                  swap_menu_msg_id=cb.message.message_id)
        await state.set_state(SettingsFSM.swap_min)
        cur_min = int(await get_pset("swap_min_toman", "10000") or "10000")
        await _edit(
            f"💰 <b>حداقل مبلغ واریز</b> (فعلی: {cur_min:,} تومان)\n"
            "مقدار جدید را به تومان بفرست:")

    elif field == "coins":
        cur_coins_str = await get_pset("swap_enabled_coins", "USDT,TON,TRX")
        selected = set(cur_coins_str.split(","))
        await state.update_data(swap_enabled_coins_set=list(selected),
                                  swap_menu_chat_id=cb.message.chat.id,
                                  swap_menu_msg_id=cb.message.message_id)
        try:
            await cb.message.edit_text("🪙 ارزهایی که کاربر می‌تواند انتخاب کند:",
                                       reply_markup=_swap_coins_admin_kb(selected))
        except Exception:
            await cb.message.answer("🪙 ارزهایی که کاربر می‌تواند انتخاب کند:",
                                    reply_markup=_swap_coins_admin_kb(selected))


@router.message(SettingsFSM.swap_edit_field, F.text)
async def swap_edit_field_handler(msg: Message, state: FSMContext):
    import swappay
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        await msg.answer("⛔️ تنظیمِ سواپ‌ولت فقط برایِ مدیر اصلی است.")  # PATCH_SWAP_AUTH_FALLBACK_V1: قبلاً بی‌صدا رد می‌شد
        return
    data = await state.get_data()
    field = data.get("swap_edit_field", "")
    menu_chat_id = data.get("swap_menu_chat_id")
    menu_msg_id = data.get("swap_menu_msg_id")
    val = msg.text.strip()
    await state.clear()

    note = None
    if field == "api":
        # === PATCH_SWAP_AUTH_FALLBACK_V1 === علتِ دقیق نشان داده می‌شود (نه فقط «نامعتبر»)
        val = swappay.clean_key(val)  # PATCH_SWAP_CLEAN_KEY_V1
        ok, why = await swappay.SwapPayClient(val).check_auth_detail()
        if not ok:
            note = f"❌ کلید API ذخیره نشد.\n{why}"
        else:
            await set_pset("swap_api_key", val)
            note = "✅ کلید API ذخیره شد."

    elif field == "usdt":
        if val == "0":
            await set_pset("swap_addr_usdt", "")
            note = "✅ آدرس USDT حذف شد."
        elif len(val) < 10:
            note = "❌ آدرس نامعتبر است."
        else:
            await set_pset("swap_addr_usdt", val)
            note = "✅ آدرس USDT ذخیره شد."

    elif field == "ton":
        if val == "0":
            await set_pset("swap_addr_ton", "")
            note = "✅ آدرس TON حذف شد."
        elif len(val) < 10:
            note = "❌ آدرس نامعتبر است."
        else:
            await set_pset("swap_addr_ton", val)
            note = "✅ آدرس TON ذخیره شد."

    elif field == "trx":
        if val == "0":
            await set_pset("swap_addr_trx", "")
            note = "✅ آدرس TRX حذف شد."
        elif len(val) < 10:
            note = "❌ آدرس نامعتبر است."
        else:
            await set_pset("swap_addr_trx", val)
            note = "✅ آدرس TRX ذخیره شد."

    try:
        await msg.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

    await _swap_admin_menu_msg(msg.bot, chat_id=menu_chat_id, msg_id=menu_msg_id, note=note)


# ─── حداقل/حداکثر ───
@router.message(SettingsFSM.swap_min, F.text)
async def set_swap_min(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    val = fa_to_int(msg.text)
    if not val or val < 1000:
        await msg.answer("مقدار نامعتبر است. حداقل ۱۰۰۰ تومان باشد:")
        return
    await set_pset("swap_min_toman", str(val))
    await state.set_state(SettingsFSM.swap_max)
    data = await state.get_data()
    menu_chat_id = data.get("swap_menu_chat_id")
    menu_msg_id = data.get("swap_menu_msg_id")
    cur_max = int(await get_pset("swap_max_toman", "0") or "0")
    txt = (
        f"✅ حداقل {val:,} تومان ذخیره شد.\n\n"
        f"💰 <b>حداکثر مبلغ واریز</b> (فعلی: {cur_max:,} تومان)\n"
        "برای بدون محدودیت عدد <b>0</b> بفرست:"
    )
    try:
        await msg.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    if menu_chat_id and menu_msg_id:
        try:
            await msg.bot.edit_message_text(txt, chat_id=menu_chat_id, message_id=menu_msg_id,
                                            reply_markup=await smart_cancel_kb())
            return
        except Exception:
            logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    await msg.answer(txt, reply_markup=await smart_cancel_kb())


@router.message(SettingsFSM.swap_max, F.text)
async def set_swap_max(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    val_str = (msg.text or "").strip()
    val = fa_to_int(val_str) if val_str != "0" else 0
    if val is None:
        val = 0
    await set_pset("swap_max_toman", str(val))
    data = await state.get_data()
    menu_chat_id = data.get("swap_menu_chat_id")
    menu_msg_id = data.get("swap_menu_msg_id")
    await state.clear()
    try:
        await msg.delete()
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    note = f"✅ حداکثر {'بدون محدودیت' if val == 0 else f'{val:,} تومان'} ذخیره شد."
    await _swap_admin_menu_msg(msg.bot, chat_id=menu_chat_id, msg_id=menu_msg_id, note=note)


# ─── ارزهای فعال ───
def _swap_coins_admin_kb(selected: set) -> InlineKeyboardMarkup:
    coins = [("USDT", "💵 تتر (USDT)"), ("TON", "💎 تون (TON)"), ("TRX", "⚡ ترون (TRX)")]
    btns = []
    for coin, label in coins:
        check = "✅ " if coin in selected else "⬜ "
        btns.append([hx_button(check + label, callback_data=f"swcoinstog:{coin}")])
    btns.append([hx_button("✔️ ذخیره", callback_data="swcoins:done",
                                      style=ButtonStyle.SUCCESS)])
    btns.append([hx_button("❌ لغو", callback_data="swcoins:cancel",
                                      style=ButtonStyle.DANGER)])
    return InlineKeyboardMarkup(inline_keyboard=btns)


@router.callback_query(F.data == "swcoins:cancel")
async def swap_coins_cancel(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer()
        return
    await state.clear()
    await _swap_admin_menu(cb)
    await cb.answer()


@router.callback_query(F.data.startswith("swcoinstog:"))
async def swap_coins_toggle(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer()
        return
    coin = cb.data.split(":")[1]
    data = await state.get_data()
    selected = set(data.get("swap_enabled_coins_set", ["USDT", "TON", "TRX"]))
    if coin in selected:
        selected.discard(coin)
    else:
        selected.add(coin)
    await state.update_data(swap_enabled_coins_set=list(selected))
    await cb.message.edit_reply_markup(reply_markup=_swap_coins_admin_kb(selected))
    await cb.answer()


@router.callback_query(F.data == "swcoins:done")
async def swap_coins_done(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer()
        return
    data = await state.get_data()
    selected = list(data.get("swap_enabled_coins_set", ["USDT", "TON", "TRX"]))
    if not selected:
        await cb.answer("حداقل یک ارز باید انتخاب شود.", show_alert=True)
        return
    await state.clear()
    await set_pset("swap_enabled_coins", ",".join(selected))
    note = f"✅ ارزهای فعال: {', '.join(selected)} ذخیره شد."
    await _swap_admin_menu_msg(cb.message.bot, chat_id=cb.message.chat.id,
                                msg_id=cb.message.message_id, note=note)
    await cb.answer()


