@router.message(SettingsFSM.reaction_custom, F.text)
async def set_pstart_reaction_custom_save(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    emoji = (msg.text or "").strip()
    await state.clear()
    if not emoji or len(emoji) > 8:
        await msg.answer("❌ این یک ایموجیِ معتبر نبود؛ فقط خودِ ایموجی را بفرست.")
        return
    try:
        await msg.react([ReactionTypeEmoji(emoji=emoji)], is_big=True)
    except Exception:
        await msg.answer(
            f"❌ تلگرام «{emoji}» را به‌عنوانِ ری‌اکشن قبول نکرد. "
            "یکی از ایموجی‌هایِ رایج (مثلِ 👍❤️🔥🎉) را امتحان کن.")
        current = await get_pset("start_reaction_emoji", "")
        await msg.answer(_pstart_reaction_text(current), reply_markup=_pstart_reaction_kb(current))
        return
    await set_pset("start_reaction_emoji", emoji)
    await msg.answer(f"✅ ذخیره شد؛ از این به بعد رویِ پیامِ /start کاربرها «{emoji}» می‌آید.")
    await msg.answer(_pstart_reaction_text(emoji), reply_markup=_pstart_reaction_kb(emoji))


async def _platform_welcome_typewriter_kb() -> InlineKeyboardMarkup:
    enabled = (await get_pset("platform_welcome_typewriter_enabled", "0")) == "1"
    return InlineKeyboardMarkup(inline_keyboard=[
        [hx_button(
            ("🟢 جلوهٔ تایپ خوش‌آمد: فعال" if enabled else "🔴 جلوهٔ تایپ خوش‌آمد: غیرفعال"),
            callback_data="set:toggle_platform_welcome_typewriter",
            style=(ButtonStyle.SUCCESS if enabled else ButtonStyle.DANGER),
        )],
        [hx_button("❌ لغو / بازگشت", callback_data="set:hub_general", style=ButtonStyle.DANGER)],
    ])


