@router.callback_query(F.data == "set:pwelcome")
async def set_pwelcome_start(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("فقط مدیر اصلی", show_alert=True)
        return
    cur = await get_pset("welcome_msg", "")
    await state.set_state(SettingsFSM.welcome)
    await cb.message.answer(
        "✏️ <b>متن جدید پیام خوش‌آمد</b> را بفرست.\n\n"
        "هر فرمتی که در تلگرام بزنی حفظ می‌شود:\n"
        "• <b>بولد</b> و <i>ایتالیک</i> و <u>زیرخط</u> و <s>خط‌خورده</s>\n"
        "• <tg-spoiler>اسپویلر</tg-spoiler> و <code>مونو/کد</code>\n"
        "• نقل‌قول (همان قابلیت Quote تلگرام)\n"
        "• لینک‌دار کردن کلمه‌ها\n\n"
        "🔤 <b>متغیرها</b> (خودکار جایگزین می‌شوند):\n"
        "<code>{name}</code> → نام کوچک کاربر\n"
        "<code>{fullname}</code> → نام کامل کاربر\n"
        "<code>{id}</code> → آیدی عددی کاربر\n\n"
        "💡 <b>چند ایدهٔ جذاب:</b>\n"
        "سلام <b>{name}</b> عزیز 👋 به جمع ما خوش اومدی!\n"
        "یک خط را <b>نقل‌قول</b> کن و قوانین یا یک پیام انگیزشی بنویس.\n"
        "آیدی کاربر را با کد نشان بده: کد پشتیبانی شما <code>{id}</code>\n\n"
        "برای بازگشت به پیش‌فرض: <code>/default</code>\n\n"
        f"جلوهٔ تایپ تدریجی: {'فعال' if (await get_pset('platform_welcome_typewriter_enabled', '0')) == '1' else 'غیرفعال'}\n\n"
        f"— متن فعلی —\n{cur or '(پیش‌فرض)'}",
        reply_markup=await _platform_welcome_typewriter_kb(),
    )
    await cb.answer()


@router.message(SettingsFSM.welcome, F.text)
async def set_pwelcome_save(msg: Message, state: FSMContext):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        return
    if msg.text.strip() == BTN_CANCEL:
        await state.clear()
        await msg.answer("لغو شد.", reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    if msg.text.strip() == "/default":
        await set_pset("welcome_msg", "")
        await state.clear()
        await msg.answer("✅ پیام خوش‌آمد به حالت پیش‌فرض بازگشت.",
                         reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))
        return
    # html_text فرمت‌هایی که کاربر در تلگرام زده (بولد/کوتیشن/...) را به HTML تبدیل می‌کند
    await set_pset("welcome_msg", msg.html_text)
    await state.clear()
    await msg.answer("✅ پیام خوش‌آمد ذخیره شد. برای دیدن نتیجه /start بزن.",
                     reply_markup=await smart_home_kb(msg.from_user.id, show_admin=True))


