@router.message(SettingsFSM.big_chat, F.text)
async def set_bigchat_save(msg: Message, state: FSMContext):
    raw = (msg.text or "").strip()
    if raw == BTN_CANCEL:
        return
    # === PATCH_BIG_CHARGE_DIRECT_V1 ===
    # «@name» به دایرکتِ کانال تبدیل می‌شود (?direct). اگر مقصد یک اکانتِ
    # شخصی است، لینکِ کاملِ بدونِ ?direct را دستی بفرست.
    if raw.startswith("@"):
        raw = f"https://t.me/{raw[1:]}?direct"
    if not raw.startswith("https://t.me/"):
        await msg.answer("لینک باید با <code>https://t.me/</code> شروع شود یا با @ بفرست:")
        return
    await state.clear()
    await set_pset("big_charge_chat", raw)
    await msg.answer(f"✅ لینکِ هماهنگی ذخیره شد:\n<code>{raw}</code>",
                     reply_markup=await smart_home_kb(msg.from_user.id))


