# میدل‌ور عضویت اجباری: کاربران غیرادمین تا عضو نشوند بلاک می‌شوند (fail-open در خطا).
@router.message.outer_middleware
async def force_join_mw(handler, event, data):
    # === PATCH_FORCE_JOIN_PRIVATE_ONLY_V1 ===
    # قبلاً این میدل‌ور روی *همه‌ی* چت‌ها (شاملِ گروه/سوپرگروه/کانال) اعمال
    # می‌شد — یعنی مثلاً هر ریپلایی تو یه گروهِ متصل‌به‌قرعه‌کشی هم اول از
    # این چک رد می‌شد، و اگه فرستنده عضوِ کانالِ عضویتِ اجباری نبود، کلاً
    # جلوی رسیدنِ پیام به هندلرهای واقعی (raffle و غیره) گرفته می‌شد؛ حتی
    # پیامِ «عضو شو» هم توی همون گروهِ عمومی پست می‌شد که بی‌ربط/مزاحم بود.
    # عضویتِ اجباری از اساس برایِ تعاملِ شخصیِ کاربر با بات (مثلِ /start) طراحی
    # شده، نه تعاملِ گروهی؛ برای همین الان فقط روی چتِ خصوصی اعمال می‌شه.
    chat = getattr(event, "chat", None)
    if chat is not None and getattr(chat, "type", "private") != "private":
        return await handler(event, data)
    u = getattr(event, "from_user", None)
    if u and not await _is_any_admin(u.id):
        if (await get_pset("fj_enabled", "off")) == "on":
            target = await get_pset("fj_target", "")
            if target:
                bot = data.get("bot") or event.bot
                if not await is_channel_member(bot, target, u.id):
                    link = await get_pset("fj_link", "")
                    dm_topic = getattr(event, "direct_messages_topic", None)
                    dm_topic_id = getattr(dm_topic, "topic_id", None)
                    try:
                        await event.answer(
                            "🔒 برای استفاده از ربات، ابتدا در کانال ما عضو شو و بعد «✅ عضو شدم» را بزن.",
                            reply_markup=force_join_kb(link),
                            direct_messages_topic_id=dm_topic_id)
                    except Exception:
                        # fail-open: اگر پیامِ عضویت اجباری ارسال نشد (مثلاً به‌دلیل
                        # محدودیت‌های جدید تلگرام روی چت‌های Direct Messages)، کاربر را
                        # بلاک نکن تا کل ربات به‌خاطر این خطا از کار نیفتد.
                        pass
                    return
    return await handler(event, data)


async def _is_any_admin(uid: int) -> bool:
    """PATCH_FORCE_JOIN_SUBADMIN_V1 — قبلاً force_join_mw فقط is_admin (یعنی
    فقط PLATFORM_ADMIN_ID) را چک می‌کرد، پس ادمین‌های فرعی هم به‌اشتباه مثلِ
    یک کاربرِ عادی مشمولِ عضویتِ اجباری می‌شدند. اینجا هر دو حالت را می‌بیند."""
    if is_admin(uid):
        return True
    async with Session() as s:
        return bool(await get_sub_admin(s, uid))

# ======================= آنتی‌اسپم (فلود پیام) =======================
# اگر کاربری ۱۰ پیام پشت‌سرهم (در یک بازه‌ی کوتاه) بفرستد، یک «فلود» شمرده
# می‌شود: بار اول و دوم فقط اخطار می‌گیرد، بار سوم به‌طور خودکار بن می‌شود.
_ANTISPAM_WINDOW_SECONDS = 8     # بازهٔ زمانیِ «پشت‌سرهم»
_ANTISPAM_MSG_THRESHOLD = 10     # چند پیام در این بازه = یک فلود
_ANTISPAM_MAX_WARNINGS = 2       # این‌قدر اخطار می‌گیرد، دفعهٔ بعد (سوم) بن می‌شود

_antispam_times: dict[int, deque] = {}       # telegram_id -> زمانِ آخرین پیام‌ها
_antispam_cooldown: dict[int, float] = {}    # جلوگیری از شمارشِ یک فلودِ واحد به چند incident


@router.message.outer_middleware
async def antispam_mw(handler, event, data):
    u = getattr(event, "from_user", None)
    if u and not is_admin(u.id):
        # کاربری که وسطِ یک فرمِ چندمرحله‌ای است هرگز آنتی‌اسپم نخورد.
        fsm_state = data.get("state")
        if fsm_state is not None:
            try:
                if await fsm_state.get_state() is not None:
                    return await handler(event, data)
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        async with Session() as s:
            pu = await get_user(s, u.id, u.full_name or "")
            # === PATCH_MEMBER_STATS_V1 ===
            # فقط اگر آخرین ثبت بیش از ۲ دقیقه پیش بوده بنویس؛ نوشتن روی هر پیام (۷۵ هزار UPDATE با
            # میانگین ۱۶ms در آمار) ردیفِ کاربر را قفل می‌کرد و دقتِ بیشتر از دقیقه لازم نیست.
            _now_act = datetime.datetime.utcnow()
            if pu.last_active_at is None or (_now_act - pu.last_active_at).total_seconds() > 120:
                pu.last_active_at = _now_act
                await s.commit()
            already_banned = pu.is_banned
            warnings_now = pu.spam_warnings or 0

        if already_banned:
            return  # کاربرِ بن‌شده؛ کاملاً نادیده گرفته می‌شود (نه پاسخ، نه پردازش)

        if (await get_pset("antispam_enabled", "on")) == "on":
            now = time.monotonic()
            dq = _antispam_times.setdefault(u.id, deque())
            dq.append(now)
            while dq and now - dq[0] > _ANTISPAM_WINDOW_SECONDS:
                dq.popleft()

            if len(dq) >= _ANTISPAM_MSG_THRESHOLD:
                last_trigger = _antispam_cooldown.get(u.id, float("-inf"))
                if now - last_trigger > _ANTISPAM_WINDOW_SECONDS:
                    _antispam_cooldown[u.id] = now
                    dq.clear()
                    new_warnings = warnings_now + 1
                    will_ban = new_warnings > _ANTISPAM_MAX_WARNINGS
                    async with Session() as s:
                        pu2 = await s.scalar(select(PlatformUser).where(PlatformUser.telegram_id == u.id))
                        if pu2:
                            pu2.spam_warnings = new_warnings
                            if will_ban:
                                pu2.is_banned = True
                        await s.commit()
                    if will_ban:
                        await event.answer(
                            "🚫 به‌دلیل ارسال بیش‌ازحدِ پیام (اسپم)، دسترسی‌ات به ربات مسدود شد.\n"
                            "برای رفعِ مسدودی با پشتیبانی تماس بگیر.")
                    else:
                        await event.answer(
                            f"⚠️ اخطار {new_warnings}/{_ANTISPAM_MAX_WARNINGS}: لطفاً پیام‌های پشت‌سرهم و زیاد نفرست.\n"
                            "در صورت تکرار، دسترسی‌ات به ربات مسدود خواهد شد.")
                    return
    return await handler(event, data)



# ======================= انجمن بات‌ساز =======================
# استخراج شده به platform_community.py — روتر در همین فایل بالا ثبت شده
# (community_router). این خطوط دیگه فقط یه نشونه هستن که کاربر بدونه بخشِ
# انجمن بات‌ساز از platform_bot.py رفته بیرون.


# ════════════ ارسال پیام همگانی (پلتفرم بات‌ساز) ════════════
# پشتیبانی کامل از قالب‌بندی تلگرام (بولد/ایتالیک/نقل‌قول/لینک)، عکس، ویدیو،
# فایل، گیف و استیکر — با کپی عینی پیام (copy_message) و امکان لغو حین ارسال.

class BroadcastFSM(StatesGroup):
    wait_msg = State()
    confirm = State()


def _bcast_confirm_kb() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("✅ ارسال به همه", callback_data="bcast:send",
                              style=ButtonStyle.SUCCESS)],
        [hx_button("❌ لغو", callback_data="bcast:cancel",
                              style=ButtonStyle.DANGER)],
    ])


@router.callback_query(F.data == "adm:broadcast")
async def adm_broadcast_start(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    await state.set_state(BroadcastFSM.wait_msg)
    await cb.message.answer(
        "📢 <b>ارسال پیام همگانی</b>\n\n"
        "پیامی که می‌خواهی برای همهٔ کاربران بات‌ساز فرستاده شود را همین‌جا بفرست:\n"
        "• متن با قالب‌بندی تلگرام (بولد، ایتالیک، نقل‌قول، لینک و...)\n"
        "• عکس، ویدیو، فایل، گیف یا استیکر — همراه کپشن دلخواه\n\n"
        "دقیقاً همان چیزی که بفرستی، عیناً برای کاربران ارسال می‌شود.",
        reply_markup=await smart_cancel_kb(),
    )
    await cb.answer()


@router.message(BroadcastFSM.wait_msg)
async def adm_broadcast_preview(msg: Message, state: FSMContext, bot: Bot):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        return
    descr = ((msg.caption or msg.text) or "[رسانه]")[:500]
    await state.update_data(src_chat=msg.chat.id, src_msg=msg.message_id, descr=descr)
    await state.set_state(BroadcastFSM.confirm)
    await msg.answer("👁 <b>پیش‌نمایش</b> (همین پیام برای کاربران ارسال می‌شود):")
    try:
        await bot.copy_message(chat_id=msg.chat.id, from_chat_id=msg.chat.id,
                               message_id=msg.message_id)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    async with Session() as s:
        cnt = await s.scalar(
            select(func.count()).select_from(PlatformUser)
            .where(PlatformUser.is_banned == False)
        )
    await msg.answer(
        f"این پیام به حدود <b>{cnt or 0}</b> کاربر ارسال شود؟",
        reply_markup=_bcast_confirm_kb(),
    )


@router.callback_query(BroadcastFSM.confirm, F.data == "bcast:cancel")
async def adm_broadcast_cancel(cb: CallbackQuery, state: FSMContext):
    await state.clear()
    try:
        await cb.message.edit_text("❌ ارسال همگانی لغو شد.", reply_markup=back_to_admin_kb())
    except Exception:
        await cb.message.answer("❌ ارسال همگانی لغو شد.", reply_markup=back_to_admin_kb())
    await cb.answer()


@router.callback_query(BroadcastFSM.confirm, F.data == "bcast:send")
async def adm_broadcast_send(cb: CallbackQuery, state: FSMContext, bot: Bot):
    import asyncio
    from models import Broadcast
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    data = await state.get_data()
    await state.clear()
    src_chat = data.get("src_chat")
    src_msg = data.get("src_msg")
    descr = data.get("descr") or "[رسانه]"
    if not src_chat or not src_msg:
        await cb.answer("پیام نامعتبر است؛ دوباره تلاش کن.", show_alert=True)
        return
    async with Session() as s:
        bc = Broadcast(bot_id=0, text=descr, status="sending")
        s.add(bc)
        await s.flush()
        bc_id = bc.id
        users = (await s.scalars(
            select(PlatformUser).where(PlatformUser.is_banned == False)
        )).all()
        await s.commit()
    kb_cancel = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("🛑 لغو ارسال", callback_data=f"pbcast:stop:{bc_id}")]
    ])
    try:
        await cb.message.edit_text(
            f"📢 در حال ارسال به {len(users)} کاربر...",
            reply_markup=kb_cancel,
        )
    except Exception:
        await cb.message.answer(
            f"📢 در حال ارسال به {len(users)} کاربر...",
            reply_markup=kb_cancel,
        )
    await cb.answer()
    sent = 0
    failed = 0
    for u in users:
        async with Session() as s:
            bc_row = await s.get(Broadcast, bc_id)
            if bc_row and bc_row.status == "cancelled":
                break
        try:
            await bot.copy_message(chat_id=u.telegram_id, from_chat_id=src_chat,
                                    message_id=src_msg)
            sent += 1
        except Exception:
            failed += 1
        await asyncio.sleep(0.05)
    async with Session() as s:
        bc_row = await s.get(Broadcast, bc_id)
        if bc_row and bc_row.status != "cancelled":
            bc_row.status = "done"
        if bc_row:
            bc_row.sent_count = sent
            bc_row.failed_count = failed
        await s.commit()
    try:
        await cb.message.edit_text(
            f"✅ ارسال همگانی #{bc_id} تمام شد.\nموفق: {sent} | ناموفق: {failed}",
            reply_markup=back_to_admin_kb(),
        )
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


@router.callback_query(F.data.startswith("pbcast:stop:"))
async def adm_broadcast_stop(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    bc_id = int(cb.data.split(":")[2])
    async with Session() as s:
        bc_row = await s.get(Broadcast, bc_id)
        if bc_row and bc_row.status == "sending":
            bc_row.status = "cancelled"
            await s.commit()
    await cb.answer("ارسال لغو شد", show_alert=True)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


# ════════ تبلیغ در ربات‌های رایگان (پیام تبلیغاتی داخل تمام ربات‌های پلن رایگان) ════════
# ادمین پیامی می‌فرستد (متن با قالب‌بندی کامل تلگرام، عکس/ویدیو/گیف/استیکر و
# شکلک‌های پرمیوم) و همان پیام با copy_message عیناً — بدون هیچ تغییری در
# فرمت یا entity ها (از جمله custom_emoji یعنی شکلک پرمیوم) — به همهٔ
# کاربرانِ نهاییِ ربات‌هایی که روی پلن رایگان هستند ارسال می‌شود.
# از آنجا که copy_message تمام entity های پیام مبدأ را عیناً کپی می‌کند،
# نیازی به بازسازی دستی بولد/ایتالیک/لینک/شکلک پرمیوم نیست.

class AdFreeBroadcastFSM(StatesGroup):
    wait_msg = State()
    confirm = State()


def _ad_free_promo_kb() -> InlineKeyboardMarkup:
    """کیبوردِ ثابتی که همراهِ خودِ پیامِ تبلیغاتی برای کاربرانِ نهاییِ
    ربات‌های رایگان ارسال می‌شود (نه کیبوردِ تاییدِ ادمین). یک دکمهٔ لینکِ
    ثابت به خودِ بات‌ساز (@BaBotSazBot) برای تبلیغِ خودِ پلتفرم."""
    return InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("🤖 ساخت ربات با بات‌ساز", url="https://t.me/BaBotSazBot", style=ButtonStyle.SUCCESS)],
    ])


def _ad_free_confirm_kb() -> InlineKeyboardMarkup:
    return InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("✅ ارسال به همهٔ ربات‌های رایگان", callback_data="adfree:send",
                              style=ButtonStyle.SUCCESS)],
        [hx_button("❌ لغو", callback_data="adfree:cancel",
                              style=ButtonStyle.DANGER)],
    ])


# === PATCH_AD_FREE_CROSSBOT_FIX_MARKER ===
# مجموعهٔ انواعِ محتوایی که این قابلیت پشتیبانی می‌کند (متن + رایج‌ترین رسانه‌ها)
_AD_FREE_SUPPORTED_TYPES = {
    "text", "photo", "video", "animation", "document", "voice", "video_note", "sticker",
}


def _ad_free_extract_file_id(sent_msg, content_type: str):
    """PATCH_AD_FREE_CROSSBOT_FIX_MARKER — پس از اولین ارسالِ موفقِ رسانه توسط یک ربات، file_id را
    برای استفادهٔ مجدد (بدون آپلودِ دوباره) برای کاربرانِ بعدیِ همان ربات
    برمی‌گرداند."""
    try:
        if content_type == "photo":
            return sent_msg.photo[-1].file_id
        return getattr(sent_msg, content_type).file_id
    except Exception:
        return None


async def _ad_free_send_via_bot(tb: Bot, chat_id: int, content_type: str,
                                 text: str, caption: str, media_arg):
    """PATCH_AD_FREE_CROSSBOT_FIX_MARKER — پیام را با خودِ رباتِ مستأجر (تازه‌ساز) بازسازی و ارسال می‌کند
    (به‌جای copy_message که بینِ دو ربات متفاوت هرگز کار نمی‌کند)."""
    kb = _ad_free_promo_kb()
    if content_type == "text":
        return await tb.send_message(chat_id=chat_id, text=text, parse_mode="HTML",
                                      reply_markup=kb)
    if content_type == "photo":
        return await tb.send_photo(chat_id=chat_id, photo=media_arg, caption=caption,
                                    parse_mode="HTML", reply_markup=kb)
    if content_type == "video":
        return await tb.send_video(chat_id=chat_id, video=media_arg, caption=caption,
                                    parse_mode="HTML", reply_markup=kb)
    if content_type == "animation":
        return await tb.send_animation(chat_id=chat_id, animation=media_arg, caption=caption,
                                        parse_mode="HTML", reply_markup=kb)
    if content_type == "voice":
        return await tb.send_voice(chat_id=chat_id, voice=media_arg, caption=caption,
                                    parse_mode="HTML", reply_markup=kb)
    if content_type == "video_note":
        return await tb.send_video_note(chat_id=chat_id, video_note=media_arg, reply_markup=kb)
    if content_type == "sticker":
        return await tb.send_sticker(chat_id=chat_id, sticker=media_arg, reply_markup=kb)
    return await tb.send_document(chat_id=chat_id, document=media_arg, caption=caption,
                                   parse_mode="HTML", reply_markup=kb)


@router.callback_query(F.data == "adm:ad_free")
async def adm_ad_free_start(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    await state.set_state(AdFreeBroadcastFSM.wait_msg)
    await cb.message.answer(
        "📣 <b>تبلیغ در ربات‌های رایگان</b>\n\n"
        "پیامی که می‌خواهی به کاربران <b>همهٔ ربات‌های پلن رایگان</b> نشان داده شود را همین‌جا بفرست:\n"
        "• متن با تمام قالب‌بندی‌های تلگرام (بولد، ایتالیک، زیرخط، خط‌خورده، "
        "نقل‌قول، اسپویلر، کد، لینک)\n"
        "• شکلک‌های پرمیوم (Premium Emoji) — اگر با اکانت پرمیوم ارسال کنی، عیناً حفظ می‌شود\n"
        "• عکس، ویدیو، گیف، فایل یا استیکر همراه کپشن دلخواه\n\n"
        "پیام دقیقاً همان‌طور که فرستاده‌ای (بدون تغییر) داخل ربات‌های رایگان برای کاربرانشان کپی می‌شود.",
        reply_markup=await smart_cancel_kb(),
    )
    await cb.answer()


@router.message(AdFreeBroadcastFSM.wait_msg)
async def adm_ad_free_preview(msg: Message, state: FSMContext, bot: Bot):
    if msg.from_user.id != PLATFORM_ADMIN_ID:
        return
    descr = ((msg.caption or msg.text) or "[رسانه]")[:500]

    # === PATCH_AD_FREE_CROSSBOT_FIX_MARKER ===
    # محتوای پیام را همین‌جا (با دسترسیِ رباتِ پلتفرم که پیام را دریافت کرده)
    # می‌گیریم تا در مرحلهٔ ارسال، هر رباتِ مستأجر بتواند خودش دوباره بسازد
    # و بفرستد؛ چون copy_message بینِ دو ربات متفاوت هرگز کار نمی‌کند.
    content_type = msg.content_type
    if content_type not in _AD_FREE_SUPPORTED_TYPES:
        await msg.answer(
            "⚠️ این نوع پیام (مثلاً نظرسنجی/لوکیشن/مخاطب) پشتیبانی نمی‌شود.\n"
            "لطفاً فقط متن، عکس، ویدیو، گیف، فایل، ویس، ویدیو-نوت یا استیکر بفرست.",
        )
        return

    text = msg.html_text if content_type == "text" else None
    caption = msg.html_text if (content_type != "text" and (msg.caption or msg.caption_entities)) else None
    media_bytes = None
    media_filename = None
    file_id = None
    if content_type == "photo":
        file_id = msg.photo[-1].file_id
    elif content_type in ("video", "animation", "document", "voice", "video_note", "audio"):
        file_id = getattr(msg, content_type).file_id
    elif content_type == "sticker":
        file_id = msg.sticker.file_id

    if file_id:
        tg_file = await bot.get_file(file_id)
        buf = await bot.download_file(tg_file.file_path)
        media_bytes = buf.read()
        media_filename = (tg_file.file_path or "file").rsplit("/", 1)[-1]

    await state.update_data(
        content_type=content_type, text=text, caption=caption,
        media_bytes=media_bytes, media_filename=media_filename, descr=descr,
    )
    await state.set_state(AdFreeBroadcastFSM.confirm)
    await msg.answer("👁 <b>پیش‌نمایش</b> (همین پیام عیناً برای کاربران ربات‌های رایگان ارسال می‌شود):")
    try:
        await bot.copy_message(chat_id=msg.chat.id, from_chat_id=msg.chat.id,
                                message_id=msg.message_id,
                                reply_markup=_ad_free_promo_kb())
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
    async with Session() as s:
        free_bots = (await s.scalars(
            select(BotRow).where(BotRow.plan == Plan.FREE.value, BotRow.status == "active")
        )).all()
        bot_ids = [b.id for b in free_bots]
        total_users = 0
        if bot_ids:
            total_users = await s.scalar(
                select(func.count()).select_from(BotUser)
                .where(BotUser.bot_id.in_(bot_ids), BotUser.is_banned == False)
            ) or 0
    await msg.answer(
        f"این پیام داخل <b>{len(free_bots)}</b> ربات رایگان، برای حدود "
        f"<b>{total_users}</b> کاربر نهایی ارسال شود؟",
        reply_markup=_ad_free_confirm_kb(),
    )


@router.callback_query(AdFreeBroadcastFSM.confirm, F.data == "adfree:cancel")
async def adm_ad_free_cancel(cb: CallbackQuery, state: FSMContext):
    await state.clear()
    try:
        await cb.message.edit_text("❌ ارسال تبلیغ لغو شد.", reply_markup=back_to_admin_kb())
    except Exception:
        await cb.message.answer("❌ ارسال تبلیغ لغو شد.", reply_markup=back_to_admin_kb())
    await cb.answer()


@router.callback_query(AdFreeBroadcastFSM.confirm, F.data == "adfree:send")
async def adm_ad_free_send(cb: CallbackQuery, state: FSMContext):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await state.clear()
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    data = await state.get_data()
    await state.clear()
    # === PATCH_AD_FREE_CROSSBOT_FIX_MARKER ===
    content_type = data.get("content_type")
    text = data.get("text")
    caption = data.get("caption")
    media_bytes = data.get("media_bytes")
    media_filename = data.get("media_filename")
    descr = data.get("descr") or "[رسانه]"
    if not content_type or (content_type == "text" and not text) or \
            (content_type != "text" and not media_bytes):
        await cb.answer("پیام نامعتبر است؛ دوباره تلاش کن.", show_alert=True)
        return

    async with Session() as s:
        bc = Broadcast(bot_id=0, text=f"[AD_FREE] {descr}", status="sending")
        s.add(bc)
        await s.flush()
        bc_id = bc.id
        free_bots = (await s.scalars(
            select(BotRow).where(BotRow.plan == Plan.FREE.value, BotRow.status == "active")
        )).all()
        await s.commit()

    kb_cancel = InlineKeyboardMarkup(inline_keyboard=[
        [hx_button("🛑 لغو ارسال", callback_data=f"adfree:stop:{bc_id}")]
    ])
    try:
        await cb.message.edit_text(
            f"📣 در حال ارسال تبلیغ به {len(free_bots)} ربات رایگان...",
            reply_markup=kb_cancel,
        )
    except Exception:
        await cb.message.answer(
            f"📣 در حال ارسال تبلیغ به {len(free_bots)} ربات رایگان...",
            reply_markup=kb_cancel,
        )
    await cb.answer()

    total_sent = 0
    total_failed = 0
    bots_done = 0
    for row in free_bots:
        # بررسی لغو سراسری قبل از هر ربات
        async with Session() as s:
            bc_row = await s.get(Broadcast, bc_id)
            if bc_row and bc_row.status == "cancelled":
                break
        try:
            tb = Bot(token=row.token)
        except Exception:
            continue
        try:
            async with Session() as s:
                end_users = (await s.scalars(
                    select(BotUser).where(BotUser.bot_id == row.id, BotUser.is_banned == False)
                )).all()
            reused_media = None  # PATCH_AD_FREE_CROSSBOT_FIX_MARKER: file_id پس از اولین ارسالِ موفقِ همین ربات (بدون آپلودِ دوباره)
            for u in end_users:
                async with Session() as s:
                    bc_row = await s.get(Broadcast, bc_id)
                    if bc_row and bc_row.status == "cancelled":
                        break
                try:
                    if content_type == "text":
                        media_arg = None
                    elif reused_media is not None:
                        media_arg = reused_media
                    else:
                        media_arg = BufferedInputFile(media_bytes, filename=media_filename or "file")
                    sent_msg = await _ad_free_send_via_bot(
                        tb, u.telegram_id, content_type, text, caption, media_arg,
                    )
                    if content_type != "text" and reused_media is None:
                        reused_media = _ad_free_extract_file_id(sent_msg, content_type)
                    total_sent += 1
                except Exception:
                    total_failed += 1
                await asyncio.sleep(0.05)
        finally:
            try:
                await tb.session.close()
            except Exception:
                logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")
        bots_done += 1

    async with Session() as s:
        bc_row = await s.get(Broadcast, bc_id)
        if bc_row and bc_row.status != "cancelled":
            bc_row.status = "done"
        if bc_row:
            bc_row.sent_count = total_sent
            bc_row.failed_count = total_failed
        await s.commit()
    try:
        await cb.message.edit_text(
            f"✅ ارسال تبلیغ #{bc_id} در {bots_done} ربات رایگان تمام شد.\n"
            f"موفق: {total_sent} | ناموفق: {total_failed}",
            reply_markup=back_to_admin_kb(),
        )
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")


@router.callback_query(F.data.startswith("adfree:stop:"))
async def adm_ad_free_stop(cb: CallbackQuery):
    if cb.from_user.id != PLATFORM_ADMIN_ID:
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    bc_id = int(cb.data.split(":")[2])
    async with Session() as s:
        bc_row = await s.get(Broadcast, bc_id)
        if bc_row and bc_row.status == "sending":
            bc_row.status = "cancelled"
            await s.commit()
    await cb.answer("ارسال تبلیغ لغو شد", show_alert=True)
    try:
        await cb.message.edit_reply_markup(reply_markup=None)
    except Exception:
        logger.exception("خطای نادیده‌گرفته‌شده (قبلاً فقط pass بود)")

