@router.callback_query(F.data.startswith("abotdetach:"))
async def adm_bot_detach_partner(cb: CallbackQuery):
    """درخواستِ جداکردنِ ربات از همکار — قبل از اجرا، تاییدِ نهایی می‌خواهد."""
    if not await has_perm(cb.from_user.id, "adm:bots"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")  # abotdetach:{bot_id}:{src}
    bot_id = int(parts[1])
    src = parts[2] if len(parts) > 2 else "bots"
    from models import PartnerSale
    async with Session() as s:
        sale = await s.scalar(select(PartnerSale).where(PartnerSale.sold_bot_id == bot_id))
    if not sale:
        await cb.answer("این ربات از قبل مستقیم است (فروشِ همکار برایش ثبت نشده).", show_alert=True)
        return
    kb = InlineKeyboardMarkup(inline_keyboard=[[
        hx_button("✅ بله، منتقل شود", callback_data=f"abotdetachyes:{bot_id}:{src}"),
        hx_button("❌ خیر", callback_data=f"abot:{bot_id}:{src}"),
    ]])
    await cb.message.edit_text(
        "⚠️ این ربات از ربات همکار جدا و به‌عنوانِ ربات <b>مستقیمِ بات‌ساز</b> "
        "ثبت شود؟\n\n"
        "پلن/سررسید/مالکیتِ ربات تغییر نمی‌کند — فقط دیگر جزوِ فروشِ همکار "
        "حساب نمی‌شود و مالک از همینجا، مستقیم از بات‌سازِ اصلی، می‌تواند "
        "ارتقا/تمدید/فعال‌سازیش کند.",
        reply_markup=kb)
    await cb.answer()


# === PATCH_ADM_BOT_ADMINS_LIST_V1 ===
async def _bot_admins_screen(bot_id: int, src: str):
    from models import AdminSupport as _AS
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r:
            return None, None
        admins = (await s.scalars(select(_AS).where(_AS.bot_id == bot_id).order_by(_AS.id))).all()
    lines = [f"👥 <b>ادمین‌هایِ رباتِ @{r.username or r.id}</b>", "",
             f"👑 مالک: <code>{r.owner_id}</code> (قابل‌حذف نیست)", ""]
    rows = []
    if not admins:
        lines.append("هیچ ادمین/پشتیبانِ دیگری ثبت نشده.")
    for ad in admins:
        nm = _html.escape(ad.full_name or "بی‌نام")
        lines.append(f"• {nm} — <code>{ad.telegram_id}</code>"
                     + ("  👑 (مالک)" if int(ad.telegram_id) == int(r.owner_id) else ""))
        rows.append([hx_button(f"🗑 حذفِ {ad.full_name or ad.telegram_id}",
                               callback_data=f"abotadmdel:{bot_id}:{ad.id}:{src}", style=ButtonStyle.DANGER)])
    rows.append([hx_button("⬅️ بازگشت", callback_data=f"abot:{bot_id}:{src}", style=ButtonStyle.DANGER)])
    return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)


@router.callback_query(F.data.startswith("abotadm:"))
async def adm_bot_admins_show(cb: CallbackQuery, bot: Bot):
    if not await has_perm(cb.from_user.id, "adm:bots"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")
    bot_id, src = int(parts[1]), (parts[2] if len(parts) > 2 else "bots")
    text, kb = await _bot_admins_screen(bot_id, src)
    if not text:
        await cb.answer("یافت نشد", show_alert=True)
        return
    try:
        await cb.message.edit_text(text, reply_markup=kb)
    except Exception:
        await cb.message.answer(text, reply_markup=kb)
    await cb.answer()


@router.callback_query(F.data.startswith("abotadmdel:"))
async def adm_bot_admins_delete(cb: CallbackQuery, bot: Bot):
    if not await has_perm(cb.from_user.id, "adm:bots"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    from models import AdminSupport as _AS
    parts = cb.data.split(":")  # abotadmdel:{bot_id}:{admin_row_id}:{src}
    bot_id, adm_id = int(parts[1]), int(parts[2])
    src = parts[3] if len(parts) > 3 else "bots"
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        ad = await s.get(_AS, adm_id)
        if not r or not ad or ad.bot_id != bot_id:
            await cb.answer("یافت نشد (شاید قبلاً حذف شده).", show_alert=True)
        else:
            tok, tid = r.token, ad.telegram_id
            await s.delete(ad)
            await s.commit()
            try:
                import tenant_status_bus
                await tenant_status_bus.publish_tenant_invalidate(tok)
            except Exception:
                logger.exception("حذفِ ادمین: بی‌اعتبارکردنِ کشِ ربات ناموفق بود")
            await cb.answer(f"✅ ادمین {tid} حذف شد", show_alert=True)
    text, kb = await _bot_admins_screen(bot_id, src)
    if text:
        try:
            await cb.message.edit_text(text, reply_markup=kb)
        except Exception:
            logger.exception("نمایشِ مجددِ فهرستِ ادمین‌ها")


@router.callback_query(F.data.startswith("abotdetachyes:"))
async def adm_bot_detach_partner_yes(cb: CallbackQuery, bot: Bot):
    if not await has_perm(cb.from_user.id, "adm:bots"):
        await cb.answer("دسترسی ندارید", show_alert=True)
        return
    parts = cb.data.split(":")  # abotdetachyes:{bot_id}:{src}
    bot_id = int(parts[1])
    src = parts[2] if len(parts) > 2 else "bots"
    from models import PartnerSale
    async with Session() as s:
        r = await s.get(BotRow, bot_id)
        if not r:
            await cb.answer("یافت نشد", show_alert=True)
            return
        sale = await s.scalar(select(PartnerSale).where(PartnerSale.sold_bot_id == bot_id))
        if not sale:
            await cb.answer("این ربات از قبل مستقیم است.", show_alert=True)
            return
        # === PATCH_PARTNER_DETACH_NO_ACCESS_V1 ===
        # همکار نباید هیچ ردپای دسترسی‌ای به این ربات بماند: اگر خودِ همکار (یا
        # مالکِ رباتِ همکار) به‌عنوان «ادمین/پشتیبان» در این ربات ثبت شده، حذف می‌شود
        # (مگر خودِ مالکِ ربات باشد).
        from models import PartnerBot as _PB
        _pbot = await s.get(_PB, sale.partner_bot_id)
        _partner_owner = _pbot.owner_id if _pbot else None
        if _partner_owner and int(_partner_owner) != int(r.owner_id):
            for _adm in (await s.scalars(select(AdminSupport).where(
                    AdminSupport.bot_id == bot_id,
                    AdminSupport.telegram_id == int(_partner_owner)))).all():
                await s.delete(_adm)
        await s.delete(sale)
        owner_id, uname, _tok = r.owner_id, r.username, r.token
        await s.commit()
    try:
        import tenant_status_bus
        await tenant_status_bus.publish_tenant_invalidate(_tok)
    except Exception:
        logger.exception("detach: بی‌اعتبارکردنِ کشِ ربات ناموفق بود (نادیده گرفته شد)")
    try:
        await bot.send_message(
            owner_id,
            f"🔓 ربات @{uname} از این پس مستقیماً زیرِ نظرِ بات‌سازِ اصلی است.\n"
            "برای ارتقا، تمدید یا فعال‌سازی، از «🗂 ربات‌های من» در همین ربات اقدام کن.")
    except Exception:
        logger.exception("اطلاعِ جداشدن از همکار به مالک ناموفق بود (نادیده گرفته شد)")
    await _render_bot_detail(cb, bot_id, src, note="✅ ربات به بات‌سازِ اصلی منتقل شد.")


# === PATCH_PLATFORM_ADMIN_CB_GUARD_V1 ===
# callback_data را تلگرام اعتبارسنجی نمی‌کند. چند هندلرِ پنلِ مدیریتِ ربات‌ساز
# (فهرستِ همهٔ ربات‌ها «adm:bots»، بایگانی، ویرایشِ دکمه‌هایِ کامیونیتی، …) هیچ
# چکِ ادمینی نداشتند و هر کاربری با callbackِ دست‌ساز فهرستِ ربات‌ها و مالک‌هایشان
# را می‌دید. پیشوندهایی که فقط در پنلِ مدیریت ساخته می‌شوند، این‌جا قبل از هر هندلری
# به ادمینِ اصلی یا ادمینِ فرعیِ فعال محدود می‌شوند (چکِ دسترسیِ ریزِ خودِ هندلرها
# — has_perm — سرِ جایش می‌ماند).
_PLATFORM_ADMIN_CB_PREFIXES = (
    "adm:", "admarch:", "admbots:", "admfield", "abot", "usr:", "usr_", "usrdays",
    "usrmove:", "set:", "cadm:", "pgbset:", "pgmset:", "bcast:", "adfree:", "pf:",
    "vip", "swadm", "trialrenew:appr:", "trialrenew:rej:", "chgok", "chgrev", "smsexp", "ppsmsexp",
    "bigreq", "tkswapdecide", "mapall", "pbcast", "psa:", "sszg2:", "sszg3:", "ssfinal:",
)


# دکمه‌هایی که با پیشوندِ مدیریتی شروع می‌شوند ولی مالِ کاربرِ عادی‌اند
# (هندلرشان مالکیت را خودش چک می‌کند): «ارسالِ توکن» توسطِ مالکِ جدیدِ انتقال
_PLATFORM_ADMIN_CB_EXEMPT = ("abotxferself:",)


async def _platform_admin_cb_guard(handler, event, data):
    cbd = getattr(event, "data", None) or ""
    if (not cbd.startswith(_PLATFORM_ADMIN_CB_PREFIXES)
            or cbd.startswith(_PLATFORM_ADMIN_CB_EXEMPT)):
        return await handler(event, data)
    uid = getattr(getattr(event, "from_user", None), "id", None)
    ok = uid is not None and is_admin(uid)
    if not ok and uid is not None:
        try:
            async with Session() as s:
                ok = await get_sub_admin(s, uid) is not None
        except Exception:
            logger.exception("platform admin guard: خواندنِ ادمینِ فرعی ناموفق بود")
            ok = False
    if ok:
        return await handler(event, data)
    logger.warning("platform admin guard: callbackِ مدیریتی از کاربرِ غیرمجاز رد شد (user=%s data=%r)",
                   uid, cbd[:64])
    try:
        await event.answer()
    except Exception:
        logger.debug("platform admin guard: پاسخ به callback ممکن نشد", exc_info=True)
    return None


router.callback_query.outer_middleware(_platform_admin_cb_guard)
